const DATA=[{"t":"scene","act":1,"scene":"I","loc":"Elsinore. A platform before the Castle.","id":0},{"t":"sd","text":"Enter Francisco and Barnardo, two sentinels.","id":1},{"t":"sp","who":"BARNARDO","lines":["Who's there?"],"id":2,"m":"Who's there?"},{"t":"sp","who":"FRANCISCO","lines":["Nay, answer me. Stand and unfold yourself."],"id":3,"m":"No, you answer me. Stop and show who you are."},{"t":"sp","who":"BARNARDO","lines":["Long live the King!"],"id":4,"m":"Long live the King!"},{"t":"sp","who":"FRANCISCO","lines":["Barnardo?"],"id":5,"m":"Barnardo?"},{"t":"sp","who":"BARNARDO","lines":["He."],"id":6,"m":"It's me."},{"t":"sp","who":"FRANCISCO","lines":["You come most carefully upon your hour."],"id":7,"m":"You've come exactly on time."},{"t":"sp","who":"BARNARDO","lines":["'Tis now struck twelve. Get thee to bed, Francisco."],"id":8,"m":"It has just struck twelve. Go to bed, Francisco."},{"t":"sp","who":"FRANCISCO","lines":["For this relief much thanks. 'Tis bitter cold,","And I am sick at heart."],"id":9,"m":"Thanks for taking over. It's bitterly cold, and I feel low and uneasy."},{"t":"sp","who":"BARNARDO","lines":["Have you had quiet guard?"],"id":10,"m":"Has your watch been quiet?"},{"t":"sp","who":"FRANCISCO","lines":["Not a mouse stirring."],"id":11,"m":"Not even a mouse moving."},{"t":"sp","who":"BARNARDO","lines":["Well, good night.","If you do meet Horatio and Marcellus,","The rivals of my watch, bid them make haste."],"id":12,"m":"Well, good night. If you meet Horatio and Marcellus, who are on watch with me, tell them to hurry."},{"t":"sd","text":"Enter Horatio and Marcellus.","id":13},{"t":"sp","who":"FRANCISCO","lines":["I think I hear them. Stand, ho! Who is there?"],"id":14,"m":"I think I can hear them. Stop! Who's there?"},{"t":"sp","who":"HORATIO","lines":["Friends to this ground."],"id":15,"m":"Friends of this country."},{"t":"sp","who":"MARCELLUS","lines":["And liegemen to the Dane."],"id":16,"m":"And loyal subjects of the Danish king."},{"t":"sp","who":"FRANCISCO","lines":["Give you good night."],"id":17,"m":"Good night to you."},{"t":"sp","who":"MARCELLUS","lines":["O, farewell, honest soldier, who hath reliev'd you?"],"id":18,"m":"Oh, goodbye, honest soldier. Who has taken over from you?"},{"t":"sp","who":"FRANCISCO","lines":["Barnardo has my place. Give you good-night."],"id":19,"m":"Barnardo has my place. Good night."},{"t":"sd","text":"Exit","id":20},{"t":"sp","who":"MARCELLUS","lines":["Holla, Barnardo!"],"id":21,"m":"Hello, Barnardo!"},{"t":"sp","who":"BARNARDO","lines":["Say, what, is Horatio there?"],"id":22,"m":"Tell me, is Horatio there?"},{"t":"sp","who":"HORATIO","lines":["A piece of him."],"id":23,"m":"Part of him is."},{"t":"sp","who":"BARNARDO","lines":["Welcome, Horatio. Welcome, good Marcellus."],"id":24,"m":"Welcome, Horatio. Welcome, good Marcellus."},{"t":"sp","who":"MARCELLUS","lines":["What, has this thing appear'd again tonight?"],"id":25,"m":"So, has this thing appeared again tonight?"},{"t":"sp","who":"BARNARDO","lines":["I have seen nothing."],"id":26,"m":"I haven't seen anything."},{"t":"sp","who":"MARCELLUS","lines":["Horatio says 'tis but our fantasy,","And will not let belief take hold of him","Touching this dreaded sight, twice seen of us.","Therefore I have entreated him along","With us to watch the minutes of this night,","That if again this apparition come","He may approve our eyes and speak to it."],"id":27,"m":"Horatio says it's only our imagination, and he won't let himself believe in this terrible thing we've seen twice. So I've begged him to come and keep watch with us tonight, so that if the ghost comes again he can confirm what we saw and speak to it."},{"t":"sp","who":"HORATIO","lines":["Tush, tush, 'twill not appear."],"id":28,"m":"Nonsense, nonsense, it won't appear."},{"t":"sp","who":"BARNARDO","lines":["Sit down awhile,","And let us once again assail your ears,","That are so fortified against our story,","What we two nights have seen."],"id":29,"m":"Sit down for a while, and let us attack your ears once more, since they are so well defended against our story, with what we have seen these two nights."},{"t":"sp","who":"HORATIO","lines":["Well, sit we down,","And let us hear Barnardo speak of this."],"id":30,"m":"Well, let's sit down and hear Barnardo tell it."},{"t":"sp","who":"BARNARDO","lines":["Last night of all,","When yond same star that's westward from the pole,","Had made his course t'illume that part of heaven","Where now it burns, Marcellus and myself,","The bell then beating one—"],"id":31,"m":"Last night, when that star west of the North Star had moved across to light the part of the sky where it is shining now, Marcellus and I, just as the bell was striking one—"},{"t":"sp","who":"MARCELLUS","lines":["Peace, break thee off. Look where it comes again."],"id":32,"m":"Quiet, stop! Look, here it comes again."},{"t":"sd","text":"Enter Ghost.","id":33},{"t":"sp","who":"BARNARDO","lines":["In the same figure, like the King that's dead."],"id":34,"m":"In the same shape as the dead King."},{"t":"sp","who":"MARCELLUS","lines":["Thou art a scholar; speak to it, Horatio."],"id":35,"m":"You're an educated man; speak to it, Horatio."},{"t":"sp","who":"BARNARDO","lines":["Looks it not like the King? Mark it, Horatio."],"id":36,"m":"Doesn't it look like the King? Look closely, Horatio."},{"t":"sp","who":"HORATIO","lines":["Most like. It harrows me with fear and wonder."],"id":37,"m":"Very like him. It tears through me with fear and amazement."},{"t":"sp","who":"BARNARDO","lines":["It would be spoke to."],"id":38,"m":"It wants someone to speak to it."},{"t":"sp","who":"MARCELLUS","lines":["Question it, Horatio."],"id":39,"m":"Ask it something, Horatio."},{"t":"sp","who":"HORATIO","lines":["What art thou that usurp'st this time of night,","Together with that fair and warlike form","In which the majesty of buried Denmark","Did sometimes march? By heaven I charge thee speak."],"id":40,"m":"What are you, that take over this time of night, and the fine, warlike shape in which the buried King of Denmark used to march? In heaven's name, I order you to speak!"},{"t":"sp","who":"MARCELLUS","lines":["It is offended."],"id":41,"m":"It is offended."},{"t":"sp","who":"BARNARDO","lines":["See, it stalks away."],"id":42,"m":"Look, it's striding away."},{"t":"sp","who":"HORATIO","lines":["Stay! speak, speak! I charge thee speak!"],"id":43,"m":"Stop! Speak, speak! I order you to speak!"},{"t":"sd","text":"Exit Ghost","id":44},{"t":"sp","who":"MARCELLUS","lines":["'Tis gone, and will not answer."],"id":45,"m":"It's gone, and it won't answer."},{"t":"sp","who":"BARNARDO","lines":["How now, Horatio! You tremble and look pale.","Is not this something more than fantasy?","What think you on't?"],"id":46,"m":"What's this, Horatio? You're trembling and pale. Isn't this something more than imagination? What do you think of it?"},{"t":"sp","who":"HORATIO","lines":["Before my God, I might not this believe","Without the sensible and true avouch","Of mine own eyes."],"id":47,"m":"I swear to God, I could never have believed this without the clear, true evidence of my own eyes."},{"t":"sp","who":"MARCELLUS","lines":["Is it not like the King?"],"id":48,"m":"Isn't it like the King?"},{"t":"sp","who":"HORATIO","lines":["As thou art to thyself:","Such was the very armour he had on","When he th'ambitious Norway combated;","So frown'd he once, when in an angry parle","He smote the sledded Polacks on the ice.","'Tis strange."],"id":49,"m":"As much as you are like yourself. That was the very armour he wore when he fought the ambitious King of Norway. He frowned like that once when, in an angry meeting, he struck the Poles on their sledges on the ice. It's strange."},{"t":"sp","who":"MARCELLUS","lines":["Thus twice before, and jump at this dead hour,","With martial stalk hath he gone by our watch."],"id":50,"m":"Twice before, at exactly this dead hour, it has marched past our guard post like a soldier."},{"t":"sp","who":"HORATIO","lines":["In what particular thought to work I know not;","But in the gross and scope of my opinion,","This bodes some strange eruption to our state."],"id":51,"m":"I don't know exactly what to think, but my general opinion is that this is a sign of some strange upheaval coming to our country."},{"t":"sp","who":"MARCELLUS","lines":["Good now, sit down, and tell me, he that knows,","Why this same strict and most observant watch","So nightly toils the subject of the land,","And why such daily cast of brazen cannon","And foreign mart for implements of war;","Why such impress of shipwrights, whose sore task","Does not divide the Sunday from the week.","What might be toward, that this sweaty haste","Doth make the night joint-labourer with the day:","Who is't that can inform me?"],"id":52,"m":"Please, sit down, and whoever knows, tell me why this strict, watchful guard is kept every night, wearing out the people of the country, and why bronze cannons are cast every day and weapons bought abroad; why shipbuilders are forced to work so hard that they don't get Sundays off. What is about to happen, that this sweating haste makes night work as hard as day? Who can tell me?"},{"t":"sp","who":"HORATIO","lines":["That can I;","At least, the whisper goes so. Our last King,","Whose image even but now appear'd to us,","Was, as you know, by Fortinbras of Norway,","Thereto prick'd on by a most emulate pride,","Dar'd to the combat; in which our valiant Hamlet,","For so this side of our known world esteem'd him,","Did slay this Fortinbras; who by a seal'd compact,","Well ratified by law and heraldry,","Did forfeit, with his life, all those his lands","Which he stood seiz'd of, to the conqueror;","Against the which, a moiety competent","Was gaged by our King; which had return'd","To the inheritance of Fortinbras,","Had he been vanquisher; as by the same cov'nant","And carriage of the article design'd,","His fell to Hamlet. Now, sir, young Fortinbras,","Of unimproved mettle, hot and full,","Hath in the skirts of Norway, here and there,","Shark'd up a list of lawless resolutes,","For food and diet, to some enterprise","That hath a stomach in't; which is no other,","As it doth well appear unto our state,","But to recover of us by strong hand","And terms compulsatory, those foresaid lands","So by his father lost. And this, I take it,","Is the main motive of our preparations,","The source of this our watch, and the chief head","Of this post-haste and rummage in the land."],"id":53,"m":"I can; at least, this is the rumour. Our last King, whose image appeared to us just now, was, as you know, challenged to single combat by Fortinbras of Norway, who was spurred on by jealous pride. In that fight our brave Hamlet, for that's how this half of the known world thought of him, killed this Fortinbras. By a sealed agreement, properly made by law and the rules of chivalry, Fortinbras lost all the lands he owned, along with his life, to the winner. Our King had staked an equal share of land, which would have gone to Fortinbras if he had won; by the same agreement and its terms, Fortinbras's lands went to Hamlet. Now, sir, young Fortinbras, untested, hot-headed and full of spirit, has rounded up a band of lawless desperadoes from the edges of Norway, men who'll fight for their food, for some bold enterprise. As our government sees it, this is nothing other than to take back from us by force the lands his father lost. And this, I think, is the main reason for our preparations, the cause of our guard duty and the chief source of all this rush and bustle in the country."},{"t":"sp","who":"BARNARDO","lines":["I think it be no other but e'en so:","Well may it sort that this portentous figure","Comes armed through our watch so like the King","That was and is the question of these wars."],"id":54,"m":"I think that's exactly it. It would fit that this ominous figure comes armed past our guard looking so like the King who was, and still is, the cause of these wars."},{"t":"sp","who":"HORATIO","lines":["A mote it is to trouble the mind's eye.","In the most high and palmy state of Rome,","A little ere the mightiest Julius fell,","The graves stood tenantless and the sheeted dead","Did squeak and gibber in the Roman streets;","As stars with trains of fire and dews of blood,","Disasters in the sun; and the moist star,","Upon whose influence Neptune's empire stands,","Was sick almost to doomsday with eclipse.","And even the like precurse of fierce events,","As harbingers preceding still the fates","And prologue to the omen coming on,","Have heaven and earth together demonstrated","Unto our climatures and countrymen."],"id":55,"m":"It's a speck of dust to trouble the mind's eye. In Rome, at the height of its glory, just before the mighty Julius Caesar fell, the graves were emptied and the dead in their shrouds squeaked and gibbered in the Roman streets. There were comets with tails of fire, dews of blood, bad signs in the sun, and the moon, which controls the tides, was so darkened by eclipse it was almost like the end of the world. And the same kind of warnings of terrible events, like messengers always running ahead of fate and like a prologue to the disaster that is coming, have been shown by heaven and earth together to our country and our people."},{"t":"sd","text":"Re-enter Ghost.","id":56},{"t":"sp","who":"HORATIO","cont":1,"lines":["But, soft, behold! Lo, where it comes again!","I'll cross it, though it blast me. Stay, illusion!","If thou hast any sound, or use of voice,","Speak to me.","If there be any good thing to be done,","That may to thee do ease, and grace to me,","Speak to me.","If thou art privy to thy country's fate,","Which, happily, foreknowing may avoid,","O speak!","Or if thou hast uphoarded in thy life","Extorted treasure in the womb of earth,","For which, they say, you spirits oft walk in death,","Speak of it. Stay, and speak!"],"id":57,"m":"But wait, look! Here it comes again! I'll stand in its way, even if it destroys me. Stop, illusion! If you can make any sound or use a voice, speak to me. If there is any good deed that could be done to give you peace and win me grace, speak to me. If you know some secret about your country's fate, which knowing in advance might help us avoid, oh, speak! Or if in your life you buried stolen treasure in the earth, which they say is why spirits often walk after death, speak of it. Stop, and speak!"},{"t":"sd","text":"The cock crows","id":58},{"t":"sp","who":"HORATIO","cont":1,"lines":["Stop it, Marcellus!"],"id":59,"m":"Stop it, Marcellus!"},{"t":"sp","who":"MARCELLUS","lines":["Shall I strike at it with my partisan?"],"id":60,"m":"Shall I strike at it with my spear?"},{"t":"sp","who":"HORATIO","lines":["Do, if it will not stand."],"id":61,"m":"Do it, if it won't stand still."},{"t":"sp","who":"BARNARDO","lines":["'Tis here!"],"id":62,"m":"It's here!"},{"t":"sp","who":"HORATIO","lines":["'Tis here!"],"id":63,"m":"It's here!"},{"t":"sd","text":"Exit Ghost","id":64},{"t":"sp","who":"MARCELLUS","lines":["'Tis gone!","We do it wrong, being so majestical,","To offer it the show of violence,","For it is as the air, invulnerable,","And our vain blows malicious mockery."],"id":65,"m":"It's gone! We do wrong to threaten it with violence when it looks so majestic. It is like the air, it can't be wounded, and our useless blows are just spiteful mockery."},{"t":"sp","who":"BARNARDO","lines":["It was about to speak, when the cock crew."],"id":66,"m":"It was about to speak when the cock crowed."},{"t":"sp","who":"HORATIO","lines":["And then it started, like a guilty thing","Upon a fearful summons. I have heard","The cock, that is the trumpet to the morn,","Doth with his lofty and shrill-sounding throat","Awake the god of day; and at his warning,","Whether in sea or fire, in earth or air,","Th'extravagant and erring spirit hies","To his confine. And of the truth herein","This present object made probation."],"id":67,"m":"And then it jumped, like a guilty person called to answer for something. I've heard that the cock, the trumpeter of the morning, wakes the god of day with his high, shrill throat, and when he gives his warning, any wandering spirit, whether in sea or fire, earth or air, hurries back to where it is confined. And what we've just seen proves that this is true."},{"t":"sp","who":"MARCELLUS","lines":["It faded on the crowing of the cock.","Some say that ever 'gainst that season comes","Wherein our Saviour's birth is celebrated,","The bird of dawning singeth all night long;","And then, they say, no spirit dare stir abroad,","The nights are wholesome, then no planets strike,","No fairy takes, nor witch hath power to charm;","So hallow'd and so gracious is the time."],"id":68,"m":"It faded when the cock crowed. Some say that whenever the season comes when we celebrate our Saviour's birth, the bird of dawn sings all night long. And then, they say, no spirit dares to walk abroad. The nights are healthy, no planets bring harm, no fairy casts a spell and no witch has power to charm, the time is so holy and so full of grace."},{"t":"sp","who":"HORATIO","lines":["So have I heard, and do in part believe it.","But look, the morn in russet mantle clad,","Walks o'er the dew of yon high eastward hill.","Break we our watch up, and by my advice,","Let us impart what we have seen tonight","Unto young Hamlet; for upon my life,","This spirit, dumb to us, will speak to him.","Do you consent we shall acquaint him with it,","As needful in our loves, fitting our duty?"],"id":69,"m":"So I've heard, and I partly believe it. But look, the morning, dressed in a reddish-brown cloak, is walking over the dew on that high hill in the east. Let's end our watch, and I advise that we tell young Hamlet what we've seen tonight. I'd bet my life this spirit, silent to us, will speak to him. Do you agree that we should tell him, as our love for him demands and as our duty requires?"},{"t":"sp","who":"MARCELLUS","lines":["Let's do't, I pray, and I this morning know","Where we shall find him most conveniently."],"id":70,"m":"Let's do it, please. I know where we can find him most easily this morning."},{"t":"sd","text":"Exeunt","id":71},{"t":"scene","act":1,"scene":"II","loc":"Elsinore. A room of state in the Castle.","id":72},{"t":"sd","text":"Enter Claudius King of Denmark, Gertrude the Queen, Hamlet, Polonius, Laertes, Voltemand, Cornelius, Lords and Attendant.","id":73},{"t":"sp","who":"CLAUDIUS","lines":["Though yet of Hamlet our dear brother's death","The memory be green, and that it us befitted","To bear our hearts in grief, and our whole kingdom","To be contracted in one brow of woe;","Yet so far hath discretion fought with nature","That we with wisest sorrow think on him,","Together with remembrance of ourselves.","Therefore our sometime sister, now our queen,","Th'imperial jointress to this warlike state,","Have we, as 'twere with a defeated joy,","With one auspicious and one dropping eye,","With mirth in funeral, and with dirge in marriage,","In equal scale weighing delight and dole,","Taken to wife; nor have we herein barr'd","Your better wisdoms, which have freely gone","With this affair along. For all, our thanks.","Now follows, that you know young Fortinbras,","Holding a weak supposal of our worth,","Or thinking by our late dear brother's death","Our state to be disjoint and out of frame,","Colleagued with this dream of his advantage,","He hath not fail'd to pester us with message,","Importing the surrender of those lands","Lost by his father, with all bonds of law,","To our most valiant brother. So much for him.","Now for ourself and for this time of meeting:","Thus much the business is: we have here writ","To Norway, uncle of young Fortinbras,","Who, impotent and bed-rid, scarcely hears","Of this his nephew's purpose, to suppress","His further gait herein; in that the levies,","The lists, and full proportions are all made","Out of his subject: and we here dispatch","You, good Cornelius, and you, Voltemand,","For bearers of this greeting to old Norway,","Giving to you no further personal power","To business with the King, more than the scope","Of these dilated articles allow.","Farewell; and let your haste commend your duty."],"id":74,"m":"Although the death of our dear brother Hamlet is still fresh in our memory, and it was right for us to keep our hearts in mourning and for the whole kingdom to wear one frowning face of grief, good sense has so far fought against natural feeling that we think of him with wise sorrow while also remembering ourselves. So we have married our former sister-in-law, now our queen, who shares the rule of this warlike country. We have done it with a kind of spoiled joy, with one eye hopeful and one eye weeping, with laughter at the funeral and lament at the wedding, weighing happiness and grief equally. And we did not ignore your wise advice, which freely supported this whole matter. Thank you all. Next, as you know, young Fortinbras, who either thinks little of our strength or believes that our dear brother's recent death has thrown our country into disorder, has joined that fantasy of his advantage to constant messages pestering us to hand back the lands his father lost, legally, to our brave brother. So much for him. Now for us and the reason for this meeting. This is the business: we have written to the King of Norway, young Fortinbras's uncle, who is weak and bedridden and has hardly heard of his nephew's plans, asking him to stop him going any further, since the troops, the lists of recruits and all the supplies are drawn from his own subjects. And we are sending you, good Cornelius, and you, Voltemand, to carry this greeting to old Norway. You have no personal power to deal with the King beyond what these detailed terms allow. Goodbye, and show your loyalty by your speed."},{"t":"sp","who":"CORNELIUS AND VOLTEMAND","lines":["In that, and all things, will we show our duty."],"id":75,"m":"In that, and in everything, we will show our loyalty."},{"t":"sp","who":"CLAUDIUS","lines":["We doubt it nothing: heartily farewell."],"id":76,"m":"We don't doubt it at all. A warm farewell."},{"t":"sd","text":"Exeunt Voltemand and Cornelius","id":77},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["And now, Laertes, what's the news with you?","You told us of some suit. What is't, Laertes?","You cannot speak of reason to the Dane,","And lose your voice. What wouldst thou beg, Laertes,","That shall not be my offer, not thy asking?","The head is not more native to the heart,","The hand more instrumental to the mouth,","Than is the throne of Denmark to thy father.","What wouldst thou have, Laertes?"],"id":78,"m":"And now, Laertes, what's your news? You mentioned a request. What is it, Laertes? You can't make a reasonable request to the King of Denmark and waste your breath. What could you ask for, Laertes, that I wouldn't offer before you asked? The head is not more closely linked to the heart, nor the hand more ready to serve the mouth, than the throne of Denmark is to your father. What do you want, Laertes?"},{"t":"sp","who":"LAERTES","lines":["Dread my lord,","Your leave and favour to return to France,","From whence though willingly I came to Denmark","To show my duty in your coronation;","Yet now I must confess, that duty done,","My thoughts and wishes bend again toward France,","And bow them to your gracious leave and pardon."],"id":79,"m":"My respected lord, your permission to go back to France. I came to Denmark willingly to show my loyalty at your coronation, but now I must admit that, with that duty done, my thoughts and wishes are turning back to France, and they bow to ask your gracious permission."},{"t":"sp","who":"CLAUDIUS","lines":["Have you your father's leave? What says Polonius?"],"id":80,"m":"Do you have your father's permission? What does Polonius say?"},{"t":"sp","who":"POLONIUS","lines":["He hath, my lord, wrung from me my slow leave","By laboursome petition; and at last","Upon his will I seal'd my hard consent.","I do beseech you give him leave to go."],"id":81,"m":"He has, my lord, squeezed my reluctant permission out of me by begging hard, and in the end I gave my unwilling consent to what he wanted. I beg you, let him go."},{"t":"sp","who":"CLAUDIUS","lines":["Take thy fair hour, Laertes; time be thine,","And thy best graces spend it at thy will!","But now, my cousin Hamlet, and my son—"],"id":82,"m":"Make the most of your youth, Laertes. Your time is your own; spend it as you like, with your best qualities! But now, Hamlet, my nephew and my son—"},{"t":"sp","who":"HAMLET","lines":["[Aside] A little more than kin, and less than kind."],"id":83,"m":"[Aside] A bit too closely related now, and not the loving kind."},{"t":"sp","who":"CLAUDIUS","lines":["How is it that the clouds still hang on you?"],"id":84,"m":"Why are the clouds still hanging over you?"},{"t":"sp","who":"HAMLET","lines":["Not so, my lord, I am too much i' the sun."],"id":85,"m":"Not at all, my lord. I'm getting too much sun, and too much of being called your 'son'."},{"t":"sp","who":"GERTRUDE","lines":["Good Hamlet, cast thy nighted colour off,","And let thine eye look like a friend on Denmark.","Do not for ever with thy vailed lids","Seek for thy noble father in the dust.","Thou know'st 'tis common, all that lives must die,","Passing through nature to eternity."],"id":86,"m":"Good Hamlet, throw off your dark mood and your black clothes, and look at the King of Denmark like a friend. Don't keep searching for your noble father in the dust with your eyes cast down. You know it's common: everything that lives must die, passing through nature to eternity."},{"t":"sp","who":"HAMLET","lines":["Ay, madam, it is common."],"id":87,"m":"Yes, madam, it is common."},{"t":"sp","who":"GERTRUDE","lines":["If it be,","Why seems it so particular with thee?"],"id":88,"m":"If it is, why does it seem so special in your case?"},{"t":"sp","who":"HAMLET","lines":["Seems, madam! Nay, it is; I know not seems.","'Tis not alone my inky cloak, good mother,","Nor customary suits of solemn black,","Nor windy suspiration of forc'd breath,","No, nor the fruitful river in the eye,","Nor the dejected haviour of the visage,","Together with all forms, moods, shows of grief,","That can denote me truly. These indeed seem,","For they are actions that a man might play;","But I have that within which passeth show;","These but the trappings and the suits of woe."],"id":89,"m":"Seems, madam? No, it is. I don't know about 'seems'. It isn't just my inky black cloak, good mother, or my usual formal black clothes, or heavy sighing, or the flood of tears from my eyes, or the downcast look on my face, together with all the outward forms, moods and signs of grief, that can show what I truly feel. Those things really do seem, because they are actions a man could put on like an actor. But I have something inside me that goes beyond any show; those are just the decorations and costumes of grief."},{"t":"sp","who":"CLAUDIUS","lines":["'Tis sweet and commendable in your nature, Hamlet,","To give these mourning duties to your father;","But you must know, your father lost a father,","That father lost, lost his, and the survivor bound","In filial obligation, for some term","To do obsequious sorrow. But to persevere","In obstinate condolement is a course","Of impious stubbornness. 'Tis unmanly grief,","It shows a will most incorrect to heaven,","A heart unfortified, a mind impatient,","An understanding simple and unschool'd;","For what we know must be, and is as common","As any the most vulgar thing to sense,","Why should we in our peevish opposition","Take it to heart? Fie, 'tis a fault to heaven,","A fault against the dead, a fault to nature,","To reason most absurd, whose common theme","Is death of fathers, and who still hath cried,","From the first corse till he that died today,","'This must be so.' We pray you throw to earth","This unprevailing woe, and think of us","As of a father; for let the world take note","You are the most immediate to our throne,","And with no less nobility of love","Than that which dearest father bears his son","Do I impart toward you. For your intent","In going back to school in Wittenberg,","It is most retrograde to our desire:","And we beseech you bend you to remain","Here in the cheer and comfort of our eye,","Our chiefest courtier, cousin, and our son."],"id":90,"m":"It is sweet and admirable in your nature, Hamlet, to give your father these duties of mourning. But you must know that your father lost a father; that father lost his; and the son left behind was bound by duty to mourn for a while. But to carry on stubbornly grieving is a course of ungodly obstinacy. It is unmanly grief. It shows a will that rebels against heaven, a weak heart, an undisciplined mind, a simple, untrained understanding. Why should we, in childish resistance, take to heart something we know must happen, something as ordinary as the most common thing we see? Shame! It is an offence against heaven, an offence against the dead, an offence against nature and completely unreasonable, since reason's constant theme is the death of fathers, and it has always cried, from the first corpse to the man who died today, 'This is how it must be.' We beg you, throw away this useless grief, and think of us as a father. For let the world note that you are next in line to our throne, and that I offer you love no less noble than the dearest father feels for his son. As for your plan to go back to university in Wittenberg, it is completely against our wishes. We beg you to agree to stay here, where we can cheer and comfort you, as our leading courtier, our nephew and our son."},{"t":"sp","who":"GERTRUDE","lines":["Let not thy mother lose her prayers, Hamlet.","I pray thee stay with us; go not to Wittenberg."],"id":91,"m":"Don't let your mother's prayers go unanswered, Hamlet. Please, stay with us. Don't go to Wittenberg."},{"t":"sp","who":"HAMLET","lines":["I shall in all my best obey you, madam."],"id":92,"m":"I'll do my best to obey you, madam."},{"t":"sp","who":"CLAUDIUS","lines":["Why, 'tis a loving and a fair reply.","Be as ourself in Denmark. Madam, come;","This gentle and unforc'd accord of Hamlet","Sits smiling to my heart; in grace whereof,","No jocund health that Denmark drinks today","But the great cannon to the clouds shall tell,","And the King's rouse the heaven shall bruit again,","Re-speaking earthly thunder. Come away."],"id":93,"m":"Why, that's a loving and a proper answer. Be as free as I am in Denmark. Madam, come. Hamlet's gentle, willing agreement makes my heart smile. To celebrate it, every merry toast the King drinks today will be announced to the clouds by the great cannon, and the heavens will echo the King's drinking, repeating the earthly thunder. Come away."},{"t":"sd","text":"Exeunt all but Hamlet","id":94},{"t":"sp","who":"HAMLET","lines":["O that this too too solid flesh would melt,","Thaw, and resolve itself into a dew!","Or that the Everlasting had not fix'd","His canon 'gainst self-slaughter. O God! O God!","How weary, stale, flat, and unprofitable","Seem to me all the uses of this world!","Fie on't! Oh fie! 'tis an unweeded garden","That grows to seed; things rank and gross in nature","Possess it merely. That it should come to this!","But two months dead—nay, not so much, not two:","So excellent a king; that was to this","Hyperion to a satyr; so loving to my mother,","That he might not beteem the winds of heaven","Visit her face too roughly. Heaven and earth!","Must I remember? Why, she would hang on him","As if increase of appetite had grown","By what it fed on; and yet, within a month—","Let me not think on't—Frailty, thy name is woman!","A little month, or ere those shoes were old","With which she followed my poor father's body","Like Niobe, all tears.—Why she, even she—","O God! A beast that wants discourse of reason","Would have mourn'd longer,—married with mine uncle,","My father's brother; but no more like my father","Than I to Hercules. Within a month,","Ere yet the salt of most unrighteous tears","Had left the flushing in her galled eyes,","She married. O most wicked speed, to post","With such dexterity to incestuous sheets!","It is not, nor it cannot come to good.","But break, my heart, for I must hold my tongue."],"id":95,"m":"Oh, I wish this too, too solid flesh would melt, thaw and dissolve into dew! Or that God had not made his law against suicide! Oh God! God! How weary, stale, flat and pointless all the ways of this world seem to me! Damn it, damn it! It's an unweeded garden that is going to seed; rank and coarse things completely fill it. That it should come to this! Only two months dead, no, not even that, not two. Such an excellent king, compared to this one like the sun god to a goat-man. So loving to my mother that he wouldn't let the winds of heaven blow too roughly on her face. Heaven and earth! Must I remember? Why, she would cling to him as if her hunger grew by feeding on him. And yet, within a month, I won't think about it! Weakness, your name is woman! One little month, before the shoes she wore to follow my poor father's coffin were even old, weeping like Niobe, why she, even she, oh God, an animal with no power to reason would have mourned longer, married my uncle, my father's brother, but no more like my father than I am like Hercules. Within a month, before the salt of her false tears had stopped reddening her sore eyes, she married. Oh, wicked speed, to rush so nimbly into an incestuous bed! It is not good, and it can't come to any good. But break, my heart, because I must keep quiet."},{"t":"sd","text":"Enter Horatio, Marcellus and Barnardo.","id":96},{"t":"sp","who":"HORATIO","lines":["Hail to your lordship!"],"id":97,"m":"Greetings, my lord!"},{"t":"sp","who":"HAMLET","lines":["I am glad to see you well:","Horatio, or I do forget myself."],"id":98,"m":"I'm glad to see you well. Horatio, or I've forgotten who I am!"},{"t":"sp","who":"HORATIO","lines":["The same, my lord,","And your poor servant ever."],"id":99,"m":"The same, my lord, and always your humble servant."},{"t":"sp","who":"HAMLET","lines":["Sir, my good friend;","I'll change that name with you:","And what make you from Wittenberg, Horatio?—","Marcellus?"],"id":100,"m":"Sir, my good friend. I'll swap that name with you; we are friends, not master and servant. And what are you doing away from Wittenberg, Horatio? Marcellus?"},{"t":"sp","who":"MARCELLUS","lines":["My good lord."],"id":101,"m":"My good lord."},{"t":"sp","who":"HAMLET","lines":["I am very glad to see you.—Good even, sir.—","But what, in faith, make you from Wittenberg?"],"id":102,"m":"I'm very glad to see you. Good evening, sir. But really, why have you left Wittenberg?"},{"t":"sp","who":"HORATIO","lines":["A truant disposition, good my lord."],"id":103,"m":"Because I like skipping school, my good lord."},{"t":"sp","who":"HAMLET","lines":["I would not hear your enemy say so;","Nor shall you do my ear that violence,","To make it truster of your own report","Against yourself. I know you are no truant.","But what is your affair in Elsinore?","We'll teach you to drink deep ere you depart."],"id":104,"m":"I wouldn't let your enemy say that, and you won't hurt my ears by making them believe you when you speak against yourself. I know you're no truant. But what are you doing in Elsinore? We'll teach you to drink heavily before you leave."},{"t":"sp","who":"HORATIO","lines":["My lord, I came to see your father's funeral."],"id":105,"m":"My lord, I came to see your father's funeral."},{"t":"sp","who":"HAMLET","lines":["I prithee do not mock me, fellow-student.","I think it was to see my mother's wedding."],"id":106,"m":"Please don't mock me, fellow student. I think it was to see my mother's wedding."},{"t":"sp","who":"HORATIO","lines":["Indeed, my lord, it follow'd hard upon."],"id":107,"m":"It's true, my lord, it came soon after."},{"t":"sp","who":"HAMLET","lines":["Thrift, thrift, Horatio! The funeral bak'd meats","Did coldly furnish forth the marriage tables.","Would I had met my dearest foe in heaven","Or ever I had seen that day, Horatio.","My father,—methinks I see my father."],"id":108,"m":"It saved money, Horatio! The meat pies baked for the funeral were served cold at the wedding feast. I'd rather have met my worst enemy in heaven than have lived to see that day, Horatio. My father, I think I can see my father."},{"t":"sp","who":"HORATIO","lines":["Where, my lord?"],"id":109,"m":"Where, my lord?"},{"t":"sp","who":"HAMLET","lines":["In my mind's eye, Horatio."],"id":110,"m":"In my imagination, Horatio."},{"t":"sp","who":"HORATIO","lines":["I saw him once; he was a goodly king."],"id":111,"m":"I saw him once. He was a fine king."},{"t":"sp","who":"HAMLET","lines":["He was a man, take him for all in all,","I shall not look upon his like again."],"id":112,"m":"He was a man, take him for all he was. I'll never see anyone like him again."},{"t":"sp","who":"HORATIO","lines":["My lord, I think I saw him yesternight."],"id":113,"m":"My lord, I think I saw him last night."},{"t":"sp","who":"HAMLET","lines":["Saw? Who?"],"id":114,"m":"Saw? Who?"},{"t":"sp","who":"HORATIO","lines":["My lord, the King your father."],"id":115,"m":"My lord, the King your father."},{"t":"sp","who":"HAMLET","lines":["The King my father!"],"id":116,"m":"The King my father!"},{"t":"sp","who":"HORATIO","lines":["Season your admiration for a while","With an attent ear, till I may deliver","Upon the witness of these gentlemen","This marvel to you."],"id":117,"m":"Control your amazement for a moment and listen carefully, while I tell you this marvel, with these gentlemen as witnesses."},{"t":"sp","who":"HAMLET","lines":["For God's love let me hear."],"id":118,"m":"For God's sake, let me hear it."},{"t":"sp","who":"HORATIO","lines":["Two nights together had these gentlemen,","Marcellus and Barnardo, on their watch","In the dead waste and middle of the night,","Been thus encounter'd. A figure like your father,","Armed at point exactly, cap-à-pie,","Appears before them, and with solemn march","Goes slow and stately by them: thrice he walk'd","By their oppress'd and fear-surprised eyes,","Within his truncheon's length; whilst they, distill'd","Almost to jelly with the act of fear,","Stand dumb, and speak not to him. This to me","In dreadful secrecy impart they did,","And I with them the third night kept the watch,","Where, as they had deliver'd, both in time,","Form of the thing, each word made true and good,","The apparition comes. I knew your father;","These hands are not more like."],"id":119,"m":"For two nights in a row these gentlemen, Marcellus and Barnardo, on guard duty in the dead, empty middle of the night, met this. A figure like your father, armed exactly from head to foot, appears in front of them, and with a solemn march walks slowly and grandly past. Three times he walked past their frightened, astonished eyes, as close as the length of his staff, while they, almost melted to jelly with fear, stand silent and do not speak to him. They told me this in fearful secrecy, and on the third night I kept watch with them. And there, just as they had described it, at the same time and in the same shape, every word proved true, the ghost comes. I knew your father. These two hands are not more alike."},{"t":"sp","who":"HAMLET","lines":["But where was this?"],"id":120,"m":"But where was this?"},{"t":"sp","who":"MARCELLUS","lines":["My lord, upon the platform where we watch."],"id":121,"m":"My lord, on the battlements where we keep watch."},{"t":"sp","who":"HAMLET","lines":["Did you not speak to it?"],"id":122,"m":"Didn't you speak to it?"},{"t":"sp","who":"HORATIO","lines":["My lord, I did;","But answer made it none: yet once methought","It lifted up it head, and did address","Itself to motion, like as it would speak.","But even then the morning cock crew loud,","And at the sound it shrunk in haste away,","And vanish'd from our sight."],"id":123,"m":"My lord, I did, but it gave no answer. Yet once I thought it lifted its head and began to move as if it wanted to speak. But just then the morning cock crowed loudly, and at the sound it shrank hurriedly away and vanished from our sight."},{"t":"sp","who":"HAMLET","lines":["'Tis very strange."],"id":124,"m":"It's very strange."},{"t":"sp","who":"HORATIO","lines":["As I do live, my honour'd lord, 'tis true;","And we did think it writ down in our duty","To let you know of it."],"id":125,"m":"As sure as I'm alive, my honoured lord, it's true, and we thought it was our duty to let you know."},{"t":"sp","who":"HAMLET","lines":["Indeed, indeed, sirs, but this troubles me.","Hold you the watch tonight?"],"id":126,"m":"Yes, yes, sirs, but this troubles me. Are you on guard tonight?"},{"t":"sp","who":"MARCELLUS AND BARNARDO","lines":["We do, my lord."],"id":127,"m":"We are, my lord."},{"t":"sp","who":"HAMLET","lines":["Arm'd, say you?"],"id":128,"m":"Armed, you say?"},{"t":"sp","who":"BOTH","lines":["Arm'd, my lord."],"id":129,"m":"Armed, my lord."},{"t":"sp","who":"HAMLET","lines":["From top to toe?"],"id":130,"m":"From head to toe?"},{"t":"sp","who":"BOTH","lines":["My lord, from head to foot."],"id":131,"m":"My lord, from head to foot."},{"t":"sp","who":"HAMLET","lines":["Then saw you not his face?"],"id":132,"m":"Then you didn't see his face?"},{"t":"sp","who":"HORATIO","lines":["O yes, my lord, he wore his beaver up."],"id":133,"m":"Oh yes, my lord, he had the visor of his helmet raised."},{"t":"sp","who":"HAMLET","lines":["What, look'd he frowningly?"],"id":134,"m":"What, did he look angry?"},{"t":"sp","who":"HORATIO","lines":["A countenance more in sorrow than in anger."],"id":135,"m":"His face showed more sorrow than anger."},{"t":"sp","who":"HAMLET","lines":["Pale, or red?"],"id":136,"m":"Pale or flushed?"},{"t":"sp","who":"HORATIO","lines":["Nay, very pale."],"id":137,"m":"No, very pale."},{"t":"sp","who":"HAMLET","lines":["And fix'd his eyes upon you?"],"id":138,"m":"And he stared at you?"},{"t":"sp","who":"HORATIO","lines":["Most constantly."],"id":139,"m":"All the time."},{"t":"sp","who":"HAMLET","lines":["I would I had been there."],"id":140,"m":"I wish I'd been there."},{"t":"sp","who":"HORATIO","lines":["It would have much amaz'd you."],"id":141,"m":"It would have astonished you."},{"t":"sp","who":"HAMLET","lines":["Very like, very like. Stay'd it long?"],"id":142,"m":"Very likely, very likely. Did it stay long?"},{"t":"sp","who":"HORATIO","lines":["While one with moderate haste might tell a hundred."],"id":143,"m":"As long as it takes to count to a hundred at a steady pace."},{"t":"sp","who":"MARCELLUS AND BARNARDO","lines":["Longer, longer."],"id":144,"m":"Longer, longer."},{"t":"sp","who":"HORATIO","lines":["Not when I saw't."],"id":145,"m":"Not when I saw it."},{"t":"sp","who":"HAMLET","lines":["His beard was grizzled, no?"],"id":146,"m":"His beard was grey, wasn't it?"},{"t":"sp","who":"HORATIO","lines":["It was, as I have seen it in his life,","A sable silver'd."],"id":147,"m":"It was as I saw it when he was alive, black flecked with silver."},{"t":"sp","who":"HAMLET","lines":["I will watch tonight;","Perchance 'twill walk again."],"id":148,"m":"I'll keep watch tonight. Perhaps it will walk again."},{"t":"sp","who":"HORATIO","lines":["I warrant you it will."],"id":149,"m":"I promise you it will."},{"t":"sp","who":"HAMLET","lines":["If it assume my noble father's person,","I'll speak to it, though hell itself should gape","And bid me hold my peace. I pray you all,","If you have hitherto conceal'd this sight,","Let it be tenable in your silence still;","And whatsoever else shall hap tonight,","Give it an understanding, but no tongue.","I will requite your loves. So, fare ye well.","Upon the platform 'twixt eleven and twelve,","I'll visit you."],"id":150,"m":"If it takes my noble father's shape, I'll speak to it, even if hell itself opens its mouth and tells me to be quiet. I beg you all, if you've kept this sight secret until now, keep holding it in silence. And whatever else happens tonight, understand it but don't talk about it. I will repay your love. So, goodbye. I'll come to you on the battlements between eleven and twelve."},{"t":"sp","who":"ALL","lines":["Our duty to your honour."],"id":151,"m":"Our duty to your lordship."},{"t":"sp","who":"HAMLET","lines":["Your loves, as mine to you: farewell."],"id":152,"m":"Your love, as I give mine to you. Goodbye."},{"t":"sd","text":"Exeunt Horatio, Marcellus and Barnardo","id":153},{"t":"sp","who":"HAMLET","cont":1,"lines":["My father's spirit in arms! All is not well;","I doubt some foul play: would the night were come!","Till then sit still, my soul: foul deeds will rise,","Though all the earth o'erwhelm them, to men's eyes."],"id":154,"m":"My father's ghost in armour! All is not well. I suspect some foul play. I wish night had come! Until then, be calm, my soul. Foul deeds will come to light, even if the whole earth covers them, for men to see."},{"t":"sd","text":"Exit","id":155},{"t":"scene","act":1,"scene":"III","loc":"A room in Polonius's house.","id":156},{"t":"sd","text":"Enter Laertes and Ophelia.","id":157},{"t":"sp","who":"LAERTES","lines":["My necessaries are embark'd. Farewell.","And, sister, as the winds give benefit","And convoy is assistant, do not sleep,","But let me hear from you."],"id":158,"m":"My luggage is on board. Goodbye. And, sister, whenever the winds are good and a ship is going, don't be lazy; write to me."},{"t":"sp","who":"OPHELIA","lines":["Do you doubt that?"],"id":159,"m":"Do you doubt that I will?"},{"t":"sp","who":"LAERTES","lines":["For Hamlet, and the trifling of his favour,","Hold it a fashion and a toy in blood;","A violet in the youth of primy nature,","Forward, not permanent, sweet, not lasting;","The perfume and suppliance of a minute;","No more."],"id":160,"m":"As for Hamlet and his flirting attentions, think of them as a passing fashion, a whim of hot young blood, a violet in the spring of life: early, not permanent, sweet, not lasting, the scent and pastime of a minute. Nothing more."},{"t":"sp","who":"OPHELIA","lines":["No more but so?"],"id":161,"m":"Nothing more than that?"},{"t":"sp","who":"LAERTES","lines":["Think it no more.","For nature crescent does not grow alone","In thews and bulk; but as this temple waxes,","The inward service of the mind and soul","Grows wide withal. Perhaps he loves you now,","And now no soil nor cautel doth besmirch","The virtue of his will; but you must fear,","His greatness weigh'd, his will is not his own;","For he himself is subject to his birth:","He may not, as unvalu'd persons do,","Carve for himself; for on his choice depends","The sanctity and health of this whole state;","And therefore must his choice be circumscrib'd","Unto the voice and yielding of that body","Whereof he is the head. Then if he says he loves you,","It fits your wisdom so far to believe it","As he in his particular act and place","May give his saying deed; which is no further","Than the main voice of Denmark goes withal.","Then weigh what loss your honour may sustain","If with too credent ear you list his songs,","Or lose your heart, or your chaste treasure open","To his unmaster'd importunity.","Fear it, Ophelia, fear it, my dear sister;","And keep you in the rear of your affection,","Out of the shot and danger of desire.","The chariest maid is prodigal enough","If she unmask her beauty to the moon.","Virtue itself 'scapes not calumnious strokes:","The canker galls the infants of the spring","Too oft before their buttons be disclos'd,","And in the morn and liquid dew of youth","Contagious blastments are most imminent.","Be wary then, best safety lies in fear.","Youth to itself rebels, though none else near."],"id":162,"m":"Think of it as nothing more. When a person grows up, it isn't only muscles and size that grow; as the body, this temple, gets bigger, the mind and soul inside it grow too. Perhaps he loves you now, and no stain or deceit spoils his honest intentions. But you must be careful: considering his rank, his will is not his own, because he is bound by his birth. He can't choose for himself, as unimportant people do, because the safety and health of the whole country depend on his choice. So his choice must be limited by the agreement and approval of the nation he will lead. So if he says he loves you, you would be wise to believe it only as far as a man in his particular position can act on what he says, which is no further than the main body of Denmark agrees. Then think what damage your honour may suffer if you listen too trustingly to his love songs, or lose your heart, or open your chaste treasure to his uncontrolled pleading. Be afraid of it, Ophelia, be afraid of it, my dear sister. Keep back behind your feelings, out of range of the shots and dangers of desire. The most careful girl is reckless enough if she shows her beauty even to the moon. Virtue itself can't escape the blows of slander. The canker worm eats the young flowers of spring too often before their buds have opened, and in the dewy morning of youth, infection is most likely to strike. So be careful. The safest thing is fear. Youth rebels against itself even when no one else is near."},{"t":"sp","who":"OPHELIA","lines":["I shall th'effect of this good lesson keep","As watchman to my heart. But good my brother,","Do not as some ungracious pastors do,","Show me the steep and thorny way to heaven;","Whilst like a puff'd and reckless libertine","Himself the primrose path of dalliance treads,","And recks not his own rede."],"id":163,"m":"I'll keep the message of this good lesson as a guard over my heart. But, my good brother, don't be like some bad priests who show me the steep and thorny path to heaven, while they, like proud and reckless pleasure-seekers, walk the easy primrose path of pleasure and ignore their own advice."},{"t":"sp","who":"LAERTES","lines":["O, fear me not.","I stay too long. But here my father comes."],"id":164,"m":"Oh, don't worry about me. I've stayed too long. But here comes my father."},{"t":"sd","text":"Enter Polonius.","id":165},{"t":"sp","who":"LAERTES","cont":1,"lines":["A double blessing is a double grace;","Occasion smiles upon a second leave."],"id":166,"m":"Two blessings mean double grace. Luck has given me a chance to say goodbye twice."},{"t":"sp","who":"POLONIUS","lines":["Yet here, Laertes? Aboard, aboard, for shame.","The wind sits in the shoulder of your sail,","And you are stay'd for. There, my blessing with you."],"id":167,"m":"Still here, Laertes? On board, on board, for shame! The wind is filling your sails and they are waiting for you. There, take my blessing with you."},{"t":"sd","text":"Laying his hand on Laertes's head","id":168},{"t":"sp","who":"POLONIUS","cont":1,"lines":["And these few precepts in thy memory","Look thou character. Give thy thoughts no tongue,","Nor any unproportion'd thought his act.","Be thou familiar, but by no means vulgar.","Those friends thou hast, and their adoption tried,","Grapple them unto thy soul with hoops of steel;","But do not dull thy palm with entertainment","Of each new-hatch'd, unfledg'd comrade. Beware","Of entrance to a quarrel; but being in,","Bear't that th'opposed may beware of thee.","Give every man thine ear, but few thy voice:","Take each man's censure, but reserve thy judgement.","Costly thy habit as thy purse can buy,","But not express'd in fancy; rich, not gaudy:","For the apparel oft proclaims the man;","And they in France of the best rank and station","Are of a most select and generous chief in that.","Neither a borrower nor a lender be:","For loan oft loses both itself and friend;","And borrowing dulls the edge of husbandry.","This above all: to thine own self be true;","And it must follow, as the night the day,","Thou canst not then be false to any man.","Farewell: my blessing season this in thee."],"id":169,"m":"And make sure you write these few rules in your memory. Don't say what you are thinking, and don't act on any unwise thought. Be friendly, but not overfamiliar with everyone. Once you have friends and have tested them, hold them to your soul with hoops of steel, but don't wear out your hand shaking hands with every new, untried companion. Be careful not to get into a quarrel, but once you are in one, act so that your opponent learns to beware of you. Listen to everyone, but speak to few. Hear everyone's opinion, but keep your own judgement to yourself. Buy clothes as expensive as you can afford, but not showy; rich, not flashy, because clothes often show what a man is, and the French of the highest rank are especially choosy and refined in this. Don't be a borrower or a lender, because a loan often loses both the money and the friend, and borrowing blunts the habit of thrift. Above all: be true to yourself, and it must follow, as night follows day, that you can't then be false to anyone. Goodbye. May my blessing make this advice grow in you."},{"t":"sp","who":"LAERTES","lines":["Most humbly do I take my leave, my lord."],"id":170,"m":"Most humbly I say goodbye, my lord."},{"t":"sp","who":"POLONIUS","lines":["The time invites you; go, your servants tend."],"id":171,"m":"It's time to go. Your servants are waiting."},{"t":"sp","who":"LAERTES","lines":["Farewell, Ophelia, and remember well","What I have said to you."],"id":172,"m":"Goodbye, Ophelia, and remember what I've said to you."},{"t":"sp","who":"OPHELIA","lines":["'Tis in my memory lock'd,","And you yourself shall keep the key of it."],"id":173,"m":"It's locked in my memory, and you will keep the key yourself."},{"t":"sp","who":"LAERTES","lines":["Farewell."],"id":174,"m":"Goodbye."},{"t":"sd","text":"Exit","id":175},{"t":"sp","who":"POLONIUS","lines":["What is't, Ophelia, he hath said to you?"],"id":176,"m":"What has he been saying to you, Ophelia?"},{"t":"sp","who":"OPHELIA","lines":["So please you, something touching the Lord Hamlet."],"id":177,"m":"If you must know, something about Lord Hamlet."},{"t":"sp","who":"POLONIUS","lines":["Marry, well bethought:","'Tis told me he hath very oft of late","Given private time to you; and you yourself","Have of your audience been most free and bounteous.","If it be so,—as so 'tis put on me,","And that in way of caution,—I must tell you","You do not understand yourself so clearly","As it behoves my daughter and your honour.","What is between you? Give me up the truth."],"id":178,"m":"Indeed, that's a good thought. I've been told he has very often spent time alone with you lately, and that you have been very free and generous in letting him see you. If that is true, as I've been told by people warning me, I must tell you that you don't understand your position as clearly as my daughter should, for the sake of your honour. What is going on between you? Tell me the truth."},{"t":"sp","who":"OPHELIA","lines":["He hath, my lord, of late made many tenders","Of his affection to me."],"id":179,"m":"He has, my lord, recently made many offers of his love to me."},{"t":"sp","who":"POLONIUS","lines":["Affection! Pooh! You speak like a green girl,","Unsifted in such perilous circumstance.","Do you believe his tenders, as you call them?"],"id":180,"m":"Love! Pah! You talk like an inexperienced girl who knows nothing about such dangerous situations. Do you believe his 'offers', as you call them?"},{"t":"sp","who":"OPHELIA","lines":["I do not know, my lord, what I should think."],"id":181,"m":"I don't know, my lord, what I should think."},{"t":"sp","who":"POLONIUS","lines":["Marry, I'll teach you; think yourself a baby;","That you have ta'en these tenders for true pay,","Which are not sterling. Tender yourself more dearly;","Or,—not to crack the wind of the poor phrase,","Running it thus,—you'll tender me a fool."],"id":182,"m":"Well, I'll teach you. Think of yourself as a baby for taking these offers as real money when they are fake. Offer yourself at a higher price, or, not to run the poor word into the ground, you'll offer me a fool, and make me look like one."},{"t":"sp","who":"OPHELIA","lines":["My lord, he hath importun'd me with love","In honourable fashion."],"id":183,"m":"My lord, he has pressed his love on me in an honourable way."},{"t":"sp","who":"POLONIUS","lines":["Ay, fashion you may call it; go to, go to."],"id":184,"m":"Yes, 'way' is the word, a passing fashion. Come on, come on."},{"t":"sp","who":"OPHELIA","lines":["And hath given countenance to his speech, my lord,","With almost all the holy vows of heaven."],"id":185,"m":"And he has backed up his words, my lord, with almost every holy vow there is."},{"t":"sp","who":"POLONIUS","lines":["Ay, springes to catch woodcocks. I do know,","When the blood burns, how prodigal the soul","Lends the tongue vows: these blazes, daughter,","Giving more light than heat, extinct in both,","Even in their promise, as it is a-making,","You must not take for fire. From this time","Be something scanter of your maiden presence;","Set your entreatments at a higher rate","Than a command to parley. For Lord Hamlet,","Believe so much in him that he is young;","And with a larger tether may he walk","Than may be given you. In few, Ophelia,","Do not believe his vows; for they are brokers,","Not of that dye which their investments show,","But mere implorators of unholy suits,","Breathing like sanctified and pious bawds,","The better to beguile. This is for all:","I would not, in plain terms, from this time forth","Have you so slander any moment leisure","As to give words or talk with the Lord Hamlet.","Look to't, I charge you; come your ways."],"id":186,"m":"Yes, traps to catch stupid birds. I know how generously the soul supplies the tongue with vows when passion is burning. These flames, daughter, give more light than heat, and both die out even while the promise is being made. You must not take them for real fire. From now on, be a little more sparing with your company. Don't be so ready to talk just because he asks you to. As for Lord Hamlet, believe this much: he is young, and he can do more of what he likes than you can. In short, Ophelia, don't believe his vows. They are go-betweens, not what they appear to be, just pleaders for sinful requests, speaking like holy, religious pimps to trick you better. This is my final word: plainly, from now on, I don't want you to waste a single spare moment talking to Lord Hamlet. See to it, I order you. Come along."},{"t":"sp","who":"OPHELIA","lines":["I shall obey, my lord."],"id":187,"m":"I'll obey, my lord."},{"t":"sd","text":"Exeunt","id":188},{"t":"scene","act":1,"scene":"IV","loc":"The platform.","id":189},{"t":"sd","text":"Enter Hamlet, Horatio and Marcellus.","id":190},{"t":"sp","who":"HAMLET","lines":["The air bites shrewdly; it is very cold."],"id":191,"m":"The air bites sharply. It's very cold."},{"t":"sp","who":"HORATIO","lines":["It is a nipping and an eager air."],"id":192,"m":"It's a nipping, biting air."},{"t":"sp","who":"HAMLET","lines":["What hour now?"],"id":193,"m":"What time is it now?"},{"t":"sp","who":"HORATIO","lines":["I think it lacks of twelve."],"id":194,"m":"I think it's not quite twelve."},{"t":"sp","who":"MARCELLUS","lines":["No, it is struck."],"id":195,"m":"No, it has struck."},{"t":"sp","who":"HORATIO","lines":["Indeed? I heard it not. It then draws near the season","Wherein the spirit held his wont to walk."],"id":196,"m":"Really? I didn't hear it. Then it's nearly the time when the ghost usually walks."},{"t":"sd","text":"A flourish of trumpets, and ordnance shot off within","id":197},{"t":"sp","who":"HORATIO","cont":1,"lines":["What does this mean, my lord?"],"id":198,"m":"What does this mean, my lord?"},{"t":"sp","who":"HAMLET","lines":["The King doth wake tonight and takes his rouse,","Keeps wassail, and the swaggering upspring reels;","And as he drains his draughts of Rhenish down,","The kettle-drum and trumpet thus bray out","The triumph of his pledge."],"id":199,"m":"The King is staying up late tonight, drinking and partying, dancing wild, staggering dances. And as he drains his cups of German wine, the drums and trumpets blare out like this to celebrate each toast he downs."},{"t":"sp","who":"HORATIO","lines":["Is it a custom?"],"id":200,"m":"Is it a custom?"},{"t":"sp","who":"HAMLET","lines":["Ay marry is't;","And to my mind, though I am native here,","And to the manner born, it is a custom","More honour'd in the breach than the observance.","This heavy-headed revel east and west","Makes us traduc'd and tax'd of other nations:","They clepe us drunkards, and with swinish phrase","Soil our addition; and indeed it takes","From our achievements, though perform'd at height,","The pith and marrow of our attribute.","So oft it chances in particular men","That for some vicious mole of nature in them,","As in their birth, wherein they are not guilty,","Since nature cannot choose his origin,","By their o'ergrowth of some complexion,","Oft breaking down the pales and forts of reason;","Or by some habit, that too much o'erleavens","The form of plausive manners;—that these men,","Carrying, I say, the stamp of one defect,","Being Nature's livery or Fortune's star,—","His virtues else,—be they as pure as grace,","As infinite as man may undergo,","Shall in the general censure take corruption","From that particular fault. The dram of evil","Doth all the noble substance of a doubt","To his own scandal."],"id":201,"m":"Yes, it is. And to my mind, though I was born here and brought up in these ways, it's a custom it would be more honourable to break than to keep. This drunken partying makes us mocked and criticised by other nations, east and west. They call us drunkards and dirty our name by calling us pigs. And it does take away the heart and core of our reputation from our achievements, however great they are. It often happens the same way with individual men. Because of some natural flaw in them, perhaps from their birth, which isn't their fault, since nobody can choose where he comes from; or because one part of their temperament grows too strong and breaks down the fences and forts of reason; or because of some habit that spoils their good manners; these men, I say, who carry the mark of one defect, whether it came from nature or from bad luck, even if their other virtues are as pure as grace and as great as any man can have, will be thought corrupt by everyone because of that one fault. A tiny drop of evil can spoil all the noble substance and bring it into disgrace."},{"t":"sp","who":"HORATIO","lines":["Look, my lord, it comes!"],"id":202,"m":"Look, my lord, it's coming!"},{"t":"sd","text":"Enter Ghost.","id":203},{"t":"sp","who":"HAMLET","lines":["Angels and ministers of grace defend us!","Be thou a spirit of health or goblin damn'd,","Bring with thee airs from heaven or blasts from hell,","Be thy intents wicked or charitable,","Thou com'st in such a questionable shape","That I will speak to thee. I'll call thee Hamlet,","King, father, royal Dane. O, answer me!","Let me not burst in ignorance; but tell","Why thy canoniz'd bones, hearsed in death,","Have burst their cerements; why the sepulchre,","Wherein we saw thee quietly inurn'd,","Hath op'd his ponderous and marble jaws","To cast thee up again! What may this mean,","That thou, dead corse, again in complete steel,","Revisit'st thus the glimpses of the moon,","Making night hideous, and we fools of nature","So horridly to shake our disposition","With thoughts beyond the reaches of our souls?","Say, why is this? Wherefore? What should we do?"],"id":204,"m":"Angels and messengers of God, protect us! Whether you are a good spirit or a damned demon, whether you bring heavenly air or blasts from hell, whether your purpose is evil or kind, you come in such a shape that invites questions, so I will speak to you. I'll call you Hamlet, King, father, royal Dane. Oh, answer me! Don't let me burst with not knowing, but tell me why your holy bones, buried with full rites, have broken out of their burial clothes; why the tomb where we saw you quietly laid has opened its heavy marble jaws to throw you up again. What can it mean, that you, a dead body, in full armour again, come back to the moonlit world, making the night hideous, and making us, mere fools of nature, shake so horribly with thoughts beyond what our souls can reach? Say, why is this? Why? What should we do?"},{"t":"sd","text":"Ghost beckons Hamlet","id":205},{"t":"sp","who":"HORATIO","lines":["It beckons you to go away with it,","As if it some impartment did desire","To you alone."],"id":206,"m":"It's beckoning you to go away with it, as if it wanted to tell something to you alone."},{"t":"sp","who":"MARCELLUS","lines":["Look with what courteous action","It waves you to a more removed ground.","But do not go with it."],"id":207,"m":"Look how politely it waves you to a more private place. But don't go with it."},{"t":"sp","who":"HORATIO","lines":["No, by no means."],"id":208,"m":"No, certainly not."},{"t":"sp","who":"HAMLET","lines":["It will not speak; then will I follow it."],"id":209,"m":"It won't speak here, so I'll follow it."},{"t":"sp","who":"HORATIO","lines":["Do not, my lord."],"id":210,"m":"Don't, my lord."},{"t":"sp","who":"HAMLET","lines":["Why, what should be the fear?","I do not set my life at a pin's fee;","And for my soul, what can it do to that,","Being a thing immortal as itself?","It waves me forth again. I'll follow it."],"id":211,"m":"Why, what is there to fear? I don't value my life at the price of a pin. And as for my soul, what can it do to that, since it is immortal like the ghost itself? It's waving me on again. I'll follow it."},{"t":"sp","who":"HORATIO","lines":["What if it tempt you toward the flood, my lord,","Or to the dreadful summit of the cliff","That beetles o'er his base into the sea,","And there assume some other horrible form","Which might deprive your sovereignty of reason,","And draw you into madness? Think of it.","The very place puts toys of desperation,","Without more motive, into every brain","That looks so many fathoms to the sea","And hears it roar beneath."],"id":212,"m":"What if it tempts you toward the sea, my lord, or to the terrifying top of the cliff that hangs over its base into the sea, and there takes on some other horrible shape that might rob you of your reason and drive you mad? Think about it. The place itself, without any other reason, puts desperate thoughts into the head of anyone who looks down so far to the sea and hears it roaring below."},{"t":"sp","who":"HAMLET","lines":["It waves me still.","Go on, I'll follow thee."],"id":213,"m":"It's still waving to me. Go on, I'll follow you."},{"t":"sp","who":"MARCELLUS","lines":["You shall not go, my lord."],"id":214,"m":"You won't go, my lord."},{"t":"sp","who":"HAMLET","lines":["Hold off your hands."],"id":215,"m":"Take your hands off me."},{"t":"sp","who":"HORATIO","lines":["Be rul'd; you shall not go."],"id":216,"m":"Be sensible. You won't go."},{"t":"sp","who":"HAMLET","lines":["My fate cries out,","And makes each petty artery in this body","As hardy as the Nemean lion's nerve."],"id":217,"m":"My fate is calling, and it makes every tiny vein in my body as strong as the sinews of the Nemean lion that Hercules fought."},{"t":"sd","text":"Ghost beckons","id":218},{"t":"sp","who":"HAMLET","cont":1,"lines":["Still am I call'd. Unhand me, gentlemen."],"id":219,"m":"It's still calling me. Let go of me, gentlemen."},{"t":"sd","text":"Breaking free from them","id":220},{"t":"sp","who":"HAMLET","cont":1,"lines":["By heaven, I'll make a ghost of him that lets me.","I say, away!—Go on, I'll follow thee."],"id":221,"m":"By heaven, I'll make a ghost of anyone who stops me! I said get away! Go on, I'll follow you."},{"t":"sd","text":"Exeunt Ghost and Hamlet","id":222},{"t":"sp","who":"HORATIO","lines":["He waxes desperate with imagination."],"id":223,"m":"His imagination is making him desperate."},{"t":"sp","who":"MARCELLUS","lines":["Let's follow; 'tis not fit thus to obey him."],"id":224,"m":"Let's follow. It's not right to obey him in this."},{"t":"sp","who":"HORATIO","lines":["Have after. To what issue will this come?"],"id":225,"m":"Let's go after him. How will this end?"},{"t":"sp","who":"MARCELLUS","lines":["Something is rotten in the state of Denmark."],"id":226,"m":"Something is rotten in the state of Denmark."},{"t":"sp","who":"HORATIO","lines":["Heaven will direct it."],"id":227,"m":"Heaven will take care of it."},{"t":"sp","who":"MARCELLUS","lines":["Nay, let's follow him."],"id":228,"m":"No, let's follow him."},{"t":"sd","text":"Exeunt","id":229},{"t":"scene","act":1,"scene":"V","loc":"A more remote part of the Castle.","id":230},{"t":"sd","text":"Enter Ghost and Hamlet.","id":231},{"t":"sp","who":"HAMLET","lines":["Whither wilt thou lead me? Speak, I'll go no further."],"id":232,"m":"Where are you taking me? Speak. I won't go any further."},{"t":"sp","who":"GHOST","lines":["Mark me."],"id":233,"m":"Listen to me."},{"t":"sp","who":"HAMLET","lines":["I will."],"id":234,"m":"I will."},{"t":"sp","who":"GHOST","lines":["My hour is almost come,","When I to sulph'rous and tormenting flames","Must render up myself."],"id":235,"m":"It is almost time for me to give myself up again to the burning, tormenting flames."},{"t":"sp","who":"HAMLET","lines":["Alas, poor ghost!"],"id":236,"m":"Oh, poor ghost!"},{"t":"sp","who":"GHOST","lines":["Pity me not, but lend thy serious hearing","To what I shall unfold."],"id":237,"m":"Don't pity me, but listen seriously to what I am going to tell you."},{"t":"sp","who":"HAMLET","lines":["Speak, I am bound to hear."],"id":238,"m":"Speak. I am bound to listen."},{"t":"sp","who":"GHOST","lines":["So art thou to revenge, when thou shalt hear."],"id":239,"m":"And you will be bound to take revenge when you have heard."},{"t":"sp","who":"HAMLET","lines":["What?"],"id":240,"m":"What?"},{"t":"sp","who":"GHOST","lines":["I am thy father's spirit,","Doom'd for a certain term to walk the night,","And for the day confin'd to fast in fires,","Till the foul crimes done in my days of nature","Are burnt and purg'd away. But that I am forbid","To tell the secrets of my prison-house,","I could a tale unfold whose lightest word","Would harrow up thy soul; freeze thy young blood,","Make thy two eyes like stars start from their spheres,","Thy knotted and combined locks to part,","And each particular hair to stand on end","Like quills upon the fretful porpentine.","But this eternal blazon must not be","To ears of flesh and blood. List, list, O, list!","If thou didst ever thy dear father love—"],"id":241,"m":"I am your father's spirit, condemned for a fixed time to walk at night, and in the day shut away to starve in fire until the foul sins I committed while I was alive are burnt and cleansed away. If I were not forbidden to tell the secrets of my prison, I could tell a story whose lightest word would tear up your soul, freeze your young blood, make your eyes jump out of their sockets like shooting stars, part your neatly combed hair and make each separate hair stand on end like the quills of an angry porcupine. But this description of eternity must not be told to ears of flesh and blood. Listen, listen, oh, listen! If you ever loved your dear father—"},{"t":"sp","who":"HAMLET","lines":["O God!"],"id":242,"m":"Oh God!"},{"t":"sp","who":"GHOST","lines":["Revenge his foul and most unnatural murder."],"id":243,"m":"Avenge his foul and most unnatural murder."},{"t":"sp","who":"HAMLET","lines":["Murder!"],"id":244,"m":"Murder!"},{"t":"sp","who":"GHOST","lines":["Murder most foul, as in the best it is;","But this most foul, strange, and unnatural."],"id":245,"m":"Murder is always foul, even at best, but this was the foulest, strangest and most unnatural."},{"t":"sp","who":"HAMLET","lines":["Haste me to know't, that I, with wings as swift","As meditation or the thoughts of love","May sweep to my revenge."],"id":246,"m":"Hurry and tell me, so that with wings as quick as thought or the thoughts of love I can sweep to my revenge."},{"t":"sp","who":"GHOST","lines":["I find thee apt;","And duller shouldst thou be than the fat weed","That rots itself in ease on Lethe wharf,","Wouldst thou not stir in this. Now, Hamlet, hear.","'Tis given out that, sleeping in my orchard,","A serpent stung me; so the whole ear of Denmark","Is by a forged process of my death","Rankly abus'd; but know, thou noble youth,","The serpent that did sting thy father's life","Now wears his crown."],"id":247,"m":"I see you are ready. You'd be duller than the fat weed that lazily rots on the banks of Lethe, the river of forgetting, if this didn't stir you. Now, Hamlet, listen. It has been announced that a snake stung me while I was sleeping in my orchard, so all of Denmark has been grossly deceived by a false story of my death. But know this, noble young man: the snake that took your father's life now wears his crown."},{"t":"sp","who":"HAMLET","lines":["O my prophetic soul!","Mine uncle!"],"id":248,"m":"Oh, my soul guessed it! My uncle!"},{"t":"sp","who":"GHOST","lines":["Ay, that incestuous, that adulterate beast,","With witchcraft of his wit, with traitorous gifts,—","O wicked wit, and gifts, that have the power","So to seduce!—won to his shameful lust","The will of my most seeming-virtuous queen.","O Hamlet, what a falling off was there,","From me, whose love was of that dignity","That it went hand in hand even with the vow","I made to her in marriage; and to decline","Upon a wretch whose natural gifts were poor","To those of mine. But virtue, as it never will be mov'd,","Though lewdness court it in a shape of heaven;","So lust, though to a radiant angel link'd,","Will sate itself in a celestial bed","And prey on garbage.","But soft! methinks I scent the morning air;","Brief let me be. Sleeping within my orchard,","My custom always of the afternoon,","Upon my secure hour thy uncle stole","With juice of cursed hebenon in a vial,","And in the porches of my ears did pour","The leperous distilment, whose effect","Holds such an enmity with blood of man","That swift as quicksilver it courses through","The natural gates and alleys of the body;","And with a sudden vigour it doth posset","And curd, like eager droppings into milk,","The thin and wholesome blood. So did it mine;","And a most instant tetter bark'd about,","Most lazar-like, with vile and loathsome crust","All my smooth body.","Thus was I, sleeping, by a brother's hand,","Of life, of crown, of queen at once dispatch'd:","Cut off even in the blossoms of my sin,","Unhous'led, disappointed, unanel'd;","No reckoning made, but sent to my account","With all my imperfections on my head.","O horrible! O horrible! most horrible!","If thou hast nature in thee, bear it not;","Let not the royal bed of Denmark be","A couch for luxury and damned incest.","But howsoever thou pursu'st this act,","Taint not thy mind, nor let thy soul contrive","Against thy mother aught; leave her to heaven,","And to those thorns that in her bosom lodge,","To prick and sting her. Fare thee well at once!","The glow-worm shows the matin to be near,","And 'gins to pale his uneffectual fire.","Adieu, adieu, adieu. Remember me."],"id":249,"m":"Yes, that incestuous, adulterous beast. With his clever witchcraft and treacherous gifts, oh, wicked cleverness and gifts that have the power to seduce like that, he won over my queen, who seemed so virtuous, to his shameful lust. Oh, Hamlet, what a fall that was! From me, whose love was so honourable that it kept faithfully to the vow I made her at our wedding, down to a wretch whose natural gifts were poor compared to mine. But just as virtue will never be tempted, even if lust courts it disguised as an angel, so lust, even if it is joined to a shining angel, will get tired of a heavenly bed and feed on garbage. But wait! I think I can smell the morning air. Let me be quick. While I was sleeping in my orchard, as I always did in the afternoon, your uncle crept up on me in that unguarded hour with a bottle of the juice of cursed hebenon, and poured the poisonous liquid into the entrances of my ears. Its effect is so hostile to human blood that it runs as fast as mercury through the natural gates and passages of the body, and with sudden force it thickens and curdles the thin, healthy blood, like acid dropped into milk. That is what it did to mine. And at once a scaly rash covered my smooth body with a vile, disgusting crust like a leper's. So, while I slept, by my brother's hand I lost my life, my crown and my queen all at once. I was cut off with my sins in full bloom, without the last sacrament, unprepared, without the last rites, with no chance to settle my account, but sent to judgement with all my faults on my head. Oh, horrible! Horrible! Most horrible! If you have natural feeling in you, don't put up with it. Don't let the royal bed of Denmark be a bed for lust and damned incest. But however you carry out this act, don't corrupt your mind, and don't let your soul plot anything against your mother. Leave her to heaven, and to the thorns of conscience inside her to prick and sting her. Goodbye now! The glow-worm shows that morning is near, and its light is fading. Goodbye, goodbye, goodbye. Remember me."},{"t":"sd","text":"Exit","id":250},{"t":"sp","who":"HAMLET","lines":["O all you host of heaven! O earth! What else?","And shall I couple hell? O, fie! Hold, my heart;","And you, my sinews, grow not instant old,","But bear me stiffly up. Remember thee?","Ay, thou poor ghost, while memory holds a seat","In this distracted globe. Remember thee?","Yea, from the table of my memory","I'll wipe away all trivial fond records,","All saws of books, all forms, all pressures past,","That youth and observation copied there;","And thy commandment all alone shall live","Within the book and volume of my brain,","Unmix'd with baser matter. Yes, by heaven!","O most pernicious woman!","O villain, villain, smiling damned villain!","My tables. Meet it is I set it down,","That one may smile, and smile, and be a villain!","At least I am sure it may be so in Denmark."],"id":251,"m":"Oh, all you angels in heaven! Oh, earth! What else? Shall I call on hell too? Oh, no! Hold on, my heart, and you, my muscles, don't grow suddenly old, but hold me firmly up. Remember you? Yes, you poor ghost, as long as memory has a place in this confused head. Remember you? Yes, from the notebook of my memory I'll wipe out all trivial, foolish notes, all sayings from books, all images and impressions from the past that youth and observation copied there, and your command alone shall live in the book of my brain, not mixed with less important things. Yes, by heaven! Oh, most wicked woman! Oh, villain, villain, smiling, damned villain! My notebook. It's right that I write it down, that one may smile, and smile, and be a villain. At least I'm sure it can be so in Denmark."},{"t":"sd","text":"Writing","id":252},{"t":"sp","who":"HAMLET","cont":1,"lines":["So, uncle, there you are. Now to my word;","It is 'Adieu, adieu, remember me.'","I have sworn't."],"id":253,"m":"So, uncle, there you are. Now for my motto. It is 'Goodbye, goodbye, remember me.' I have sworn it."},{"t":"sp","who":"HORATIO AND MARCELLUS","lines":["[Within] My lord, my lord."],"id":254,"m":"[Within] My lord, my lord!"},{"t":"sp","who":"MARCELLUS","lines":["[Within] Lord Hamlet."],"id":255,"m":"[Within] Lord Hamlet!"},{"t":"sp","who":"HORATIO","lines":["[Within] Heaven secure him."],"id":256,"m":"[Within] Heaven keep him safe!"},{"t":"sp","who":"HAMLET","lines":["So be it!"],"id":257,"m":"So be it!"},{"t":"sp","who":"MARCELLUS","lines":["[Within] Illo, ho, ho, my lord!"],"id":258,"m":"[Within] Hello, ho, ho, my lord!"},{"t":"sp","who":"HAMLET","lines":["Hillo, ho, ho, boy! Come, bird, come."],"id":259,"m":"Hello, ho, ho, boy! Come, bird, come."},{"t":"sd","text":"Enter Horatio and Marcellus.","id":260},{"t":"sp","who":"MARCELLUS","lines":["How is't, my noble lord?"],"id":261,"m":"How are you, my noble lord?"},{"t":"sp","who":"HORATIO","lines":["What news, my lord?"],"id":262,"m":"What's the news, my lord?"},{"t":"sp","who":"HAMLET","lines":["O, wonderful!"],"id":263,"m":"Oh, wonderful!"},{"t":"sp","who":"HORATIO","lines":["Good my lord, tell it."],"id":264,"m":"My good lord, tell us."},{"t":"sp","who":"HAMLET","lines":["No, you'll reveal it."],"id":265,"m":"No, you'll give it away."},{"t":"sp","who":"HORATIO","lines":["Not I, my lord, by heaven."],"id":266,"m":"Not me, my lord, I swear by heaven."},{"t":"sp","who":"MARCELLUS","lines":["Nor I, my lord."],"id":267,"m":"Nor me, my lord."},{"t":"sp","who":"HAMLET","lines":["How say you then, would heart of man once think it?—","But you'll be secret?"],"id":268,"m":"What do you say, then? Would anyone ever have imagined it? But you'll keep it secret?"},{"t":"sp","who":"HORATIO AND MARCELLUS","lines":["Ay, by heaven, my lord."],"id":269,"m":"Yes, by heaven, my lord."},{"t":"sp","who":"HAMLET","lines":["There's ne'er a villain dwelling in all Denmark","But he's an arrant knave."],"id":270,"m":"There's not a villain living in all Denmark who isn't a complete scoundrel."},{"t":"sp","who":"HORATIO","lines":["There needs no ghost, my lord, come from the grave","To tell us this."],"id":271,"m":"We don't need a ghost to come from the grave to tell us that, my lord."},{"t":"sp","who":"HAMLET","lines":["Why, right; you are i' the right;","And so, without more circumstance at all,","I hold it fit that we shake hands and part:","You, as your business and desire shall point you,—","For every man hath business and desire,","Such as it is;—and for my own poor part,","Look you, I'll go pray."],"id":272,"m":"Why, right, you're right. And so, without any more fuss, I think it's best that we shake hands and part. You go wherever your business and wishes take you, since every man has business and wishes, whatever they are. And as for my own poor self, look, I'll go and pray."},{"t":"sp","who":"HORATIO","lines":["These are but wild and whirling words, my lord."],"id":273,"m":"These are wild, whirling words, my lord."},{"t":"sp","who":"HAMLET","lines":["I'm sorry they offend you, heartily;","Yes faith, heartily."],"id":274,"m":"I'm sorry they offend you, truly, yes, in faith, truly."},{"t":"sp","who":"HORATIO","lines":["There's no offence, my lord."],"id":275,"m":"There's no offence, my lord."},{"t":"sp","who":"HAMLET","lines":["Yes, by Saint Patrick, but there is, Horatio,","And much offence too. Touching this vision here,","It is an honest ghost, that let me tell you.","For your desire to know what is between us,","O'ermaster't as you may. And now, good friends,","As you are friends, scholars, and soldiers,","Give me one poor request."],"id":276,"m":"Yes, by Saint Patrick, there is, Horatio, and a great offence too. About this vision: it's an honest ghost, I can tell you that. As for your wish to know what passed between us, control it as best you can. And now, good friends, since you are friends, scholars and soldiers, grant me one small request."},{"t":"sp","who":"HORATIO","lines":["What is't, my lord? We will."],"id":277,"m":"What is it, my lord? We will."},{"t":"sp","who":"HAMLET","lines":["Never make known what you have seen tonight."],"id":278,"m":"Never tell anyone what you've seen tonight."},{"t":"sp","who":"HORATIO AND MARCELLUS","lines":["My lord, we will not."],"id":279,"m":"My lord, we won't."},{"t":"sp","who":"HAMLET","lines":["Nay, but swear't."],"id":280,"m":"No, swear it."},{"t":"sp","who":"HORATIO","lines":["In faith, my lord, not I."],"id":281,"m":"On my word, my lord, I won't."},{"t":"sp","who":"MARCELLUS","lines":["Nor I, my lord, in faith."],"id":282,"m":"Nor I, my lord, on my word."},{"t":"sp","who":"HAMLET","lines":["Upon my sword."],"id":283,"m":"On my sword."},{"t":"sp","who":"MARCELLUS","lines":["We have sworn, my lord, already."],"id":284,"m":"We've already sworn, my lord."},{"t":"sp","who":"HAMLET","lines":["Indeed, upon my sword, indeed."],"id":285,"m":"Yes, on my sword, really."},{"t":"sp","who":"GHOST","lines":["[Cries under the stage] Swear."],"id":286,"m":"[Cries under the stage] Swear."},{"t":"sp","who":"HAMLET","lines":["Ha, ha boy, sayst thou so? Art thou there, truepenny?","Come on, you hear this fellow in the cellarage.","Consent to swear."],"id":287,"m":"Ha, ha, boy, is that what you say? Are you there, old fellow? Come on, you hear this fellow down in the cellar. Agree to swear."},{"t":"sp","who":"HORATIO","lines":["Propose the oath, my lord."],"id":288,"m":"Tell us the oath, my lord."},{"t":"sp","who":"HAMLET","lines":["Never to speak of this that you have seen.","Swear by my sword."],"id":289,"m":"Never to speak of what you've seen. Swear by my sword."},{"t":"sp","who":"GHOST","lines":["[Beneath] Swear."],"id":290,"m":"[Beneath] Swear."},{"t":"sp","who":"HAMLET","lines":["Hic et ubique? Then we'll shift our ground.","Come hither, gentlemen,","And lay your hands again upon my sword.","Never to speak of this that you have heard.","Swear by my sword."],"id":291,"m":"Here and everywhere? Then we'll move. Come over here, gentlemen, and put your hands on my sword again. Never to speak of what you've heard. Swear by my sword."},{"t":"sp","who":"GHOST","lines":["[Beneath] Swear."],"id":292,"m":"[Beneath] Swear."},{"t":"sp","who":"HAMLET","lines":["Well said, old mole! Canst work i' th'earth so fast?","A worthy pioner! Once more remove, good friends."],"id":293,"m":"Well said, old mole! Can you dig through the earth so fast? A fine soldier-miner! Move once more, good friends."},{"t":"sp","who":"HORATIO","lines":["O day and night, but this is wondrous strange."],"id":294,"m":"By day and night, this is incredibly strange!"},{"t":"sp","who":"HAMLET","lines":["And therefore as a stranger give it welcome.","There are more things in heaven and earth, Horatio,","Than are dreamt of in your philosophy. But come,","Here, as before, never, so help you mercy,","How strange or odd soe'er I bear myself,—","As I perchance hereafter shall think meet","To put an antic disposition on—","That you, at such times seeing me, never shall,","With arms encumber'd thus, or this head-shake,","Or by pronouncing of some doubtful phrase,","As 'Well, we know', or 'We could and if we would',","Or 'If we list to speak'; or 'There be and if they might',","Or such ambiguous giving out, to note","That you know aught of me:—this not to do.","So grace and mercy at your most need help you,","Swear."],"id":295,"m":"Then welcome it as you would a stranger. There are more things in heaven and earth, Horatio, than your philosophy dreams of. But come. Swear, as before, as you hope for God's mercy, that however strange or odd I behave, since I may later think it right to act crazy, when you see me at those times you will never fold your arms like this, or shake your head like this, or say something mysterious like 'Well, we know', or 'We could if we wanted', or 'If we chose to speak', or 'There are some who could if they were allowed', or any such hint, to show that you know anything about me. Swear you won't do this, so may grace and mercy help you when you need it most."},{"t":"sp","who":"GHOST","lines":["[Beneath] Swear."],"id":296,"m":"[Beneath] Swear."},{"t":"sp","who":"HAMLET","lines":["Rest, rest, perturbed spirit. So, gentlemen,","With all my love I do commend me to you;","And what so poor a man as Hamlet is","May do t'express his love and friending to you,","God willing, shall not lack. Let us go in together,","And still your fingers on your lips, I pray.","The time is out of joint. O cursed spite,","That ever I was born to set it right.","Nay, come, let's go together."],"id":297,"m":"Rest, rest, troubled spirit! So, gentlemen, I give you all my love, and whatever a poor man like Hamlet can do to show his love and friendship, God willing, he will do. Let's go in together, and keep your fingers on your lips, I beg you. The times are out of joint. Oh, cursed bad luck that I was ever born to set them right! No, come on, let's go together."},{"t":"sd","text":"Exeunt","id":298},{"t":"scene","act":2,"scene":"I","loc":"A room in Polonius's house.","id":299},{"t":"sd","text":"Enter Polonius and Reynaldo.","id":300},{"t":"sp","who":"POLONIUS","lines":["Give him this money and these notes, Reynaldo."],"id":301,"m":"Give him this money and these letters, Reynaldo."},{"t":"sp","who":"REYNALDO","lines":["I will, my lord."],"id":302,"m":"I will, my lord."},{"t":"sp","who":"POLONIUS","lines":["You shall do marvellous wisely, good Reynaldo,","Before you visit him, to make inquiry","Of his behaviour."],"id":303,"m":"It would be very wise of you, good Reynaldo, to find out how he is behaving before you visit him."},{"t":"sp","who":"REYNALDO","lines":["My lord, I did intend it."],"id":304,"m":"My lord, I meant to."},{"t":"sp","who":"POLONIUS","lines":["Marry, well said; very well said. Look you, sir,","Enquire me first what Danskers are in Paris;","And how, and who, what means, and where they keep,","What company, at what expense; and finding","By this encompassment and drift of question,","That they do know my son, come you more nearer","Than your particular demands will touch it.","Take you as 'twere some distant knowledge of him,","As thus, 'I know his father and his friends,","And in part him'—do you mark this, Reynaldo?"],"id":305,"m":"Indeed, well said, very well said. Look, sir, first find out for me which Danes are in Paris, and how and who they are, what money they have, where they live, who they mix with and what they spend. And when you discover, by this roundabout way of asking, that they know my son, then get closer to the point than direct questions would. Pretend to know him a little, from a distance, like this: 'I know his father and his friends, and a bit of him.' Are you following this, Reynaldo?"},{"t":"sp","who":"REYNALDO","lines":["Ay, very well, my lord."],"id":306,"m":"Yes, very well, my lord."},{"t":"sp","who":"POLONIUS","lines":["'And in part him, but,' you may say, 'not well;","But if't be he I mean, he's very wild;","Addicted so and so;' and there put on him","What forgeries you please; marry, none so rank","As may dishonour him; take heed of that;","But, sir, such wanton, wild, and usual slips","As are companions noted and most known","To youth and liberty."],"id":307,"m":"'And a bit of him, but,' you might say, 'not well. But if it's the man I mean, he's very wild, given to this and that.' And then accuse him of whatever invented faults you like; but none so bad as to dishonour him, be careful of that. Just, sir, the sort of reckless, wild and usual slips that are well known to go with youth and freedom."},{"t":"sp","who":"REYNALDO","lines":["As gaming, my lord?"],"id":308,"m":"Like gambling, my lord?"},{"t":"sp","who":"POLONIUS","lines":["Ay, or drinking, fencing, swearing,","Quarrelling, drabbing. You may go so far."],"id":309,"m":"Yes, or drinking, fencing, swearing, quarrelling, whoring. You can go that far."},{"t":"sp","who":"REYNALDO","lines":["My lord, that would dishonour him."],"id":310,"m":"My lord, that would dishonour him."},{"t":"sp","who":"POLONIUS","lines":["Faith no, as you may season it in the charge.","You must not put another scandal on him,","That he is open to incontinency;","That's not my meaning: but breathe his faults so quaintly","That they may seem the taints of liberty;","The flash and outbreak of a fiery mind,","A savageness in unreclaimed blood,","Of general assault."],"id":311,"m":"No, really, not if you soften it as you make the charge. You mustn't add a different scandal, that he is given to unbridled lust; that's not what I mean. But hint at his faults so skilfully that they seem the flaws of freedom, the flash and outburst of a fiery mind, the wildness of untamed blood, the kind that happens to everyone."},{"t":"sp","who":"REYNALDO","lines":["But my good lord—"],"id":312,"m":"But, my good lord—"},{"t":"sp","who":"POLONIUS","lines":["Wherefore should you do this?"],"id":313,"m":"Why should you do this?"},{"t":"sp","who":"REYNALDO","lines":["Ay, my lord, I would know that."],"id":314,"m":"Yes, my lord, I'd like to know that."},{"t":"sp","who":"POLONIUS","lines":["Marry, sir, here's my drift,","And I believe it is a fetch of warrant.","You laying these slight sullies on my son,","As 'twere a thing a little soil'd i' th' working,","Mark you,","Your party in converse, him you would sound,","Having ever seen in the prenominate crimes","The youth you breathe of guilty, be assur'd","He closes with you in this consequence;","'Good sir,' or so; or 'friend,' or 'gentleman'—","According to the phrase or the addition","Of man and country."],"id":315,"m":"Well, sir, here is my plan, and I believe it's a trick that works. When you put these slight stains on my son, as if he were something a little soiled in the making, listen to me: the man you are talking to, the one you want to sound out, if he has ever seen the young man you mention committing those faults, you can be sure he will agree with you like this: 'Good sir', or something like it, or 'friend', or 'gentleman', depending on how people speak and address each other in that country."},{"t":"sp","who":"REYNALDO","lines":["Very good, my lord."],"id":316,"m":"Very good, my lord."},{"t":"sp","who":"POLONIUS","lines":["And then, sir, does he this,—","He does—What was I about to say?","By the mass, I was about to say something. Where did I leave?"],"id":317,"m":"And then, sir, he does this, he does... what was I going to say? By the Mass, I was about to say something. Where did I stop?"},{"t":"sp","who":"REYNALDO","lines":["At 'closes in the consequence.'","At 'friend or so,' and 'gentleman.'"],"id":318,"m":"At 'will agree with you like this'. At 'friend, or something like it', and 'gentleman'."},{"t":"sp","who":"POLONIUS","lines":["At 'closes in the consequence' ay, marry!","He closes with you thus: 'I know the gentleman,","I saw him yesterday, or t'other day,","Or then, or then, with such and such; and, as you say,","There was he gaming, there o'ertook in's rouse,","There falling out at tennis': or perchance,","'I saw him enter such a house of sale'—","Videlicet, a brothel, or so forth. See you now;","Your bait of falsehood takes this carp of truth;","And thus do we of wisdom and of reach,","With windlasses, and with assays of bias,","By indirections find directions out.","So by my former lecture and advice","Shall you my son. You have me, have you not?"],"id":319,"m":"At 'will agree with you', yes, indeed! He'll agree with you like this: 'I know the gentleman. I saw him yesterday, or the other day, or then, or then, with so-and-so, and, as you say, he was gambling there, there he was drunk, there quarrelling over tennis.' Or perhaps, 'I saw him go into a house of business', that is, a brothel, and so on. You see now: your bait of lies catches this fish of truth. And that's how we wise and far-sighted men, by roundabout ways and indirect approaches, find out the direct truth. So, by my lecture and advice, you'll find out about my son. You understand me, don't you?"},{"t":"sp","who":"REYNALDO","lines":["My lord, I have."],"id":320,"m":"My lord, I do."},{"t":"sp","who":"POLONIUS","lines":["God b' wi' you, fare you well."],"id":321,"m":"God be with you. Goodbye."},{"t":"sp","who":"REYNALDO","lines":["Good my lord."],"id":322,"m":"My good lord."},{"t":"sp","who":"POLONIUS","lines":["Observe his inclination in yourself."],"id":323,"m":"Watch his behaviour for yourself."},{"t":"sp","who":"REYNALDO","lines":["I shall, my lord."],"id":324,"m":"I will, my lord."},{"t":"sp","who":"POLONIUS","lines":["And let him ply his music."],"id":325,"m":"And let him get on with his music."},{"t":"sp","who":"REYNALDO","lines":["Well, my lord."],"id":326,"m":"Very well, my lord."},{"t":"sp","who":"POLONIUS","lines":["Farewell."],"id":327,"m":"Goodbye."},{"t":"sd","text":"Exit Reynaldo","id":328},{"t":"sd","text":"Enter Ophelia.","id":329},{"t":"sp","who":"POLONIUS","cont":1,"lines":["How now, Ophelia, what's the matter?"],"id":330,"m":"What's this, Ophelia? What's the matter?"},{"t":"sp","who":"OPHELIA","lines":["Alas, my lord, I have been so affrighted."],"id":331,"m":"Oh, my lord, I've been so frightened!"},{"t":"sp","who":"POLONIUS","lines":["With what, in the name of God?"],"id":332,"m":"By what, in God's name?"},{"t":"sp","who":"OPHELIA","lines":["My lord, as I was sewing in my chamber,","Lord Hamlet, with his doublet all unbrac'd,","No hat upon his head, his stockings foul'd,","Ungart'red, and down-gyved to his ankle,","Pale as his shirt, his knees knocking each other,","And with a look so piteous in purport","As if he had been loosed out of hell","To speak of horrors, he comes before me."],"id":333,"m":"My lord, as I was sewing in my room, Lord Hamlet came in front of me with his jacket all unfastened, no hat on his head, his stockings dirty, with no garters, and fallen down round his ankles like chains, as pale as his shirt, his knees knocking together, and with a look as pitiful as if he had been let out of hell to tell of horrors."},{"t":"sp","who":"POLONIUS","lines":["Mad for thy love?"],"id":334,"m":"Mad with love for you?"},{"t":"sp","who":"OPHELIA","lines":["My lord, I do not know, but truly I do fear it."],"id":335,"m":"My lord, I don't know, but I'm truly afraid so."},{"t":"sp","who":"POLONIUS","lines":["What said he?"],"id":336,"m":"What did he say?"},{"t":"sp","who":"OPHELIA","lines":["He took me by the wrist and held me hard;","Then goes he to the length of all his arm;","And with his other hand thus o'er his brow,","He falls to such perusal of my face","As he would draw it. Long stay'd he so,","At last,—a little shaking of mine arm,","And thrice his head thus waving up and down,","He rais'd a sigh so piteous and profound","As it did seem to shatter all his bulk","And end his being. That done, he lets me go,","And with his head over his shoulder turn'd","He seem'd to find his way without his eyes,","For out o' doors he went without their help,","And to the last bended their light on me."],"id":337,"m":"He took me by the wrist and held me tight. Then he moved back the whole length of his arm, and with his other hand over his forehead like this, he started studying my face as if he were going to draw it. He stayed like that a long time. At last, shaking my arm a little and nodding his head up and down three times like this, he gave a sigh so pitiful and deep that it seemed to shatter his whole body and end his life. After that, he let me go, and with his head turned over his shoulder, he seemed to find his way without his eyes, because he went out of the door without their help, and kept them fixed on me to the end."},{"t":"sp","who":"POLONIUS","lines":["Come, go with me. I will go seek the King.","This is the very ecstasy of love,","Whose violent property fordoes itself,","And leads the will to desperate undertakings,","As oft as any passion under heaven","That does afflict our natures. I am sorry,—","What, have you given him any hard words of late?"],"id":338,"m":"Come, come with me. I'll go and find the King. This is the very madness of love, which by its violent nature destroys itself and drives people to desperate actions as often as any passion under heaven that afflicts us. I'm sorry. What, have you said anything harsh to him recently?"},{"t":"sp","who":"OPHELIA","lines":["No, my good lord; but as you did command,","I did repel his letters and denied","His access to me."],"id":339,"m":"No, my good lord, but as you ordered, I sent back his letters and refused to see him."},{"t":"sp","who":"POLONIUS","lines":["That hath made him mad.","I am sorry that with better heed and judgement","I had not quoted him. I fear'd he did but trifle,","And meant to wreck thee. But beshrew my jealousy!","It seems it is as proper to our age","To cast beyond ourselves in our opinions","As it is common for the younger sort","To lack discretion. Come, go we to the King.","This must be known, which, being kept close, might move","More grief to hide than hate to utter love."],"id":340,"m":"That has made him mad. I'm sorry I didn't watch him with more care and judgement. I was afraid he was only playing with you and meant to ruin you. Curse my suspicion! It seems old men are as likely to go too far in our opinions as young people are to lack good sense. Come, let's go to the King. He must know about this. Keeping it secret might cause more grief than the anger we'll cause by revealing this love."},{"t":"sd","text":"Exeunt","id":341},{"t":"scene","act":2,"scene":"II","loc":"A room in the Castle.","id":342},{"t":"sd","text":"Enter King, Queen, Rosencrantz, Guildenstern and Attendants.","id":343},{"t":"sp","who":"CLAUDIUS","lines":["Welcome, dear Rosencrantz and Guildenstern.","Moreover that we much did long to see you,","The need we have to use you did provoke","Our hasty sending. Something have you heard","Of Hamlet's transformation; so I call it,","Since nor th'exterior nor the inward man","Resembles that it was. What it should be,","More than his father's death, that thus hath put him","So much from th'understanding of himself,","I cannot dream of. I entreat you both","That, being of so young days brought up with him,","And since so neighbour'd to his youth and humour,","That you vouchsafe your rest here in our court","Some little time, so by your companies","To draw him on to pleasures and to gather,","So much as from occasion you may glean,","Whether aught to us unknown afflicts him thus","That, open'd, lies within our remedy."],"id":344,"m":"Welcome, dear Rosencrantz and Guildenstern. Besides wanting very much to see you, we sent for you in a hurry because we need your help. You have heard something about Hamlet's transformation; I call it that because neither his outward appearance nor his inner self is like it was. What it can be, other than his father's death, that has put him so far out of his right mind, I can't imagine. I beg you both, since you were brought up with him from childhood and know his youth and temperament so well, to agree to stay here at our court for a little while, so that your company may draw him into some pleasures, and to find out, from whatever chances you get, whether something we don't know about is troubling him, which, once revealed, we could cure."},{"t":"sp","who":"GERTRUDE","lines":["Good gentlemen, he hath much talk'd of you,","And sure I am, two men there are not living","To whom he more adheres. If it will please you","To show us so much gentry and good will","As to expend your time with us awhile,","For the supply and profit of our hope,","Your visitation shall receive such thanks","As fits a king's remembrance."],"id":345,"m":"Good gentlemen, he has talked about you a lot, and I'm sure there are no two men alive he is more attached to. If you will be kind and generous enough to spend some time with us, to help and further our hopes, your visit will be rewarded with the thanks a king remembers."},{"t":"sp","who":"ROSENCRANTZ","lines":["Both your majesties","Might, by the sovereign power you have of us,","Put your dread pleasures more into command","Than to entreaty."],"id":346,"m":"Your majesties both have royal power over us, and could give your wishes to us as orders rather than requests."},{"t":"sp","who":"GUILDENSTERN","lines":["We both obey,","And here give up ourselves, in the full bent,","To lay our service freely at your feet","To be commanded."],"id":347,"m":"We both obey, and offer ourselves completely, to lay our service freely at your feet, ready for your commands."},{"t":"sp","who":"CLAUDIUS","lines":["Thanks, Rosencrantz and gentle Guildenstern."],"id":348,"m":"Thank you, Rosencrantz and gentle Guildenstern."},{"t":"sp","who":"GERTRUDE","lines":["Thanks, Guildenstern and gentle Rosencrantz.","And I beseech you instantly to visit","My too much changed son. Go, some of you,","And bring these gentlemen where Hamlet is."],"id":349,"m":"Thank you, Guildenstern and gentle Rosencrantz. And I beg you to visit my son, who has changed so much, at once. Some of you, go and take these gentlemen to Hamlet."},{"t":"sp","who":"GUILDENSTERN","lines":["Heavens make our presence and our practices","Pleasant and helpful to him."],"id":350,"m":"May heaven make our presence and our actions pleasant and helpful to him!"},{"t":"sp","who":"GERTRUDE","lines":["Ay, amen."],"id":351,"m":"Yes, amen."},{"t":"sd","text":"Exeunt Rosencrantz, Guildenstern and some Attendants","id":352},{"t":"sd","text":"Enter Polonius.","id":353},{"t":"sp","who":"POLONIUS","lines":["Th'ambassadors from Norway, my good lord,","Are joyfully return'd."],"id":354,"m":"The ambassadors from Norway, my good lord, have returned with good news."},{"t":"sp","who":"CLAUDIUS","lines":["Thou still hast been the father of good news."],"id":355,"m":"You have always been the father of good news."},{"t":"sp","who":"POLONIUS","lines":["Have I, my lord? Assure you, my good liege,","I hold my duty, as I hold my soul,","Both to my God and to my gracious King:","And I do think,—or else this brain of mine","Hunts not the trail of policy so sure","As it hath us'd to do—that I have found","The very cause of Hamlet's lunacy."],"id":356,"m":"Have I, my lord? I assure you, my good King, I keep my duty, as I keep my soul, both to my God and to my gracious King. And I think, unless this brain of mine doesn't follow the trail of political cunning as surely as it used to, that I have found the real cause of Hamlet's madness."},{"t":"sp","who":"CLAUDIUS","lines":["O speak of that, that do I long to hear."],"id":357,"m":"Oh, speak about that! That's what I long to hear."},{"t":"sp","who":"POLONIUS","lines":["Give first admittance to th'ambassadors;","My news shall be the fruit to that great feast."],"id":358,"m":"Receive the ambassadors first. My news will be the dessert after that great feast."},{"t":"sp","who":"CLAUDIUS","lines":["Thyself do grace to them, and bring them in."],"id":359,"m":"You do them the honour yourself, and bring them in."},{"t":"sd","text":"Exit Polonius","id":360},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["He tells me, my sweet queen, that he hath found","The head and source of all your son's distemper."],"id":361,"m":"He tells me, my sweet queen, that he has found the root and cause of all your son's illness."},{"t":"sp","who":"GERTRUDE","lines":["I doubt it is no other but the main,","His father's death and our o'erhasty marriage."],"id":362,"m":"I suspect it is nothing other than the main thing, his father's death and our too hasty marriage."},{"t":"sp","who":"CLAUDIUS","lines":["Well, we shall sift him."],"id":363,"m":"Well, we'll question him closely."},{"t":"sd","text":"Enter Polonius with Voltemand and Cornelius.","id":364},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["Welcome, my good friends!","Say, Voltemand, what from our brother Norway?"],"id":365,"m":"Welcome, my good friends! Tell me, Voltemand, what news from our brother the King of Norway?"},{"t":"sp","who":"VOLTEMAND","lines":["Most fair return of greetings and desires.","Upon our first, he sent out to suppress","His nephew's levies, which to him appear'd","To be a preparation 'gainst the Polack;","But better look'd into, he truly found","It was against your Highness; whereat griev'd,","That so his sickness, age, and impotence","Was falsely borne in hand, sends out arrests","On Fortinbras; which he, in brief, obeys,","Receives rebuke from Norway; and in fine,","Makes vow before his uncle never more","To give th'assay of arms against your Majesty.","Whereon old Norway, overcome with joy,","Gives him three thousand crowns in annual fee,","And his commission to employ those soldiers","So levied as before, against the Polack:","With an entreaty, herein further shown,","[Gives a paper]","That it might please you to give quiet pass","Through your dominions for this enterprise,","On such regards of safety and allowance","As therein are set down."],"id":366,"m":"He returns your greetings and good wishes most kindly. As soon as we raised the matter, he sent orders to stop his nephew's recruiting, which he had thought was preparation for a war against the Poles. But when he looked into it, he found it was really against your Highness. He was upset that his sickness, age and weakness had been taken advantage of, so he sent orders to arrest Fortinbras. In short, Fortinbras obeys, is told off by the King of Norway, and finally swears before his uncle never again to take up arms against your Majesty. At this, old Norway, overjoyed, gives him an income of three thousand crowns a year and permission to use the soldiers he raised against the Poles, with a request, set out here [Gives a paper], that you would allow them to pass peacefully through your lands for this expedition, on the terms of safety and permission written down in it."},{"t":"sp","who":"CLAUDIUS","lines":["It likes us well;","And at our more consider'd time we'll read,","Answer, and think upon this business.","Meantime we thank you for your well-took labour.","Go to your rest, at night we'll feast together:.","Most welcome home."],"id":367,"m":"We are pleased with this. When we have more time to think, we'll read it, reply and consider this business. Meanwhile, we thank you for your successful work. Go and rest. Tonight we'll feast together. Welcome home!"},{"t":"sd","text":"Exeunt Voltemand and Cornelius","id":368},{"t":"sp","who":"POLONIUS","lines":["This business is well ended.","My liege and madam, to expostulate","What majesty should be, what duty is,","Why day is day, night night, and time is time","Were nothing but to waste night, day and time.","Therefore, since brevity is the soul of wit,","And tediousness the limbs and outward flourishes,","I will be brief. Your noble son is mad.","Mad call I it; for to define true madness,","What is't but to be nothing else but mad?","But let that go."],"id":369,"m":"This business has ended well. My King and madam, to discuss what majesty should be, what duty is, why day is day, night is night, and time is time, would only waste night, day and time. So, since keeping it short is the heart of wisdom, and long-windedness is just its limbs and outward decoration, I will be brief. Your noble son is mad. I call it mad, because what is true madness except being nothing else but mad? But let that go."},{"t":"sp","who":"GERTRUDE","lines":["More matter, with less art."],"id":370,"m":"More substance, with less fancy talk."},{"t":"sp","who":"POLONIUS","lines":["Madam, I swear I use no art at all.","That he is mad, 'tis true: 'tis true 'tis pity;","And pity 'tis 'tis true. A foolish figure,","But farewell it, for I will use no art.","Mad let us grant him then. And now remains","That we find out the cause of this effect,","Or rather say, the cause of this defect,","For this effect defective comes by cause.","Thus it remains, and the remainder thus. Perpend,","I have a daughter—have whilst she is mine—","Who in her duty and obedience, mark,","Hath given me this. Now gather, and surmise.","[Reads]","To the celestial, and my soul's idol, the most beautified Ophelia—","That's an ill phrase, a vile phrase; 'beautified' is a vile","phrase: but you shall hear.","[Reads]","these; in her excellent white bosom, these, &c."],"id":371,"m":"Madam, I swear I'm not using any fancy talk at all. That he is mad is true; it's true it's a pity; and it's a pity it's true. A foolish figure of speech, but goodbye to it, because I won't use any art. Let's agree he is mad, then. Now what remains is to find the cause of this effect, or rather the cause of this defect, because this defective effect has a cause. That's what remains, and here's the rest. Consider this. I have a daughter, have her while she's still mine, who, out of duty and obedience, mark you, has given me this. Now listen and draw your conclusions. [Reads] 'To the heavenly one, my soul's idol, the most beautified Ophelia.' That's a bad phrase, a vile phrase; 'beautified' is a vile phrase. But you'll hear. [Reads] 'These, to her excellent white breast, these...' and so on."},{"t":"sp","who":"GERTRUDE","lines":["Came this from Hamlet to her?"],"id":372,"m":"Did this come from Hamlet to her?"},{"t":"sp","who":"POLONIUS","lines":["Good madam, stay awhile; I will be faithful.","[Reads]","Doubt thou the stars are fire,","Doubt that the sun doth move,","Doubt truth to be a liar,","But never doubt I love.","O dear Ophelia, I am ill at these numbers. I have not art to reckon my","groans. But that I love thee best, O most best, believe it. Adieu.","Thine evermore, most dear lady, whilst this machine is to him,","HAMLET.","This in obedience hath my daughter show'd me;","And more above, hath his solicitings,","As they fell out by time, by means, and place,","All given to mine ear."],"id":373,"m":"Good madam, wait a moment. I'll read it all faithfully. [Reads] 'Doubt that the stars are fire, doubt that the sun moves, doubt that truth is truth, but never doubt that I love. Oh, dear Ophelia, I'm bad at writing verse. I don't have the skill to count out my groans in rhyme. But that I love you best, oh, very best, believe it. Goodbye. Yours forever, dearest lady, while this body belongs to him, Hamlet.' My daughter, out of obedience, has shown me this, and besides that she has told me about all his advances, when, how and where they happened."},{"t":"sp","who":"CLAUDIUS","lines":["But how hath she receiv'd his love?"],"id":374,"m":"But how has she received his love?"},{"t":"sp","who":"POLONIUS","lines":["What do you think of me?"],"id":375,"m":"What do you think of me?"},{"t":"sp","who":"CLAUDIUS","lines":["As of a man faithful and honourable."],"id":376,"m":"That you are a faithful and honourable man."},{"t":"sp","who":"POLONIUS","lines":["I would fain prove so. But what might you think,","When I had seen this hot love on the wing,","As I perceiv'd it, I must tell you that,","Before my daughter told me, what might you,","Or my dear Majesty your queen here, think,","If I had play'd the desk or table-book,","Or given my heart a winking, mute and dumb,","Or look'd upon this love with idle sight,","What might you think? No, I went round to work,","And my young mistress thus I did bespeak:","'Lord Hamlet is a prince, out of thy star.","This must not be.' And then I precepts gave her,","That she should lock herself from his resort,","Admit no messengers, receive no tokens.","Which done, she took the fruits of my advice,","And he, repulsed,—a short tale to make—","Fell into a sadness, then into a fast,","Thence to a watch, thence into a weakness,","Thence to a lightness, and, by this declension,","Into the madness wherein now he raves,","And all we wail for."],"id":377,"m":"I'd like to prove that I am. But what would you have thought, when I saw this passionate love taking flight, and I noticed it, I must tell you, before my daughter told me, what would you, or my dear Majesty your queen here, have thought, if I had kept it to myself like a desk or notebook, or made my heart shut its eyes and stay silent, or looked on this love without seeing it? What would you have thought? No, I got straight to work, and spoke to my young lady like this: 'Lord Hamlet is a prince, out of your sphere. This must not happen.' And then I gave her orders to lock herself away from his visits, to see no messengers and accept no gifts. She did as I advised, and he, rejected, to make a long story short, became sad, then stopped eating, then couldn't sleep, then grew weak, then light-headed, and, sinking step by step like this, fell into the madness he now raves in, and that we all grieve over."},{"t":"sp","who":"CLAUDIUS","lines":["Do you think 'tis this?"],"id":378,"m":"Do you think this is the cause?"},{"t":"sp","who":"GERTRUDE","lines":["It may be, very likely."],"id":379,"m":"It may be, very possibly."},{"t":"sp","who":"POLONIUS","lines":["Hath there been such a time, I'd fain know that,","That I have positively said ''Tis so,'","When it prov'd otherwise?"],"id":380,"m":"Has there ever been a time, I'd like to know, when I have said for certain 'It is so', and it turned out otherwise?"},{"t":"sp","who":"CLAUDIUS","lines":["Not that I know."],"id":381,"m":"Not that I know of."},{"t":"sp","who":"POLONIUS","lines":["Take this from this, if this be otherwise.","[Points to his head and shoulder]","If circumstances lead me, I will find","Where truth is hid, though it were hid indeed","Within the centre."],"id":382,"m":"Cut this off from this if I am wrong. [Points to his head and shoulder] If the evidence leads me, I'll find where the truth is hidden, even if it were hidden at the centre of the earth."},{"t":"sp","who":"CLAUDIUS","lines":["How may we try it further?"],"id":383,"m":"How can we test this further?"},{"t":"sp","who":"POLONIUS","lines":["You know sometimes he walks four hours together","Here in the lobby."],"id":384,"m":"You know that sometimes he walks for four hours at a time here in the hall."},{"t":"sp","who":"GERTRUDE","lines":["So he does indeed."],"id":385,"m":"Yes, he does."},{"t":"sp","who":"POLONIUS","lines":["At such a time I'll loose my daughter to him.","Be you and I behind an arras then,","Mark the encounter. If he love her not,","And be not from his reason fall'n thereon,","Let me be no assistant for a state,","But keep a farm and carters."],"id":386,"m":"At a time like that I'll let my daughter loose on him. You and I will hide behind a curtain then and watch what happens. If he doesn't love her, and hasn't lost his mind because of it, then let me give up being a royal adviser and run a farm with carters instead."},{"t":"sp","who":"CLAUDIUS","lines":["We will try it."],"id":387,"m":"We'll try it."},{"t":"sd","text":"Enter Hamlet, reading.","id":388},{"t":"sp","who":"GERTRUDE","lines":["But look where sadly the poor wretch comes reading."],"id":389,"m":"But look how sadly the poor wretch is coming, reading."},{"t":"sp","who":"POLONIUS","lines":["Away, I do beseech you, both away","I'll board him presently. O, give me leave."],"id":390,"m":"Go, I beg you, both of you go. I'll approach him at once. Oh, please leave me."},{"t":"sd","text":"Exeunt King, Queen and Attendants","id":391},{"t":"sp","who":"POLONIUS","cont":1,"lines":["How does my good Lord Hamlet?"],"id":392,"m":"How is my good Lord Hamlet?"},{"t":"sp","who":"HAMLET","lines":["Well, God-a-mercy."],"id":393,"m":"Well, thank you."},{"t":"sp","who":"POLONIUS","lines":["Do you know me, my lord?"],"id":394,"m":"Do you know me, my lord?"},{"t":"sp","who":"HAMLET","lines":["Excellent well. You are a fishmonger."],"id":395,"m":"Very well. You're a fishmonger."},{"t":"sp","who":"POLONIUS","lines":["Not I, my lord."],"id":396,"m":"Not me, my lord."},{"t":"sp","who":"HAMLET","lines":["Then I would you were so honest a man."],"id":397,"m":"Then I wish you were as honest as a fishmonger."},{"t":"sp","who":"POLONIUS","lines":["Honest, my lord?"],"id":398,"m":"Honest, my lord?"},{"t":"sp","who":"HAMLET","lines":["Ay sir, to be honest, as this world goes, is to be one man picked out","of ten thousand."],"id":399,"m":"Yes, sir. To be honest, the way the world is now, is to be one man picked out of ten thousand."},{"t":"sp","who":"POLONIUS","lines":["That's very true, my lord."],"id":400,"m":"That's very true, my lord."},{"t":"sp","who":"HAMLET","lines":["For if the sun breed maggots in a dead dog, being a good kissing","carrion,—","Have you a daughter?"],"id":401,"m":"For if the sun breeds maggots in a dead dog, a lovely bit of flesh for it to kiss... Do you have a daughter?"},{"t":"sp","who":"POLONIUS","lines":["I have, my lord."],"id":402,"m":"I have, my lord."},{"t":"sp","who":"HAMLET","lines":["Let her not walk i' th' sun. Conception is a blessing, but not as your","daughter may conceive. Friend, look to't."],"id":403,"m":"Don't let her walk in the sun. Understanding is a blessing, but not the way your daughter might conceive. Friend, watch out."},{"t":"sp","who":"POLONIUS","lines":["How say you by that? [Aside] Still harping on my daughter. Yet he","knew me not at first; he said I was a fishmonger. He is far gone, far","gone. And truly in my youth I suffered much extremity for love; very","near this. I'll speak to him again.—What do you read, my lord?"],"id":404,"m":"What do you mean by that? [Aside] Still going on about my daughter. And yet he didn't know me at first; he said I was a fishmonger. He's far gone, far gone. And honestly, when I was young I suffered terribly for love, very like this. I'll speak to him again. What are you reading, my lord?"},{"t":"sp","who":"HAMLET","lines":["Words, words, words."],"id":405,"m":"Words, words, words."},{"t":"sp","who":"POLONIUS","lines":["What is the matter, my lord?"],"id":406,"m":"What is the matter, my lord?"},{"t":"sp","who":"HAMLET","lines":["Between who?"],"id":407,"m":"Between who?"},{"t":"sp","who":"POLONIUS","lines":["I mean the matter that you read, my lord."],"id":408,"m":"I mean what is the matter in what you are reading, my lord."},{"t":"sp","who":"HAMLET","lines":["Slanders, sir. For the satirical slave says here that old men have grey","beards; that their faces are wrinkled; their eyes purging thick amber","and plum-tree gum; and that they have a plentiful lack of wit, together","with most weak hams. All which, sir, though I most powerfully and","potently believe, yet I hold it not honesty to have it thus set down.","For you yourself, sir, should be old as I am, if like a crab you could","go backward."],"id":409,"m":"Slanders, sir. This mocking rascal says here that old men have grey beards, that their faces are wrinkled, that their eyes ooze thick yellow sap like plum-tree gum, and that they have a great lack of brains, along with very weak thighs. All of which, sir, though I believe it completely and absolutely, I don't think it's decent to have it written down like this. Because you yourself, sir, would be as old as I am, if you could go backwards like a crab."},{"t":"sp","who":"POLONIUS","lines":["[Aside] Though this be madness, yet there is method in't.—","Will you walk out of the air, my lord?"],"id":410,"m":"[Aside] Though this is madness, there's a method in it. Will you walk out of the open air, my lord?"},{"t":"sp","who":"HAMLET","lines":["Into my grave?"],"id":411,"m":"Into my grave?"},{"t":"sp","who":"POLONIUS","lines":["Indeed, that is out o' the air. [Aside] How pregnant sometimes his","replies are! A happiness that often madness hits on, which reason and","sanity could not so prosperously be delivered of. I will leave him and","suddenly contrive the means of meeting between him and my daughter.","My honourable lord, I will most humbly take my leave of you."],"id":412,"m":"Well, that's out of the air, certainly. [Aside] How full of meaning his answers sometimes are! Madness often hits on a lucky phrase that reason and sanity could not produce so well. I'll leave him and quickly arrange a meeting between him and my daughter. My honourable lord, I'll most humbly take my leave of you."},{"t":"sp","who":"HAMLET","lines":["You cannot, sir, take from me anything that I will more willingly part","withal, except my life, except my life, except my life."],"id":413,"m":"You can't take anything from me, sir, that I'd more willingly give up, except my life, except my life, except my life."},{"t":"sp","who":"POLONIUS","lines":["Fare you well, my lord."],"id":414,"m":"Goodbye, my lord."},{"t":"sp","who":"HAMLET","lines":["These tedious old fools."],"id":415,"m":"These boring old fools!"},{"t":"sd","text":"Enter Rosencrantz and Guildenstern.","id":416},{"t":"sp","who":"POLONIUS","lines":["You go to seek the Lord Hamlet; there he is."],"id":417,"m":"You're looking for Lord Hamlet; there he is."},{"t":"sp","who":"ROSENCRANTZ","lines":["[To Polonius] God save you, sir."],"id":418,"m":"[To Polonius] God keep you, sir."},{"t":"sd","text":"Exit Polonius","id":419},{"t":"sp","who":"GUILDENSTERN","lines":["My honoured lord!"],"id":420,"m":"My honoured lord!"},{"t":"sp","who":"ROSENCRANTZ","lines":["My most dear lord!"],"id":421,"m":"My dearest lord!"},{"t":"sp","who":"HAMLET","lines":["My excellent good friends! How dost thou, Guildenstern? Ah,","Rosencrantz. Good lads, how do ye both?"],"id":422,"m":"My excellent good friends! How are you, Guildenstern? Ah, Rosencrantz! Good lads, how are you both?"},{"t":"sp","who":"ROSENCRANTZ","lines":["As the indifferent children of the earth."],"id":423,"m":"Like ordinary people, neither good nor bad."},{"t":"sp","who":"GUILDENSTERN","lines":["Happy in that we are not over-happy;","On Fortune's cap we are not the very button."],"id":424,"m":"Happy in not being too happy. We're not the button on top of Lady Fortune's cap."},{"t":"sp","who":"HAMLET","lines":["Nor the soles of her shoe?"],"id":425,"m":"Nor the soles of her shoes?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Neither, my lord."],"id":426,"m":"Neither, my lord."},{"t":"sp","who":"HAMLET","lines":["Then you live about her waist, or in the middle of her favours?"],"id":427,"m":"Then you live around her waist, in the middle of her favours?"},{"t":"sp","who":"GUILDENSTERN","lines":["Faith, her privates we."],"id":428,"m":"Well, we're her private parts."},{"t":"sp","who":"HAMLET","lines":["In the secret parts of Fortune? O, most true; she is a strumpet. What's","the news?"],"id":429,"m":"In Fortune's private parts? Oh, very true, she is a whore. What's the news?"},{"t":"sp","who":"ROSENCRANTZ","lines":["None, my lord, but that the world's grown honest."],"id":430,"m":"None, my lord, except that the world has become honest."},{"t":"sp","who":"HAMLET","lines":["Then is doomsday near. But your news is not true. Let me question more","in particular. What have you, my good friends, deserved at the hands of","Fortune, that she sends you to prison hither?"],"id":431,"m":"Then the Day of Judgement is near. But your news isn't true. Let me ask you more specifically. What have you done, my good friends, to deserve being sent by Fortune to prison here?"},{"t":"sp","who":"GUILDENSTERN","lines":["Prison, my lord?"],"id":432,"m":"Prison, my lord?"},{"t":"sp","who":"HAMLET","lines":["Denmark's a prison."],"id":433,"m":"Denmark's a prison."},{"t":"sp","who":"ROSENCRANTZ","lines":["Then is the world one."],"id":434,"m":"Then the whole world is one."},{"t":"sp","who":"HAMLET","lines":["A goodly one; in which there are many confines, wards, and dungeons,","Denmark being one o' th' worst."],"id":435,"m":"A fine one, with many cells, wards and dungeons, and Denmark is one of the worst."},{"t":"sp","who":"ROSENCRANTZ","lines":["We think not so, my lord."],"id":436,"m":"We don't think so, my lord."},{"t":"sp","who":"HAMLET","lines":["Why, then 'tis none to you; for there is nothing either good or bad but","thinking makes it so. To me it is a prison."],"id":437,"m":"Why, then it isn't one for you, because nothing is good or bad, only thinking makes it so. To me it is a prison."},{"t":"sp","who":"ROSENCRANTZ","lines":["Why, then your ambition makes it one; 'tis too narrow for your mind."],"id":438,"m":"Why, then your ambition makes it one. It's too small for your mind."},{"t":"sp","who":"HAMLET","lines":["O God, I could be bounded in a nutshell, and count myself a king of","infinite space, were it not that I have bad dreams."],"id":439,"m":"Oh God, I could be shut up in a nutshell and think myself a king of endless space, if it weren't for my bad dreams."},{"t":"sp","who":"GUILDENSTERN","lines":["Which dreams, indeed, are ambition; for the very substance of the","ambitious is merely the shadow of a dream."],"id":440,"m":"And those dreams are really ambition, because what the ambitious man is made of is only the shadow of a dream."},{"t":"sp","who":"HAMLET","lines":["A dream itself is but a shadow."],"id":441,"m":"A dream itself is only a shadow."},{"t":"sp","who":"ROSENCRANTZ","lines":["Truly, and I hold ambition of so airy and light a quality that it is","but a shadow's shadow."],"id":442,"m":"True, and I think ambition is so airy and light that it is only a shadow's shadow."},{"t":"sp","who":"HAMLET","lines":["Then are our beggars bodies, and our monarchs and outstretch'd heroes","the beggars' shadows. Shall we to th' court? For, by my fay, I cannot","reason."],"id":443,"m":"Then beggars are the only real bodies, and our kings and swollen heroes are the beggars' shadows. Shall we go to the court? Because, on my faith, I can't argue any more."},{"t":"sp","who":"ROSENCRANTZ AND GUILDENSTERN","lines":["We'll wait upon you."],"id":444,"m":"We'll go with you and serve you."},{"t":"sp","who":"HAMLET","lines":["No such matter. I will not sort you with the rest of my servants; for,","to speak to you like an honest man, I am most dreadfully attended. But,","in the beaten way of friendship, what make you at Elsinore?"],"id":445,"m":"Nothing of the sort. I won't class you with the rest of my servants, because, to tell you honestly, I'm dreadfully waited on. But, as old friends to old friends, what are you doing in Elsinore?"},{"t":"sp","who":"ROSENCRANTZ","lines":["To visit you, my lord, no other occasion."],"id":446,"m":"Visiting you, my lord, no other reason."},{"t":"sp","who":"HAMLET","lines":["Beggar that I am, I am even poor in thanks; but I thank you. And sure,","dear friends, my thanks are too dear a halfpenny. Were you not sent","for? Is it your own inclining? Is it a free visitation? Come, deal","justly with me. Come, come; nay, speak."],"id":447,"m":"Beggar that I am, I'm even poor in thanks, but I thank you. And really, dear friends, my thanks are overpriced at a halfpenny. Weren't you sent for? Is it your own idea? Is it a free visit? Come, be honest with me. Come on, come on. No, speak."},{"t":"sp","who":"GUILDENSTERN","lines":["What should we say, my lord?"],"id":448,"m":"What should we say, my lord?"},{"t":"sp","who":"HAMLET","lines":["Why, anything. But to the purpose. You were sent for; and there is a","kind of confession in your looks, which your modesties have not craft","enough to colour. I know the good King and Queen have sent for you."],"id":449,"m":"Why, anything, as long as it's to the point. You were sent for, and there's a kind of confession in your faces that you're too decent to disguise. I know the good King and Queen have sent for you."},{"t":"sp","who":"ROSENCRANTZ","lines":["To what end, my lord?"],"id":450,"m":"For what purpose, my lord?"},{"t":"sp","who":"HAMLET","lines":["That you must teach me. But let me conjure you, by the rights of our","fellowship, by the consonancy of our youth, by the obligation of our","ever-preserved love, and by what more dear a better proposer could","charge you withal, be even and direct with me, whether you were sent","for or no."],"id":451,"m":"That's what you must tell me. But let me beg you, by the rights of our friendship, by the harmony of our youth, by the duty of our long-lasting love, and by anything more precious that a better speaker could use to persuade you, be straight and direct with me: were you sent for or not?"},{"t":"sp","who":"ROSENCRANTZ","lines":["[To Guildenstern] What say you?"],"id":452,"m":"[To Guildenstern] What do you say?"},{"t":"sp","who":"HAMLET","lines":["[Aside] Nay, then I have an eye of you. If you love me, hold not","off."],"id":453,"m":"[Aside] No, I've got my eye on you. If you love me, don't hold back."},{"t":"sp","who":"GUILDENSTERN","lines":["My lord, we were sent for."],"id":454,"m":"My lord, we were sent for."},{"t":"sp","who":"HAMLET","lines":["I will tell you why; so shall my anticipation prevent your discovery,","and your secrecy to the King and Queen moult no feather. I have of","late, but wherefore I know not, lost all my mirth, forgone all custom","of exercises; and indeed, it goes so heavily with my disposition that","this goodly frame the earth, seems to me a sterile promontory; this","most excellent canopy the air, look you, this brave o'erhanging","firmament, this majestical roof fretted with golden fire, why, it","appears no other thing to me than a foul and pestilent congregation of","vapours. What a piece of work is man, how noble in reason, how infinite","in faculties, in form and moving, how express and admirable; in action","how like an angel, in apprehension, how like a god: the beauty of the","world, the paragon of animals. And yet, to me, what is this","quintessence of dust? Man delights not me; no, nor woman neither,","though by your smiling you seem to say so."],"id":455,"m":"I'll tell you why, and then I'll have said it before you have to reveal it, and your promise of secrecy to the King and Queen won't lose a single feather. Lately, though I don't know why, I have lost all my cheerfulness and given up all my usual exercise. And it weighs so heavily on my mind that this fine structure, the earth, seems to me a barren rock sticking out into the sea. This most excellent canopy, the air, look, this splendid overhanging sky, this majestic roof decorated with golden fire, why, it seems to me nothing more than a foul, diseased mass of vapours. What a masterpiece man is! How noble in his reason, how unlimited in his powers, in his shape and movement how precise and admirable, in action how like an angel, in understanding how like a god! The beauty of the world, the finest of animals! And yet, to me, what is this essence of dust? Man doesn't delight me. No, nor woman either, though your smiling seems to say so."},{"t":"sp","who":"ROSENCRANTZ","lines":["My lord, there was no such stuff in my thoughts."],"id":456,"m":"My lord, there was nothing like that in my thoughts."},{"t":"sp","who":"HAMLET","lines":["Why did you laugh then, when I said 'Man delights not me'?"],"id":457,"m":"Then why did you laugh when I said 'Man doesn't delight me'?"},{"t":"sp","who":"ROSENCRANTZ","lines":["To think, my lord, if you delight not in man, what Lenten entertainment","the players shall receive from you. We coted them on the way, and","hither are they coming to offer you service."],"id":458,"m":"I was thinking, my lord, that if you don't delight in man, what a poor, meagre welcome the actors will get from you. We overtook them on the way, and they are coming here to offer you their services."},{"t":"sp","who":"HAMLET","lines":["He that plays the king shall be welcome,—his Majesty shall have tribute","of me; the adventurous knight shall use his foil and target; the lover","shall not sigh gratis, the humorous man shall end his part in peace;","the clown shall make those laugh whose lungs are tickle o' th' sere;","and the lady shall say her mind freely, or the blank verse shall halt","for't. What players are they?"],"id":459,"m":"The one who plays the king will be welcome; his majesty will get payment from me. The adventurous knight can use his sword and shield, the lover won't sigh for nothing, the moody character can finish his part in peace, the clown will make those laugh whose lungs are easily tickled, and the lady will speak her mind freely, or the verse will limp because of it. Which actors are they?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Even those you were wont to take such delight in—the tragedians of the","city."],"id":460,"m":"The very ones you used to enjoy so much, the tragic actors of the city."},{"t":"sp","who":"HAMLET","lines":["How chances it they travel? Their residence, both in reputation and","profit, was better both ways."],"id":461,"m":"Why are they on tour? Staying at home was better for them, both for their reputation and their earnings."},{"t":"sp","who":"ROSENCRANTZ","lines":["I think their inhibition comes by the means of the late innovation."],"id":462,"m":"I think they've been stopped from playing there because of the recent new fashion."},{"t":"sp","who":"HAMLET","lines":["Do they hold the same estimation they did when I was in the city? Are","they so followed?"],"id":463,"m":"Are they as well thought of as when I was in the city? Do they have such big audiences?"},{"t":"sp","who":"ROSENCRANTZ","lines":["No, indeed, they are not."],"id":464,"m":"No, they don't."},{"t":"sp","who":"HAMLET","lines":["How comes it? Do they grow rusty?"],"id":465,"m":"Why is that? Are they getting rusty?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Nay, their endeavour keeps in the wonted pace; but there is, sir, an","aerie of children, little eyases, that cry out on the top of question,","and are most tyrannically clapped for't. These are now the fashion, and","so berattle the common stages—so they call them—that many wearing","rapiers are afraid of goose-quills and dare scarce come thither."],"id":466,"m":"No, they work as hard as they always did. But there is, sir, a nest of children, little baby hawks, who shout out their lines at the top of their voices and are wildly applauded for it. They are the fashion now, and they so attack the common theatres, as they call them, that many gentlemen who wear swords are afraid of the playwrights' pens and hardly dare go there."},{"t":"sp","who":"HAMLET","lines":["What, are they children? Who maintains 'em? How are they escoted? Will","they pursue the quality no longer than they can sing? Will they not say","afterwards, if they should grow themselves to common players—as it is","most like, if their means are no better—their writers do them wrong to","make them exclaim against their own succession?"],"id":467,"m":"What, they are children? Who keeps them? How are they paid? Will they stop acting when their voices break? Won't they say later, if they grow up to be common actors themselves, as is very likely if they have no better way to earn a living, that their writers did them wrong by making them attack their own future profession?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Faith, there has been much to do on both sides; and the nation holds it","no sin to tarre them to controversy. There was for a while, no money","bid for argument unless the poet and the player went to cuffs in the","question."],"id":468,"m":"Honestly, there's been a lot of fuss on both sides, and people think it's no sin to egg them on to fight. For a while no one would pay for a play unless the writer and the actors came to blows over this quarrel in it."},{"t":"sp","who":"HAMLET","lines":["Is't possible?"],"id":469,"m":"Is that possible?"},{"t":"sp","who":"GUILDENSTERN","lines":["O, there has been much throwing about of brains."],"id":470,"m":"Oh, there's been a lot of brain-bashing."},{"t":"sp","who":"HAMLET","lines":["Do the boys carry it away?"],"id":471,"m":"Are the boys winning?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Ay, that they do, my lord. Hercules and his load too."],"id":472,"m":"Yes, they are, my lord, Hercules and the world he carries too."},{"t":"sp","who":"HAMLET","lines":["It is not very strange; for my uncle is King of Denmark, and those that","would make mouths at him while my father lived, give twenty, forty,","fifty, a hundred ducats apiece for his picture in little. 'Sblood,","there is something in this more than natural, if philosophy could find","it out."],"id":473,"m":"It isn't very strange, since my uncle is King of Denmark, and those who would pull faces at him while my father was alive now pay twenty, forty, fifty, a hundred gold coins each for a miniature portrait of him. By God's blood, there's something unnatural in this, if philosophy could find it out."},{"t":"sd","text":"Flourish of trumpets within","id":474},{"t":"sp","who":"GUILDENSTERN","lines":["There are the players."],"id":475,"m":"There are the actors."},{"t":"sp","who":"HAMLET","lines":["Gentlemen, you are welcome to Elsinore. Your hands, come. The","appurtenance of welcome is fashion and ceremony. Let me comply with you","in this garb, lest my extent to the players, which I tell you must show","fairly outward, should more appear like entertainment than yours. You","are welcome. But my uncle-father and aunt-mother are deceived."],"id":476,"m":"Gentlemen, you're welcome to Elsinore. Give me your hands, come. Ceremony and good manners go with a welcome. Let me greet you properly like this, or my welcome to the actors, which I tell you must look generous, might seem warmer than yours. You're welcome. But my uncle-father and aunt-mother are mistaken."},{"t":"sp","who":"GUILDENSTERN","lines":["In what, my dear lord?"],"id":477,"m":"About what, my dear lord?"},{"t":"sp","who":"HAMLET","lines":["I am but mad north-north-west. When the wind is southerly, I know a","hawk from a handsaw."],"id":478,"m":"I'm only mad when the wind blows from the north-north-west. When the wind is from the south, I can tell a hawk from a heron."},{"t":"sd","text":"Enter Polonius.","id":479},{"t":"sp","who":"POLONIUS","lines":["Well be with you, gentlemen."],"id":480,"m":"Good day to you, gentlemen."},{"t":"sp","who":"HAMLET","lines":["Hark you, Guildenstern, and you too, at each ear a hearer. That great","baby you see there is not yet out of his swaddling clouts."],"id":481,"m":"Listen, Guildenstern, and you too, a listener at each ear. That big baby you see there isn't out of his nappies yet."},{"t":"sp","who":"ROSENCRANTZ","lines":["Happily he's the second time come to them; for they say an old man is","twice a child."],"id":482,"m":"Perhaps he's gone back into them for the second time, because they say an old man is a child twice."},{"t":"sp","who":"HAMLET","lines":["I will prophesy he comes to tell me of the players. Mark it.—You say","right, sir: for a Monday morning 'twas so indeed."],"id":483,"m":"I predict he's come to tell me about the actors. Watch. You're right, sir, it was on Monday morning, that's right."},{"t":"sp","who":"POLONIUS","lines":["My lord, I have news to tell you."],"id":484,"m":"My lord, I have news to tell you."},{"t":"sp","who":"HAMLET","lines":["My lord, I have news to tell you. When Roscius was an actor in Rome—"],"id":485,"m":"My lord, I have news to tell you. When Roscius was an actor in Rome—"},{"t":"sp","who":"POLONIUS","lines":["The actors are come hither, my lord."],"id":486,"m":"The actors have come here, my lord."},{"t":"sp","who":"HAMLET","lines":["Buzz, buzz."],"id":487,"m":"Buzz, buzz! Old news."},{"t":"sp","who":"POLONIUS","lines":["Upon my honour."],"id":488,"m":"On my honour."},{"t":"sp","who":"HAMLET","lines":["Then came each actor on his ass—"],"id":489,"m":"Then came each actor on his donkey—"},{"t":"sp","who":"POLONIUS","lines":["The best actors in the world, either for tragedy, comedy, history,","pastoral, pastoral-comical, historical-pastoral, tragical-historical,","tragical-comical-historical-pastoral, scene individable, or poem","unlimited. Seneca cannot be too heavy, nor Plautus too light, for the","law of writ and the liberty. These are the only men."],"id":490,"m":"The best actors in the world, whether for tragedy, comedy, history, pastoral, pastoral-comedy, historical-pastoral, tragical-historical, tragical-comical-historical-pastoral, plays that keep the classical rules or plays that ignore them. They can't make Seneca too heavy or Plautus too light. For plays written by the rules or freely, these are the only men."},{"t":"sp","who":"HAMLET","lines":["O Jephthah, judge of Israel, what a treasure hadst thou!"],"id":491,"m":"Oh, Jephthah, judge of Israel, what a treasure you had!"},{"t":"sp","who":"POLONIUS","lines":["What treasure had he, my lord?"],"id":492,"m":"What treasure did he have, my lord?"},{"t":"sp","who":"HAMLET","lines":["Why—","'One fair daughter, and no more,","The which he loved passing well.'"],"id":493,"m":"Why, 'One fair daughter and no more, whom he loved very much.'"},{"t":"sp","who":"POLONIUS","lines":["[Aside] Still on my daughter."],"id":494,"m":"[Aside] Still on my daughter."},{"t":"sp","who":"HAMLET","lines":["Am I not i' th' right, old Jephthah?"],"id":495,"m":"Aren't I right, old Jephthah?"},{"t":"sp","who":"POLONIUS","lines":["If you call me Jephthah, my lord, I have a daughter that I love passing","well."],"id":496,"m":"If you call me Jephthah, my lord, I do have a daughter I love very much."},{"t":"sp","who":"HAMLET","lines":["Nay, that follows not."],"id":497,"m":"No, that doesn't follow."},{"t":"sp","who":"POLONIUS","lines":["What follows then, my lord?"],"id":498,"m":"What follows then, my lord?"},{"t":"sp","who":"HAMLET","lines":["Why,","As by lot, God wot,","and then, you know,","It came to pass, as most like it was.","The first row of the pious chanson will show you more. For look where","my abridgement comes."],"id":499,"m":"Why, 'As by chance, God knows', and then, you know, 'It came to pass, as was most likely'. The first verse of the holy song will tell you more, because look, here comes something to cut me short."},{"t":"sd","text":"Enter four or five Players.","id":500},{"t":"sp","who":"HAMLET","cont":1,"lines":["You are welcome, masters, welcome all. I am glad to see thee well.","Welcome, good friends. O, my old friend! Thy face is valanc'd since I","saw thee last. Com'st thou to beard me in Denmark? What, my young lady","and mistress! By'r lady, your ladyship is nearer to heaven than when I","saw you last, by the altitude of a chopine. Pray God your voice, like a","piece of uncurrent gold, be not cracked within the ring. Masters, you","are all welcome. We'll e'en to't like French falconers, fly at anything","we see. We'll have a speech straight. Come, give us a taste of your","quality. Come, a passionate speech."],"id":501,"m":"You're welcome, masters, welcome, all. I'm glad to see you well. Welcome, good friends. Oh, my old friend! Your face has grown a beard since I last saw you. Have you come to beard me in Denmark? What, my young lady and mistress! By our Lady, your ladyship is closer to heaven than when I last saw you, by the height of a platform shoe. Please God your voice hasn't cracked, like a gold coin cracked inside the ring and no longer worth anything. Masters, you are all welcome. We'll go straight at it like French falconers, fly at anything we see. We'll have a speech right now. Come, give us a taste of your skill. Come, a passionate speech."},{"t":"sp","who":"FIRST PLAYER","lines":["What speech, my lord?"],"id":502,"m":"Which speech, my lord?"},{"t":"sp","who":"HAMLET","lines":["I heard thee speak me a speech once, but it was never acted, or if it","was, not above once, for the play, I remember, pleased not the million,","'twas caviare to the general. But it was—as I received it, and others,","whose judgements in such matters cried in the top of mine—an excellent","play, well digested in the scenes, set down with as much modesty as","cunning. I remember one said there were no sallets in the lines to make","the matter savoury, nor no matter in the phrase that might indite the","author of affectation, but called it an honest method, as wholesome as","sweet, and by very much more handsome than fine. One speech in it, I","chiefly loved. 'Twas Aeneas' tale to Dido, and thereabout of it","especially where he speaks of Priam's slaughter. If it live in your","memory, begin at this line, let me see, let me see:","The rugged Pyrrhus, like th' Hyrcanian beast,—","It is not so: it begins with Pyrrhus—","The rugged Pyrrhus, he whose sable arms,","Black as his purpose, did the night resemble","When he lay couched in the ominous horse,","Hath now this dread and black complexion smear'd","With heraldry more dismal. Head to foot","Now is he total gules, horridly trick'd","With blood of fathers, mothers, daughters, sons,","Bak'd and impasted with the parching streets,","That lend a tyrannous and a damned light","To their vile murders. Roasted in wrath and fire,","And thus o'ersized with coagulate gore,","With eyes like carbuncles, the hellish Pyrrhus","Old grandsire Priam seeks.","So, proceed you."],"id":503,"m":"I heard you recite a speech to me once, but it was never acted, or if it was, not more than once, because the play, I remember, didn't please the masses; it was caviar to the common people. But it was, as I and others whose judgement in such things was better than mine thought, an excellent play, well arranged in its scenes, written with as much restraint as skill. I remember someone said there were no spicy bits in the lines to make the story tasty, and nothing in the language that could charge the author with showing off, but called it an honest style, as healthy as it was sweet, and much more truly beautiful than showy. One speech in it I especially loved: it was Aeneas telling Dido the story, and especially the part where he speaks of Priam's murder. If you remember it, start at this line, let me see, let me see: 'The rugged Pyrrhus, like the tiger of Hyrcania,' no, that's not it; it begins with Pyrrhus: 'The rugged Pyrrhus, whose black armour, as black as his purpose, looked like the night when he lay hidden in the fateful wooden horse, has now smeared his dark and dreadful look with a more dismal colour. From head to foot he is now all red, horribly painted with the blood of fathers, mothers, daughters, sons, baked and crusted on by the burning streets, which give a cruel, damned light to their vile murders. Roasted in anger and fire, and covered like this with clotted blood, with eyes like glowing red jewels, hellish Pyrrhus looks for old grandfather Priam.' Now you carry on."},{"t":"sp","who":"POLONIUS","lines":["'Fore God, my lord, well spoken, with good accent and good discretion."],"id":504,"m":"By God, my lord, well spoken, with good expression and good judgement."},{"t":"sp","who":"FIRST PLAYER","lines":["Anon he finds him,","Striking too short at Greeks. His antique sword,","Rebellious to his arm, lies where it falls,","Repugnant to command. Unequal match'd,","Pyrrhus at Priam drives, in rage strikes wide;","But with the whiff and wind of his fell sword","Th'unnerved father falls. Then senseless Ilium,","Seeming to feel this blow, with flaming top","Stoops to his base, and with a hideous crash","Takes prisoner Pyrrhus' ear. For lo, his sword,","Which was declining on the milky head","Of reverend Priam, seem'd i' th'air to stick.","So, as a painted tyrant, Pyrrhus stood,","And like a neutral to his will and matter,","Did nothing.","But as we often see against some storm,","A silence in the heavens, the rack stand still,","The bold winds speechless, and the orb below","As hush as death, anon the dreadful thunder","Doth rend the region; so after Pyrrhus' pause,","Aroused vengeance sets him new a-work,","And never did the Cyclops' hammers fall","On Mars's armour, forg'd for proof eterne,","With less remorse than Pyrrhus' bleeding sword","Now falls on Priam.","Out, out, thou strumpet Fortune! All you gods,","In general synod, take away her power;","Break all the spokes and fellies from her wheel,","And bowl the round nave down the hill of heaven,","As low as to the fiends."],"id":505,"m":"'Soon he finds him, striking at the Greeks and falling short. His old sword, refusing to obey his arm, stays where it falls, disobeying orders. Unevenly matched, Pyrrhus rushes at Priam; in his rage he misses, but the rush of air from his deadly sword is enough to knock the weakened father down. Then the senseless city of Troy, seeming to feel this blow, collapses with its burning towers, and with a hideous crash catches Pyrrhus's ear. For look, his sword, which was coming down on the white head of the respected Priam, seemed to stick in the air. So Pyrrhus stood like a tyrant in a painting, and, as if halfway between his intention and the deed, did nothing. But as we often see, before a storm, a silence in the heavens, the clouds standing still, the bold winds silent and the earth below as quiet as death, then suddenly dreadful thunder rips the sky; so, after Pyrrhus's pause, reawakened vengeance sets him to work again. And the Cyclops' hammers never fell on the armour of Mars, made to last forever, with less pity than Pyrrhus's bleeding sword now falls on Priam. Out, out, you whore, Fortune! All you gods, in a general council, take away her power. Break all the spokes and rims of her wheel, and roll the round hub down the hill of heaven as low as hell!'"},{"t":"sp","who":"POLONIUS","lines":["This is too long."],"id":506,"m":"This is too long."},{"t":"sp","who":"HAMLET","lines":["It shall to the barber's, with your beard.—Prithee say on.","He's for a jig or a tale of bawdry, or he sleeps.","Say on; come to Hecuba."],"id":507,"m":"It shall go to the barber's, with your beard. Please, go on. He only likes a dance or a dirty story, or else he falls asleep. Go on, come to Hecuba."},{"t":"sp","who":"FIRST PLAYER","lines":["But who, O who, had seen the mobled queen,—"],"id":508,"m":"'But who, oh who, had seen the muffled queen—'"},{"t":"sp","who":"HAMLET","lines":["'The mobled queen'?"],"id":509,"m":"'The muffled queen'?"},{"t":"sp","who":"POLONIUS","lines":["That's good! 'Mobled queen' is good."],"id":510,"m":"That's good! 'Muffled queen' is good."},{"t":"sp","who":"FIRST PLAYER","lines":["Run barefoot up and down, threat'ning the flames","With bisson rheum. A clout upon that head","Where late the diadem stood, and for a robe,","About her lank and all o'erteemed loins,","A blanket, in th'alarm of fear caught up—","Who this had seen, with tongue in venom steep'd,","'Gainst Fortune's state would treason have pronounc'd.","But if the gods themselves did see her then,","When she saw Pyrrhus make malicious sport","In mincing with his sword her husband's limbs,","The instant burst of clamour that she made,—","Unless things mortal move them not at all,—","Would have made milch the burning eyes of heaven,","And passion in the gods."],"id":511,"m":"'Running barefoot up and down, threatening the flames with her blinding tears, a rag on the head where the crown so recently sat, and for a robe, wrapped round her thin body worn out with childbearing, a blanket grabbed up in the panic. Anyone who had seen this, with a tongue soaked in poison, would have spoken treason against the rule of Fortune. But if the gods themselves had seen her then, when she saw Pyrrhus making cruel sport, chopping up her husband's limbs with his sword, the sudden cry she let out, unless human things don't move them at all, would have made the burning eyes of heaven flow with tears and filled the gods with grief.'"},{"t":"sp","who":"POLONIUS","lines":["Look, where he has not turn'd his colour, and has tears in's eyes. Pray","you, no more."],"id":512,"m":"Look how he has turned pale and has tears in his eyes. Please, no more."},{"t":"sp","who":"HAMLET","lines":["'Tis well. I'll have thee speak out the rest of this soon.—Good my","lord, will you see the players well bestowed? Do you hear, let them be","well used; for they are the abstracts and brief chronicles of the time.","After your death you were better have a bad epitaph than their ill","report while you live."],"id":513,"m":"That's good. I'll have you recite the rest of this soon. My good lord, will you see that the actors are well looked after? Do you hear? Let them be treated well, because they sum up and record our times. After you're dead you'd be better off with a bad epitaph than a bad report from them while you live."},{"t":"sp","who":"POLONIUS","lines":["My lord, I will use them according to their desert."],"id":514,"m":"My lord, I'll treat them as they deserve."},{"t":"sp","who":"HAMLET","lines":["God's bodikin, man, much better. Use every man after his desert, and who","should 'scape whipping? Use them after your own honour and dignity. The","less they deserve, the more merit is in your bounty. Take them in."],"id":515,"m":"By God's little body, man, much better! Treat every man as he deserves, and who would escape a whipping? Treat them according to your own honour and dignity. The less they deserve, the more credit your generosity earns. Take them in."},{"t":"sp","who":"POLONIUS","lines":["Come, sirs."],"id":516,"m":"Come, sirs."},{"t":"sp","who":"HAMLET","lines":["Follow him, friends. We'll hear a play tomorrow."],"id":517,"m":"Follow him, friends. We'll see a play tomorrow."},{"t":"sd","text":"Exeunt Polonius with all the Players but the First","id":518},{"t":"sp","who":"HAMLET","cont":1,"lines":["Dost thou hear me, old friend? Can you play The Murder of Gonzago?"],"id":519,"m":"Do you hear me, old friend? Can you perform The Murder of Gonzago?"},{"t":"sp","who":"FIRST PLAYER","lines":["Ay, my lord."],"id":520,"m":"Yes, my lord."},{"t":"sp","who":"HAMLET","lines":["We'll ha't tomorrow night. You could for a need study a speech of some","dozen or sixteen lines, which I would set down and insert in't, could","you not?"],"id":521,"m":"We'll have it tomorrow night. If necessary, you could learn a speech of twelve or sixteen lines which I'll write and put into it, couldn't you?"},{"t":"sp","who":"FIRST PLAYER","lines":["Ay, my lord."],"id":522,"m":"Yes, my lord."},{"t":"sp","who":"HAMLET","lines":["Very well. Follow that lord, and look you mock him not."],"id":523,"m":"Very good. Follow that lord, and be careful not to make fun of him."},{"t":"sd","text":"Exit First Player","id":524},{"t":"sp","who":"HAMLET","cont":1,"lines":["[To Rosencrantz and Guildenstern] My good friends, I'll leave you","till night. You are welcome to Elsinore."],"id":525,"m":"[To Rosencrantz and Guildenstern] My good friends, I'll leave you until tonight. You're welcome to Elsinore."},{"t":"sp","who":"ROSENCRANTZ","lines":["Good my lord."],"id":526,"m":"My good lord."},{"t":"sd","text":"Exeunt Rosencrantz and Guildenstern","id":527},{"t":"sp","who":"HAMLET","lines":["Ay, so, God b' wi' ye. Now I am alone.","O what a rogue and peasant slave am I!","Is it not monstrous that this player here,","But in a fiction, in a dream of passion,","Could force his soul so to his own conceit","That from her working all his visage wan'd;","Tears in his eyes, distraction in's aspect,","A broken voice, and his whole function suiting","With forms to his conceit? And all for nothing!","For Hecuba?","What's Hecuba to him, or he to Hecuba,","That he should weep for her? What would he do,","Had he the motive and the cue for passion","That I have? He would drown the stage with tears","And cleave the general ear with horrid speech;","Make mad the guilty, and appal the free,","Confound the ignorant, and amaze indeed,","The very faculties of eyes and ears. Yet I,","A dull and muddy-mettled rascal, peak","Like John-a-dreams, unpregnant of my cause,","And can say nothing. No, not for a king","Upon whose property and most dear life","A damn'd defeat was made. Am I a coward?","Who calls me villain, breaks my pate across?","Plucks off my beard and blows it in my face?","Tweaks me by the nose, gives me the lie i' th' throat","As deep as to the lungs? Who does me this?","Ha! 'Swounds, I should take it: for it cannot be","But I am pigeon-liver'd, and lack gall","To make oppression bitter, or ere this","I should have fatted all the region kites","With this slave's offal. Bloody, bawdy villain!","Remorseless, treacherous, lecherous, kindless villain!","Oh vengeance!","Why, what an ass am I! This is most brave,","That I, the son of a dear father murder'd,","Prompted to my revenge by heaven and hell,","Must, like a whore, unpack my heart with words","And fall a-cursing like a very drab,","A scullion! Fie upon't! Foh!","About, my brain! I have heard","That guilty creatures sitting at a play,","Have by the very cunning of the scene,","Been struck so to the soul that presently","They have proclaim'd their malefactions.","For murder, though it have no tongue, will speak","With most miraculous organ. I'll have these players","Play something like the murder of my father","Before mine uncle. I'll observe his looks;","I'll tent him to the quick. If he but blench,","I know my course. The spirit that I have seen","May be the devil, and the devil hath power","T'assume a pleasing shape, yea, and perhaps","Out of my weakness and my melancholy,","As he is very potent with such spirits,","Abuses me to damn me. I'll have grounds","More relative than this. The play's the thing","Wherein I'll catch the conscience of the King."],"id":528,"m":"Yes, goodbye to you. Now I'm alone. Oh, what a rogue and low slave I am! Isn't it monstrous that this actor here, just in a story, in a dream of passion, could force his soul to feel what he imagined, so that it made his face go pale, tears in his eyes, wildness in his look, a broken voice, and his whole body acting out what he imagined? And all for nothing! For Hecuba! What is Hecuba to him, or he to Hecuba, that he should weep for her? What would he do if he had the reason and the cue for passion that I have? He would drown the stage with tears, split everyone's ears with terrible words, drive the guilty mad, terrify the innocent, confuse the ignorant and stun the very senses of sight and hearing. And yet I, a dull, spiritless rascal, mope around like a dreamer, not stirred by my cause, and can say nothing. No, not even for a king whose kingdom and precious life were destroyed by a damned crime. Am I a coward? Who calls me villain? Hits me across the head? Pulls off my beard and blows it in my face? Tweaks my nose? Calls me a liar to my face, as deep as my lungs? Who does this to me? Ha! By God's wounds, I would take it, because I must be as meek as a pigeon and have no bitterness to make wrongs feel bitter, or I would have fattened all the hawks in the sky with this slave's guts by now. Bloody, filthy villain! Pitiless, treacherous, lustful, unnatural villain! Oh, vengeance! Why, what an ass I am! This is really fine, that I, the son of a dear father who was murdered, urged on to my revenge by heaven and hell, must unload my heart with words like a whore, and start cursing like a common slut, a kitchen servant! Shame on it! Ugh! Get to work, my brain! I have heard that guilty people watching a play have been so struck to the soul by the skill of the scene that they have confessed their crimes on the spot. For murder, though it has no tongue, will speak by some miraculous means. I'll have these actors perform something like my father's murder in front of my uncle. I'll watch his face. I'll probe him to the quick. If he so much as flinches, I'll know what to do. The spirit I have seen may be the devil, and the devil has the power to take on a pleasing shape. Yes, and perhaps, because of my weakness and my depression, since he has great power over people in that state, he is deceiving me to damn me. I'll get evidence more solid than this. The play's the thing in which I'll catch the conscience of the King."},{"t":"sd","text":"Exit","id":529},{"t":"scene","act":3,"scene":"I","loc":"A room in the Castle.","id":530},{"t":"sd","text":"Enter King, Queen, Polonius, Ophelia, Rosencrantz and Guildenstern.","id":531},{"t":"sp","who":"CLAUDIUS","lines":["And can you by no drift of circumstance","Get from him why he puts on this confusion,","Grating so harshly all his days of quiet","With turbulent and dangerous lunacy?"],"id":532,"m":"And can't you, by steering the conversation, get out of him why he is acting so confused, spoiling his peaceful days so harshly with wild and dangerous madness?"},{"t":"sp","who":"ROSENCRANTZ","lines":["He does confess he feels himself distracted,","But from what cause he will by no means speak."],"id":533,"m":"He admits that he feels disturbed, but he won't say at all what the cause is."},{"t":"sp","who":"GUILDENSTERN","lines":["Nor do we find him forward to be sounded,","But with a crafty madness keeps aloof","When we would bring him on to some confession","Of his true state."],"id":534,"m":"And we don't find him willing to be questioned. With a cunning kind of madness he keeps his distance whenever we try to lead him into admitting how he really is."},{"t":"sp","who":"GERTRUDE","lines":["Did he receive you well?"],"id":535,"m":"Did he welcome you well?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Most like a gentleman."],"id":536,"m":"Very much like a gentleman."},{"t":"sp","who":"GUILDENSTERN","lines":["But with much forcing of his disposition."],"id":537,"m":"But it was clearly an effort for him."},{"t":"sp","who":"ROSENCRANTZ","lines":["Niggard of question, but of our demands,","Most free in his reply."],"id":538,"m":"He asked few questions, but answered ours very freely."},{"t":"sp","who":"GERTRUDE","lines":["Did you assay him to any pastime?"],"id":539,"m":"Did you try to interest him in any entertainment?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Madam, it so fell out that certain players","We o'er-raught on the way. Of these we told him,","And there did seem in him a kind of joy","To hear of it. They are about the court,","And, as I think, they have already order","This night to play before him."],"id":540,"m":"Madam, it happened that we overtook some actors on the way. We told him about them, and he seemed to show a kind of joy at hearing it. They are here at court, and I believe they've already been told to perform for him tonight."},{"t":"sp","who":"POLONIUS","lines":["'Tis most true;","And he beseech'd me to entreat your Majesties","To hear and see the matter."],"id":541,"m":"That's very true, and he begged me to ask your Majesties to come and watch the play."},{"t":"sp","who":"CLAUDIUS","lines":["With all my heart; and it doth much content me","To hear him so inclin'd.","Good gentlemen, give him a further edge,","And drive his purpose on to these delights."],"id":542,"m":"With all my heart. It pleases me very much to hear he is in that mood. Good gentlemen, sharpen his interest further, and encourage him towards these pleasures."},{"t":"sp","who":"ROSENCRANTZ","lines":["We shall, my lord."],"id":543,"m":"We will, my lord."},{"t":"sd","text":"Exeunt Rosencrantz and Guildenstern","id":544},{"t":"sp","who":"CLAUDIUS","lines":["Sweet Gertrude, leave us too,","For we have closely sent for Hamlet hither,","That he, as 'twere by accident, may here","Affront Ophelia.","Her father and myself, lawful espials,","Will so bestow ourselves that, seeing unseen,","We may of their encounter frankly judge,","And gather by him, as he is behav'd,","If't be th'affliction of his love or no","That thus he suffers for."],"id":545,"m":"Sweet Gertrude, leave us too, because we have secretly sent for Hamlet to come here, so that, as if by accident, he may meet Ophelia face to face. Her father and I, spying for good reasons, will hide ourselves so that, seeing without being seen, we can judge their meeting clearly and work out from the way he behaves whether it is lovesickness or not that makes him suffer like this."},{"t":"sp","who":"GERTRUDE","lines":["I shall obey you.","And for your part, Ophelia, I do wish","That your good beauties be the happy cause","Of Hamlet's wildness: so shall I hope your virtues","Will bring him to his wonted way again,","To both your honours."],"id":546,"m":"I'll obey you. And as for you, Ophelia, I hope that your beauty is the happy cause of Hamlet's madness. Then I can hope your virtues will bring him back to his usual self, to the honour of you both."},{"t":"sp","who":"OPHELIA","lines":["Madam, I wish it may."],"id":547,"m":"Madam, I hope so too."},{"t":"sd","text":"Exit Queen","id":548},{"t":"sp","who":"POLONIUS","lines":["Ophelia, walk you here.—Gracious, so please you,","We will bestow ourselves.—[To Ophelia] Read on this book,","That show of such an exercise may colour","Your loneliness.—We are oft to blame in this,","'Tis too much prov'd, that with devotion's visage","And pious action we do sugar o'er","The devil himself."],"id":549,"m":"Ophelia, walk here. Your Majesty, if you please, we'll hide ourselves. [To Ophelia] Read this prayer book, so that looking busy with devotion will explain why you're alone. We are often to blame in this, it's been proved too often: with a holy face and pious actions we sugar-coat the devil himself."},{"t":"sp","who":"CLAUDIUS","lines":["[Aside] O 'tis too true!","How smart a lash that speech doth give my conscience!","The harlot's cheek, beautied with plastering art,","Is not more ugly to the thing that helps it","Than is my deed to my most painted word.","O heavy burden!"],"id":550,"m":"[Aside] Oh, it's too true! What a sharp whip that speech lays on my conscience! The whore's cheek, made pretty with plastered make-up, is not uglier underneath than my crime is underneath my most painted words. Oh, heavy burden!"},{"t":"sp","who":"POLONIUS","lines":["I hear him coming. Let's withdraw, my lord."],"id":551,"m":"I can hear him coming. Let's hide, my lord."},{"t":"sd","text":"Exeunt King and Polonius","id":552},{"t":"sd","text":"Enter Hamlet.","id":553},{"t":"sp","who":"HAMLET","lines":["To be, or not to be, that is the question:","Whether 'tis nobler in the mind to suffer","The slings and arrows of outrageous fortune,","Or to take arms against a sea of troubles,","And by opposing end them? To die—to sleep,","No more; and by a sleep to say we end","The heart-ache, and the thousand natural shocks","That flesh is heir to: 'tis a consummation","Devoutly to be wish'd. To die, to sleep.","To sleep, perchance to dream—ay, there's the rub,","For in that sleep of death what dreams may come,","When we have shuffled off this mortal coil,","Must give us pause. There's the respect","That makes calamity of so long life.","For who would bear the whips and scorns of time,","The oppressor's wrong, the proud man's contumely,","The pangs of dispriz'd love, the law's delay,","The insolence of office, and the spurns","That patient merit of the unworthy takes,","When he himself might his quietus make","With a bare bodkin? Who would these fardels bear,","To grunt and sweat under a weary life,","But that the dread of something after death,","The undiscover'd country, from whose bourn","No traveller returns, puzzles the will,","And makes us rather bear those ills we have","Than fly to others that we know not of?","Thus conscience does make cowards of us all,","And thus the native hue of resolution","Is sicklied o'er with the pale cast of thought,","And enterprises of great pith and moment,","With this regard their currents turn awry","And lose the name of action. Soft you now,","The fair Ophelia! Nymph, in thy orisons","Be all my sins remember'd."],"id":554,"m":"To be, or not to be, that is the question: whether it is nobler to put up with all the blows and arrows that cruel fortune throws at us, or to fight against a whole sea of troubles and end them by fighting? To die, to sleep, nothing more; and if by a sleep we could end the heartache and the thousand natural shocks that the body inherits, that would be an ending we should pray for. To die, to sleep. To sleep, perhaps to dream. Yes, that's the problem, because the thought of what dreams may come in that sleep of death, once we have thrown off the tangle of this life, must make us stop and think. That's the consideration that makes us put up with misery for so long. For who would bear the whips and scorn of the world, the wrongs of the oppressor, the insults of the proud, the pain of rejected love, the slowness of the law, the rudeness of officials and the kicks that patient, deserving people get from the unworthy, when he could settle his own account with a simple dagger? Who would carry these burdens, grunting and sweating under a weary life, if it weren't that the dread of something after death, that undiscovered country from which no traveller ever comes back, confuses the will, and makes us prefer to bear the troubles we have rather than rush to others we know nothing about? So thinking makes cowards of us all, and so the natural colour of determination is covered with the pale, sickly look of thought, and great, important plans turn aside because of this and lose the name of action. But quiet now: the lovely Ophelia! Beautiful girl, remember all my sins in your prayers."},{"t":"sp","who":"OPHELIA","lines":["Good my lord,","How does your honour for this many a day?"],"id":555,"m":"My good lord, how has your lordship been all these days?"},{"t":"sp","who":"HAMLET","lines":["I humbly thank you; well, well, well."],"id":556,"m":"I humbly thank you. Well, well, well."},{"t":"sp","who":"OPHELIA","lines":["My lord, I have remembrances of yours","That I have longed long to re-deliver.","I pray you, now receive them."],"id":557,"m":"My lord, I have some gifts of yours that I have long wanted to give back. Please, take them now."},{"t":"sp","who":"HAMLET","lines":["No, not I.","I never gave you aught."],"id":558,"m":"No, not me. I never gave you anything."},{"t":"sp","who":"OPHELIA","lines":["My honour'd lord, you know right well you did,","And with them words of so sweet breath compos'd","As made the things more rich; their perfume lost,","Take these again; for to the noble mind","Rich gifts wax poor when givers prove unkind.","There, my lord."],"id":559,"m":"My honoured lord, you know very well you did, and with them you gave words so sweetly spoken that they made the gifts richer. Now their perfume is gone, take them back, because to a noble mind rich gifts become poor when the givers turn unkind. There, my lord."},{"t":"sp","who":"HAMLET","lines":["Ha, ha! Are you honest?"],"id":560,"m":"Ha, ha! Are you honest?"},{"t":"sp","who":"OPHELIA","lines":["My lord?"],"id":561,"m":"My lord?"},{"t":"sp","who":"HAMLET","lines":["Are you fair?"],"id":562,"m":"Are you beautiful?"},{"t":"sp","who":"OPHELIA","lines":["What means your lordship?"],"id":563,"m":"What does your lordship mean?"},{"t":"sp","who":"HAMLET","lines":["That if you be honest and fair, your honesty should admit no discourse","to your beauty."],"id":564,"m":"That if you are honest and beautiful, your honesty should not allow anyone to talk to your beauty."},{"t":"sp","who":"OPHELIA","lines":["Could beauty, my lord, have better commerce than with honesty?"],"id":565,"m":"Could beauty, my lord, have a better companion than honesty?"},{"t":"sp","who":"HAMLET","lines":["Ay, truly; for the power of beauty will sooner transform honesty from","what it is to a bawd than the force of honesty can translate beauty","into his likeness. This was sometime a paradox, but now the time gives","it proof. I did love you once."],"id":566,"m":"Yes, truly, because the power of beauty will turn honesty into a pimp sooner than the strength of honesty can make beauty like itself. This used to be a paradox, but now the times prove it. I did love you once."},{"t":"sp","who":"OPHELIA","lines":["Indeed, my lord, you made me believe so."],"id":567,"m":"Indeed, my lord, you made me believe so."},{"t":"sp","who":"HAMLET","lines":["You should not have believed me; for virtue cannot so inoculate our old","stock but we shall relish of it. I loved you not."],"id":568,"m":"You shouldn't have believed me, because virtue can't be grafted onto our old sinful stock without some taste of the old stock remaining. I didn't love you."},{"t":"sp","who":"OPHELIA","lines":["I was the more deceived."],"id":569,"m":"Then I was all the more deceived."},{"t":"sp","who":"HAMLET","lines":["Get thee to a nunnery. Why wouldst thou be a breeder of sinners? I am","myself indifferent honest; but yet I could accuse me of such things","that it were better my mother had not borne me. I am very proud,","revengeful, ambitious, with more offences at my beck than I have","thoughts to put them in, imagination to give them shape, or time to act","them in. What should such fellows as I do crawling between earth and","heaven? We are arrant knaves all, believe none of us. Go thy ways to a","nunnery. Where's your father?"],"id":570,"m":"Get yourself to a nunnery. Why would you want to give birth to sinners? I'm fairly honest myself, but I could still accuse myself of such things that it would be better if my mother had never given birth to me. I'm very proud, vengeful, ambitious, with more sins ready to commit than I have thoughts to put them in, imagination to give them shape or time to carry them out. What should fellows like me be doing, crawling between earth and heaven? We are all complete villains. Don't believe any of us. Go on, off to a nunnery. Where's your father?"},{"t":"sp","who":"OPHELIA","lines":["At home, my lord."],"id":571,"m":"At home, my lord."},{"t":"sp","who":"HAMLET","lines":["Let the doors be shut upon him, that he may play the fool nowhere but","in's own house. Farewell."],"id":572,"m":"Then shut the doors on him, so he can play the fool only in his own house. Goodbye."},{"t":"sp","who":"OPHELIA","lines":["O help him, you sweet heavens!"],"id":573,"m":"Oh, help him, sweet heavens!"},{"t":"sp","who":"HAMLET","lines":["If thou dost marry, I'll give thee this plague for thy dowry. Be thou","as chaste as ice, as pure as snow, thou shalt not escape calumny. Get","thee to a nunnery, go: farewell. Or if thou wilt needs marry, marry a","fool; for wise men know well enough what monsters you make of them. To","a nunnery, go; and quickly too. Farewell."],"id":574,"m":"If you marry, I'll give you this curse as your dowry: be as chaste as ice and as pure as snow, you still won't escape slander. Get yourself to a nunnery. Go. Goodbye. Or if you must marry, marry a fool, because wise men know well enough what monsters you turn them into. To a nunnery, go, and quickly too. Goodbye."},{"t":"sp","who":"OPHELIA","lines":["O heavenly powers, restore him!"],"id":575,"m":"Oh, heavenly powers, make him well again!"},{"t":"sp","who":"HAMLET","lines":["I have heard of your paintings too, well enough. God hath given you one","face, and you make yourselves another. You jig, you amble, and you","lisp, and nickname God's creatures, and make your wantonness your","ignorance. Go to, I'll no more on't, it hath made me mad. I say, we","will have no more marriages. Those that are married already, all but","one, shall live; the rest shall keep as they are. To a nunnery, go."],"id":576,"m":"I've heard about your make-up too, plenty. God has given you one face and you paint yourselves another. You dance and sway and lisp, you give silly nicknames to God's creatures, and you pretend your flirting is innocence. Go on, I'll have no more of it. It's made me mad. I say we'll have no more marriages. Those who are married already, all except one, will live; the rest will stay as they are. To a nunnery, go."},{"t":"sd","text":"Exit","id":577},{"t":"sp","who":"OPHELIA","lines":["O, what a noble mind is here o'erthrown!","The courtier's, soldier's, scholar's, eye, tongue, sword,","Th'expectancy and rose of the fair state,","The glass of fashion and the mould of form,","Th'observ'd of all observers, quite, quite down!","And I, of ladies most deject and wretched,","That suck'd the honey of his music vows,","Now see that noble and most sovereign reason,","Like sweet bells jangled out of tune and harsh,","That unmatch'd form and feature of blown youth","Blasted with ecstasy. O woe is me,","T'have seen what I have seen, see what I see."],"id":578,"m":"Oh, what a noble mind is ruined here! The eye of a courtier, the tongue of a scholar, the sword of a soldier, the hope and flower of this fair kingdom, the mirror of fashion and the model of good behaviour, the one everyone watched, completely, completely fallen! And I, the most miserable and wretched of women, who sucked the honey of his musical promises, now see that noble, commanding reason jangling out of tune and harsh like sweet bells, that unequalled shape and face of young manhood in full bloom destroyed by madness. Oh, how wretched I am, to have seen what I saw, and to see what I see!"},{"t":"sd","text":"Enter King and Polonius.","id":579},{"t":"sp","who":"CLAUDIUS","lines":["Love? His affections do not that way tend,","Nor what he spake, though it lack'd form a little,","Was not like madness. There's something in his soul","O'er which his melancholy sits on brood,","And I do doubt the hatch and the disclose","Will be some danger, which for to prevent,","I have in quick determination","Thus set it down: he shall with speed to England","For the demand of our neglected tribute:","Haply the seas and countries different,","With variable objects, shall expel","This something settled matter in his heart,","Whereon his brains still beating puts him thus","From fashion of himself. What think you on't?"],"id":580,"m":"Love? His feelings don't go that way. And what he said, though it was a little disordered, wasn't like madness. There's something in his soul that his depression is sitting on like a bird on eggs, and I fear that when it hatches and comes out it will be dangerous. To prevent that, I have quickly made up my mind: he will go to England at once, to demand the payment they owe us and haven't paid. Perhaps the sea and different countries, with new things to see, will drive out this thing that has settled in his heart, which his brain keeps beating on, making him so unlike himself. What do you think?"},{"t":"sp","who":"POLONIUS","lines":["It shall do well. But yet do I believe","The origin and commencement of his grief","Sprung from neglected love. How now, Ophelia?","You need not tell us what Lord Hamlet said,","We heard it all. My lord, do as you please,","But if you hold it fit, after the play,","Let his queen mother all alone entreat him","To show his grief, let her be round with him,","And I'll be plac'd, so please you, in the ear","Of all their conference. If she find him not,","To England send him; or confine him where","Your wisdom best shall think."],"id":581,"m":"It will work well. But I still believe the origin and beginning of his grief came from rejected love. Well, Ophelia? You needn't tell us what Lord Hamlet said; we heard it all. My lord, do as you like, but if you think it right, after the play let his mother the Queen beg him alone to reveal his grief. Let her be blunt with him, and, if you agree, I'll hide where I can hear their whole conversation. If she can't find out what's wrong, send him to England, or shut him away wherever your wisdom thinks best."},{"t":"sp","who":"CLAUDIUS","lines":["It shall be so.","Madness in great ones must not unwatch'd go."],"id":582,"m":"So it shall be. Madness in important people must not go unwatched."},{"t":"sd","text":"Exeunt","id":583},{"t":"scene","act":3,"scene":"II","loc":"A hall in the Castle.","id":584},{"t":"sd","text":"Enter Hamlet and certain Players.","id":585},{"t":"sp","who":"HAMLET","lines":["Speak the speech, I pray you, as I pronounced it to you, trippingly on","the tongue. But if you mouth it, as many of your players do, I had as","lief the town-crier spoke my lines. Nor do not saw the air too much","with your hand, thus, but use all gently; for in the very torrent,","tempest, and, as I may say, whirlwind of passion, you must acquire and","beget a temperance that may give it smoothness. O, it offends me to the","soul to hear a robustious periwig-pated fellow tear a passion to","tatters, to very rags, to split the ears of the groundlings, who, for","the most part, are capable of nothing but inexplicable dumb shows and","noise. I would have such a fellow whipped for o'erdoing Termagant. It","out-Herods Herod. Pray you avoid it."],"id":586,"m":"Say the speech, please, the way I said it to you, lightly and naturally. But if you overact it the way many of you actors do, I'd rather have the town crier speak my lines. And don't saw the air with your hand like this, but do everything gently, because even in the flood, the storm, and I might say the whirlwind of passion, you must find and create a self-control that gives it smoothness. Oh, it hurts me to the soul to hear a loud, bewigged actor tear a passion to shreds, to rags, to split the ears of the people standing in the pit, who mostly can't appreciate anything except meaningless mime and noise. I'd have that sort of actor whipped for overplaying the ranting villain. It out-Herods Herod. Please avoid it."},{"t":"sp","who":"FIRST PLAYER","lines":["I warrant your honour."],"id":587,"m":"I promise your honour."},{"t":"sp","who":"HAMLET","lines":["Be not too tame neither; but let your own discretion be your tutor.","Suit the action to the word, the word to the action, with this special","observance, that you o'erstep not the modesty of nature; for anything","so overdone is from the purpose of playing, whose end, both at the","first and now, was and is, to hold as 'twere the mirror up to nature;","to show virtue her own feature, scorn her own image, and the very age","and body of the time his form and pressure. Now, this overdone, or come","tardy off, though it make the unskilful laugh, cannot but make the","judicious grieve; the censure of the which one must in your allowance","o'erweigh a whole theatre of others. O, there be players that I have","seen play—and heard others praise, and that highly—not to speak it","profanely, that, neither having the accent of Christians, nor the gait","of Christian, pagan, nor man, have so strutted and bellowed that I have","thought some of Nature's journeymen had made men, and not made them","well, they imitated humanity so abominably."],"id":588,"m":"Don't be too tame either, but let your own judgement teach you. Fit the action to the word and the word to the action, taking special care not to go beyond what is natural. Anything overdone like that goes against the purpose of acting, whose aim, from the beginning until now, was and is to hold a mirror up to nature: to show virtue its own face, scorn its own image, and the age and body of the times its shape and imprint. Now, if this is overdone or underdone, though it makes the ignorant laugh, it can only upset the judicious, and you must value the opinion of one of them more than a whole theatre full of the others. Oh, there are actors I have seen, and heard others praise highly, who, not to put it too irreverently, didn't speak or walk like Christians, pagans or even men, and strutted and bellowed so much that I thought some of Nature's apprentice workmen had made them, and made them badly, they imitated humanity so horribly."},{"t":"sp","who":"FIRST PLAYER","lines":["I hope we have reform'd that indifferently with us, sir."],"id":589,"m":"I hope we have more or less corrected that in our company, sir."},{"t":"sp","who":"HAMLET","lines":["O reform it altogether. And let those that play your clowns speak no","more than is set down for them. For there be of them that will","themselves laugh, to set on some quantity of barren spectators to laugh","too, though in the meantime some necessary question of the play be then","to be considered. That's villainous, and shows a most pitiful ambition","in the fool that uses it. Go make you ready."],"id":590,"m":"Oh, correct it completely. And don't let the actors who play your clowns say any more than is written for them. Some of them will laugh themselves to set off some stupid spectators laughing too, even though some important point in the play needs attention at that moment. That's wicked, and shows a pathetic ambition in the fool who does it. Go and get ready."},{"t":"sd","text":"Exeunt Players","id":591},{"t":"sd","text":"Enter Polonius, Rosencrantz and Guildenstern.","id":592},{"t":"sp","who":"HAMLET","cont":1,"lines":["How now, my lord?","Will the King hear this piece of work?"],"id":593,"m":"Well, my lord? Will the King come to see this play?"},{"t":"sp","who":"POLONIUS","lines":["And the Queen too, and that presently."],"id":594,"m":"And the Queen too, very soon."},{"t":"sp","who":"HAMLET","lines":["Bid the players make haste."],"id":595,"m":"Tell the actors to hurry."},{"t":"sd","text":"Exit Polonius","id":596},{"t":"sp","who":"HAMLET","cont":1,"lines":["Will you two help to hasten them?"],"id":597,"m":"Will you two help to hurry them?"},{"t":"sp","who":"ROSENCRANTZ AND GUILDENSTERN","lines":["We will, my lord."],"id":598,"m":"We will, my lord."},{"t":"sd","text":"Exeunt Rosencrantz and Guildenstern","id":599},{"t":"sp","who":"HAMLET","lines":["What ho, Horatio!"],"id":600,"m":"Hey there, Horatio!"},{"t":"sd","text":"Enter Horatio.","id":601},{"t":"sp","who":"HORATIO","lines":["Here, sweet lord, at your service."],"id":602,"m":"Here, sweet lord, at your service."},{"t":"sp","who":"HAMLET","lines":["Horatio, thou art e'en as just a man","As e'er my conversation cop'd withal."],"id":603,"m":"Horatio, you are as honest and balanced a man as I have ever met."},{"t":"sp","who":"HORATIO","lines":["O my dear lord."],"id":604,"m":"Oh, my dear lord—"},{"t":"sp","who":"HAMLET","lines":["Nay, do not think I flatter;","For what advancement may I hope from thee,","That no revenue hast, but thy good spirits","To feed and clothe thee? Why should the poor be flatter'd?","No, let the candied tongue lick absurd pomp,","And crook the pregnant hinges of the knee","Where thrift may follow fawning. Dost thou hear?","Since my dear soul was mistress of her choice,","And could of men distinguish, her election","Hath seal'd thee for herself. For thou hast been","As one, in suffering all, that suffers nothing,","A man that Fortune's buffets and rewards","Hast ta'en with equal thanks. And blessed are those","Whose blood and judgement are so well co-mingled","That they are not a pipe for Fortune's finger","To sound what stop she please. Give me that man","That is not passion's slave, and I will wear him","In my heart's core, ay, in my heart of heart,","As I do thee. Something too much of this.","There is a play tonight before the King.","One scene of it comes near the circumstance","Which I have told thee, of my father's death.","I prithee, when thou see'st that act a-foot,","Even with the very comment of thy soul","Observe mine uncle. If his occulted guilt","Do not itself unkennel in one speech,","It is a damned ghost that we have seen;","And my imaginations are as foul","As Vulcan's stithy. Give him heedful note;","For I mine eyes will rivet to his face;","And after we will both our judgements join","In censure of his seeming."],"id":605,"m":"No, don't think I'm flattering you. What reward could I hope for from you, when you have no income except your good spirits to feed and clothe you? Why should anyone flatter the poor? No, let the sugary tongue lick foolish grandeur, and let the ready knee bend where profit may follow from fawning. Do you hear? Ever since my soul could make its own choices and tell one man from another, it has chosen you for itself. Because you have been like someone who suffers everything and yet is not hurt by it, a man who has taken Fortune's blows and rewards with equal thanks. And blessed are those whose passion and judgement are so well mixed that they are not a pipe for Fortune to play whatever note she likes. Give me the man who is not a slave to passion, and I will keep him at the centre of my heart, yes, in my heart of hearts, as I do you. That's a little too much of this. There is a play tonight in front of the King. One scene in it is close to what I told you about my father's death. Please, when you see that part start, watch my uncle with all the attention of your soul. If his hidden guilt doesn't break out of hiding at one particular speech, then it is a damned ghost we have seen, and my imaginings are as filthy as the blacksmith god Vulcan's forge. Watch him carefully, because I'll fix my eyes on his face, and afterwards we'll put our judgements together to decide what his reaction showed."},{"t":"sp","who":"HORATIO","lines":["Well, my lord.","If he steal aught the whilst this play is playing,","And 'scape detecting, I will pay the theft."],"id":606,"m":"Very well, my lord. If he steals anything while the play is on and escapes being caught, I'll pay for the theft."},{"t":"sp","who":"HAMLET","lines":["They are coming to the play. I must be idle.","Get you a place."],"id":607,"m":"They're coming to the play. I must look idle. Find yourself a seat."},{"t":"sd","text":"Danish march. A flourish. Enter King, Queen, Polonius, Ophelia, Rosencrantz, Guildenstern and others.","id":608},{"t":"sp","who":"CLAUDIUS","lines":["How fares our cousin Hamlet?"],"id":609,"m":"How is our nephew Hamlet?"},{"t":"sp","who":"HAMLET","lines":["Excellent, i' faith; of the chameleon's dish: I eat the air,","promise-crammed: you cannot feed capons so."],"id":610,"m":"Excellent, really. I live on the chameleon's diet: I eat the air, stuffed full of promises. You can't fatten chickens like that."},{"t":"sp","who":"CLAUDIUS","lines":["I have nothing with this answer, Hamlet; these words are not mine."],"id":611,"m":"That answer means nothing to me, Hamlet. Those words have nothing to do with what I asked."},{"t":"sp","who":"HAMLET","lines":["No, nor mine now. [To Polonius] My lord, you play'd once i'","th'university, you say?"],"id":612,"m":"No, nor with me now. [To Polonius] My lord, you acted once at the university, you say?"},{"t":"sp","who":"POLONIUS","lines":["That did I, my lord, and was accounted a good actor."],"id":613,"m":"I did, my lord, and was thought to be a good actor."},{"t":"sp","who":"HAMLET","lines":["What did you enact?"],"id":614,"m":"What part did you play?"},{"t":"sp","who":"POLONIUS","lines":["I did enact Julius Caesar. I was kill'd i' th' Capitol. Brutus killed","me."],"id":615,"m":"I played Julius Caesar. I was killed in the Capitol. Brutus killed me."},{"t":"sp","who":"HAMLET","lines":["It was a brute part of him to kill so capital a calf there. Be the","players ready?"],"id":616,"m":"It was a brutal part of him to kill such a capital calf there. Are the actors ready?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Ay, my lord; they stay upon your patience."],"id":617,"m":"Yes, my lord. They are waiting for your permission."},{"t":"sp","who":"GERTRUDE","lines":["Come hither, my dear Hamlet, sit by me."],"id":618,"m":"Come here, my dear Hamlet, sit by me."},{"t":"sp","who":"HAMLET","lines":["No, good mother, here's metal more attractive."],"id":619,"m":"No, good mother, here's a stronger magnet."},{"t":"sp","who":"POLONIUS","lines":["[To the King] O ho! do you mark that?"],"id":620,"m":"[To the King] Oho! Did you notice that?"},{"t":"sp","who":"HAMLET","lines":["Lady, shall I lie in your lap?"],"id":621,"m":"Lady, shall I lie in your lap?"},{"t":"sd","text":"Lying down at Ophelia's feet","id":622},{"t":"sp","who":"OPHELIA","lines":["No, my lord."],"id":623,"m":"No, my lord."},{"t":"sp","who":"HAMLET","lines":["I mean, my head upon your lap?"],"id":624,"m":"I mean, my head in your lap?"},{"t":"sp","who":"OPHELIA","lines":["Ay, my lord."],"id":625,"m":"Yes, my lord."},{"t":"sp","who":"HAMLET","lines":["Do you think I meant country matters?"],"id":626,"m":"Did you think I meant something rude?"},{"t":"sp","who":"OPHELIA","lines":["I think nothing, my lord."],"id":627,"m":"I think nothing, my lord."},{"t":"sp","who":"HAMLET","lines":["That's a fair thought to lie between maids' legs."],"id":628,"m":"That's a nice thought to lie between a girl's legs."},{"t":"sp","who":"OPHELIA","lines":["What is, my lord?"],"id":629,"m":"What is, my lord?"},{"t":"sp","who":"HAMLET","lines":["Nothing."],"id":630,"m":"Nothing."},{"t":"sp","who":"OPHELIA","lines":["You are merry, my lord."],"id":631,"m":"You are in a good mood, my lord."},{"t":"sp","who":"HAMLET","lines":["Who, I?"],"id":632,"m":"Who, me?"},{"t":"sp","who":"OPHELIA","lines":["Ay, my lord."],"id":633,"m":"Yes, my lord."},{"t":"sp","who":"HAMLET","lines":["O God, your only jig-maker! What should a man do but be merry? For look","you how cheerfully my mother looks, and my father died within's two","hours."],"id":634,"m":"Oh God, I'm the best comedian there is! What should a man do but be cheerful? Look how happy my mother looks, and my father died only two hours ago."},{"t":"sp","who":"OPHELIA","lines":["Nay, 'tis twice two months, my lord."],"id":635,"m":"No, it's twice two months, my lord."},{"t":"sp","who":"HAMLET","lines":["So long? Nay then, let the devil wear black, for I'll have a suit of","sables. O heavens! die two months ago, and not forgotten yet? Then","there's hope a great man's memory may outlive his life half a year. But","by'r lady, he must build churches then; or else shall he suffer not","thinking on, with the hobby-horse, whose epitaph is 'For, O, for O, the","hobby-horse is forgot!'"],"id":636,"m":"So long? Well then, let the devil wear black, because I'll have a suit of rich furs. Oh heavens! Died two months ago and not forgotten yet? Then there's hope that a great man's memory may outlive him by half a year. But, by our Lady, he'll have to build churches then, or else he'll be forgotten like the hobby-horse, whose epitaph is 'For oh, for oh, the hobby-horse is forgot!'"},{"t":"sd","text":"Trumpets sound. The dumb show enters.","id":637},{"t":"sd","text":"Enter a King and a Queen very lovingly; the Queen embracing him and he her. She kneels, and makes show of protestation unto him. He takes her up, and declines his head upon her neck. Lays him down upon a bank of flowers. She, seeing him asleep, leaves him. Anon comes in a fellow, takes off his crown, kisses it, pours poison in the King's ears, and exits. The Queen returns, finds the King dead, and makes passionate action. The Poisoner with some three or four Mutes, comes in again, seeming to lament with her. The dead body is carried away. The Poisoner woos the Queen with gifts. She seems loth and unwilling awhile, but in the end accepts his love.","id":638},{"t":"sd","text":"Exeunt","id":639},{"t":"sp","who":"OPHELIA","lines":["What means this, my lord?"],"id":640,"m":"What does this mean, my lord?"},{"t":"sp","who":"HAMLET","lines":["Marry, this is miching mallecho; it means mischief."],"id":641,"m":"Indeed, this is sneaking mischief. It means trouble."},{"t":"sp","who":"OPHELIA","lines":["Belike this show imports the argument of the play."],"id":642,"m":"Perhaps this mime shows the plot of the play."},{"t":"sd","text":"Enter Prologue.","id":643},{"t":"sp","who":"HAMLET","lines":["We shall know by this fellow: the players cannot keep counsel; they'll","tell all."],"id":644,"m":"We'll find out from this fellow. Actors can't keep a secret; they'll tell everything."},{"t":"sp","who":"OPHELIA","lines":["Will they tell us what this show meant?"],"id":645,"m":"Will he tell us what this show meant?"},{"t":"sp","who":"HAMLET","lines":["Ay, or any show that you'll show him. Be not you ashamed to show, he'll","not shame to tell you what it means."],"id":646,"m":"Yes, or any show you'll show him. As long as you're not ashamed to show, he won't be ashamed to tell you what it means."},{"t":"sp","who":"OPHELIA","lines":["You are naught, you are naught: I'll mark the play."],"id":647,"m":"You're wicked, you're wicked. I'll watch the play."},{"t":"sp","who":"PROLOGUE","lines":["For us, and for our tragedy,","Here stooping to your clemency,","We beg your hearing patiently."],"id":648,"m":"For us and for our tragedy, bowing here to ask your kindness, we beg you to listen patiently."},{"t":"sp","who":"HAMLET","lines":["Is this a prologue, or the posy of a ring?"],"id":649,"m":"Is this a prologue, or the motto inside a ring?"},{"t":"sp","who":"OPHELIA","lines":["'Tis brief, my lord."],"id":650,"m":"It's short, my lord."},{"t":"sp","who":"HAMLET","lines":["As woman's love."],"id":651,"m":"Like a woman's love."},{"t":"sd","text":"Enter a King and a Queen.","id":652},{"t":"sp","who":"PLAYER KING","lines":["Full thirty times hath Phoebus' cart gone round","Neptune's salt wash and Tellus' orbed ground,","And thirty dozen moons with borrow'd sheen","About the world have times twelve thirties been,","Since love our hearts, and Hymen did our hands","Unite commutual in most sacred bands."],"id":653,"m":"The sun god's chariot has gone round the salty sea and the round earth a full thirty times, and thirty dozen moons with borrowed light have circled the world twelve times thirty, since love joined our hearts and the god of marriage joined our hands in the most sacred bonds."},{"t":"sp","who":"PLAYER QUEEN","lines":["So many journeys may the sun and moon","Make us again count o'er ere love be done.","But, woe is me, you are so sick of late,","So far from cheer and from your former state,","That I distrust you. Yet, though I distrust,","Discomfort you, my lord, it nothing must:","For women's fear and love holds quantity,","In neither aught, or in extremity.","Now what my love is, proof hath made you know,","And as my love is siz'd, my fear is so.","Where love is great, the littlest doubts are fear;","Where little fears grow great, great love grows there."],"id":654,"m":"May the sun and moon make as many journeys again before our love is over! But I'm so sorry, you have been so ill lately, so far from cheerful and from your old self, that I am worried about you. But although I'm worried, it mustn't upset you at all, my lord, because women's fear and love go together in equal amounts: either none of either, or too much of both. Now, you know from experience how great my love is, and my fear is as great as my love. Where love is great, the smallest doubts become fears; where little fears grow great, great love grows there."},{"t":"sp","who":"PLAYER KING","lines":["Faith, I must leave thee, love, and shortly too:","My operant powers their functions leave to do:","And thou shalt live in this fair world behind,","Honour'd, belov'd, and haply one as kind","For husband shalt thou—"],"id":655,"m":"Truly, I must leave you, love, and soon too. My bodily powers are stopping working. And you will live on in this lovely world after me, honoured and loved, and perhaps one as kind will be your husband—"},{"t":"sp","who":"PLAYER QUEEN","lines":["O confound the rest.","Such love must needs be treason in my breast.","In second husband let me be accurst!","None wed the second but who kill'd the first."],"id":656,"m":"Oh, damn the rest! Such love would have to be treason in my heart. Let me be cursed if I take a second husband! No woman marries a second unless she killed the first."},{"t":"sp","who":"HAMLET","lines":["[Aside] Wormwood, wormwood."],"id":657,"m":"[Aside] Bitter, bitter."},{"t":"sp","who":"PLAYER QUEEN","lines":["The instances that second marriage move","Are base respects of thrift, but none of love.","A second time I kill my husband dead,","When second husband kisses me in bed."],"id":658,"m":"The reasons that lead to a second marriage are low concerns about money, never love. I kill my dead husband a second time when a second husband kisses me in bed."},{"t":"sp","who":"PLAYER KING","lines":["I do believe you think what now you speak;","But what we do determine, oft we break.","Purpose is but the slave to memory,","Of violent birth, but poor validity:","Which now, like fruit unripe, sticks on the tree,","But fall unshaken when they mellow be.","Most necessary 'tis that we forget","To pay ourselves what to ourselves is debt.","What to ourselves in passion we propose,","The passion ending, doth the purpose lose.","The violence of either grief or joy","Their own enactures with themselves destroy.","Where joy most revels, grief doth most lament;","Grief joys, joy grieves, on slender accident.","This world is not for aye; nor 'tis not strange","That even our loves should with our fortunes change,","For 'tis a question left us yet to prove,","Whether love lead fortune, or else fortune love.","The great man down, you mark his favourite flies,","The poor advanc'd makes friends of enemies;","And hitherto doth love on fortune tend:","For who not needs shall never lack a friend,","And who in want a hollow friend doth try,","Directly seasons him his enemy.","But orderly to end where I begun,","Our wills and fates do so contrary run","That our devices still are overthrown.","Our thoughts are ours, their ends none of our own.","So think thou wilt no second husband wed,","But die thy thoughts when thy first lord is dead."],"id":659,"m":"I do believe you mean what you are saying now, but we often break what we decide. Intentions are only slaves to memory, strong when they are born but with little staying power. Now, like unripe fruit, they stick to the tree, but they fall without shaking once they are ripe. It is unavoidable that we forget to pay ourselves the debts we owe ourselves. What we promise ourselves in passion, we lose the purpose of once the passion ends. Violent grief or joy destroys its own actions along with itself. Where joy celebrates most, grief mourns most; grief turns to joy and joy to grief on the slightest chance. This world doesn't last forever, and it isn't strange that even our loves should change with our fortunes, because it's still an open question whether love leads fortune, or fortune love. When a great man falls, you'll see his favourite runs away; when a poor man rises, his enemies become his friends. And so far love follows fortune, because the man who doesn't need anything will never lack a friend, and the man in need who tests a false friend immediately turns him into an enemy. But to finish properly where I began, our wishes and our fates run so contrary to each other that our plans are always overthrown. Our thoughts are our own, but their outcomes are not. So you think you will never marry a second husband, but your thoughts will die when your first lord is dead."},{"t":"sp","who":"PLAYER QUEEN","lines":["Nor earth to me give food, nor heaven light,","Sport and repose lock from me day and night,","To desperation turn my trust and hope,","An anchor's cheer in prison be my scope,","Each opposite that blanks the face of joy,","Meet what I would have well, and it destroy!","Both here and hence pursue me lasting strife,","If, once a widow, ever I be wife."],"id":660,"m":"May the earth give me no food and heaven no light, may pleasure and rest be locked away from me day and night, may my trust and hope turn to despair, may a hermit's life in prison be all I have, may everything that drains the face of joy meet what I want to go well and destroy it! In this world and the next may endless trouble pursue me, if, once a widow, I ever become a wife!"},{"t":"sp","who":"HAMLET","lines":["[To Ophelia] If she should break it now."],"id":661,"m":"[To Ophelia] What if she broke it now!"},{"t":"sp","who":"PLAYER KING","lines":["'Tis deeply sworn. Sweet, leave me here awhile.","My spirits grow dull, and fain I would beguile","The tedious day with sleep.","[Sleeps]"],"id":662,"m":"That is a deep oath. Sweet, leave me here for a while. My spirits are growing heavy, and I'd like to pass the boring day with sleep. [Sleeps]"},{"t":"sp","who":"PLAYER QUEEN","lines":["Sleep rock thy brain,","And never come mischance between us twain."],"id":663,"m":"May sleep soothe your brain, and may no bad luck ever come between us two!"},{"t":"sd","text":"Exit","id":664},{"t":"sp","who":"HAMLET","lines":["Madam, how like you this play?"],"id":665,"m":"Madam, how do you like this play?"},{"t":"sp","who":"GERTRUDE","lines":["The lady protests too much, methinks."],"id":666,"m":"The lady makes too many promises, I think."},{"t":"sp","who":"HAMLET","lines":["O, but she'll keep her word."],"id":667,"m":"Oh, but she'll keep her word."},{"t":"sp","who":"CLAUDIUS","lines":["Have you heard the argument? Is there no offence in't?"],"id":668,"m":"Do you know the plot? Is there nothing offensive in it?"},{"t":"sp","who":"HAMLET","lines":["No, no, they do but jest, poison in jest; no offence i' th' world."],"id":669,"m":"No, no, they're only joking, poisoning in jest. No offence in the world."},{"t":"sp","who":"CLAUDIUS","lines":["What do you call the play?"],"id":670,"m":"What is the play called?"},{"t":"sp","who":"HAMLET","lines":["The Mousetrap. Marry, how? Tropically. This play is the image of a","murder done in Vienna. Gonzago is the Duke's name, his wife Baptista:","you shall see anon; 'tis a knavish piece of work: but what o' that?","Your majesty, and we that have free souls, it touches us not. Let the","gall'd jade wince; our withers are unwrung."],"id":671,"m":"The Mousetrap. Why? It's a figure of speech. This play is a picture of a murder done in Vienna. The Duke's name is Gonzago; his wife is Baptista. You'll see soon. It's a wicked piece of work, but what of it? Your majesty, and we who have clear consciences, it doesn't touch us. Let the horse with the saddle sore flinch; our backs aren't rubbed raw."},{"t":"sd","text":"Enter Lucianus.","id":672},{"t":"sp","who":"HAMLET","cont":1,"lines":["This is one Lucianus, nephew to the King."],"id":673,"m":"This is someone called Lucianus, the King's nephew."},{"t":"sp","who":"OPHELIA","lines":["You are a good chorus, my lord."],"id":674,"m":"You're as good as a narrator, my lord."},{"t":"sp","who":"HAMLET","lines":["I could interpret between you and your love, if I could see the puppets","dallying."],"id":675,"m":"I could explain what's going on between you and your lover, if I could see the puppets flirting."},{"t":"sp","who":"OPHELIA","lines":["You are keen, my lord, you are keen."],"id":676,"m":"You're sharp, my lord, you're sharp."},{"t":"sp","who":"HAMLET","lines":["It would cost you a groaning to take off my edge."],"id":677,"m":"It would cost you some groaning to take off my edge."},{"t":"sp","who":"OPHELIA","lines":["Still better, and worse."],"id":678,"m":"Better and worse."},{"t":"sp","who":"HAMLET","lines":["So you mistake your husbands.—Begin, murderer. Pox, leave thy damnable","faces, and begin. Come, the croaking raven doth bellow for revenge."],"id":679,"m":"That's how you take your husbands, for better, for worse. Begin, murderer. Damn it, stop pulling those wicked faces and begin. Come on: 'The croaking raven bellows for revenge.'"},{"t":"sp","who":"LUCIANUS","lines":["Thoughts black, hands apt, drugs fit, and time agreeing,","Confederate season, else no creature seeing;","Thou mixture rank, of midnight weeds collected,","With Hecate's ban thrice blasted, thrice infected,","Thy natural magic and dire property","On wholesome life usurp immediately."],"id":680,"m":"Dark thoughts, ready hands, the right drugs and a suitable time, the moment on my side, and no one else watching. You foul mixture, made of weeds gathered at midnight, cursed three times by the witch goddess Hecate and three times poisoned, let your natural magic and deadly power take healthy life away at once."},{"t":"sd","text":"Pours the poison into the sleeper's ears","id":681},{"t":"sp","who":"HAMLET","lines":["He poisons him i' th'garden for's estate. His name's Gonzago. The story","is extant, and written in very choice Italian. You shall see anon how","the murderer gets the love of Gonzago's wife."],"id":682,"m":"He poisons him in the garden to get his property. His name is Gonzago. The story exists, written in very fine Italian. You'll see soon how the murderer wins the love of Gonzago's wife."},{"t":"sp","who":"OPHELIA","lines":["The King rises."],"id":683,"m":"The King is getting up."},{"t":"sp","who":"HAMLET","lines":["What, frighted with false fire?"],"id":684,"m":"What, scared by a blank shot?"},{"t":"sp","who":"GERTRUDE","lines":["How fares my lord?"],"id":685,"m":"How is my lord?"},{"t":"sp","who":"POLONIUS","lines":["Give o'er the play."],"id":686,"m":"Stop the play."},{"t":"sp","who":"CLAUDIUS","lines":["Give me some light. Away."],"id":687,"m":"Give me some light. Away!"},{"t":"sp","who":"ALL","lines":["Lights, lights, lights."],"id":688,"m":"Lights, lights, lights!"},{"t":"sd","text":"Exeunt all but Hamlet and Horatio","id":689},{"t":"sp","who":"HAMLET","lines":["Why, let the strucken deer go weep,","The hart ungalled play;","For some must watch, while some must sleep,","So runs the world away.","Would not this, sir, and a forest of feathers, if the rest of my","fortunes turn Turk with me; with two Provincial roses on my razed","shoes, get me a fellowship in a cry of players, sir?"],"id":690,"m":"Why, let the wounded deer go and weep, while the unhurt stag plays; for some must stay awake while others sleep. That's how the world goes. Sir, wouldn't this, along with a forest of feathers in my hat, if the rest of my luck turns against me, and two big rosettes on my slashed shoes, get me a partnership in a company of actors?"},{"t":"sp","who":"HORATIO","lines":["Half a share."],"id":691,"m":"Half a share."},{"t":"sp","who":"HAMLET","lines":["A whole one, I.","For thou dost know, O Damon dear,","This realm dismantled was","Of Jove himself, and now reigns here","A very, very—pajock."],"id":692,"m":"A whole one, for me. For you know, oh dear Damon, this kingdom was robbed of Jove himself, and now there reigns here a real, real... peacock."},{"t":"sp","who":"HORATIO","lines":["You might have rhymed."],"id":693,"m":"You could have made it rhyme."},{"t":"sp","who":"HAMLET","lines":["O good Horatio, I'll take the ghost's word for a thousand pound. Didst","perceive?"],"id":694,"m":"Oh, good Horatio, I'd bet a thousand pounds on the ghost's word. Did you see?"},{"t":"sp","who":"HORATIO","lines":["Very well, my lord."],"id":695,"m":"Very well, my lord."},{"t":"sp","who":"HAMLET","lines":["Upon the talk of the poisoning?"],"id":696,"m":"When they talked about the poisoning?"},{"t":"sp","who":"HORATIO","lines":["I did very well note him."],"id":697,"m":"I watched him very carefully."},{"t":"sp","who":"HAMLET","lines":["Ah, ha! Come, some music. Come, the recorders.","For if the king like not the comedy,","Why then, belike he likes it not, perdie.","Come, some music."],"id":698,"m":"Aha! Come, some music! Come, the recorders! For if the King doesn't like the comedy, why then, he doesn't like it, by God. Come, some music!"},{"t":"sd","text":"Enter Rosencrantz and Guildenstern.","id":699},{"t":"sp","who":"GUILDENSTERN","lines":["Good my lord, vouchsafe me a word with you."],"id":700,"m":"My good lord, may I have a word with you?"},{"t":"sp","who":"HAMLET","lines":["Sir, a whole history."],"id":701,"m":"Sir, a whole history."},{"t":"sp","who":"GUILDENSTERN","lines":["The King, sir—"],"id":702,"m":"The King, sir—"},{"t":"sp","who":"HAMLET","lines":["Ay, sir, what of him?"],"id":703,"m":"Yes, sir, what about him?"},{"t":"sp","who":"GUILDENSTERN","lines":["Is in his retirement, marvellous distempered."],"id":704,"m":"Has gone to his rooms, terribly upset."},{"t":"sp","who":"HAMLET","lines":["With drink, sir?"],"id":705,"m":"From drink, sir?"},{"t":"sp","who":"GUILDENSTERN","lines":["No, my lord; rather with choler."],"id":706,"m":"No, my lord, from anger."},{"t":"sp","who":"HAMLET","lines":["Your wisdom should show itself more richer to signify this to the","doctor, for me to put him to his purgation would perhaps plunge him","into far more choler."],"id":707,"m":"You'd show more wisdom by telling the doctor this, because if I tried to purge him it might plunge him into far more anger."},{"t":"sp","who":"GUILDENSTERN","lines":["Good my lord, put your discourse into some frame, and start not so","wildly from my affair."],"id":708,"m":"My good lord, put some order into what you say, and don't jump away so wildly from my business."},{"t":"sp","who":"HAMLET","lines":["I am tame, sir, pronounce."],"id":709,"m":"I'm tame, sir. Speak."},{"t":"sp","who":"GUILDENSTERN","lines":["The Queen your mother, in most great affliction of spirit, hath sent me","to you."],"id":710,"m":"The Queen your mother, very upset in spirit, has sent me to you."},{"t":"sp","who":"HAMLET","lines":["You are welcome."],"id":711,"m":"You are welcome."},{"t":"sp","who":"GUILDENSTERN","lines":["Nay, good my lord, this courtesy is not of the right breed. If it shall","please you to make me a wholesome answer, I will do your mother's","commandment; if not, your pardon and my return shall be the end of my","business."],"id":712,"m":"No, my good lord, this politeness isn't the right kind. If you'll give me a sensible answer, I'll carry out your mother's order. If not, I'll beg your pardon and go back, and that will be the end of my business."},{"t":"sp","who":"HAMLET","lines":["Sir, I cannot."],"id":713,"m":"Sir, I can't."},{"t":"sp","who":"GUILDENSTERN","lines":["What, my lord?"],"id":714,"m":"Can't what, my lord?"},{"t":"sp","who":"HAMLET","lines":["Make you a wholesome answer. My wit's diseased. But, sir, such answer","as I can make, you shall command; or rather, as you say, my mother.","Therefore no more, but to the matter. My mother, you say,—"],"id":715,"m":"Give you a sensible answer. My mind is diseased. But, sir, whatever answer I can give, you can have, or rather, as you say, my mother can. So no more of this, let's get to the point. My mother, you say—"},{"t":"sp","who":"ROSENCRANTZ","lines":["Then thus she says: your behaviour hath struck her into amazement and","admiration."],"id":716,"m":"Then this is what she says: your behaviour has astonished and amazed her."},{"t":"sp","who":"HAMLET","lines":["O wonderful son, that can so stonish a mother! But is there no sequel","at the heels of this mother's admiration?"],"id":717,"m":"Oh, what a wonderful son, who can so astonish a mother! But is there nothing following on the heels of this mother's amazement? Tell me."},{"t":"sp","who":"ROSENCRANTZ","lines":["She desires to speak with you in her closet ere you go to bed."],"id":718,"m":"She wants to speak to you in her private room before you go to bed."},{"t":"sp","who":"HAMLET","lines":["We shall obey, were she ten times our mother. Have you any further","trade with us?"],"id":719,"m":"We'll obey, even if she were our mother ten times over. Do you have any more business with us?"},{"t":"sp","who":"ROSENCRANTZ","lines":["My lord, you once did love me."],"id":720,"m":"My lord, you once loved me."},{"t":"sp","who":"HAMLET","lines":["And so I do still, by these pickers and stealers."],"id":721,"m":"And I still do, by these thieving hands."},{"t":"sp","who":"ROSENCRANTZ","lines":["Good my lord, what is your cause of distemper? You do surely bar the","door upon your own liberty if you deny your griefs to your friend."],"id":722,"m":"My good lord, what is the cause of your illness? You are certainly shutting the door on your own freedom if you won't tell your friend what is troubling you."},{"t":"sp","who":"HAMLET","lines":["Sir, I lack advancement."],"id":723,"m":"Sir, I'm not getting promotion."},{"t":"sp","who":"ROSENCRANTZ","lines":["How can that be, when you have the voice of the King himself for your","succession in Denmark?"],"id":724,"m":"How can that be, when you have the King's own word that you'll succeed him on the throne of Denmark?"},{"t":"sp","who":"HAMLET","lines":["Ay, sir, but while the grass grows—the proverb is something musty."],"id":725,"m":"Yes, sir, but 'while the grass grows...' The proverb is a bit stale."},{"t":"sd","text":"Re-enter the Players with recorders.","id":726},{"t":"sp","who":"HAMLET","cont":1,"lines":["O, the recorders. Let me see one.—To withdraw with you, why do you go","about to recover the wind of me, as if you would drive me into a toil?"],"id":727,"m":"Oh, the recorders! Let me see one. To talk privately with you: why do you keep circling round to get downwind of me, as if you wanted to drive me into a net?"},{"t":"sp","who":"GUILDENSTERN","lines":["O my lord, if my duty be too bold, my love is too unmannerly."],"id":728,"m":"Oh, my lord, if my duty makes me too bold, it's because my love makes me forget my manners."},{"t":"sp","who":"HAMLET","lines":["I do not well understand that. Will you play upon this pipe?"],"id":729,"m":"I don't really understand that. Will you play this pipe?"},{"t":"sp","who":"GUILDENSTERN","lines":["My lord, I cannot."],"id":730,"m":"My lord, I can't."},{"t":"sp","who":"HAMLET","lines":["I pray you."],"id":731,"m":"Please."},{"t":"sp","who":"GUILDENSTERN","lines":["Believe me, I cannot."],"id":732,"m":"Believe me, I can't."},{"t":"sp","who":"HAMLET","lines":["I do beseech you."],"id":733,"m":"I beg you."},{"t":"sp","who":"GUILDENSTERN","lines":["I know no touch of it, my lord."],"id":734,"m":"I don't know how to play it at all, my lord."},{"t":"sp","who":"HAMLET","lines":["'Tis as easy as lying: govern these ventages with your finger and","thumb, give it breath with your mouth, and it will discourse most","eloquent music. Look you, these are the stops."],"id":735,"m":"It's as easy as lying. Control these holes with your fingers and thumb, blow into it with your mouth, and it will make the most eloquent music. Look, these are the stops."},{"t":"sp","who":"GUILDENSTERN","lines":["But these cannot I command to any utterance of harmony. I have not the","skill."],"id":736,"m":"But I can't make them play any tune. I don't have the skill."},{"t":"sp","who":"HAMLET","lines":["Why, look you now, how unworthy a thing you make of me! You would play","upon me; you would seem to know my stops; you would pluck out the heart","of my mystery; you would sound me from my lowest note to the top of my","compass; and there is much music, excellent voice, in this little","organ, yet cannot you make it speak. 'Sblood, do you think I am easier","to be played on than a pipe? Call me what instrument you will, though","you can fret me, you cannot play upon me."],"id":737,"m":"Why, look now how worthless you think I am! You would play on me. You act as if you know my stops. You want to pluck out the heart of my secret. You would sound me from my lowest note to the top of my range. And there is a lot of music, an excellent voice, in this little instrument, yet you can't make it speak. By God's blood, do you think I'm easier to play on than a pipe? Call me whatever instrument you like: though you can fret me, you can't play on me."},{"t":"sd","text":"Enter Polonius.","id":738},{"t":"sp","who":"HAMLET","cont":1,"lines":["God bless you, sir."],"id":739,"m":"God bless you, sir."},{"t":"sp","who":"POLONIUS","lines":["My lord, the Queen would speak with you, and presently."],"id":740,"m":"My lord, the Queen wants to speak to you, at once."},{"t":"sp","who":"HAMLET","lines":["Do you see yonder cloud that's almost in shape of a camel?"],"id":741,"m":"Do you see that cloud there that's almost in the shape of a camel?"},{"t":"sp","who":"POLONIUS","lines":["By the mass, and 'tis like a camel indeed."],"id":742,"m":"By the Mass, it does look like a camel."},{"t":"sp","who":"HAMLET","lines":["Methinks it is like a weasel."],"id":743,"m":"I think it looks like a weasel."},{"t":"sp","who":"POLONIUS","lines":["It is backed like a weasel."],"id":744,"m":"It has a back like a weasel."},{"t":"sp","who":"HAMLET","lines":["Or like a whale."],"id":745,"m":"Or like a whale."},{"t":"sp","who":"POLONIUS","lines":["Very like a whale."],"id":746,"m":"Very like a whale."},{"t":"sp","who":"HAMLET","lines":["Then will I come to my mother by and by.—They fool me to the top of my","bent.—I will come by and by."],"id":747,"m":"Then I'll come to my mother soon. [Aside] They humour my madness to the limit. I'll come soon."},{"t":"sp","who":"POLONIUS","lines":["I will say so."],"id":748,"m":"I'll tell her so."},{"t":"sd","text":"Exit","id":749},{"t":"sp","who":"HAMLET","lines":["By and by is easily said. Leave me, friends."],"id":750,"m":"'Soon' is easily said. Leave me, friends."},{"t":"sd","text":"Exeunt all but Hamlet","id":751},{"t":"sp","who":"HAMLET","cont":1,"lines":["'Tis now the very witching time of night,","When churchyards yawn, and hell itself breathes out","Contagion to this world. Now could I drink hot blood,","And do such bitter business as the day","Would quake to look on. Soft now, to my mother.","O heart, lose not thy nature; let not ever","The soul of Nero enter this firm bosom:","Let me be cruel, not unnatural.","I will speak daggers to her, but use none;","My tongue and soul in this be hypocrites.","How in my words somever she be shent,","To give them seals never, my soul, consent."],"id":752,"m":"Now it's the very time of night when witches work, when churchyards open and hell itself breathes out disease into this world. Now I could drink hot blood, and do such cruel things that the day would tremble to see them. Quiet now, I must go to my mother. Oh, heart, don't lose your natural feeling. Never let the soul of Nero, who killed his mother, enter this firm heart. Let me be cruel, but not unnatural. I'll speak daggers to her, but use none. Let my tongue and soul be hypocrites in this: however much my words shame her, my soul, never agree to turn them into actions."},{"t":"sd","text":"Exit","id":753},{"t":"scene","act":3,"scene":"III","loc":"A room in the Castle.","id":754},{"t":"sd","text":"Enter King, Rosencrantz and Guildenstern.","id":755},{"t":"sp","who":"CLAUDIUS","lines":["I like him not, nor stands it safe with us","To let his madness range. Therefore prepare you,","I your commission will forthwith dispatch,","And he to England shall along with you.","The terms of our estate may not endure","Hazard so near us as doth hourly grow","Out of his lunacies."],"id":756,"m":"I don't like him, and it isn't safe for us to let his madness run free. So get ready. I'll have your orders drawn up at once, and he will go to England with you. My position as king can't put up with dangers so close to us, which grow every hour out of his madness."},{"t":"sp","who":"GUILDENSTERN","lines":["We will ourselves provide.","Most holy and religious fear it is","To keep those many many bodies safe","That live and feed upon your Majesty."],"id":757,"m":"We'll get ready. It is a holy and religious concern to keep safe the many, many people who live and depend on your Majesty."},{"t":"sp","who":"ROSENCRANTZ","lines":["The single and peculiar life is bound","With all the strength and armour of the mind,","To keep itself from 'noyance; but much more","That spirit upon whose weal depend and rest","The lives of many. The cease of majesty","Dies not alone; but like a gulf doth draw","What's near it with it. It is a massy wheel","Fix'd on the summit of the highest mount,","To whose huge spokes ten thousand lesser things","Are mortis'd and adjoin'd; which when it falls,","Each small annexment, petty consequence,","Attends the boist'rous ruin. Never alone","Did the King sigh, but with a general groan."],"id":758,"m":"Every private individual is bound, with all the strength and armour of the mind, to protect himself from harm; but much more so the man on whose well-being the lives of many depend and rest. When a king dies, he doesn't die alone, but like a whirlpool drags what's near him down with him. He is a huge wheel fixed on the top of the highest mountain, with ten thousand smaller things fitted and joined to its great spokes; when it falls, every small attachment, every little thing connected to it, goes down with the noisy ruin. The King never sighs alone, but the whole nation groans with him."},{"t":"sp","who":"CLAUDIUS","lines":["Arm you, I pray you, to this speedy voyage;","For we will fetters put upon this fear,","Which now goes too free-footed."],"id":759,"m":"Prepare yourselves, please, for this quick voyage, because we will put chains on this danger, which now walks about too freely."},{"t":"sp","who":"ROSENCRANTZ AND GUILDENSTERN","lines":["We will haste us."],"id":760,"m":"We'll hurry."},{"t":"sd","text":"Exeunt Rosencrantz and Guildenstern","id":761},{"t":"sd","text":"Enter Polonius.","id":762},{"t":"sp","who":"POLONIUS","lines":["My lord, he's going to his mother's closet.","Behind the arras I'll convey myself","To hear the process. I'll warrant she'll tax him home,","And as you said, and wisely was it said,","'Tis meet that some more audience than a mother,","Since nature makes them partial, should o'erhear","The speech of vantage. Fare you well, my liege,","I'll call upon you ere you go to bed,","And tell you what I know."],"id":763,"m":"My lord, he's going to his mother's room. I'll hide myself behind the curtain to hear what happens. I promise you she'll tell him off thoroughly. And as you said, and it was wisely said, it's right that someone other than his mother, since mothers are naturally biased, should overhear what he says, from a good hiding place. Goodbye, my King. I'll come to you before you go to bed and tell you what I know."},{"t":"sp","who":"CLAUDIUS","lines":["Thanks, dear my lord."],"id":764,"m":"Thank you, my dear lord."},{"t":"sd","text":"Exit Polonius","id":765},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["O, my offence is rank, it smells to heaven;","It hath the primal eldest curse upon't,—","A brother's murder! Pray can I not,","Though inclination be as sharp as will:","My stronger guilt defeats my strong intent,","And, like a man to double business bound,","I stand in pause where I shall first begin,","And both neglect. What if this cursed hand","Were thicker than itself with brother's blood,","Is there not rain enough in the sweet heavens","To wash it white as snow? Whereto serves mercy","But to confront the visage of offence?","And what's in prayer but this twofold force,","To be forestalled ere we come to fall,","Or pardon'd being down? Then I'll look up.","My fault is past. But O, what form of prayer","Can serve my turn? Forgive me my foul murder!","That cannot be; since I am still possess'd","Of those effects for which I did the murder,—","My crown, mine own ambition, and my queen.","May one be pardon'd and retain th'offence?","In the corrupted currents of this world","Offence's gilded hand may shove by justice,","And oft 'tis seen the wicked prize itself","Buys out the law. But 'tis not so above;","There is no shuffling, there the action lies","In his true nature, and we ourselves compell'd","Even to the teeth and forehead of our faults,","To give in evidence. What then? What rests?","Try what repentance can. What can it not?","Yet what can it, when one cannot repent?","O wretched state! O bosom black as death!","O limed soul, that struggling to be free,","Art more engag'd! Help, angels! Make assay:","Bow, stubborn knees; and heart with strings of steel,","Be soft as sinews of the new-born babe.","All may be well."],"id":766,"m":"Oh, my crime is foul. It stinks all the way to heaven. It carries the first and oldest curse, Cain's curse: a brother's murder. I can't pray, though my wish to is as strong as my will. My stronger guilt defeats my strong intention, and like a man bound to do two things at once, I stand hesitating over where to begin, and do neither. What if this cursed hand were coated thicker than itself with a brother's blood? Isn't there enough rain in the sweet heavens to wash it as white as snow? What is mercy for, if not to face sin head on? And what is prayer, if not this double power: to stop us before we fall, or to pardon us once we have fallen? Then I'll look up. My crime is in the past. But oh, what kind of prayer can work for me? 'Forgive me my foul murder'? That can't be, since I still have all the things I murdered for: my crown, my own ambition and my queen. Can a man be pardoned and keep what he gained from the crime? In the corrupt ways of this world, the gold-covered hand of crime can push justice aside, and often the stolen profits themselves are used to buy off the law. But it isn't like that in heaven. There's no trickery there; there the deed is seen as it really is, and we ourselves are forced to give evidence against our own faults, face to face. What then? What's left? Try what repentance can do. What can't it do? But what can it do when someone cannot repent? Oh, wretched state! Oh, heart as black as death! Oh, trapped soul, that struggles to be free and only gets more stuck! Help, angels! Make an effort. Bend, stubborn knees, and heart, with your strings of steel, be as soft as the muscles of a newborn baby! All may be well."},{"t":"sd","text":"Retires and kneels","id":767},{"t":"sd","text":"Enter Hamlet.","id":768},{"t":"sp","who":"HAMLET","lines":["Now might I do it pat, now he is praying.","And now I'll do't. And so he goes to heaven;","And so am I reveng'd. That would be scann'd:","A villain kills my father, and for that","I, his sole son, do this same villain send","To heaven. O, this is hire and salary, not revenge.","He took my father grossly, full of bread,","With all his crimes broad blown, as flush as May;","And how his audit stands, who knows save heaven?","But in our circumstance and course of thought,","'Tis heavy with him. And am I then reveng'd,","To take him in the purging of his soul,","When he is fit and season'd for his passage? No.","Up, sword, and know thou a more horrid hent:","When he is drunk asleep; or in his rage,","Or in th'incestuous pleasure of his bed,","At gaming, swearing; or about some act","That has no relish of salvation in't,","Then trip him, that his heels may kick at heaven,","And that his soul may be as damn'd and black","As hell, whereto it goes. My mother stays.","This physic but prolongs thy sickly days."],"id":769,"m":"Now I could do it easily, now he's praying. And now I'll do it. And so he goes to heaven, and so I'm revenged. That needs thinking about. A villain kills my father, and for that I, his only son, send this same villain to heaven. Oh, this is like doing him a paid favour, not revenge. He killed my father when he was full of food and unprepared, with all his sins in full bloom, as lush as May. And how his account stands, who knows except heaven? But as far as we can see and think, it goes badly for him. And am I then revenged, if I kill this man while he is cleansing his soul, when he is ready and prepared for his journey? No. Back in your sheath, sword, and wait for a more horrible occasion: when he is asleep drunk, or in a rage, or enjoying the incestuous pleasures of his bed, gambling, swearing, or doing something that has no hint of salvation in it. Then trip him up, so that his heels kick at heaven and his soul is as damned and black as hell, where it is going. My mother is waiting. This medicine of prayer only lengthens your sick life."},{"t":"sd","text":"Exit","id":770},{"t":"sd","text":"The King rises and advances.","id":771},{"t":"sp","who":"CLAUDIUS","lines":["My words fly up, my thoughts remain below.","Words without thoughts never to heaven go."],"id":772,"m":"My words fly up to heaven, but my thoughts stay down here. Words without real feeling never get to heaven."},{"t":"sd","text":"Exit","id":773},{"t":"scene","act":3,"scene":"IV","loc":"Another room in the Castle.","id":774},{"t":"sd","text":"Enter Queen and Polonius.","id":775},{"t":"sp","who":"POLONIUS","lines":["He will come straight. Look you lay home to him,","Tell him his pranks have been too broad to bear with,","And that your Grace hath screen'd and stood between","Much heat and him. I'll silence me e'en here.","Pray you be round with him."],"id":776,"m":"He'll come straight away. Make sure you tell him off thoroughly. Tell him his pranks have been too outrageous to put up with, and that your Grace has protected him and stood between him and a lot of anger. I'll hide and be quiet right here. Please, be blunt with him."},{"t":"sp","who":"HAMLET","lines":["[Within] Mother, mother, mother."],"id":777,"m":"[Within] Mother, mother, mother!"},{"t":"sp","who":"GERTRUDE","lines":["I'll warrant you, Fear me not.","Withdraw, I hear him coming."],"id":778,"m":"I promise you. Don't worry about me. Hide, I can hear him coming."},{"t":"sd","text":"Polonius goes behind the arras","id":779},{"t":"sd","text":"Enter Hamlet.","id":780},{"t":"sp","who":"HAMLET","lines":["Now, mother, what's the matter?"],"id":781,"m":"Now, mother, what's the matter?"},{"t":"sp","who":"GERTRUDE","lines":["Hamlet, thou hast thy father much offended."],"id":782,"m":"Hamlet, you have offended your father very much."},{"t":"sp","who":"HAMLET","lines":["Mother, you have my father much offended."],"id":783,"m":"Mother, you have offended my father very much."},{"t":"sp","who":"GERTRUDE","lines":["Come, come, you answer with an idle tongue."],"id":784,"m":"Come, come, you answer with a foolish tongue."},{"t":"sp","who":"HAMLET","lines":["Go, go, you question with a wicked tongue."],"id":785,"m":"Go, go, you question with a wicked tongue."},{"t":"sp","who":"GERTRUDE","lines":["Why, how now, Hamlet?"],"id":786,"m":"Why, what's this, Hamlet?"},{"t":"sp","who":"HAMLET","lines":["What's the matter now?"],"id":787,"m":"What's the matter now?"},{"t":"sp","who":"GERTRUDE","lines":["Have you forgot me?"],"id":788,"m":"Have you forgotten who I am?"},{"t":"sp","who":"HAMLET","lines":["No, by the rood, not so.","You are the Queen, your husband's brother's wife,","And, would it were not so. You are my mother."],"id":789,"m":"No, by the cross, not at all. You are the Queen, your husband's brother's wife, and, I wish it weren't so, you are my mother."},{"t":"sp","who":"GERTRUDE","lines":["Nay, then I'll set those to you that can speak."],"id":790,"m":"Well, then I'll send people to you who can speak to you properly."},{"t":"sp","who":"HAMLET","lines":["Come, come, and sit you down, you shall not budge.","You go not till I set you up a glass","Where you may see the inmost part of you."],"id":791,"m":"Come, come, sit down. You won't move. You're not going until I've set up a mirror where you can see the innermost part of yourself."},{"t":"sp","who":"GERTRUDE","lines":["What wilt thou do? Thou wilt not murder me?","Help, help, ho!"],"id":792,"m":"What are you going to do? You won't murder me? Help, help, ho!"},{"t":"sp","who":"POLONIUS","lines":["[Behind] What, ho! help, help, help!"],"id":793,"m":"[Behind] What, ho! Help, help, help!"},{"t":"sp","who":"HAMLET","lines":["How now? A rat? [Draws]","Dead for a ducat, dead!"],"id":794,"m":"What's this? A rat? [Draws] Dead, I bet a ducat, dead!"},{"t":"sd","text":"Makes a pass through the arras","id":795},{"t":"sp","who":"POLONIUS","lines":["[Behind] O, I am slain!"],"id":796,"m":"[Behind] Oh, I'm killed!"},{"t":"sd","text":"Falls and dies","id":797},{"t":"sp","who":"GERTRUDE","lines":["O me, what hast thou done?"],"id":798,"m":"Oh no, what have you done?"},{"t":"sp","who":"HAMLET","lines":["Nay, I know not. Is it the King?"],"id":799,"m":"No, I don't know. Is it the King?"},{"t":"sd","text":"Draws forth Polonius","id":800},{"t":"sp","who":"GERTRUDE","lines":["O what a rash and bloody deed is this!"],"id":801,"m":"Oh, what a rash and bloody deed this is!"},{"t":"sp","who":"HAMLET","lines":["A bloody deed. Almost as bad, good mother,","As kill a king and marry with his brother."],"id":802,"m":"A bloody deed. Almost as bad, good mother, as killing a king and marrying his brother."},{"t":"sp","who":"GERTRUDE","lines":["As kill a king?"],"id":803,"m":"As killing a king?"},{"t":"sp","who":"HAMLET","lines":["Ay, lady, 'twas my word.—","[To Polonius] Thou wretched, rash, intruding fool, farewell!","I took thee for thy better. Take thy fortune,","Thou find'st to be too busy is some danger.—","Leave wringing of your hands. Peace, sit you down,","And let me wring your heart, for so I shall,","If it be made of penetrable stuff;","If damned custom have not braz'd it so,","That it is proof and bulwark against sense."],"id":804,"m":"Yes, lady, that's what I said. [To Polonius] You wretched, rash, interfering fool, goodbye! I took you for your superior. Accept your fate. You've found out that being too busy is dangerous. Stop wringing your hands. Quiet, sit down, and let me wring your heart instead, because I will, if it's made of anything that can be pierced, if damned habit hasn't turned it to brass so that it's armoured and defended against all feeling."},{"t":"sp","who":"GERTRUDE","lines":["What have I done, that thou dar'st wag thy tongue","In noise so rude against me?"],"id":805,"m":"What have I done, that you dare to wag your tongue so rudely against me?"},{"t":"sp","who":"HAMLET","lines":["Such an act","That blurs the grace and blush of modesty,","Calls virtue hypocrite, takes off the rose","From the fair forehead of an innocent love,","And sets a blister there. Makes marriage vows","As false as dicers' oaths. O such a deed","As from the body of contraction plucks","The very soul, and sweet religion makes","A rhapsody of words. Heaven's face doth glow,","Yea this solidity and compound mass,","With tristful visage, as against the doom,","Is thought-sick at the act."],"id":806,"m":"Such a deed that it stains the grace and the blush of modesty, calls virtue a hypocrite, takes the rose from the fair forehead of innocent love and puts a brand there; makes wedding vows as false as gamblers' oaths. Oh, such a deed as plucks the very soul out of the marriage contract, and turns sweet religion into a jumble of words. Heaven's face is blushing, and yes, this solid earth, with a sad face as if Judgement Day were coming, is sick at the thought of the deed."},{"t":"sp","who":"GERTRUDE","lines":["Ay me, what act,","That roars so loud, and thunders in the index?"],"id":807,"m":"Oh, what deed is this, that roars so loudly and thunders even in its introduction?"},{"t":"sp","who":"HAMLET","lines":["Look here upon this picture, and on this,","The counterfeit presentment of two brothers.","See what a grace was seated on this brow,","Hyperion's curls, the front of Jove himself,","An eye like Mars, to threaten and command,","A station like the herald Mercury","New lighted on a heaven-kissing hill:","A combination and a form indeed,","Where every god did seem to set his seal,","To give the world assurance of a man.","This was your husband. Look you now what follows.","Here is your husband, like a mildew'd ear","Blasting his wholesome brother. Have you eyes?","Could you on this fair mountain leave to feed,","And batten on this moor? Ha! have you eyes?","You cannot call it love; for at your age","The hey-day in the blood is tame, it's humble,","And waits upon the judgement: and what judgement","Would step from this to this? Sense sure you have,","Else could you not have motion; but sure that sense","Is apoplex'd, for madness would not err","Nor sense to ecstacy was ne'er so thrall'd","But it reserv'd some quantity of choice","To serve in such a difference. What devil was't","That thus hath cozen'd you at hoodman-blind?","Eyes without feeling, feeling without sight,","Ears without hands or eyes, smelling sans all,","Or but a sickly part of one true sense","Could not so mope. O shame! where is thy blush?","Rebellious hell,","If thou canst mutine in a matron's bones,","To flaming youth let virtue be as wax,","And melt in her own fire. Proclaim no shame","When the compulsive ardour gives the charge,","Since frost itself as actively doth burn,","And reason panders will."],"id":808,"m":"Look here at this picture, and at this one, the painted likenesses of two brothers. See what grace was in this face: the curls of the sun god Hyperion, the forehead of Jove himself, an eye like Mars, the god of war, to threaten and command, a stance like the messenger god Mercury just landed on a hill that kisses the sky; a combination and a shape indeed where every god seemed to put his stamp, to show the world what a real man is. This was your husband. Look now at what comes next. Here is your husband, like a diseased ear of corn infecting his healthy brother. Do you have eyes? Could you stop feeding on this fine mountain and gorge yourself on this barren moor? Ha! Do you have eyes? You can't call it love, because at your age the excitement in the blood is tamed, it's humble, and it obeys judgement. And what judgement would step down from this to this? You must have senses, or you couldn't move. But those senses must be paralysed, because even madness wouldn't make that mistake, and the senses were never so enslaved by madness that they didn't keep some power of choice to see such a difference. What devil tricked you like this in a game of blind man's buff? Eyes without touch, touch without sight, ears without hands or eyes, smell without anything else, even one sickly part of a single true sense could not be so stupid. Oh, shame! Where is your blush? Rebellious hell, if you can stir up revolt in a middle-aged woman's bones, then let virtue be like wax for passionate youth and melt in its own fire. Don't call it shameful when hot young desire attacks, since frost itself burns just as fiercely, and reason acts as a pimp for lust."},{"t":"sp","who":"GERTRUDE","lines":["O Hamlet, speak no more.","Thou turn'st mine eyes into my very soul,","And there I see such black and grained spots","As will not leave their tinct."],"id":809,"m":"Oh, Hamlet, say no more! You turn my eyes inward to my very soul, and there I see such black, deep-dyed stains that will never lose their colour."},{"t":"sp","who":"HAMLET","lines":["Nay, but to live","In the rank sweat of an enseamed bed,","Stew'd in corruption, honeying and making love","Over the nasty sty."],"id":810,"m":"No, but to live in the stinking sweat of a greasy bed, stewed in corruption, sweet-talking and making love in the filthy pigsty—"},{"t":"sp","who":"GERTRUDE","lines":["O speak to me no more;","These words like daggers enter in mine ears;","No more, sweet Hamlet."],"id":811,"m":"Oh, say no more to me! These words go into my ears like daggers. No more, sweet Hamlet!"},{"t":"sp","who":"HAMLET","lines":["A murderer and a villain;","A slave that is not twentieth part the tithe","Of your precedent lord. A vice of kings,","A cutpurse of the empire and the rule,","That from a shelf the precious diadem stole","And put it in his pocket!"],"id":812,"m":"A murderer and a villain, a slave who is not a twentieth of a tenth of your previous husband, a clown of a king, a pickpocket of the empire and its power, who stole the precious crown from a shelf and put it in his pocket!"},{"t":"sp","who":"GERTRUDE","lines":["No more."],"id":813,"m":"No more!"},{"t":"sp","who":"HAMLET","lines":["A king of shreds and patches!—"],"id":814,"m":"A king of rags and patches!"},{"t":"sd","text":"Enter Ghost.","id":815},{"t":"sp","who":"HAMLET","cont":1,"lines":["Save me and hover o'er me with your wings,","You heavenly guards! What would your gracious figure?"],"id":816,"m":"Save me and spread your wings over me, you heavenly guards! What does your gracious figure want?"},{"t":"sp","who":"GERTRUDE","lines":["Alas, he's mad."],"id":817,"m":"Oh no, he's mad!"},{"t":"sp","who":"HAMLET","lines":["Do you not come your tardy son to chide,","That, laps'd in time and passion, lets go by","The important acting of your dread command?","O say!"],"id":818,"m":"Haven't you come to scold your slow son, who has let time and passion slip by and fails to carry out your terrible command? Oh, say!"},{"t":"sp","who":"GHOST","lines":["Do not forget. This visitation","Is but to whet thy almost blunted purpose.","But look, amazement on thy mother sits.","O step between her and her fighting soul.","Conceit in weakest bodies strongest works.","Speak to her, Hamlet."],"id":819,"m":"Don't forget. This visit is only to sharpen your purpose, which is almost blunted. But look, your mother is overwhelmed with amazement. Oh, step in between her and her struggling soul. Imagination works most strongly on the weakest bodies. Speak to her, Hamlet."},{"t":"sp","who":"HAMLET","lines":["How is it with you, lady?"],"id":820,"m":"How are you, lady?"},{"t":"sp","who":"GERTRUDE","lines":["Alas, how is't with you,","That you do bend your eye on vacancy,","And with the incorporal air do hold discourse?","Forth at your eyes your spirits wildly peep,","And, as the sleeping soldiers in the alarm,","Your bedded hairs, like life in excrements,","Start up and stand an end. O gentle son,","Upon the heat and flame of thy distemper","Sprinkle cool patience. Whereon do you look?"],"id":821,"m":"Oh, how are you, that you stare at empty space and hold a conversation with the bodiless air? Your spirits peep wildly out of your eyes, and your hair, which was lying flat, jumps up and stands on end as if it were alive, like sleeping soldiers when the alarm sounds. Oh, gentle son, sprinkle cool patience on the heat and flame of your illness. What are you looking at?"},{"t":"sp","who":"HAMLET","lines":["On him, on him! Look you how pale he glares,","His form and cause conjoin'd, preaching to stones,","Would make them capable.—Do not look upon me,","Lest with this piteous action you convert","My stern effects. Then what I have to do","Will want true colour; tears perchance for blood."],"id":822,"m":"At him, at him! Look how pale he is, staring! His appearance and his cause together could make stones listen if he preached to them. Don't look at me, in case this pitiful look of yours turns my stern purpose aside. Then what I have to do won't be done in its true colour: tears, perhaps, instead of blood."},{"t":"sp","who":"GERTRUDE","lines":["To whom do you speak this?"],"id":823,"m":"Who are you saying this to?"},{"t":"sp","who":"HAMLET","lines":["Do you see nothing there?"],"id":824,"m":"Don't you see anything there?"},{"t":"sp","who":"GERTRUDE","lines":["Nothing at all; yet all that is I see."],"id":825,"m":"Nothing at all, and yet I see everything that's there."},{"t":"sp","who":"HAMLET","lines":["Nor did you nothing hear?"],"id":826,"m":"And didn't you hear anything?"},{"t":"sp","who":"GERTRUDE","lines":["No, nothing but ourselves."],"id":827,"m":"No, nothing except ourselves."},{"t":"sp","who":"HAMLET","lines":["Why, look you there! look how it steals away!","My father, in his habit as he liv'd!","Look where he goes even now out at the portal."],"id":828,"m":"Why, look there! Look how it creeps away! My father, in the clothes he wore when he was alive! Look, he's going out through the door right now!"},{"t":"sd","text":"Exit Ghost","id":829},{"t":"sp","who":"GERTRUDE","lines":["This is the very coinage of your brain.","This bodiless creation ecstasy","Is very cunning in."],"id":830,"m":"This is just something your brain has made up. Madness is very skilful at inventing ghosts like this."},{"t":"sp","who":"HAMLET","lines":["Ecstasy!","My pulse as yours doth temperately keep time,","And makes as healthful music. It is not madness","That I have utter'd. Bring me to the test,","And I the matter will re-word; which madness","Would gambol from. Mother, for love of grace,","Lay not that flattering unction to your soul","That not your trespass, but my madness speaks.","It will but skin and film the ulcerous place,","Whilst rank corruption, mining all within,","Infects unseen. Confess yourself to heaven,","Repent what's past, avoid what is to come;","And do not spread the compost on the weeds,","To make them ranker. Forgive me this my virtue;","For in the fatness of these pursy times","Virtue itself of vice must pardon beg,","Yea, curb and woo for leave to do him good."],"id":831,"m":"Madness! My pulse beats as steadily as yours and makes just as healthy a music. It isn't madness that I have spoken. Test me, and I'll repeat everything I said word for word, which madness would leap away from. Mother, for the love of God, don't put that comforting ointment on your soul, telling yourself it is my madness speaking and not your sin. It will only put a skin over the infected place while foul corruption eats away everything inside it unseen. Confess yourself to heaven. Repent what is past. Avoid what is to come, and don't spread manure on the weeds to make them grow stronger. Forgive me for my virtue, because in these fat, bloated times virtue itself has to beg vice for pardon, yes, bow and beg for permission to do it good."},{"t":"sp","who":"GERTRUDE","lines":["O Hamlet, thou hast cleft my heart in twain."],"id":832,"m":"Oh, Hamlet, you have split my heart in two."},{"t":"sp","who":"HAMLET","lines":["O throw away the worser part of it,","And live the purer with the other half.","Good night. But go not to mine uncle's bed.","Assume a virtue, if you have it not.","That monster custom, who all sense doth eat,","Of habits evil, is angel yet in this,","That to the use of actions fair and good","He likewise gives a frock or livery","That aptly is put on. Refrain tonight,","And that shall lend a kind of easiness","To the next abstinence. The next more easy;","For use almost can change the stamp of nature,","And either curb the devil, or throw him out","With wondrous potency. Once more, good night,","And when you are desirous to be bles'd,","I'll blessing beg of you. For this same lord","[Pointing to Polonius]","I do repent; but heaven hath pleas'd it so,","To punish me with this, and this with me,","That I must be their scourge and minister.","I will bestow him, and will answer well","The death I gave him. So again, good night.","I must be cruel, only to be kind:","Thus bad begins, and worse remains behind.","One word more, good lady."],"id":833,"m":"Oh, throw away the worse part of it, and live more purely with the other half. Good night. But don't go to my uncle's bed. Act as if you are virtuous, even if you aren't. That monster habit, which eats up all awareness of evil habits, is still an angel in this way: it also gives us a uniform for good and fair actions that fits easily. Hold back tonight, and that will make the next time you hold back a bit easier; the next time easier still, because habit can almost change our nature, and either control the devil or throw him out with wonderful power. Once more, good night, and when you want to be blessed by God, I'll ask you to bless me. [Pointing to Polonius] As for this lord, I'm sorry. But heaven has chosen to punish me with this and him with me, so that I must be heaven's whip and its agent. I'll get rid of the body and take responsibility for killing him. So again, good night. I must be cruel only to be kind. This is a bad beginning, and worse is still to come. One more word, good lady."},{"t":"sp","who":"GERTRUDE","lines":["What shall I do?"],"id":834,"m":"What should I do?"},{"t":"sp","who":"HAMLET","lines":["Not this, by no means, that I bid you do:","Let the bloat King tempt you again to bed,","Pinch wanton on your cheek, call you his mouse,","And let him, for a pair of reechy kisses,","Or paddling in your neck with his damn'd fingers,","Make you to ravel all this matter out,","That I essentially am not in madness,","But mad in craft. 'Twere good you let him know,","For who that's but a queen, fair, sober, wise,","Would from a paddock, from a bat, a gib,","Such dear concernings hide? Who would do so?","No, in despite of sense and secrecy,","Unpeg the basket on the house's top,","Let the birds fly, and like the famous ape,","To try conclusions, in the basket creep","And break your own neck down."],"id":835,"m":"Certainly not what I tell you to do: let the bloated King tempt you to bed again, pinch your cheek lustfully, call you his mouse, and for a couple of stinking kisses, or by fondling your neck with his damned fingers, get you to reveal all this, that I am not really mad, only mad on purpose. It would be good to let him know, because what queen, who is beautiful, sensible and wise, would hide such important matters from a toad, a bat, a tomcat? Who would do that? No, forget sense and secrecy: open the basket on the roof, let the birds fly out, and, like the famous ape, climb into the basket to test it and fall and break your own neck."},{"t":"sp","who":"GERTRUDE","lines":["Be thou assur'd, if words be made of breath,","And breath of life, I have no life to breathe","What thou hast said to me."],"id":836,"m":"You can be sure, if words are made of breath and breath of life, that I have no life to breathe what you have said to me."},{"t":"sp","who":"HAMLET","lines":["I must to England, you know that?"],"id":837,"m":"I must go to England. Do you know that?"},{"t":"sp","who":"GERTRUDE","lines":["Alack,","I had forgot. 'Tis so concluded on."],"id":838,"m":"Oh no, I had forgotten. It's been decided."},{"t":"sp","who":"HAMLET","lines":["There's letters seal'd: and my two schoolfellows,","Whom I will trust as I will adders fang'd,—","They bear the mandate, they must sweep my way","And marshal me to knavery. Let it work;","For 'tis the sport to have the enginer","Hoist with his own petard, and 't shall go hard","But I will delve one yard below their mines","And blow them at the moon. O, 'tis most sweet,","When in one line two crafts directly meet.","This man shall set me packing.","I'll lug the guts into the neighbour room.","Mother, good night. Indeed, this counsellor","Is now most still, most secret, and most grave,","Who was in life a foolish prating knave.","Come, sir, to draw toward an end with you.","Good night, mother."],"id":839,"m":"There are sealed letters, and my two schoolfellows, whom I'll trust as much as poisonous snakes, carry the orders. They are to clear the way for me and lead me into some trap. Let it happen, because it's fun to see the bomb-maker blown up with his own bomb. It will be hard luck if I don't dig a yard under their tunnels and blow them up to the moon. Oh, it's very sweet when two plots meet head on. This man will make me pack up and leave in a hurry. I'll drag the guts into the next room. Mother, good night. This adviser really is very still now, very secretive and very serious, who in life was a foolish, chattering rogue. Come, sir, let's finish with you. Good night, mother."},{"t":"sd","text":"Exit Hamlet dragging out Polonius","id":840},{"t":"scene","act":4,"scene":"I","loc":"A room in the Castle.","id":841},{"t":"sd","text":"Enter King, Queen, Rosencrantz and Guildenstern.","id":842},{"t":"sp","who":"CLAUDIUS","lines":["There's matter in these sighs. These profound heaves","You must translate; 'tis fit we understand them.","Where is your son?"],"id":843,"m":"There's something behind these sighs. You must explain these deep heavings; it's right that we understand them. Where is your son?"},{"t":"sp","who":"GERTRUDE","lines":["Bestow this place on us a little while."],"id":844,"m":"Leave us alone here for a little while."},{"t":"sd","text":"To Rosencrantz and Guildenstern, who go out","id":845},{"t":"sp","who":"GERTRUDE","cont":1,"lines":["Ah, my good lord, what have I seen tonight!"],"id":846,"m":"Oh, my good lord, what I have seen tonight!"},{"t":"sp","who":"CLAUDIUS","lines":["What, Gertrude? How does Hamlet?"],"id":847,"m":"What, Gertrude? How is Hamlet?"},{"t":"sp","who":"GERTRUDE","lines":["Mad as the sea and wind, when both contend","Which is the mightier. In his lawless fit","Behind the arras hearing something stir,","Whips out his rapier, cries 'A rat, a rat!'","And in this brainish apprehension kills","The unseen good old man."],"id":848,"m":"As mad as the sea and the wind when they are fighting over which is stronger. In his wild fit, hearing something move behind the curtain, he whips out his sword and shouts 'A rat, a rat!', and in this crazed imagining he kills the good old man he couldn't see."},{"t":"sp","who":"CLAUDIUS","lines":["O heavy deed!","It had been so with us, had we been there.","His liberty is full of threats to all;","To you yourself, to us, to everyone.","Alas, how shall this bloody deed be answer'd?","It will be laid to us, whose providence","Should have kept short, restrain'd, and out of haunt","This mad young man. But so much was our love","We would not understand what was most fit,","But like the owner of a foul disease,","To keep it from divulging, let it feed","Even on the pith of life. Where is he gone?"],"id":849,"m":"Oh, terrible deed! It would have happened to us if we had been there. His freedom is a threat to everyone, to you yourself, to us, to all. Oh dear, how shall we explain this bloody deed? It will be blamed on us, who should have had the foresight to keep this mad young man on a short lead, restrained and away from people. But our love was so great that we wouldn't see what was the right thing to do, and like someone with a foul disease who keeps it hidden, we let it feed on the very core of life. Where has he gone?"},{"t":"sp","who":"GERTRUDE","lines":["To draw apart the body he hath kill'd,","O'er whom his very madness, like some ore","Among a mineral of metals base,","Shows itself pure. He weeps for what is done."],"id":850,"m":"To drag away the body he has killed. Over it his madness itself, like a vein of gold in a mine of worthless metals, shows that it is pure: he is weeping for what he has done."},{"t":"sp","who":"CLAUDIUS","lines":["O Gertrude, come away!","The sun no sooner shall the mountains touch","But we will ship him hence, and this vile deed","We must with all our majesty and skill","Both countenance and excuse.—Ho, Guildenstern!"],"id":851,"m":"Oh, Gertrude, come away! As soon as the sun touches the mountains, we'll ship him away from here, and we must use all our royal authority and skill both to stand behind this vile deed and to excuse it. Hey, Guildenstern!"},{"t":"sd","text":"Re-enter Rosencrantz and Guildenstern.","id":852},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["Friends both, go join you with some further aid:","Hamlet in madness hath Polonius slain,","And from his mother's closet hath he dragg'd him.","Go seek him out, speak fair, and bring the body","Into the chapel. I pray you haste in this."],"id":853,"m":"Friends, both of you go and get some more help. Hamlet in his madness has killed Polonius, and he has dragged him from his mother's room. Go and find him, speak politely to him, and bring the body into the chapel. Please hurry with this."},{"t":"sd","text":"Exeunt Rosencrantz and Guildenstern","id":854},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["Come, Gertrude, we'll call up our wisest friends,","And let them know both what we mean to do","And what's untimely done, so haply slander,","Whose whisper o'er the world's diameter,","As level as the cannon to his blank,","Transports his poison'd shot, may miss our name,","And hit the woundless air. O, come away!","My soul is full of discord and dismay."],"id":855,"m":"Come, Gertrude, we'll call together our wisest friends and tell them both what we intend to do and what has been done so unfortunately. Then perhaps slander, whose whisper carries its poisoned shot right across the world as straight as a cannon to its target, may miss our name and hit only the air, which can't be wounded. Oh, come away! My soul is full of confusion and dread."},{"t":"sd","text":"Exeunt","id":856},{"t":"scene","act":4,"scene":"II","loc":"Another room in the Castle.","id":857},{"t":"sd","text":"Enter Hamlet.","id":858},{"t":"sp","who":"HAMLET","lines":["Safely stowed."],"id":859,"m":"Safely stored away."},{"t":"sp","who":"ROSENCRANTZ AND GUILDENSTERN","lines":["[Within] Hamlet! Lord Hamlet!"],"id":860,"m":"[Within] Hamlet! Lord Hamlet!"},{"t":"sp","who":"HAMLET","lines":["What noise? Who calls on Hamlet? O, here they come."],"id":861,"m":"What's that noise? Who's calling Hamlet? Oh, here they come."},{"t":"sd","text":"Enter Rosencrantz and Guildenstern.","id":862},{"t":"sp","who":"ROSENCRANTZ","lines":["What have you done, my lord, with the dead body?"],"id":863,"m":"What have you done with the dead body, my lord?"},{"t":"sp","who":"HAMLET","lines":["Compounded it with dust, whereto 'tis kin."],"id":864,"m":"Mixed it with the dust, which it is related to."},{"t":"sp","who":"ROSENCRANTZ","lines":["Tell us where 'tis, that we may take it thence,","And bear it to the chapel."],"id":865,"m":"Tell us where it is, so that we can take it from there and carry it to the chapel."},{"t":"sp","who":"HAMLET","lines":["Do not believe it."],"id":866,"m":"Don't believe it."},{"t":"sp","who":"ROSENCRANTZ","lines":["Believe what?"],"id":867,"m":"Believe what?"},{"t":"sp","who":"HAMLET","lines":["That I can keep your counsel, and not mine own. Besides, to be demanded","of a sponge—what replication should be made by the son of a king?"],"id":868,"m":"That I can keep your secrets and not my own. Besides, to be questioned by a sponge! What answer should a king's son give to that?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Take you me for a sponge, my lord?"],"id":869,"m":"Do you take me for a sponge, my lord?"},{"t":"sp","who":"HAMLET","lines":["Ay, sir; that soaks up the King's countenance, his rewards, his","authorities. But such officers do the King best service in the end: he","keeps them, like an ape, in the corner of his jaw; first mouthed, to be","last swallowed: when he needs what you have gleaned, it is but","squeezing you, and, sponge, you shall be dry again."],"id":870,"m":"Yes, sir, one that soaks up the King's favour, his rewards, his power. But officials like you do the King the best service in the end. He keeps them in the corner of his mouth like an ape keeps food, first put in, last swallowed. When he needs what you have collected, he only has to squeeze you, and, sponge, you'll be dry again."},{"t":"sp","who":"ROSENCRANTZ","lines":["I understand you not, my lord."],"id":871,"m":"I don't understand you, my lord."},{"t":"sp","who":"HAMLET","lines":["I am glad of it. A knavish speech sleeps in a foolish ear."],"id":872,"m":"I'm glad of it. A clever, wicked speech is wasted on a foolish ear."},{"t":"sp","who":"ROSENCRANTZ","lines":["My lord, you must tell us where the body is and go with us to the King."],"id":873,"m":"My lord, you must tell us where the body is and come with us to the King."},{"t":"sp","who":"HAMLET","lines":["The body is with the King, but the King is not with the body. The King","is a thing—"],"id":874,"m":"The body is with the King, but the King isn't with the body. The King is a thing—"},{"t":"sp","who":"GUILDENSTERN","lines":["A thing, my lord!"],"id":875,"m":"A thing, my lord?"},{"t":"sp","who":"HAMLET","lines":["Of nothing. Bring me to him. Hide fox, and all after."],"id":876,"m":"Of no importance. Take me to him. Hide, fox, and everyone after him!"},{"t":"sd","text":"Exeunt","id":877},{"t":"scene","act":4,"scene":"III","loc":"Another room in the Castle.","id":878},{"t":"sd","text":"Enter King, attended.","id":879},{"t":"sp","who":"CLAUDIUS","lines":["I have sent to seek him and to find the body.","How dangerous is it that this man goes loose!","Yet must not we put the strong law on him:","He's lov'd of the distracted multitude,","Who like not in their judgement, but their eyes;","And where 'tis so, th'offender's scourge is weigh'd,","But never the offence. To bear all smooth and even,","This sudden sending him away must seem","Deliberate pause. Diseases desperate grown","By desperate appliance are reliev'd,","Or not at all."],"id":880,"m":"I've sent people to look for him and find the body. How dangerous it is that this man is free! But we mustn't use the full force of the law on him. He is loved by the confused common people, who judge by what they see, not by reason, and when that's the case, they weigh up the offender's punishment, but never the offence. To keep everything smooth and calm, sending him away suddenly like this must look like a carefully considered decision. Diseases that have become desperate can only be cured by desperate remedies, or not at all."},{"t":"sd","text":"Enter Rosencrantz.","id":881},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["How now? What hath befall'n?"],"id":882,"m":"Well? What has happened?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Where the dead body is bestow'd, my lord,","We cannot get from him."],"id":883,"m":"We can't get him to tell us where the dead body is hidden, my lord."},{"t":"sp","who":"CLAUDIUS","lines":["But where is he?"],"id":884,"m":"But where is he?"},{"t":"sp","who":"ROSENCRANTZ","lines":["Without, my lord, guarded, to know your pleasure."],"id":885,"m":"Outside, my lord, under guard, waiting to hear what you want."},{"t":"sp","who":"CLAUDIUS","lines":["Bring him before us."],"id":886,"m":"Bring him before us."},{"t":"sp","who":"ROSENCRANTZ","lines":["Ho, Guildenstern! Bring in my lord."],"id":887,"m":"Hey, Guildenstern! Bring in my lord."},{"t":"sd","text":"Enter Hamlet and Guildenstern.","id":888},{"t":"sp","who":"CLAUDIUS","lines":["Now, Hamlet, where's Polonius?"],"id":889,"m":"Now, Hamlet, where's Polonius?"},{"t":"sp","who":"HAMLET","lines":["At supper."],"id":890,"m":"At supper."},{"t":"sp","who":"CLAUDIUS","lines":["At supper? Where?"],"id":891,"m":"At supper? Where?"},{"t":"sp","who":"HAMLET","lines":["Not where he eats, but where he is eaten. A certain convocation of","politic worms are e'en at him. Your worm is your only emperor for diet.","We fat all creatures else to fat us, and we fat ourselves for maggots.","Your fat king and your lean beggar is but variable service,—two dishes,","but to one table. That's the end."],"id":892,"m":"Not where he is eating, but where he is being eaten. A certain assembly of political worms is busy with him right now. The worm is the true emperor when it comes to food. We fatten all other creatures to fatten ourselves, and we fatten ourselves for maggots. A fat king and a thin beggar are just different courses, two dishes on the same table. That's how it ends."},{"t":"sp","who":"CLAUDIUS","lines":["Alas, alas!"],"id":893,"m":"Oh dear, oh dear!"},{"t":"sp","who":"HAMLET","lines":["A man may fish with the worm that hath eat of a king, and eat of the","fish that hath fed of that worm."],"id":894,"m":"A man may go fishing with the worm that has eaten a king, and eat the fish that has fed on that worm."},{"t":"sp","who":"CLAUDIUS","lines":["What dost thou mean by this?"],"id":895,"m":"What do you mean by this?"},{"t":"sp","who":"HAMLET","lines":["Nothing but to show you how a king may go a progress through the guts","of a beggar."],"id":896,"m":"Nothing, except to show you how a king can make a royal tour through the guts of a beggar."},{"t":"sp","who":"CLAUDIUS","lines":["Where is Polonius?"],"id":897,"m":"Where is Polonius?"},{"t":"sp","who":"HAMLET","lines":["In heaven. Send thither to see. If your messenger find him not there,","seek him i' th'other place yourself. But indeed, if you find him not","within this month, you shall nose him as you go up the stairs into the","lobby."],"id":898,"m":"In heaven. Send someone there to look. If your messenger doesn't find him there, look for him in the other place yourself. But really, if you don't find him within a month, you'll smell him as you go up the stairs into the hall."},{"t":"sp","who":"CLAUDIUS","lines":["[To some Attendants] Go seek him there."],"id":899,"m":"[To some Attendants] Go and look for him there."},{"t":"sp","who":"HAMLET","lines":["He will stay till you come."],"id":900,"m":"He'll wait until you come."},{"t":"sd","text":"Exeunt Attendants","id":901},{"t":"sp","who":"CLAUDIUS","lines":["Hamlet, this deed, for thine especial safety,—","Which we do tender, as we dearly grieve","For that which thou hast done,—must send thee hence","With fiery quickness. Therefore prepare thyself;","The bark is ready, and the wind at help,","Th'associates tend, and everything is bent","For England."],"id":902,"m":"Hamlet, for your own special safety, which we care about as much as we deeply grieve over what you have done, this deed means you must leave here as fast as fire. So get ready. The ship is ready and the wind is helpful, your companions are waiting and everything is set for England."},{"t":"sp","who":"HAMLET","lines":["For England?"],"id":903,"m":"For England?"},{"t":"sp","who":"CLAUDIUS","lines":["Ay, Hamlet."],"id":904,"m":"Yes, Hamlet."},{"t":"sp","who":"HAMLET","lines":["Good."],"id":905,"m":"Good."},{"t":"sp","who":"CLAUDIUS","lines":["So is it, if thou knew'st our purposes."],"id":906,"m":"So it is, if you knew our intentions."},{"t":"sp","who":"HAMLET","lines":["I see a cherub that sees them. But, come; for England! Farewell, dear","mother."],"id":907,"m":"I see an angel who sees them. But come, off to England! Goodbye, dear mother."},{"t":"sp","who":"CLAUDIUS","lines":["Thy loving father, Hamlet."],"id":908,"m":"Your loving father, Hamlet."},{"t":"sp","who":"HAMLET","lines":["My mother. Father and mother is man and wife; man and wife is one","flesh; and so, my mother. Come, for England."],"id":909,"m":"My mother. Father and mother are man and wife, man and wife are one flesh, and so, my mother. Come, off to England!"},{"t":"sd","text":"Exit","id":910},{"t":"sp","who":"CLAUDIUS","lines":["Follow him at foot. Tempt him with speed aboard;","Delay it not; I'll have him hence tonight.","Away, for everything is seal'd and done","That else leans on th'affair. Pray you make haste."],"id":911,"m":"Follow close behind him. Get him on board quickly. Don't delay it. I want him gone tonight. Go, because everything else to do with this business is sealed and done. Please hurry."},{"t":"sd","text":"Exeunt Rosencrantz and Guildenstern","id":912},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["And England, if my love thou hold'st at aught,—","As my great power thereof may give thee sense,","Since yet thy cicatrice looks raw and red","After the Danish sword, and thy free awe","Pays homage to us,—thou mayst not coldly set","Our sovereign process, which imports at full,","By letters conjuring to that effect,","The present death of Hamlet. Do it, England;","For like the hectic in my blood he rages,","And thou must cure me. Till I know 'tis done,","Howe'er my haps, my joys were ne'er begun."],"id":913,"m":"And King of England, if you value my love at all, as my great power should make you do, since your scar from the Danish sword still looks raw and red and you pay us respect out of your own free fear, you can't ignore our royal command, which is set out fully in letters urging this: the immediate death of Hamlet. Do it, England, because he rages in my blood like a fever, and you must cure me. Until I know it's done, whatever my luck, my happiness can never begin."},{"t":"sd","text":"Exit","id":914},{"t":"scene","act":4,"scene":"IV","loc":"A plain in Denmark.","id":915},{"t":"sd","text":"Enter Fortinbras and Forces marching.","id":916},{"t":"sp","who":"FORTINBRAS","lines":["Go, Captain, from me greet the Danish king.","Tell him that by his license, Fortinbras","Craves the conveyance of a promis'd march","Over his kingdom. You know the rendezvous.","If that his Majesty would aught with us,","We shall express our duty in his eye;","And let him know so."],"id":917,"m":"Go, Captain, and greet the Danish king for me. Tell him that, with his permission, Fortinbras asks for the promised safe passage of his army across his kingdom. You know where we are to meet. If his Majesty wants anything from us, we'll pay our respects to him in person; tell him that."},{"t":"sp","who":"CAPTAIN","lines":["I will do't, my lord."],"id":918,"m":"I'll do it, my lord."},{"t":"sp","who":"FORTINBRAS","lines":["Go softly on."],"id":919,"m":"March on slowly."},{"t":"sd","text":"Exeunt all but the Captain","id":920},{"t":"sd","text":"Enter Hamlet, Rosencrantz, Guildenstern &c.","id":921},{"t":"sp","who":"HAMLET","lines":["Good sir, whose powers are these?"],"id":922,"m":"Good sir, whose army is this?"},{"t":"sp","who":"CAPTAIN","lines":["They are of Norway, sir."],"id":923,"m":"It's from Norway, sir."},{"t":"sp","who":"HAMLET","lines":["How purpos'd, sir, I pray you?"],"id":924,"m":"Where is it going, sir, may I ask?"},{"t":"sp","who":"CAPTAIN","lines":["Against some part of Poland."],"id":925,"m":"Against part of Poland."},{"t":"sp","who":"HAMLET","lines":["Who commands them, sir?"],"id":926,"m":"Who is in command, sir?"},{"t":"sp","who":"CAPTAIN","lines":["The nephew to old Norway, Fortinbras."],"id":927,"m":"The old King of Norway's nephew, Fortinbras."},{"t":"sp","who":"HAMLET","lines":["Goes it against the main of Poland, sir,","Or for some frontier?"],"id":928,"m":"Is it going against the heart of Poland, sir, or some border area?"},{"t":"sp","who":"CAPTAIN","lines":["Truly to speak, and with no addition,","We go to gain a little patch of ground","That hath in it no profit but the name.","To pay five ducats, five, I would not farm it;","Nor will it yield to Norway or the Pole","A ranker rate, should it be sold in fee."],"id":929,"m":"To tell the truth, without exaggerating, we're going to win a little patch of ground that has nothing to be gained from it except the name. I wouldn't rent it for five ducats, five. And neither Norway nor Poland would get a higher price for it if they sold it outright."},{"t":"sp","who":"HAMLET","lines":["Why, then the Polack never will defend it."],"id":930,"m":"Why, then the Poles will never defend it."},{"t":"sp","who":"CAPTAIN","lines":["Yes, it is already garrison'd."],"id":931,"m":"Yes, they will. It's already got soldiers in it."},{"t":"sp","who":"HAMLET","lines":["Two thousand souls and twenty thousand ducats","Will not debate the question of this straw!","This is th'imposthume of much wealth and peace,","That inward breaks, and shows no cause without","Why the man dies. I humbly thank you, sir."],"id":932,"m":"Two thousand lives and twenty thousand ducats won't be enough to settle the argument over this bit of straw! This is the abscess that comes from too much wealth and peace, which bursts inside and shows nothing on the outside to explain why the man dies. I humbly thank you, sir."},{"t":"sp","who":"CAPTAIN","lines":["God b' wi' you, sir."],"id":933,"m":"God be with you, sir."},{"t":"sd","text":"Exit","id":934},{"t":"sp","who":"ROSENCRANTZ","lines":["Will't please you go, my lord?"],"id":935,"m":"Will you come now, my lord?"},{"t":"sp","who":"HAMLET","lines":["I'll be with you straight. Go a little before."],"id":936,"m":"I'll be with you in a moment. Go on a little ahead."},{"t":"sd","text":"Exeunt all but Hamlet","id":937},{"t":"sp","who":"HAMLET","cont":1,"lines":["How all occasions do inform against me,","And spur my dull revenge. What is a man","If his chief good and market of his time","Be but to sleep and feed? A beast, no more.","Sure he that made us with such large discourse,","Looking before and after, gave us not","That capability and godlike reason","To fust in us unus'd. Now whether it be","Bestial oblivion, or some craven scruple","Of thinking too precisely on th'event,—","A thought which, quarter'd, hath but one part wisdom","And ever three parts coward,—I do not know","Why yet I live to say this thing's to do,","Sith I have cause, and will, and strength, and means","To do't. Examples gross as earth exhort me,","Witness this army of such mass and charge,","Led by a delicate and tender prince,","Whose spirit, with divine ambition puff'd,","Makes mouths at the invisible event,","Exposing what is mortal and unsure","To all that fortune, death, and danger dare,","Even for an eggshell. Rightly to be great","Is not to stir without great argument,","But greatly to find quarrel in a straw","When honour's at the stake. How stand I then,","That have a father kill'd, a mother stain'd,","Excitements of my reason and my blood,","And let all sleep, while to my shame I see","The imminent death of twenty thousand men","That, for a fantasy and trick of fame,","Go to their graves like beds, fight for a plot","Whereon the numbers cannot try the cause,","Which is not tomb enough and continent","To hide the slain? O, from this time forth,","My thoughts be bloody or be nothing worth."],"id":938,"m":"How everything that happens accuses me and spurs on my slow revenge! What is a man, if the main good and use of his time is only to sleep and eat? A beast, nothing more. Surely the one who made us with such a great power of reasoning, able to look forward and back, didn't give us that ability and godlike reason to go mouldy in us unused. Now, whether it is animal forgetfulness or some cowardly worry from thinking too carefully about the outcome, a thought which, cut into four, has only one part wisdom and always three parts cowardice, I don't know why I am still alive to say 'This must be done', when I have the reason, the will, the strength and the means to do it. Examples as big as the earth urge me on. Look at this army, so large and so expensive, led by a delicate, young prince whose spirit, swollen with divine ambition, pulls faces at the unknown outcome, exposing what is mortal and uncertain to everything that fortune, death and danger can do, all for an eggshell. To be truly great is not to act without a great cause, but to find a great reason to fight over a straw when honour is at stake. Where does that leave me, then, who have a murdered father and a disgraced mother, things that should rouse my reason and my passion, and yet I let it all sleep, while to my shame I see twenty thousand men about to die, who for a fantasy and a trick of fame go to their graves as if to bed, fighting for a plot of land that isn't big enough for all the armies to fight on, and isn't even a big enough tomb to hold the dead? Oh, from now on, let my thoughts be bloody, or be worth nothing!"},{"t":"sd","text":"Exit","id":939},{"t":"scene","act":4,"scene":"V","loc":"Elsinore. A room in the Castle.","id":940},{"t":"sd","text":"Enter Queen, Horatio and a Gentleman.","id":941},{"t":"sp","who":"GERTRUDE","lines":["I will not speak with her."],"id":942,"m":"I won't speak to her."},{"t":"sp","who":"GENTLEMAN","lines":["She is importunate, indeed distract.","Her mood will needs be pitied."],"id":943,"m":"She insists, and she really is out of her mind. Her state deserves pity."},{"t":"sp","who":"GERTRUDE","lines":["What would she have?"],"id":944,"m":"What does she want?"},{"t":"sp","who":"GENTLEMAN","lines":["She speaks much of her father; says she hears","There's tricks i' th' world, and hems, and beats her heart,","Spurns enviously at straws, speaks things in doubt,","That carry but half sense. Her speech is nothing,","Yet the unshaped use of it doth move","The hearers to collection; they aim at it,","And botch the words up fit to their own thoughts,","Which, as her winks, and nods, and gestures yield them,","Indeed would make one think there might be thought,","Though nothing sure, yet much unhappily.","'Twere good she were spoken with, for she may strew","Dangerous conjectures in ill-breeding minds."],"id":945,"m":"She talks a lot about her father, says she hears there is trickery in the world, coughs and beats her breast, kicks angrily at straws, and says things that are unclear and only half make sense. Her words mean nothing, and yet their confused shape makes listeners try to piece them together. They guess at her meaning and patch the words up to fit their own thoughts, and her winks, nods and gestures do make you think there might be some meaning behind them, nothing certain, but something very unhappy. It would be good to speak with her, because she may spread dangerous suspicions in minds that breed trouble."},{"t":"sp","who":"GERTRUDE","lines":["Let her come in."],"id":946,"m":"Let her come in."},{"t":"sd","text":"Exit Gentleman","id":947},{"t":"sp","who":"GERTRUDE","cont":1,"lines":["To my sick soul, as sin's true nature is,","Each toy seems prologue to some great amiss.","So full of artless jealousy is guilt,","It spills itself in fearing to be spilt."],"id":948,"m":"[Aside] To my sick soul, as is the true nature of sin, every little thing seems the start of some great disaster. Guilt is so full of clumsy suspicion that it gives itself away by being afraid of giving itself away."},{"t":"sd","text":"Enter Ophelia.","id":949},{"t":"sp","who":"OPHELIA","lines":["Where is the beauteous Majesty of Denmark?"],"id":950,"m":"Where is the beautiful Queen of Denmark?"},{"t":"sp","who":"GERTRUDE","lines":["How now, Ophelia?"],"id":951,"m":"What is it, Ophelia?"},{"t":"sp","who":"OPHELIA","lines":["[Sings]","How should I your true love know","From another one?","By his cockle hat and staff","And his sandal shoon."],"id":952,"m":"[Sings] How will I know your true love from another one? By his pilgrim's hat with its shell, his staff and his sandals."},{"t":"sp","who":"GERTRUDE","lines":["Alas, sweet lady, what imports this song?"],"id":953,"m":"Oh, sweet lady, what does this song mean?"},{"t":"sp","who":"OPHELIA","lines":["Say you? Nay, pray you mark.","[Sings]","He is dead and gone, lady,","He is dead and gone,","At his head a grass green turf,","At his heels a stone."],"id":954,"m":"What did you say? No, please listen. [Sings] He is dead and gone, lady, he is dead and gone. At his head is green turf, at his feet a stone."},{"t":"sp","who":"GERTRUDE","lines":["Nay, but Ophelia—"],"id":955,"m":"No, but Ophelia—"},{"t":"sp","who":"OPHELIA","lines":["Pray you mark.","[Sings]","White his shroud as the mountain snow."],"id":956,"m":"Please listen. [Sings] His shroud was as white as the mountain snow—"},{"t":"sd","text":"Enter King.","id":957},{"t":"sp","who":"GERTRUDE","lines":["Alas, look here, my lord!"],"id":958,"m":"Oh, look at this, my lord!"},{"t":"sp","who":"OPHELIA","lines":["[Sings]","Larded all with sweet flowers;","Which bewept to the grave did not go","With true-love showers."],"id":959,"m":"[Sings] Covered all over with sweet flowers, which went to the grave without being wept on by true love's showers of tears."},{"t":"sp","who":"CLAUDIUS","lines":["How do you, pretty lady?"],"id":960,"m":"How are you, pretty lady?"},{"t":"sp","who":"OPHELIA","lines":["Well, God dild you! They say the owl was a baker's daughter. Lord, we","know what we are, but know not what we may be. God be at your table!"],"id":961,"m":"Well, God reward you! They say the owl was a baker's daughter. Lord, we know what we are, but not what we may become. God be at your table!"},{"t":"sp","who":"CLAUDIUS","lines":["Conceit upon her father."],"id":962,"m":"She is brooding on her father."},{"t":"sp","who":"OPHELIA","lines":["Pray you, let's have no words of this; but when they ask you what it","means, say you this:","[Sings]","Tomorrow is Saint Valentine's day,","All in the morning betime,","And I a maid at your window,","To be your Valentine.","Then up he rose and donn'd his clothes,","And dupp'd the chamber door,","Let in the maid, that out a maid","Never departed more."],"id":963,"m":"Please, let's not talk about this, but when they ask you what it means, say this: [Sings] Tomorrow is Saint Valentine's Day, early in the morning, and I'm a girl at your window, to be your Valentine. Then up he got and put his clothes on, and opened the bedroom door, and let the girl in, who never left it a girl again."},{"t":"sp","who":"CLAUDIUS","lines":["Pretty Ophelia!"],"id":964,"m":"Pretty Ophelia!"},{"t":"sp","who":"OPHELIA","lines":["Indeed la, without an oath, I'll make an end on't.","[Sings]","By Gis and by Saint Charity,","Alack, and fie for shame!","Young men will do't if they come to't;","By Cock, they are to blame.","Quoth she, before you tumbled me,","You promis'd me to wed.","So would I ha' done, by yonder sun,","An thou hadst not come to my bed."],"id":965,"m":"Yes, really, without swearing, I'll finish it. [Sings] By Jesus and by holy charity, oh no, and shame on them! Young men will do it if they get the chance; by God, they are to blame. She said, 'Before you tumbled me, you promised to marry me.' He answers: 'I would have done it, by that sun up there, if you hadn't come to my bed.'"},{"t":"sp","who":"CLAUDIUS","lines":["How long hath she been thus?"],"id":966,"m":"How long has she been like this?"},{"t":"sp","who":"OPHELIA","lines":["I hope all will be well. We must be patient. But I cannot choose but","weep, to think they would lay him i' th' cold ground. My brother shall","know of it. And so I thank you for your good counsel. Come, my coach!","Good night, ladies; good night, sweet ladies; good night, good night."],"id":967,"m":"I hope all will be well. We must be patient. But I can't help crying when I think that they laid him in the cold ground. My brother will hear about it. And so I thank you for your good advice. Come, my coach! Good night, ladies. Good night, sweet ladies. Good night, good night."},{"t":"sd","text":"Exit","id":968},{"t":"sp","who":"CLAUDIUS","lines":["Follow her close; give her good watch, I pray you."],"id":969,"m":"Follow her closely. Keep a good watch on her, please."},{"t":"sd","text":"Exit Horatio","id":970},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["O, this is the poison of deep grief; it springs","All from her father's death. O Gertrude, Gertrude,","When sorrows come, they come not single spies,","But in battalions. First, her father slain;","Next, your son gone; and he most violent author","Of his own just remove; the people muddied,","Thick, and unwholesome in their thoughts and whispers","For good Polonius' death; and we have done but greenly","In hugger-mugger to inter him. Poor Ophelia","Divided from herself and her fair judgement,","Without the which we are pictures or mere beasts.","Last, and as much containing as all these,","Her brother is in secret come from France,","Feeds on his wonder, keeps himself in clouds,","And wants not buzzers to infect his ear","With pestilent speeches of his father's death,","Wherein necessity, of matter beggar'd,","Will nothing stick our person to arraign","In ear and ear. O my dear Gertrude, this,","Like to a murdering piece, in many places","Gives me superfluous death."],"id":971,"m":"Oh, this is the poison of deep grief. It all comes from her father's death. Oh, Gertrude, Gertrude, when sorrows come, they don't come like single spies, but in whole battalions. First her father killed; next your son gone, and he himself the violent cause of his own rightful exile; the people stirred up, muddy and unhealthy in their thoughts and whispers about good Polonius's death. And we have acted foolishly in burying him in secret. Poor Ophelia, cut off from herself and her good judgement, without which we are only pictures or mere animals. Last, and as serious as all of these together, her brother has come back secretly from France. He feeds on his suspicions, keeps himself hidden in clouds, and has no shortage of gossips to infect his ear with poisonous stories about his father's death, in which, since they don't know the facts, they won't hesitate to accuse me from ear to ear. Oh, my dear Gertrude, this, like a cannon firing scattered shot, hits me in many places and kills me more times than I need."},{"t":"sd","text":"A noise within","id":972},{"t":"sp","who":"GERTRUDE","lines":["Alack, what noise is this?"],"id":973,"m":"Oh no, what's that noise?"},{"t":"sp","who":"CLAUDIUS","lines":["Where are my Switzers? Let them guard the door."],"id":974,"m":"Where are my Swiss guards? Let them guard the door."},{"t":"sd","text":"Enter a Gentleman.","id":975},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["What is the matter?"],"id":976,"m":"What's the matter?"},{"t":"sp","who":"GENTLEMAN","lines":["Save yourself, my lord.","The ocean, overpeering of his list,","Eats not the flats with more impetuous haste","Than young Laertes, in a riotous head,","O'erbears your offices. The rabble call him lord,","And, as the world were now but to begin,","Antiquity forgot, custom not known,","The ratifiers and props of every word,","They cry 'Choose we! Laertes shall be king!'","Caps, hands, and tongues applaud it to the clouds,","'Laertes shall be king, Laertes king.'"],"id":977,"m":"Save yourself, my lord. The ocean, rising over its limits, doesn't swallow up the shore with more violent speed than young Laertes, at the head of a rioting crowd, is overpowering your officers. The mob call him lord, and as if the world were only just beginning, with tradition forgotten and custom unknown, though these are what confirm and support every title, they shout 'We choose! Laertes shall be king!' Caps, hands and tongues cheer it to the clouds: 'Laertes shall be king! Laertes king!'"},{"t":"sp","who":"GERTRUDE","lines":["How cheerfully on the false trail they cry.","O, this is counter, you false Danish dogs."],"id":978,"m":"How happily they bark on the wrong trail! Oh, you're running the wrong way, you false Danish dogs!"},{"t":"sd","text":"A noise within","id":979},{"t":"sp","who":"CLAUDIUS","lines":["The doors are broke."],"id":980,"m":"The doors are broken down."},{"t":"sd","text":"Enter Laertes, armed; Danes following.","id":981},{"t":"sp","who":"LAERTES","lines":["Where is this king?—Sirs, stand you all without."],"id":982,"m":"Where is this king? Sirs, all of you stay outside."},{"t":"sp","who":"DANES","lines":["No, let's come in."],"id":983,"m":"No, let us come in."},{"t":"sp","who":"LAERTES","lines":["I pray you, give me leave."],"id":984,"m":"Please, leave this to me."},{"t":"sp","who":"DANES","lines":["We will, we will."],"id":985,"m":"We will, we will."},{"t":"sd","text":"They retire without the door","id":986},{"t":"sp","who":"LAERTES","lines":["I thank you. Keep the door. O thou vile king,","Give me my father."],"id":987,"m":"Thank you. Guard the door. Oh, you vile king, give me back my father!"},{"t":"sp","who":"GERTRUDE","lines":["Calmly, good Laertes."],"id":988,"m":"Calmly, good Laertes."},{"t":"sp","who":"LAERTES","lines":["That drop of blood that's calm proclaims me bastard;","Cries cuckold to my father, brands the harlot","Even here between the chaste unsmirched brow","Of my true mother."],"id":989,"m":"Any drop of blood in me that's calm proclaims I'm a bastard, calls my father a cuckold, and brands my true mother a whore right here on her chaste, unstained forehead."},{"t":"sp","who":"CLAUDIUS","lines":["What is the cause, Laertes,","That thy rebellion looks so giant-like?—","Let him go, Gertrude. Do not fear our person.","There's such divinity doth hedge a king,","That treason can but peep to what it would,","Acts little of his will.—Tell me, Laertes,","Why thou art thus incens'd.—Let him go, Gertrude:—","Speak, man."],"id":990,"m":"What is the reason, Laertes, that your rebellion looks so gigantic? Let him go, Gertrude. Don't worry about our safety. A king is protected by such divine power that treason can only peep at what it wants and achieves little of its aim. Tell me, Laertes, why you are so angry. Let him go, Gertrude. Speak, man."},{"t":"sp","who":"LAERTES","lines":["Where is my father?"],"id":991,"m":"Where is my father?"},{"t":"sp","who":"CLAUDIUS","lines":["Dead."],"id":992,"m":"Dead."},{"t":"sp","who":"GERTRUDE","lines":["But not by him."],"id":993,"m":"But not killed by him."},{"t":"sp","who":"CLAUDIUS","lines":["Let him demand his fill."],"id":994,"m":"Let him ask all he wants."},{"t":"sp","who":"LAERTES","lines":["How came he dead? I'll not be juggled with.","To hell, allegiance! Vows, to the blackest devil!","Conscience and grace, to the profoundest pit!","I dare damnation. To this point I stand,","That both the worlds, I give to negligence,","Let come what comes; only I'll be reveng'd","Most throughly for my father."],"id":995,"m":"How did he die? I won't be tricked. To hell with loyalty! Vows, go to the blackest devil! Conscience and grace, to the deepest pit! I dare to be damned. This is where I stand: I don't care about this world or the next. Let whatever happens happen. I'll just get revenge, completely, for my father."},{"t":"sp","who":"CLAUDIUS","lines":["Who shall stay you?"],"id":996,"m":"Who will stop you?"},{"t":"sp","who":"LAERTES","lines":["My will, not all the world.","And for my means, I'll husband them so well,","They shall go far with little."],"id":997,"m":"My own will, not the whole world. And as for my resources, I'll use them so carefully that they will go far with little."},{"t":"sp","who":"CLAUDIUS","lines":["Good Laertes,","If you desire to know the certainty","Of your dear father's death, is't writ in your revenge","That, sweepstake, you will draw both friend and foe,","Winner and loser?"],"id":998,"m":"Good Laertes, if you want to know the truth about your dear father's death, is it part of your revenge that, like a gambler sweeping up all the stakes, you will take both friend and enemy, winner and loser?"},{"t":"sp","who":"LAERTES","lines":["None but his enemies."],"id":999,"m":"Only his enemies."},{"t":"sp","who":"CLAUDIUS","lines":["Will you know them then?"],"id":1000,"m":"Do you want to know who they are, then?"},{"t":"sp","who":"LAERTES","lines":["To his good friends thus wide I'll ope my arms;","And, like the kind life-rendering pelican,","Repast them with my blood."],"id":1001,"m":"To his good friends I'll open my arms this wide, and like the kind pelican, which feeds its young with its own blood, I'll feed them with mine."},{"t":"sp","who":"CLAUDIUS","lines":["Why, now you speak","Like a good child and a true gentleman.","That I am guiltless of your father's death,","And am most sensibly in grief for it,","It shall as level to your judgement 'pear","As day does to your eye."],"id":1002,"m":"Why, now you speak like a good son and a true gentleman. That I am innocent of your father's death and grieve for it most deeply, will become as plain to your judgement as daylight is to your eyes."},{"t":"sp","who":"DANES","lines":["[Within] Let her come in."],"id":1003,"m":"[Within] Let her come in."},{"t":"sp","who":"LAERTES","lines":["How now! What noise is that?"],"id":1004,"m":"What's this? What's that noise?"},{"t":"sd","text":"Re-enter Ophelia, fantastically dressed with straws and flowers.","id":1005},{"t":"sp","who":"LAERTES","cont":1,"lines":["O heat, dry up my brains. Tears seven times salt,","Burn out the sense and virtue of mine eye.","By heaven, thy madness shall be paid by weight,","Till our scale turn the beam. O rose of May!","Dear maid, kind sister, sweet Ophelia!","O heavens, is't possible a young maid's wits","Should be as mortal as an old man's life?","Nature is fine in love, and where 'tis fine,","It sends some precious instance of itself","After the thing it loves."],"id":1006,"m":"Oh, heat, dry up my brain! Tears seven times salty, burn out the feeling and power of my eyes! By heaven, your madness will be paid for in full, until our side of the scales outweighs the other. Oh, rose of May! Dear girl, kind sister, sweet Ophelia! Oh, heavens! Is it possible that a young girl's mind can be as easily killed as an old man's life? Human nature is refined by love, and when it is, it sends some precious part of itself after the thing it loves."},{"t":"sp","who":"OPHELIA","lines":["[Sings]","They bore him barefac'd on the bier,","Hey non nonny, nonny, hey nonny","And on his grave rain'd many a tear.—","Fare you well, my dove!"],"id":1007,"m":"[Sings] They carried him on the coffin with his face uncovered, hey non nonny, nonny, hey nonny, and on his grave fell many tears. Goodbye, my dove!"},{"t":"sp","who":"LAERTES","lines":["Hadst thou thy wits, and didst persuade revenge,","It could not move thus."],"id":1008,"m":"If you were sane and urged me to take revenge, it couldn't move me as much as this."},{"t":"sp","who":"OPHELIA","lines":["You must sing 'Down a-down, and you call him a-down-a.' O, how the","wheel becomes it! It is the false steward that stole his master's","daughter."],"id":1009,"m":"You must sing 'Down a-down', and you call him 'a-down-a'. Oh, how well the refrain fits! It's about the false steward who stole his master's daughter."},{"t":"sp","who":"LAERTES","lines":["This nothing's more than matter."],"id":1010,"m":"This nonsense means more than sense."},{"t":"sp","who":"OPHELIA","lines":["There's rosemary, that's for remembrance; pray love, remember. And","there is pansies, that's for thoughts."],"id":1011,"m":"There's rosemary, that's for remembrance. Please, love, remember. And there are pansies; that's for thoughts."},{"t":"sp","who":"LAERTES","lines":["A document in madness, thoughts and remembrance fitted."],"id":1012,"m":"A lesson in madness: thoughts and remembrance put together."},{"t":"sp","who":"OPHELIA","lines":["There's fennel for you, and columbines. There's rue for you; and here's","some for me. We may call it herb of grace o' Sundays. O you must wear","your rue with a difference. There's a daisy. I would give you some","violets, but they wither'd all when my father died. They say he made a","good end.","[Sings]","For bonny sweet Robin is all my joy."],"id":1013,"m":"There's fennel for you, and columbines. There's rue for you, and here's some for me. We can call it the herb of grace on Sundays. Oh, you must wear your rue for a different reason. There's a daisy. I'd give you some violets, but they all withered when my father died. They say he died well. [Sings] For bonny sweet Robin is all my joy."},{"t":"sp","who":"LAERTES","lines":["Thought and affliction, passion, hell itself","She turns to favour and to prettiness."],"id":1014,"m":"Sorrow and suffering, passion, hell itself, she turns into charm and prettiness."},{"t":"sp","who":"OPHELIA","lines":["[Sings]","And will he not come again?","And will he not come again?","No, no, he is dead,","Go to thy death-bed,","He never will come again.","His beard was as white as snow,","All flaxen was his poll.","He is gone, he is gone,","And we cast away moan.","God ha' mercy on his soul.","And of all Christian souls, I pray God. God b' wi' ye."],"id":1015,"m":"[Sings] And won't he come back again? And won't he come back again? No, no, he is dead. Go to your deathbed. He will never come back again. His beard was as white as snow, his hair all pale like flax. He is gone, he is gone, and we throw away our grief. God have mercy on his soul! And on all Christian souls, I pray to God. God be with you."},{"t":"sd","text":"Exit","id":1016},{"t":"sp","who":"LAERTES","lines":["Do you see this, O God?"],"id":1017,"m":"Do you see this, oh God?"},{"t":"sp","who":"CLAUDIUS","lines":["Laertes, I must commune with your grief,","Or you deny me right. Go but apart,","Make choice of whom your wisest friends you will,","And they shall hear and judge 'twixt you and me.","If by direct or by collateral hand","They find us touch'd, we will our kingdom give,","Our crown, our life, and all that we call ours","To you in satisfaction; but if not,","Be you content to lend your patience to us,","And we shall jointly labour with your soul","To give it due content."],"id":1018,"m":"Laertes, I must share in your grief, or you deny me what is right. Just go aside, choose whichever of your wisest friends you like, and let them hear us and judge between you and me. If they find that I was involved, directly or indirectly, I will give you our kingdom, our crown, our life and everything we call ours, to make up for it. But if not, be content to be patient with us, and we will work together with you to give your soul the satisfaction it deserves."},{"t":"sp","who":"LAERTES","lines":["Let this be so;","His means of death, his obscure burial,—","No trophy, sword, nor hatchment o'er his bones,","No noble rite, nor formal ostentation,—","Cry to be heard, as 'twere from heaven to earth,","That I must call't in question."],"id":1019,"m":"Let it be so. The way he died, his secret burial, with no monument, sword or coat of arms over his bones, no noble ceremony or formal display, all cry out to be heard, as loudly as if from heaven to earth, so I must demand an explanation."},{"t":"sp","who":"CLAUDIUS","lines":["So you shall.","And where th'offence is let the great axe fall.","I pray you go with me."],"id":1020,"m":"And so you shall, and where the guilt lies, let the great axe fall. Please, come with me."},{"t":"sd","text":"Exeunt","id":1021},{"t":"scene","act":4,"scene":"VI","loc":"Another room in the Castle.","id":1022},{"t":"sd","text":"Enter Horatio and a Servant.","id":1023},{"t":"sp","who":"HORATIO","lines":["What are they that would speak with me?"],"id":1024,"m":"Who are the people who want to speak to me?"},{"t":"sp","who":"SERVANT","lines":["Sailors, sir. They say they have letters for you."],"id":1025,"m":"Sailors, sir. They say they have letters for you."},{"t":"sp","who":"HORATIO","lines":["Let them come in."],"id":1026,"m":"Let them come in."},{"t":"sd","text":"Exit Servant","id":1027},{"t":"sp","who":"HORATIO","cont":1,"lines":["I do not know from what part of the world","I should be greeted, if not from Lord Hamlet."],"id":1028,"m":"I don't know who in the world would be writing to me, if not Lord Hamlet."},{"t":"sd","text":"Enter Sailors.","id":1029},{"t":"sp","who":"FIRST SAILOR","lines":["God bless you, sir."],"id":1030,"m":"God bless you, sir."},{"t":"sp","who":"HORATIO","lines":["Let him bless thee too."],"id":1031,"m":"And may he bless you too."},{"t":"sp","who":"FIRST SAILOR","lines":["He shall, sir, and't please him. There's a letter for you, sir. It","comes from th'ambassador that was bound for England; if your name be","Horatio, as I am let to know it is."],"id":1032,"m":"He will, sir, if he wants to. There's a letter for you, sir. It comes from the ambassador who was going to England, if your name is Horatio, as I've been told it is."},{"t":"sp","who":"HORATIO","lines":["[Reads] 'Horatio, when thou shalt have overlooked this, give these","fellows some means to the King. They have letters for him. Ere we were","two days old at sea, a pirate of very warlike appointment gave us","chase. Finding ourselves too slow of sail, we put on a compelled","valour, and in the grapple I boarded them. On the instant they got","clear of our ship, so I alone became their prisoner. They have dealt","with me like thieves of mercy. But they knew what they did; I am to do","a good turn for them. Let the King have the letters I have sent, and","repair thou to me with as much haste as thou wouldst fly death. I have","words to speak in thine ear will make thee dumb; yet are they much too","light for the bore of the matter. These good fellows will bring thee","where I am. Rosencrantz and Guildenstern hold their course for England:","of them I have much to tell thee. Farewell.","He that thou knowest thine,","HAMLET.'","Come, I will give you way for these your letters,","And do't the speedier, that you may direct me","To him from whom you brought them."],"id":1033,"m":"[Reads] 'Horatio, when you have read this, help these fellows get to the King. They have letters for him. Before we were two days out at sea, a pirate ship very well armed chased us. Finding we were too slow, we were forced to be brave, and in the fight I boarded their ship. At that moment they got clear of our ship, so I alone became their prisoner. They have treated me like merciful thieves, but they knew what they were doing: I am to do them a favour. Let the King have the letters I have sent, and come to me as fast as you would run from death. I have things to tell you that will leave you speechless, and yet my words are far too light for the weight of the matter. These good fellows will bring you to where I am. Rosencrantz and Guildenstern are still on their way to England. I have a lot to tell you about them. Goodbye. The one you know is yours, Hamlet.' Come, I'll get these letters of yours delivered, and I'll do it all the faster so that you can take me to the man who gave them to you."},{"t":"sd","text":"Exeunt","id":1034},{"t":"scene","act":4,"scene":"VII","loc":"Another room in the Castle.","id":1035},{"t":"sd","text":"Enter King and Laertes.","id":1036},{"t":"sp","who":"CLAUDIUS","lines":["Now must your conscience my acquittance seal,","And you must put me in your heart for friend,","Sith you have heard, and with a knowing ear,","That he which hath your noble father slain","Pursu'd my life."],"id":1037,"m":"Now your conscience must confirm that I am innocent, and you must take me into your heart as a friend, since you have heard, and understood, that the man who killed your noble father was trying to kill me."},{"t":"sp","who":"LAERTES","lines":["It well appears. But tell me","Why you proceeded not against these feats,","So crimeful and so capital in nature,","As by your safety, wisdom, all things else,","You mainly were stirr'd up."],"id":1038,"m":"That seems clear. But tell me why you didn't take action against these deeds, so criminal and deserving death, when your own safety, your wisdom and everything else must have strongly urged you to."},{"t":"sp","who":"CLAUDIUS","lines":["O, for two special reasons,","Which may to you, perhaps, seem much unsinew'd,","But yet to me they are strong. The Queen his mother","Lives almost by his looks; and for myself,—","My virtue or my plague, be it either which,—","She's so conjunctive to my life and soul,","That, as the star moves not but in his sphere,","I could not but by her. The other motive,","Why to a public count I might not go,","Is the great love the general gender bear him,","Who, dipping all his faults in their affection,","Would like the spring that turneth wood to stone,","Convert his gyves to graces; so that my arrows,","Too slightly timber'd for so loud a wind,","Would have reverted to my bow again,","And not where I had aim'd them."],"id":1039,"m":"Oh, for two special reasons, which may seem very weak to you, but to me they are strong. The Queen, his mother, lives almost for the sight of him, and as for me, whether it is my virtue or my curse, she is so closely joined to my life and soul that, just as a star only moves within its own sphere, I can only move with her. The other reason I couldn't bring him to public trial is the great love the common people have for him. They dip all his faults in their affection and, like the spring that turns wood into stone, would turn his chains into honours. So my arrows, too light for such a strong wind, would have blown back to my bow and not gone where I aimed them."},{"t":"sp","who":"LAERTES","lines":["And so have I a noble father lost,","A sister driven into desperate terms,","Whose worth, if praises may go back again,","Stood challenger on mount of all the age","For her perfections. But my revenge will come."],"id":1040,"m":"And so I have lost a noble father, and my sister has been driven into desperate madness, a girl whose worth, if I may praise what she used to be, stood high above everyone of her age, challenging anyone to match her perfections. But my revenge will come."},{"t":"sp","who":"CLAUDIUS","lines":["Break not your sleeps for that. You must not think","That we are made of stuff so flat and dull","That we can let our beard be shook with danger,","And think it pastime. You shortly shall hear more.","I lov'd your father, and we love ourself,","And that, I hope, will teach you to imagine—"],"id":1041,"m":"Don't lose any sleep over that. You mustn't think we are made of such flat and dull stuff that we can let danger pull our beard and think it's a game. You'll hear more soon. I loved your father, and we love ourselves, and that, I hope, will teach you to imagine—"},{"t":"sd","text":"Enter a Messenger.","id":1042},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["How now? What news?"],"id":1043,"m":"What is it? What news?"},{"t":"sp","who":"MESSENGER","lines":["Letters, my lord, from Hamlet.","This to your Majesty; this to the Queen."],"id":1044,"m":"Letters, my lord, from Hamlet. This one for your Majesty, this one for the Queen."},{"t":"sp","who":"CLAUDIUS","lines":["From Hamlet! Who brought them?"],"id":1045,"m":"From Hamlet! Who brought them?"},{"t":"sp","who":"MESSENGER","lines":["Sailors, my lord, they say; I saw them not.","They were given me by Claudio. He receiv'd them","Of him that brought them."],"id":1046,"m":"Sailors, my lord, they say. I didn't see them. Claudio gave them to me. He got them from the man who brought them."},{"t":"sp","who":"CLAUDIUS","lines":["Laertes, you shall hear them.","Leave us."],"id":1047,"m":"Laertes, you shall hear them. Leave us."},{"t":"sd","text":"Exit Messenger","id":1048},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["[Reads] 'High and mighty, you shall know I am set naked on your","kingdom. Tomorrow shall I beg leave to see your kingly eyes. When I","shall, first asking your pardon thereunto, recount the occasions of my","sudden and more strange return.","HAMLET.'","What should this mean? Are all the rest come back?","Or is it some abuse, and no such thing?"],"id":1049,"m":"[Reads] 'High and mighty King, you should know that I have been put down on your kingdom with nothing. Tomorrow I will ask permission to see your royal eyes, and then, after first asking your pardon, I'll tell you the reasons for my sudden and even stranger return. Hamlet.' What can this mean? Have all the others come back? Or is it some trick, and nothing of the kind?"},{"t":"sp","who":"LAERTES","lines":["Know you the hand?"],"id":1050,"m":"Do you recognise the handwriting?"},{"t":"sp","who":"CLAUDIUS","lines":["'Tis Hamlet's character. 'Naked!'","And in a postscript here he says 'alone.'","Can you advise me?"],"id":1051,"m":"It's Hamlet's writing. 'With nothing'! And in a note here he adds 'alone'. Can you advise me?"},{"t":"sp","who":"LAERTES","lines":["I am lost in it, my lord. But let him come,","It warms the very sickness in my heart","That I shall live and tell him to his teeth,","'Thus diest thou.'"],"id":1052,"m":"I'm completely confused by it, my lord. But let him come. It warms the very sickness in my heart that I'll live to tell him to his face, 'This is how you die.'"},{"t":"sp","who":"CLAUDIUS","lines":["If it be so, Laertes,—","As how should it be so? How otherwise?—","Will you be rul'd by me?"],"id":1053,"m":"If that is so, Laertes, and how can it be so? Yet how can it be otherwise? Will you let me guide you?"},{"t":"sp","who":"LAERTES","lines":["Ay, my lord;","So you will not o'errule me to a peace."],"id":1054,"m":"Yes, my lord, as long as you don't order me to make peace."},{"t":"sp","who":"CLAUDIUS","lines":["To thine own peace. If he be now return'd,","As checking at his voyage, and that he means","No more to undertake it, I will work him","To an exploit, now ripe in my device,","Under the which he shall not choose but fall;","And for his death no wind shall breathe,","But even his mother shall uncharge the practice","And call it accident."],"id":1055,"m":"Only to your own peace of mind. If he has come back now, turning away from his voyage, and means not to go on it any more, I'll lead him into a plan, now fully worked out in my mind, which will certainly kill him. And there won't be a breath of blame for his death; even his mother won't accuse anyone of the plot, and will call it an accident."},{"t":"sp","who":"LAERTES","lines":["My lord, I will be rul'd;","The rather if you could devise it so","That I might be the organ."],"id":1056,"m":"My lord, I'll let you guide me, and all the more if you could arrange it so that I am the instrument."},{"t":"sp","who":"CLAUDIUS","lines":["It falls right.","You have been talk'd of since your travel much,","And that in Hamlet's hearing, for a quality","Wherein they say you shine. Your sum of parts","Did not together pluck such envy from him","As did that one, and that, in my regard,","Of the unworthiest siege."],"id":1057,"m":"That fits well. You've been talked about a lot since you went abroad, and in Hamlet's hearing, for one skill they say you shine at. All your other qualities together didn't make him as envious as that one did, though in my opinion it is the least important."},{"t":"sp","who":"LAERTES","lines":["What part is that, my lord?"],"id":1058,"m":"What skill is that, my lord?"},{"t":"sp","who":"CLAUDIUS","lines":["A very riband in the cap of youth,","Yet needful too, for youth no less becomes","The light and careless livery that it wears","Than settled age his sables and his weeds,","Importing health and graveness. Two months since","Here was a gentleman of Normandy,—","I've seen myself, and serv'd against, the French,","And they can well on horseback, but this gallant","Had witchcraft in't. He grew unto his seat,","And to such wondrous doing brought his horse,","As had he been incorps'd and demi-natur'd","With the brave beast. So far he topp'd my thought","That I in forgery of shapes and tricks,","Come short of what he did."],"id":1059,"m":"A mere ribbon in the cap of youth, and yet a necessary one too, because light, carefree clothes suit youth no less than sober furs and robes suit settled old age, showing well-being and seriousness. Two months ago there was a gentleman from Normandy here. I've seen the French myself and fought against them, and they ride very well, but this young man was like a magician. He seemed to grow into his saddle, and he made his horse do such amazing things, it was as if he had become one body with the fine animal, half man, half horse. He went so far beyond what I could imagine that I can't invent the moves and tricks he did."},{"t":"sp","who":"LAERTES","lines":["A Norman was't?"],"id":1060,"m":"He was from Normandy?"},{"t":"sp","who":"CLAUDIUS","lines":["A Norman."],"id":1061,"m":"From Normandy."},{"t":"sp","who":"LAERTES","lines":["Upon my life, Lamord."],"id":1062,"m":"On my life, Lamord!"},{"t":"sp","who":"CLAUDIUS","lines":["The very same."],"id":1063,"m":"That's the man."},{"t":"sp","who":"LAERTES","lines":["I know him well. He is the brooch indeed","And gem of all the nation."],"id":1064,"m":"I know him well. He is truly the jewel and pride of the whole nation."},{"t":"sp","who":"CLAUDIUS","lines":["He made confession of you,","And gave you such a masterly report","For art and exercise in your defence,","And for your rapier most especially,","That he cried out 'twould be a sight indeed","If one could match you. The scrimers of their nation","He swore had neither motion, guard, nor eye,","If you oppos'd them. Sir, this report of his","Did Hamlet so envenom with his envy","That he could nothing do but wish and beg","Your sudden coming o'er to play with him.","Now, out of this,—"],"id":1065,"m":"He told us about you, and gave you such a glowing report for your skill and practice in fencing, especially with the rapier, that he exclaimed it would be a real sight if anyone could match you. He swore the fencers of his country had no movement, defence or eye when they faced you. Sir, this report of his made Hamlet so poisoned with envy that he could do nothing but wish and beg for you to come back quickly and fence with him. Now, out of this—"},{"t":"sp","who":"LAERTES","lines":["What out of this, my lord?"],"id":1066,"m":"What out of this, my lord?"},{"t":"sp","who":"CLAUDIUS","lines":["Laertes, was your father dear to you?","Or are you like the painting of a sorrow,","A face without a heart?"],"id":1067,"m":"Laertes, did you love your father? Or are you like the painting of a sorrow, a face without a heart?"},{"t":"sp","who":"LAERTES","lines":["Why ask you this?"],"id":1068,"m":"Why do you ask this?"},{"t":"sp","who":"CLAUDIUS","lines":["Not that I think you did not love your father,","But that I know love is begun by time,","And that I see, in passages of proof,","Time qualifies the spark and fire of it.","There lives within the very flame of love","A kind of wick or snuff that will abate it;","And nothing is at a like goodness still,","For goodness, growing to a pleurisy,","Dies in his own too much. That we would do,","We should do when we would; for this 'would' changes,","And hath abatements and delays as many","As there are tongues, are hands, are accidents;","And then this 'should' is like a spendthrift sigh","That hurts by easing. But to the quick o' th'ulcer:","Hamlet comes back: what would you undertake","To show yourself your father's son in deed,","More than in words?"],"id":1069,"m":"Not because I think you didn't love your father, but because I know that love is started by time, and I see, from experience, that time weakens its spark and fire. Inside the very flame of love there lives a sort of wick or burnt end that will dim it, and nothing stays at the same level of goodness forever, because goodness, growing too full, dies of its own excess. What we want to do, we should do when we want to, because this 'want' changes and has as many weakenings and delays as there are tongues, hands and accidents, and then this 'should' is like a wasteful sigh that hurts while it eases. But to the heart of the sore: Hamlet comes back. What would you do to show yourself your father's son in actions, more than in words?"},{"t":"sp","who":"LAERTES","lines":["To cut his throat i' th' church."],"id":1070,"m":"Cut his throat in church."},{"t":"sp","who":"CLAUDIUS","lines":["No place, indeed, should murder sanctuarize;","Revenge should have no bounds. But good Laertes,","Will you do this, keep close within your chamber.","Hamlet return'd shall know you are come home:","We'll put on those shall praise your excellence,","And set a double varnish on the fame","The Frenchman gave you, bring you in fine together","And wager on your heads. He, being remiss,","Most generous, and free from all contriving,","Will not peruse the foils; so that with ease,","Or with a little shuffling, you may choose","A sword unbated, and in a pass of practice,","Requite him for your father."],"id":1071,"m":"No place, it's true, should give sanctuary to a murderer. Revenge should have no limits. But, good Laertes, if you'll do this, stay shut up in your room. When Hamlet comes back, he'll learn that you are home. We'll get people to praise your skill and put a double coat of polish on the reputation the Frenchman gave you, and finally bring you together and bet on you. He, being careless, very generous and free of all scheming, won't examine the swords, so that easily, or with a little sleight of hand, you can choose a sword without a safety tip, and with a thrust in the practice match pay him back for your father."},{"t":"sp","who":"LAERTES","lines":["I will do't.","And for that purpose I'll anoint my sword.","I bought an unction of a mountebank","So mortal that, but dip a knife in it,","Where it draws blood no cataplasm so rare,","Collected from all simples that have virtue","Under the moon, can save the thing from death","This is but scratch'd withal. I'll touch my point","With this contagion, that if I gall him slightly,","It may be death."],"id":1072,"m":"I'll do it, and for that purpose I'll smear poison on my sword. I bought an ointment from a travelling quack so deadly that if you just dip a knife in it, where it draws blood, no remedy, however rare, made from every herb with healing powers under the moon, can save anyone from death who is even scratched with it. I'll touch the tip of my sword with this poison, so that if I graze him even slightly, it will mean death."},{"t":"sp","who":"CLAUDIUS","lines":["Let's further think of this,","Weigh what convenience both of time and means","May fit us to our shape. If this should fail,","And that our drift look through our bad performance.","'Twere better not assay'd. Therefore this project","Should have a back or second, that might hold","If this did blast in proof. Soft, let me see.","We'll make a solemn wager on your cunnings,—","I ha't! When in your motion you are hot and dry,","As make your bouts more violent to that end,","And that he calls for drink, I'll have prepar'd him","A chalice for the nonce; whereon but sipping,","If he by chance escape your venom'd stuck,","Our purpose may hold there."],"id":1073,"m":"Let's think further about this, and consider what timing and means will best suit our roles. If this should fail, and our plan should show through because we carry it out badly, it would be better not to try. So this plan should have a backup, a second one that would work if this one blew up when tested. Wait, let me see. We'll make a formal bet on your skills. I've got it! When you are hot and thirsty from moving, and you should make your bouts more violent for that purpose, and he asks for a drink, I'll have prepared a cup for him for the occasion. If he just sips it, even if by chance he escapes your poisoned thrust, our plan will still succeed."},{"t":"sd","text":"Enter Queen.","id":1074},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["How now, sweet Queen?"],"id":1075,"m":"What is it, sweet Queen?"},{"t":"sp","who":"GERTRUDE","lines":["One woe doth tread upon another's heel,","So fast they follow. Your sister's drown'd, Laertes."],"id":1076,"m":"One sorrow treads on another's heels, they follow so fast. Your sister has drowned, Laertes."},{"t":"sp","who":"LAERTES","lines":["Drown'd! O, where?"],"id":1077,"m":"Drowned! Oh, where?"},{"t":"sp","who":"GERTRUDE","lines":["There is a willow grows aslant a brook,","That shows his hoary leaves in the glassy stream.","There with fantastic garlands did she make","Of crow-flowers, nettles, daisies, and long purples,","That liberal shepherds give a grosser name,","But our cold maids do dead men's fingers call them.","There on the pendant boughs her coronet weeds","Clamb'ring to hang, an envious sliver broke,","When down her weedy trophies and herself","Fell in the weeping brook. Her clothes spread wide,","And mermaid-like, awhile they bore her up,","Which time she chaunted snatches of old tunes,","As one incapable of her own distress,","Or like a creature native and indued","Unto that element. But long it could not be","Till that her garments, heavy with their drink,","Pull'd the poor wretch from her melodious lay","To muddy death."],"id":1078,"m":"There is a willow growing at an angle over a stream, showing its grey-white leaves in the glassy water. There she came with fantastic garlands she had made of buttercups, nettles, daisies and long purple flowers, which the coarse shepherds give a rude name, but our chaste girls call dead men's fingers. There, as she climbed to hang her crown of flowers on the hanging branches, a spiteful branch broke, and down she fell with her flowery trophies into the weeping stream. Her clothes spread out wide and held her up like a mermaid for a while, and all that time she sang bits of old songs, as if she didn't understand the danger she was in, or like a creature born and suited to the water. But it couldn't be long before her clothes, heavy with all the water they had soaked up, pulled the poor girl from her lovely singing down to a muddy death."},{"t":"sp","who":"LAERTES","lines":["Alas, then she is drown'd?"],"id":1079,"m":"Oh no, then she's drowned?"},{"t":"sp","who":"GERTRUDE","lines":["Drown'd, drown'd."],"id":1080,"m":"Drowned, drowned."},{"t":"sp","who":"LAERTES","lines":["Too much of water hast thou, poor Ophelia,","And therefore I forbid my tears. But yet","It is our trick; nature her custom holds,","Let shame say what it will. When these are gone,","The woman will be out. Adieu, my lord,","I have a speech of fire, that fain would blaze,","But that this folly douts it."],"id":1081,"m":"You've had too much water, poor Ophelia, so I won't let myself cry. But still, it's our human nature; nature keeps to her habits, whatever shame may say. When these tears are gone, the woman in me will be gone too. Goodbye, my lord. I have a fiery speech that wants to blaze out, but this foolish weeping puts it out."},{"t":"sd","text":"Exit","id":1082},{"t":"sp","who":"CLAUDIUS","lines":["Let's follow, Gertrude;","How much I had to do to calm his rage!","Now fear I this will give it start again;","Therefore let's follow."],"id":1083,"m":"Let's follow, Gertrude. How hard I worked to calm his rage! Now I'm afraid this will start it up again. So let's follow."},{"t":"sd","text":"Exeunt","id":1084},{"t":"scene","act":5,"scene":"I","loc":"A churchyard.","id":1085},{"t":"sd","text":"Enter two Clowns with spades, &c.","id":1086},{"t":"sp","who":"FIRST CLOWN","lines":["Is she to be buried in Christian burial, when she wilfully seeks her","own salvation?"],"id":1087,"m":"Is she going to be given a Christian burial, when she deliberately went looking for her own salvation?"},{"t":"sp","who":"SECOND CLOWN","lines":["I tell thee she is, and therefore make her grave straight. The crowner","hath sat on her, and finds it Christian burial."],"id":1088,"m":"I'm telling you she is, so dig her grave straight away. The coroner has held an inquest on her and decided it's to be a Christian burial."},{"t":"sp","who":"FIRST CLOWN","lines":["How can that be, unless she drowned herself in her own defence?"],"id":1089,"m":"How can that be, unless she drowned herself in self-defence?"},{"t":"sp","who":"SECOND CLOWN","lines":["Why, 'tis found so."],"id":1090,"m":"Well, that's what they decided."},{"t":"sp","who":"FIRST CLOWN","lines":["It must be se offendendo, it cannot be else. For here lies the point:","if I drown myself wittingly, it argues an act: and an act hath three","branches. It is to act, to do, and to perform: argal, she drowned","herself wittingly."],"id":1091,"m":"It must have been 'self-offence'; it can't be anything else. Because here's the point: if I drown myself on purpose, that shows an act, and an act has three branches: to act, to do and to perform. Ergo, she drowned herself on purpose."},{"t":"sp","who":"SECOND CLOWN","lines":["Nay, but hear you, goodman delver,—"],"id":1092,"m":"No, but listen, Mister Digger—"},{"t":"sp","who":"FIRST CLOWN","lines":["Give me leave. Here lies the water; good. Here stands the man; good. If","the man go to this water and drown himself, it is, will he nill he, he","goes,—mark you that. But if the water come to him and drown him, he","drowns not himself. Argal, he that is not guilty of his own death","shortens not his own life."],"id":1093,"m":"Let me finish. Here's the water, good. Here stands the man, good. If the man goes to this water and drowns himself, it is, whether he likes it or not, he goes, mark that. But if the water comes to him and drowns him, he doesn't drown himself. Ergo, the man who isn't guilty of his own death doesn't shorten his own life."},{"t":"sp","who":"SECOND CLOWN","lines":["But is this law?"],"id":1094,"m":"But is this the law?"},{"t":"sp","who":"FIRST CLOWN","lines":["Ay, marry, is't, crowner's quest law."],"id":1095,"m":"Yes, it certainly is, coroner's inquest law."},{"t":"sp","who":"SECOND CLOWN","lines":["Will you ha' the truth on't? If this had not been a gentlewoman, she","should have been buried out o' Christian burial."],"id":1096,"m":"Do you want the truth of it? If she hadn't been a gentlewoman, she wouldn't have been given a Christian burial."},{"t":"sp","who":"FIRST CLOWN","lines":["Why, there thou say'st. And the more pity that great folk should have","countenance in this world to drown or hang themselves more than their","even Christian. Come, my spade. There is no ancient gentlemen but","gardeners, ditchers, and grave-makers: they hold up Adam's profession."],"id":1097,"m":"Why, you've said it. And it's a great pity that important people should have more permission in this world to drown or hang themselves than their fellow Christians. Come, my spade. There are no gentlemen of older family than gardeners, ditch-diggers and gravediggers. They carry on Adam's profession."},{"t":"sp","who":"SECOND CLOWN","lines":["Was he a gentleman?"],"id":1098,"m":"Was Adam a gentleman?"},{"t":"sp","who":"FIRST CLOWN","lines":["He was the first that ever bore arms."],"id":1099,"m":"He was the first man ever to bear arms."},{"t":"sp","who":"SECOND CLOWN","lines":["Why, he had none."],"id":1100,"m":"Why, he didn't have a coat of arms."},{"t":"sp","who":"FIRST CLOWN","lines":["What, art a heathen? How dost thou understand the Scripture? The","Scripture says Adam digg'd. Could he dig without arms? I'll put another","question to thee. If thou answerest me not to the purpose, confess","thyself—"],"id":1101,"m":"What, are you a heathen? How do you understand the Bible? The Bible says Adam dug. Could he dig without arms? I'll ask you another question. If you don't answer me properly, confess yourself—"},{"t":"sp","who":"SECOND CLOWN","lines":["Go to."],"id":1102,"m":"Go on."},{"t":"sp","who":"FIRST CLOWN","lines":["What is he that builds stronger than either the mason, the shipwright,","or the carpenter?"],"id":1103,"m":"Who builds stronger than the stonemason, the shipbuilder or the carpenter?"},{"t":"sp","who":"SECOND CLOWN","lines":["The gallows-maker; for that frame outlives a thousand tenants."],"id":1104,"m":"The gallows-maker, because his frame outlives a thousand tenants."},{"t":"sp","who":"FIRST CLOWN","lines":["I like thy wit well in good faith, the gallows does well. But how does","it well? It does well to those that do ill. Now, thou dost ill to say","the gallows is built stronger than the church; argal, the gallows may","do well to thee. To't again, come."],"id":1105,"m":"I like your wit, honestly. The gallows does well. But how does it do well? It does well for those who do evil. Now, you do evil to say the gallows is built stronger than the church. Ergo, the gallows may do well for you. Try again, come on."},{"t":"sp","who":"SECOND CLOWN","lines":["Who builds stronger than a mason, a shipwright, or a carpenter?"],"id":1106,"m":"Who builds stronger than a stonemason, a shipbuilder or a carpenter?"},{"t":"sp","who":"FIRST CLOWN","lines":["Ay, tell me that, and unyoke."],"id":1107,"m":"Yes, tell me that, and you can stop work."},{"t":"sp","who":"SECOND CLOWN","lines":["Marry, now I can tell."],"id":1108,"m":"Well, now I can tell you."},{"t":"sp","who":"FIRST CLOWN","lines":["To't."],"id":1109,"m":"Go on."},{"t":"sp","who":"SECOND CLOWN","lines":["Mass, I cannot tell."],"id":1110,"m":"By the Mass, I can't tell you."},{"t":"sd","text":"Enter Hamlet and Horatio, at a distance.","id":1111},{"t":"sp","who":"FIRST CLOWN","lines":["Cudgel thy brains no more about it, for your dull ass will not mend his","pace with beating; and when you are asked this question next, say 'a","grave-maker'. The houses he makes last till doomsday. Go, get thee to","Yaughan; fetch me a stoup of liquor."],"id":1112,"m":"Don't beat your brains about it any more, because your dull donkey won't go any faster for being beaten. And when you're asked this question next time, say 'a gravedigger'. The houses he makes last till the Day of Judgement. Go on, off to Yaughan's and fetch me a jug of drink."},{"t":"sd","text":"Exit Second Clown","id":1113},{"t":"sd","text":"Digs and sings","id":1114},{"t":"sp","who":"FIRST CLOWN","cont":1,"lines":["In youth when I did love, did love,","Methought it was very sweet;","To contract, O, the time for, a, my behove,","O methought there was nothing meet."],"id":1115,"m":"[Sings] In my youth, when I loved, I loved, I thought it was very sweet, to pass the time for my own pleasure. Oh, I thought nothing was so fitting."},{"t":"sp","who":"HAMLET","lines":["Has this fellow no feeling of his business, that he sings at","grave-making?"],"id":1116,"m":"Doesn't this fellow have any feeling for what he's doing, that he sings while digging graves?"},{"t":"sp","who":"HORATIO","lines":["Custom hath made it in him a property of easiness."],"id":1117,"m":"Habit has made it easy for him."},{"t":"sp","who":"HAMLET","lines":["'Tis e'en so; the hand of little employment hath the daintier sense."],"id":1118,"m":"That's true. The hand that does little work has more delicate feelings."},{"t":"sp","who":"FIRST CLOWN","lines":["[Sings]","But age with his stealing steps","Hath claw'd me in his clutch,","And hath shipp'd me into the land,","As if I had never been such."],"id":1119,"m":"[Sings] But old age, creeping up with stealthy steps, has grabbed me in his claws and shipped me off into the earth, as if I had never been young."},{"t":"sd","text":"Throws up a skull","id":1120},{"t":"sp","who":"HAMLET","lines":["That skull had a tongue in it, and could sing once. How the knave jowls","it to th' ground, as if 'twere Cain's jawbone, that did the first","murder! This might be the pate of a politician which this ass now","o'er-offices, one that would circumvent God, might it not?"],"id":1121,"m":"That skull had a tongue in it and could sing once. How the rogue throws it to the ground, as if it were the jawbone of Cain, who did the first murder! This might be the head of a scheming politician, which this donkey now gets the better of, one who would try to get round God himself, mightn't it?"},{"t":"sp","who":"HORATIO","lines":["It might, my lord."],"id":1122,"m":"It might, my lord."},{"t":"sp","who":"HAMLET","lines":["Or of a courtier, which could say 'Good morrow, sweet lord! How dost","thou, good lord?' This might be my lord such-a-one, that praised my","lord such-a-one's horse when he meant to beg it, might it not?"],"id":1123,"m":"Or of a courtier, who could say 'Good morning, sweet lord! How are you, good lord?' This might be Lord So-and-so, who praised Lord So-and-so's horse when he meant to beg for it, mightn't it?"},{"t":"sp","who":"HORATIO","lines":["Ay, my lord."],"id":1124,"m":"Yes, my lord."},{"t":"sp","who":"HAMLET","lines":["Why, e'en so: and now my Lady Worm's; chapless, and knocked about the","mazard with a sexton's spade. Here's fine revolution, an we had the","trick to see't. Did these bones cost no more the breeding but to play","at loggets with 'em? Mine ache to think on't."],"id":1125,"m":"Why, exactly, and now it belongs to my Lady Worm, with no jaw, and knocked about the head with a gravedigger's spade. Here's a fine reversal of fortune, if only we had the trick of seeing it. Did these bones cost so little to bring up that they're only fit for playing skittles with? Mine ache to think about it."},{"t":"sp","who":"FIRST CLOWN","lines":["[Sings]","A pickaxe and a spade, a spade,","For and a shrouding-sheet;","O, a pit of clay for to be made","For such a guest is meet."],"id":1126,"m":"[Sings] A pickaxe and a spade, a spade, and a sheet to wrap the body in; oh, a pit of clay to be dug is just right for such a guest."},{"t":"sd","text":"Throws up another skull","id":1127},{"t":"sp","who":"HAMLET","lines":["There's another. Why may not that be the skull of a lawyer? Where be","his quiddits now, his quillets, his cases, his tenures, and his tricks?","Why does he suffer this rude knave now to knock him about the sconce","with a dirty shovel, and will not tell him of his action of battery?","Hum. This fellow might be in's time a great buyer of land, with his","statutes, his recognizances, his fines, his double vouchers, his","recoveries. Is this the fine of his fines, and the recovery of his","recoveries, to have his fine pate full of fine dirt? Will his vouchers","vouch him no more of his purchases, and double ones too, than the","length and breadth of a pair of indentures? The very conveyances of his","lands will scarcely lie in this box; and must the inheritor himself","have no more, ha?"],"id":1128,"m":"There's another. Why couldn't that be the skull of a lawyer? Where are his quibbles now, his fine distinctions, his cases, his property rights and his tricks? Why does he let this rough rogue knock him on the head with a dirty shovel, and not threaten to sue him for assault? Hm. This fellow might have been a great buyer of land in his time, with his contracts, his bonds, his transfers, his double guarantees, his legal recoveries. Is this the end of his transfers and the recovery of his recoveries, to have his fine head full of fine dirt? Will all his guarantees, even the double ones, guarantee him no more land than the length and width of a pair of contracts? The deeds to his lands would hardly fit in this box, and must the owner himself have no more than this, ha?"},{"t":"sp","who":"HORATIO","lines":["Not a jot more, my lord."],"id":1129,"m":"Not a bit more, my lord."},{"t":"sp","who":"HAMLET","lines":["Is not parchment made of sheep-skins?"],"id":1130,"m":"Isn't parchment made of sheepskin?"},{"t":"sp","who":"HORATIO","lines":["Ay, my lord, and of calf-skins too."],"id":1131,"m":"Yes, my lord, and of calfskin too."},{"t":"sp","who":"HAMLET","lines":["They are sheep and calves which seek out assurance in that. I will","speak to this fellow.—Whose grave's this, sir?"],"id":1132,"m":"People are sheep and calves to look for security in that. I'll speak to this fellow. Whose grave is this, sir?"},{"t":"sp","who":"FIRST CLOWN","lines":["Mine, sir.","[Sings]","O, a pit of clay for to be made","For such a guest is meet."],"id":1133,"m":"Mine, sir. [Sings] Oh, a pit of clay to be dug is just right for such a guest."},{"t":"sp","who":"HAMLET","lines":["I think it be thine indeed, for thou liest in't."],"id":1134,"m":"I think it really is yours, because you are lying in it."},{"t":"sp","who":"FIRST CLOWN","lines":["You lie out on't, sir, and therefore 'tis not yours.","For my part, I do not lie in't, yet it is mine."],"id":1135,"m":"You're lying outside it, sir, so it isn't yours. As for me, I'm not lying in it, and yet it's mine."},{"t":"sp","who":"HAMLET","lines":["Thou dost lie in't, to be in't and say it is thine. 'Tis for the dead,","not for the quick; therefore thou liest."],"id":1136,"m":"You are lying in it, to be in it and say it's yours. It's for the dead, not for the living, so you are lying."},{"t":"sp","who":"FIRST CLOWN","lines":["'Tis a quick lie, sir; 't will away again from me to you."],"id":1137,"m":"It's a living lie, sir. It will jump away from me to you again."},{"t":"sp","who":"HAMLET","lines":["What man dost thou dig it for?"],"id":1138,"m":"What man are you digging it for?"},{"t":"sp","who":"FIRST CLOWN","lines":["For no man, sir."],"id":1139,"m":"For no man, sir."},{"t":"sp","who":"HAMLET","lines":["What woman then?"],"id":1140,"m":"What woman, then?"},{"t":"sp","who":"FIRST CLOWN","lines":["For none neither."],"id":1141,"m":"For no woman either."},{"t":"sp","who":"HAMLET","lines":["Who is to be buried in't?"],"id":1142,"m":"Who is going to be buried in it?"},{"t":"sp","who":"FIRST CLOWN","lines":["One that was a woman, sir; but, rest her soul, she's dead."],"id":1143,"m":"One who was a woman, sir, but, God rest her soul, she's dead."},{"t":"sp","who":"HAMLET","lines":["How absolute the knave is! We must speak by the card, or equivocation","will undo us. By the Lord, Horatio, these three years I have taken note","of it, the age is grown so picked that the toe of the peasant comes so","near the heel of the courtier he galls his kibe.—How long hast thou","been a grave-maker?"],"id":1144,"m":"How precise the rogue is! We must speak exactly, or double meanings will defeat us. By God, Horatio, I've noticed it these last three years: the times have become so refined that the peasant's toe comes so close to the courtier's heel that he rubs his chilblain. How long have you been a gravedigger?"},{"t":"sp","who":"FIRST CLOWN","lines":["Of all the days i' th' year, I came to't that day that our last King","Hamlet o'ercame Fortinbras."],"id":1145,"m":"Of all the days in the year, I started on the day our last King Hamlet defeated Fortinbras."},{"t":"sp","who":"HAMLET","lines":["How long is that since?"],"id":1146,"m":"How long ago is that?"},{"t":"sp","who":"FIRST CLOWN","lines":["Cannot you tell that? Every fool can tell that. It was the very day","that young Hamlet was born,—he that is mad, and sent into England."],"id":1147,"m":"Can't you tell that? Any fool can tell that. It was the very day young Hamlet was born, the one who is mad and has been sent to England."},{"t":"sp","who":"HAMLET","lines":["Ay, marry, why was he sent into England?"],"id":1148,"m":"Yes, indeed. Why was he sent to England?"},{"t":"sp","who":"FIRST CLOWN","lines":["Why, because he was mad; he shall recover his wits there; or if he do","not, it's no great matter there."],"id":1149,"m":"Why, because he was mad. He'll get his wits back there, or if he doesn't, it doesn't much matter there."},{"t":"sp","who":"HAMLET","lines":["Why?"],"id":1150,"m":"Why?"},{"t":"sp","who":"FIRST CLOWN","lines":["'Twill not be seen in him there; there the men are as mad as he."],"id":1151,"m":"It won't be noticed in him there. The men there are as mad as he is."},{"t":"sp","who":"HAMLET","lines":["How came he mad?"],"id":1152,"m":"How did he go mad?"},{"t":"sp","who":"FIRST CLOWN","lines":["Very strangely, they say."],"id":1153,"m":"Very strangely, they say."},{"t":"sp","who":"HAMLET","lines":["How strangely?"],"id":1154,"m":"How strangely?"},{"t":"sp","who":"FIRST CLOWN","lines":["Faith, e'en with losing his wits."],"id":1155,"m":"Well, by losing his wits."},{"t":"sp","who":"HAMLET","lines":["Upon what ground?"],"id":1156,"m":"On what grounds?"},{"t":"sp","who":"FIRST CLOWN","lines":["Why, here in Denmark. I have been sexton here, man and boy, thirty","years."],"id":1157,"m":"Why, here in Denmark. I've been gravedigger here, man and boy, for thirty years."},{"t":"sp","who":"HAMLET","lines":["How long will a man lie i' th'earth ere he rot?"],"id":1158,"m":"How long will a man lie in the earth before he rots?"},{"t":"sp","who":"FIRST CLOWN","lines":["Faith, if he be not rotten before he die,—as we have many pocky corses","nowadays that will scarce hold the laying in,—he will last you some","eight year or nine year. A tanner will last you nine year."],"id":1159,"m":"Well, if he isn't rotten before he dies, since we get a lot of corpses these days so riddled with the pox that they hardly last till they're buried, he'll last you about eight or nine years. A tanner will last you nine years."},{"t":"sp","who":"HAMLET","lines":["Why he more than another?"],"id":1160,"m":"Why him more than anyone else?"},{"t":"sp","who":"FIRST CLOWN","lines":["Why, sir, his hide is so tann'd with his trade that he will keep out","water a great while. And your water is a sore decayer of your whoreson","dead body. Here's a skull now; this skull hath lain in the earth","three-and-twenty years."],"id":1161,"m":"Why, sir, his skin is so tanned by his trade that it keeps out water for a long time, and water is a terrible destroyer of your damned dead body. Here's a skull now. This skull has been lying in the earth for twenty-three years."},{"t":"sp","who":"HAMLET","lines":["Whose was it?"],"id":1162,"m":"Whose was it?"},{"t":"sp","who":"FIRST CLOWN","lines":["A whoreson, mad fellow's it was. Whose do you think it was?"],"id":1163,"m":"A damned mad fellow's it was. Whose do you think it was?"},{"t":"sp","who":"HAMLET","lines":["Nay, I know not."],"id":1164,"m":"No, I don't know."},{"t":"sp","who":"FIRST CLOWN","lines":["A pestilence on him for a mad rogue! A pour'd a flagon of Rhenish on my","head once. This same skull, sir, was Yorick's skull, the King's jester."],"id":1165,"m":"A plague on him for a mad rogue! He poured a jug of German wine over my head once. This very skull, sir, was Yorick's skull, the King's jester."},{"t":"sp","who":"HAMLET","lines":["This?"],"id":1166,"m":"This?"},{"t":"sp","who":"FIRST CLOWN","lines":["E'en that."],"id":1167,"m":"That very one."},{"t":"sp","who":"HAMLET","lines":["Let me see. [Takes the skull] Alas, poor Yorick. I knew him,","Horatio, a fellow of infinite jest, of most excellent fancy. He hath","borne me on his back a thousand times; and now, how abhorred in my","imagination it is! My gorge rises at it. Here hung those lips that I","have kiss'd I know not how oft. Where be your gibes now? your gambols?","your songs? your flashes of merriment, that were wont to set the table","on a roar? Not one now, to mock your own grinning? Quite chop-fallen?","Now get you to my lady's chamber, and tell her, let her paint an inch","thick, to this favour she must come. Make her laugh at that.—Prithee,","Horatio, tell me one thing."],"id":1168,"m":"Let me see. [Takes the skull] Oh, poor Yorick! I knew him, Horatio, a fellow of endless jokes and the most brilliant imagination. He carried me on his back a thousand times, and now how disgusting it is to think of! It makes me feel sick. Here hung those lips that I kissed I don't know how often. Where are your jokes now? Your capers? Your songs? Your flashes of fun that used to set the whole table roaring? Not one left now to mock your own grin? Your jaw has quite dropped. Now go to my lady's room and tell her that even if she paints her make-up on an inch thick, she must come to this face in the end. Make her laugh at that. Please, Horatio, tell me one thing."},{"t":"sp","who":"HORATIO","lines":["What's that, my lord?"],"id":1169,"m":"What's that, my lord?"},{"t":"sp","who":"HAMLET","lines":["Dost thou think Alexander looked o' this fashion i' th'earth?"],"id":1170,"m":"Do you think Alexander the Great looked like this in the earth?"},{"t":"sp","who":"HORATIO","lines":["E'en so."],"id":1171,"m":"Just like that."},{"t":"sp","who":"HAMLET","lines":["And smelt so? Pah!"],"id":1172,"m":"And smelt like this? Ugh!"},{"t":"sd","text":"Throws down the skull","id":1173},{"t":"sp","who":"HORATIO","lines":["E'en so, my lord."],"id":1174,"m":"Just like that, my lord."},{"t":"sp","who":"HAMLET","lines":["To what base uses we may return, Horatio! Why may not imagination trace","the noble dust of Alexander till he find it stopping a bung-hole?"],"id":1175,"m":"To what low uses we may come back, Horatio! Why couldn't the imagination follow the noble dust of Alexander until it finds it plugging a hole in a beer barrel?"},{"t":"sp","who":"HORATIO","lines":["'Twere to consider too curiously to consider so."],"id":1176,"m":"It would be thinking too elaborately to think like that."},{"t":"sp","who":"HAMLET","lines":["No, faith, not a jot. But to follow him thither with modesty enough,","and likelihood to lead it; as thus. Alexander died, Alexander was","buried, Alexander returneth into dust; the dust is earth; of earth we","make loam; and why of that loam whereto he was converted might they not","stop a beer-barrel?","Imperious Caesar, dead and turn'd to clay,","Might stop a hole to keep the wind away.","O, that that earth which kept the world in awe","Should patch a wall t'expel the winter's flaw.","But soft! but soft! aside! Here comes the King."],"id":1177,"m":"No, honestly, not a bit. Just follow him there reasonably, with likelihood to lead the way, like this: Alexander died, Alexander was buried, Alexander turns back into dust; the dust is earth; from earth we make clay; and why couldn't they use the clay he turned into to plug a beer barrel? Mighty Caesar, dead and turned to clay, might plug a hole to keep the wind away. Oh, that the earth which kept the world in awe should patch a wall to keep out the winter's gusts! But quiet! Quiet! Step aside! Here comes the King."},{"t":"sd","text":"Enter priests, &c, in procession; the corpse of Ophelia, Laertes and Mourners following; King, Queen, their Trains, &c.","id":1178},{"t":"sp","who":"HAMLET","cont":1,"lines":["The Queen, the courtiers. Who is that they follow?","And with such maimed rites? This doth betoken","The corse they follow did with desperate hand","Fordo it own life. 'Twas of some estate.","Couch we awhile and mark."],"id":1179,"m":"The Queen, the courtiers. Who is it they are following? And with such cut-down ceremonies? This shows that the body they follow took its own life with a desperate hand. It was someone of high rank. Let's hide for a while and watch."},{"t":"sd","text":"Retiring with Horatio","id":1180},{"t":"sp","who":"LAERTES","lines":["What ceremony else?"],"id":1181,"m":"What other ceremony is there?"},{"t":"sp","who":"HAMLET","lines":["That is Laertes, a very noble youth. Mark."],"id":1182,"m":"That's Laertes, a very noble young man. Watch."},{"t":"sp","who":"LAERTES","lines":["What ceremony else?"],"id":1183,"m":"What other ceremony is there?"},{"t":"sp","who":"PRIEST","lines":["Her obsequies have been as far enlarg'd","As we have warranties. Her death was doubtful;","And but that great command o'ersways the order,","She should in ground unsanctified have lodg'd","Till the last trumpet. For charitable prayers,","Shards, flints, and pebbles should be thrown on her.","Yet here she is allowed her virgin rites,","Her maiden strewments, and the bringing home","Of bell and burial."],"id":1184,"m":"Her funeral has been given as many rites as we are allowed. Her death was suspicious, and if the King's orders hadn't overruled the normal rules, she would have been buried in unholy ground until the trumpet sounds on Judgement Day. Instead of charitable prayers, broken pots, flints and pebbles would have been thrown on her. Yet here she is allowed the garlands of a virgin, flowers scattered for a maiden, and to be brought to her last home with the bell and a proper burial."},{"t":"sp","who":"LAERTES","lines":["Must there no more be done?"],"id":1185,"m":"Must nothing more be done?"},{"t":"sp","who":"PRIEST","lines":["No more be done.","We should profane the service of the dead","To sing sage requiem and such rest to her","As to peace-parted souls."],"id":1186,"m":"Nothing more must be done. We would be dishonouring the service for the dead to sing a solemn requiem and pray for rest for her as we do for souls who died in peace."},{"t":"sp","who":"LAERTES","lines":["Lay her i' th'earth,","And from her fair and unpolluted flesh","May violets spring. I tell thee, churlish priest,","A minist'ring angel shall my sister be","When thou liest howling."],"id":1187,"m":"Lay her in the earth, and may violets grow from her lovely, pure body! I tell you, you mean priest, my sister will be a ministering angel in heaven while you lie howling in hell."},{"t":"sp","who":"HAMLET","lines":["What, the fair Ophelia?"],"id":1188,"m":"What, the lovely Ophelia?"},{"t":"sp","who":"GERTRUDE","lines":["[Scattering flowers] Sweets to the sweet. Farewell.","I hop'd thou shouldst have been my Hamlet's wife;","I thought thy bride-bed to have deck'd, sweet maid,","And not have strew'd thy grave."],"id":1189,"m":"[Scattering flowers] Sweet flowers for the sweet girl. Goodbye. I hoped you would be my Hamlet's wife. I thought I'd be decorating your wedding bed, sweet girl, not scattering flowers on your grave."},{"t":"sp","who":"LAERTES","lines":["O, treble woe","Fall ten times treble on that cursed head","Whose wicked deed thy most ingenious sense","Depriv'd thee of. Hold off the earth a while,","Till I have caught her once more in mine arms.","[Leaps into the grave]","Now pile your dust upon the quick and dead,","Till of this flat a mountain you have made,","To o'ertop old Pelion or the skyish head","Of blue Olympus."],"id":1190,"m":"Oh, may three times the sorrow fall ten times three times on that cursed head whose wicked deed robbed you of your fine mind! Hold back the earth for a while, until I've held her in my arms once more. [Leaps into the grave] Now pile your dust on the living and the dead, until you've made a mountain out of this flat ground, higher than old Mount Pelion or the sky-high top of blue Olympus."},{"t":"sp","who":"HAMLET","lines":["[Advancing]","What is he whose grief","Bears such an emphasis? whose phrase of sorrow","Conjures the wand'ring stars, and makes them stand","Like wonder-wounded hearers? This is I,","Hamlet the Dane.","[Leaps into the grave]"],"id":1191,"m":"[Advancing] Who is this whose grief is shown with such emphasis, whose words of sorrow cast a spell on the wandering planets and make them stand still like listeners struck with wonder? This is I, Hamlet the Dane! [Leaps into the grave]"},{"t":"sp","who":"LAERTES","lines":["[Grappling with him] The devil take thy soul!"],"id":1192,"m":"[Grappling with him] The devil take your soul!"},{"t":"sp","who":"HAMLET","lines":["Thou pray'st not well.","I prithee take thy fingers from my throat;","For though I am not splenative and rash,","Yet have I in me something dangerous,","Which let thy wiseness fear. Away thy hand!"],"id":1193,"m":"That's not a good prayer. Please take your fingers off my throat, because although I'm not hot-tempered and rash, I still have something dangerous in me, which you would be wise to fear. Take your hand away!"},{"t":"sp","who":"CLAUDIUS","lines":["Pluck them asunder."],"id":1194,"m":"Pull them apart!"},{"t":"sp","who":"GERTRUDE","lines":["Hamlet! Hamlet!"],"id":1195,"m":"Hamlet! Hamlet!"},{"t":"sp","who":"ALL","lines":["Gentlemen!"],"id":1196,"m":"Gentlemen!"},{"t":"sp","who":"HORATIO","lines":["Good my lord, be quiet."],"id":1197,"m":"My good lord, calm down."},{"t":"sd","text":"The Attendants part them, and they come out of the grave","id":1198},{"t":"sp","who":"HAMLET","lines":["Why, I will fight with him upon this theme","Until my eyelids will no longer wag."],"id":1199,"m":"Why, I'll fight with him over this until my eyelids can no longer move."},{"t":"sp","who":"GERTRUDE","lines":["O my son, what theme?"],"id":1200,"m":"Oh, my son, over what?"},{"t":"sp","who":"HAMLET","lines":["I lov'd Ophelia; forty thousand brothers","Could not, with all their quantity of love,","Make up my sum. What wilt thou do for her?"],"id":1201,"m":"I loved Ophelia. Forty thousand brothers, with all their love added together, couldn't make up the total of mine. What will you do for her?"},{"t":"sp","who":"CLAUDIUS","lines":["O, he is mad, Laertes."],"id":1202,"m":"Oh, he is mad, Laertes."},{"t":"sp","who":"GERTRUDE","lines":["For love of God forbear him!"],"id":1203,"m":"For the love of God, leave him alone!"},{"t":"sp","who":"HAMLET","lines":["'Swounds, show me what thou'lt do:","Woul't weep? woul't fight? woul't fast? woul't tear thyself?","Woul't drink up eisel? eat a crocodile?","I'll do't. Dost thou come here to whine?","To outface me with leaping in her grave?","Be buried quick with her, and so will I.","And if thou prate of mountains, let them throw","Millions of acres on us, till our ground,","Singeing his pate against the burning zone,","Make Ossa like a wart. Nay, an thou'lt mouth,","I'll rant as well as thou."],"id":1204,"m":"By God's wounds, show me what you'll do. Will you weep? Will you fight? Will you starve yourself? Will you tear yourself to pieces? Will you drink vinegar? Eat a crocodile? I'll do it. Did you come here to whine? To outdo me by leaping into her grave? Be buried alive with her, and so will I. And if you babble about mountains, let them throw millions of acres on top of us, until the pile scorches its head against the burning sun and makes Mount Ossa look like a wart. No, if you're going to rant, I'll rant as well as you."},{"t":"sp","who":"GERTRUDE","lines":["This is mere madness:","And thus awhile the fit will work on him;","Anon, as patient as the female dove,","When that her golden couplets are disclos'd,","His silence will sit drooping."],"id":1205,"m":"This is pure madness, and the fit will work on him like this for a while. Then, as patient as the female dove when her golden pair of chicks have hatched, he'll sit silent and drooping."},{"t":"sp","who":"HAMLET","lines":["Hear you, sir;","What is the reason that you use me thus?","I lov'd you ever. But it is no matter.","Let Hercules himself do what he may,","The cat will mew, and dog will have his day."],"id":1206,"m":"Listen, sir, why do you treat me like this? I always loved you. But it doesn't matter. Let Hercules himself do what he can, the cat will mew, and the dog will have his day."},{"t":"sd","text":"Exit","id":1207},{"t":"sp","who":"CLAUDIUS","lines":["I pray thee, good Horatio, wait upon him."],"id":1208,"m":"Please, good Horatio, go and look after him."},{"t":"sd","text":"Exit Horatio","id":1209},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["[To Laertes] Strengthen your patience in our last night's speech;","We'll put the matter to the present push.—","Good Gertrude, set some watch over your son.","This grave shall have a living monument.","An hour of quiet shortly shall we see;","Till then in patience our proceeding be."],"id":1210,"m":"[To Laertes] Be patient, remembering what we said last night. We'll put the plan into action at once. Good Gertrude, have your son watched. This grave will have a living monument. We'll soon have an hour of peace. Until then, let us go about things patiently."},{"t":"sd","text":"Exeunt","id":1211},{"t":"scene","act":5,"scene":"II","loc":"A hall in the Castle.","id":1212},{"t":"sd","text":"Enter Hamlet and Horatio.","id":1213},{"t":"sp","who":"HAMLET","lines":["So much for this, sir. Now let me see the other;","You do remember all the circumstance?"],"id":1214,"m":"So much for that, sir. Now you'll hear the rest. Do you remember all the details?"},{"t":"sp","who":"HORATIO","lines":["Remember it, my lord!"],"id":1215,"m":"Remember them, my lord!"},{"t":"sp","who":"HAMLET","lines":["Sir, in my heart there was a kind of fighting","That would not let me sleep. Methought I lay","Worse than the mutinies in the bilboes. Rashly,","And prais'd be rashness for it,—let us know,","Our indiscretion sometime serves us well,","When our deep plots do pall; and that should teach us","There's a divinity that shapes our ends,","Rough-hew them how we will."],"id":1216,"m":"Sir, there was a kind of fighting in my heart that wouldn't let me sleep. I felt I was lying in a worse state than mutineers in chains. On impulse, and thank God for impulse, because we should know that our rashness sometimes works well for us when our careful plans fail, and that should teach us there's a divine power that shapes how things end, however roughly we carve them ourselves—"},{"t":"sp","who":"HORATIO","lines":["That is most certain."],"id":1217,"m":"That is quite certain."},{"t":"sp","who":"HAMLET","lines":["Up from my cabin,","My sea-gown scarf'd about me, in the dark","Grop'd I to find out them; had my desire,","Finger'd their packet, and in fine, withdrew","To mine own room again, making so bold,","My fears forgetting manners, to unseal","Their grand commission; where I found, Horatio,","Oh royal knavery! an exact command,","Larded with many several sorts of reasons,","Importing Denmark's health, and England's too,","With ho! such bugs and goblins in my life,","That on the supervise, no leisure bated,","No, not to stay the grinding of the axe,","My head should be struck off."],"id":1218,"m":"I got up from my cabin, wrapped my sea-coat round me, and groped in the dark to find them. I got what I wanted, fingered their package of letters, and finally went back to my own room, being so bold, since my fears made me forget my manners, as to break the seal on their important orders. And there I found, Horatio, oh, royal villainy! an exact command, padded with lots of different reasons about the welfare of Denmark and of England too, with such bogeymen and goblins if I were left alive, that as soon as the letter was read, with no time wasted, not even to wait for the axe to be sharpened, my head should be cut off."},{"t":"sp","who":"HORATIO","lines":["Is't possible?"],"id":1219,"m":"Is it possible?"},{"t":"sp","who":"HAMLET","lines":["Here's the commission, read it at more leisure.","But wilt thou hear me how I did proceed?"],"id":1220,"m":"Here are the orders. Read them when you have more time. But do you want to hear how I went on?"},{"t":"sp","who":"HORATIO","lines":["I beseech you."],"id":1221,"m":"Please, tell me."},{"t":"sp","who":"HAMLET","lines":["Being thus benetted round with villanies,—","Or I could make a prologue to my brains,","They had begun the play,—I sat me down,","Devis'd a new commission, wrote it fair:","I once did hold it, as our statists do,","A baseness to write fair, and labour'd much","How to forget that learning; but, sir, now","It did me yeoman's service. Wilt thou know","The effect of what I wrote?"],"id":1222,"m":"Being caught like this in a net of villainy, before I could even begin to think about it, my brain had started the play. I sat down, invented a new set of orders and wrote it out neatly. I used to think, as our statesmen do, that neat handwriting was something for lowly clerks, and I worked hard to forget that skill, but, sir, now it did me loyal service. Do you want to know what I wrote?"},{"t":"sp","who":"HORATIO","lines":["Ay, good my lord."],"id":1223,"m":"Yes, my good lord."},{"t":"sp","who":"HAMLET","lines":["An earnest conjuration from the King,","As England was his faithful tributary,","As love between them like the palm might flourish,","As peace should still her wheaten garland wear","And stand a comma 'tween their amities,","And many such-like 'as'es of great charge,","That on the view and know of these contents,","Without debatement further, more or less,","He should the bearers put to sudden death,","Not shriving-time allow'd."],"id":1224,"m":"A solemn request from the King, since England was his loyal subject state, since love between them should flourish like the palm tree, since peace should always wear her garland of wheat and stand like a link between their friendships, and many more such 'since's of great importance, that as soon as he had seen and read these contents, without any more discussion of any kind, he should put the bearers to immediate death, with no time allowed for confession."},{"t":"sp","who":"HORATIO","lines":["How was this seal'd?"],"id":1225,"m":"How did you seal it?"},{"t":"sp","who":"HAMLET","lines":["Why, even in that was heaven ordinant.","I had my father's signet in my purse,","Which was the model of that Danish seal:","Folded the writ up in the form of the other,","Subscrib'd it: gave't th'impression; plac'd it safely,","The changeling never known. Now, the next day","Was our sea-fight, and what to this was sequent","Thou know'st already."],"id":1226,"m":"Why, even in that, heaven was on my side. I had my father's seal ring in my purse, which was the original of the Danish royal seal. I folded the letter in the same way as the other one, signed it, stamped it with the seal and put it back safely; the substitute was never noticed. Now, the next day was our sea fight, and what happened after that you already know."},{"t":"sp","who":"HORATIO","lines":["So Guildenstern and Rosencrantz go to't."],"id":1227,"m":"So Guildenstern and Rosencrantz go to their deaths."},{"t":"sp","who":"HAMLET","lines":["Why, man, they did make love to this employment.","They are not near my conscience; their defeat","Does by their own insinuation grow.","'Tis dangerous when the baser nature comes","Between the pass and fell incensed points","Of mighty opposites."],"id":1228,"m":"Why, man, they courted this job. They don't weigh on my conscience. Their destruction comes from their own meddling. It's dangerous when lesser people come between the thrusts and fierce, angry sword points of mighty enemies."},{"t":"sp","who":"HORATIO","lines":["Why, what a king is this!"],"id":1229,"m":"Why, what a king this is!"},{"t":"sp","who":"HAMLET","lines":["Does it not, thinks't thee, stand me now upon,—","He that hath kill'd my king, and whor'd my mother,","Popp'd in between th'election and my hopes,","Thrown out his angle for my proper life,","And with such cozenage—is't not perfect conscience","To quit him with this arm? And is't not to be damn'd","To let this canker of our nature come","In further evil?"],"id":1230,"m":"Don't you think it's now my duty, against the man who has killed my king and made my mother a whore, who pushed in between the election and my hopes of the throne, who cast his fishing line for my own life, and with such trickery, isn't it right in all conscience to pay him back with this arm? And wouldn't I be damned to let this cancer on humanity go on to do more evil?"},{"t":"sp","who":"HORATIO","lines":["It must be shortly known to him from England","What is the issue of the business there."],"id":1231,"m":"He'll soon hear from England how the business there has turned out."},{"t":"sp","who":"HAMLET","lines":["It will be short. The interim is mine;","And a man's life's no more than to say 'One'.","But I am very sorry, good Horatio,","That to Laertes I forgot myself;","For by the image of my cause I see","The portraiture of his. I'll court his favours.","But sure the bravery of his grief did put me","Into a tow'ring passion."],"id":1232,"m":"It will be soon. The time in between is mine, and a man's life is no longer than it takes to say 'one'. But I'm very sorry, good Horatio, that I forgot myself with Laertes, because in the picture of my own cause I can see the likeness of his. I'll try to win his friendship. But the showiness of his grief really put me into a towering rage."},{"t":"sp","who":"HORATIO","lines":["Peace, who comes here?"],"id":1233,"m":"Quiet! Who's coming?"},{"t":"sd","text":"Enter Osric.","id":1234},{"t":"sp","who":"OSRIC","lines":["Your lordship is right welcome back to Denmark."],"id":1235,"m":"Your lordship is very welcome back to Denmark."},{"t":"sp","who":"HAMLET","lines":["I humbly thank you, sir. Dost know this waterfly?"],"id":1236,"m":"I humbly thank you, sir. [Aside to Horatio] Do you know this mayfly?"},{"t":"sp","who":"HORATIO","lines":["No, my good lord."],"id":1237,"m":"No, my good lord."},{"t":"sp","who":"HAMLET","lines":["Thy state is the more gracious; for 'tis a vice to know him. He hath","much land, and fertile; let a beast be lord of beasts, and his crib","shall stand at the king's mess; 'tis a chough; but, as I say, spacious","in the possession of dirt."],"id":1238,"m":"You're all the better for it, because it's a vice to know him. He has a lot of land, and good land. Let an animal be lord of animals, and his feeding trough will stand at the King's table. He's a chattering jackdaw, but, as I say, he owns a great deal of dirt."},{"t":"sp","who":"OSRIC","lines":["Sweet lord, if your lordship were at leisure, I should impart a thing","to you from his Majesty."],"id":1239,"m":"Sweet lord, if your lordship had time, I'd tell you something from his Majesty."},{"t":"sp","who":"HAMLET","lines":["I will receive it with all diligence of spirit. Put your bonnet to his","right use; 'tis for the head."],"id":1240,"m":"I'll receive it with all my attention. Put your hat to its proper use. It's for the head."},{"t":"sp","who":"OSRIC","lines":["I thank your lordship, 'tis very hot."],"id":1241,"m":"I thank your lordship, it's very hot."},{"t":"sp","who":"HAMLET","lines":["No, believe me, 'tis very cold, the wind is northerly."],"id":1242,"m":"No, believe me, it's very cold. The wind is from the north."},{"t":"sp","who":"OSRIC","lines":["It is indifferent cold, my lord, indeed."],"id":1243,"m":"It is fairly cold, my lord, indeed."},{"t":"sp","who":"HAMLET","lines":["Methinks it is very sultry and hot for my complexion."],"id":1244,"m":"But I think it's very sultry and hot for someone like me."},{"t":"sp","who":"OSRIC","lines":["Exceedingly, my lord; it is very sultry,—as 'twere—I cannot tell how.","But, my lord, his Majesty bade me signify to you that he has laid a","great wager on your head. Sir, this is the matter,—"],"id":1245,"m":"Very, my lord. It's very sultry, as if, I can't say how. But, my lord, his Majesty asked me to tell you that he has made a large bet on you. Sir, this is the matter—"},{"t":"sp","who":"HAMLET","lines":["I beseech you, remember,—"],"id":1246,"m":"Please, remember—"},{"t":"sd","text":"Hamlet moves him to put on his hat","id":1247},{"t":"sp","who":"OSRIC","lines":["Nay, in good faith; for mine ease, in good faith. Sir, here is newly","come to court Laertes; believe me, an absolute gentleman, full of most","excellent differences, of very soft society and great showing. Indeed,","to speak feelingly of him, he is the card or calendar of gentry; for","you shall find in him the continent of what part a gentleman would see."],"id":1248,"m":"No, really, I'm comfortable, really. Sir, Laertes has just come to court. Believe me, a perfect gentleman, full of the most excellent qualities, very pleasant company and very impressive. Indeed, to speak of him fittingly, he is the map and guide of good breeding, because you will find in him every quality a gentleman would want to see."},{"t":"sp","who":"HAMLET","lines":["Sir, his definement suffers no perdition in you, though I know, to","divide him inventorially would dizzy th'arithmetic of memory, and yet","but yaw neither, in respect of his quick sail. But, in the verity of","extolment, I take him to be a soul of great article and his infusion of","such dearth and rareness as, to make true diction of him, his semblable","is his mirror and who else would trace him his umbrage, nothing more."],"id":1249,"m":"Sir, his description loses nothing in your telling, though I know that to list his qualities one by one would make the memory dizzy with counting, and even then it would only stagger along behind his speed. But, to praise him truthfully, I take him to be a soul of great importance, and his nature so precious and rare that, to speak truly of him, the only thing like him is his own mirror, and anyone else who tried to follow him would be his shadow, nothing more."},{"t":"sp","who":"OSRIC","lines":["Your lordship speaks most infallibly of him."],"id":1250,"m":"Your lordship speaks of him with complete accuracy."},{"t":"sp","who":"HAMLET","lines":["The concernancy, sir? Why do we wrap the gentleman in our more rawer","breath?"],"id":1251,"m":"The point, sir? Why are we wrapping the gentleman in our cruder breath?"},{"t":"sp","who":"OSRIC","lines":["Sir?"],"id":1252,"m":"Sir?"},{"t":"sp","who":"HORATIO","lines":["Is't not possible to understand in another tongue? You will do't, sir,","really."],"id":1253,"m":"Isn't it possible to understand in a different language? You'll manage it, sir, really."},{"t":"sp","who":"HAMLET","lines":["What imports the nomination of this gentleman?"],"id":1254,"m":"Why are we mentioning this gentleman?"},{"t":"sp","who":"OSRIC","lines":["Of Laertes?"],"id":1255,"m":"Laertes?"},{"t":"sp","who":"HORATIO","lines":["His purse is empty already, all's golden words are spent."],"id":1256,"m":"[Aside] His purse is empty already. All his golden words are spent."},{"t":"sp","who":"HAMLET","lines":["Of him, sir."],"id":1257,"m":"Him, sir."},{"t":"sp","who":"OSRIC","lines":["I know you are not ignorant,—"],"id":1258,"m":"I know you are not ignorant—"},{"t":"sp","who":"HAMLET","lines":["I would you did, sir; yet in faith if you did, it would not much","approve me. Well, sir?"],"id":1259,"m":"I wish you did know it, sir, though honestly, if you did, it wouldn't be much of a compliment to me. Well, sir?"},{"t":"sp","who":"OSRIC","lines":["You are not ignorant of what excellence Laertes is,—"],"id":1260,"m":"You are not ignorant of how excellent Laertes is—"},{"t":"sp","who":"HAMLET","lines":["I dare not confess that, lest I should compare with him in excellence;","but to know a man well were to know himself."],"id":1261,"m":"I don't dare admit that, in case I seem to compare myself with him in excellence. To know another man well, you'd have to know yourself."},{"t":"sp","who":"OSRIC","lines":["I mean, sir, for his weapon; but in the imputation laid on him, by them","in his meed he's unfellowed."],"id":1262,"m":"I mean, sir, with his weapon. In the reputation people give him, he has no equal in his skill."},{"t":"sp","who":"HAMLET","lines":["What's his weapon?"],"id":1263,"m":"What's his weapon?"},{"t":"sp","who":"OSRIC","lines":["Rapier and dagger."],"id":1264,"m":"Rapier and dagger."},{"t":"sp","who":"HAMLET","lines":["That's two of his weapons. But well."],"id":1265,"m":"That's two of his weapons. But go on."},{"t":"sp","who":"OSRIC","lines":["The King, sir, hath wager'd with him six Barbary horses, against the","which he has imponed, as I take it, six French rapiers and poniards,","with their assigns, as girdle, hangers, and so. Three of the carriages,","in faith, are very dear to fancy, very responsive to the hilts, most","delicate carriages, and of very liberal conceit."],"id":1266,"m":"The King, sir, has bet him six Arab horses, and against them he has staked, as I understand it, six French rapiers and daggers, with their accessories, such as belts, hangers and so on. Three of the 'carriages', honestly, are very fine to look at, very well matched to the hilts, very delicate carriages and very elaborately designed."},{"t":"sp","who":"HAMLET","lines":["What call you the carriages?"],"id":1267,"m":"What do you call the carriages?"},{"t":"sp","who":"HORATIO","lines":["I knew you must be edified by the margin ere you had done."],"id":1268,"m":"[Aside to Hamlet] I knew you'd need the footnotes before you'd finished."},{"t":"sp","who":"OSRIC","lines":["The carriages, sir, are the hangers."],"id":1269,"m":"The carriages, sir, are the hangers."},{"t":"sp","who":"HAMLET","lines":["The phrase would be more german to the matter if we could carry cannon","by our sides. I would it might be hangers till then. But on. Six","Barbary horses against six French swords, their assigns, and three","liberal conceited carriages: that's the French bet against the Danish.","Why is this all imponed, as you call it?"],"id":1270,"m":"The word would be more fitting if we carried cannon at our sides. Until then I'd prefer 'hangers'. But go on. Six Arab horses against six French swords, their accessories and three elaborately designed carriages: that's the French bet against the Danish. Why is all this 'staked', as you call it?"},{"t":"sp","who":"OSRIC","lines":["The King, sir, hath laid that in a dozen passes between you and him, he","shall not exceed you three hits. He hath laid on twelve for nine. And","it would come to immediate trial if your lordship would vouchsafe the","answer."],"id":1271,"m":"The King, sir, has bet that in a dozen bouts between you and Laertes, he won't beat you by more than three hits. Laertes has bet he'll win twelve for nine. And it would be tried at once if your lordship would agree to answer."},{"t":"sp","who":"HAMLET","lines":["How if I answer no?"],"id":1272,"m":"What if I answer no?"},{"t":"sp","who":"OSRIC","lines":["I mean, my lord, the opposition of your person in trial."],"id":1273,"m":"I mean, my lord, the meeting of your person with him in the contest."},{"t":"sp","who":"HAMLET","lines":["Sir, I will walk here in the hall. If it please his Majesty, it is the","breathing time of day with me. Let the foils be brought, the gentleman","willing, and the King hold his purpose, I will win for him if I can; if","not, I will gain nothing but my shame and the odd hits."],"id":1274,"m":"Sir, I'll be walking here in the hall. If it pleases his Majesty, this is my time of day for exercise. Let the swords be brought. If the gentleman is willing and the King still wants it, I'll win for him if I can. If not, I'll gain nothing but my shame and the odd hits."},{"t":"sp","who":"OSRIC","lines":["Shall I re-deliver you e'en so?"],"id":1275,"m":"Shall I take back your answer like that?"},{"t":"sp","who":"HAMLET","lines":["To this effect, sir; after what flourish your nature will."],"id":1276,"m":"Along those lines, sir, with whatever decorations you like."},{"t":"sp","who":"OSRIC","lines":["I commend my duty to your lordship."],"id":1277,"m":"I offer my service to your lordship."},{"t":"sp","who":"HAMLET","lines":["Yours, yours."],"id":1278,"m":"Yours, yours."},{"t":"sd","text":"Exit Osric","id":1279},{"t":"sp","who":"HAMLET","cont":1,"lines":["He does well to commend it himself, there are no tongues else for's","turn."],"id":1280,"m":"He does well to offer it himself. There's no one else's tongue that would do it for him."},{"t":"sp","who":"HORATIO","lines":["This lapwing runs away with the shell on his head."],"id":1281,"m":"This baby bird is running off with the shell still on its head."},{"t":"sp","who":"HAMLET","lines":["He did comply with his dug before he suck'd it. Thus has he,—and many","more of the same bevy that I know the drossy age dotes on,— only got","the tune of the time and outward habit of encounter; a kind of yeasty","collection, which carries them through and through the most fanned and","winnowed opinions; and do but blow them to their trial, the bubbles are","out."],"id":1282,"m":"He bowed and scraped to his mother's breast before he sucked it. Like him, and many more of the same flock that I know this worthless age dotes on, he has only learned the fashionable tune of the times and the outward manners of conversation, a kind of frothy collection of phrases that carries them through even the most refined and sifted opinions. But just blow on them to test them, and the bubbles burst."},{"t":"sd","text":"Enter a Lord.","id":1283},{"t":"sp","who":"LORD","lines":["My lord, his Majesty commended him to you by young Osric, who brings","back to him that you attend him in the hall. He sends to know if your","pleasure hold to play with Laertes or that you will take longer time."],"id":1284,"m":"My lord, his Majesty sent his greetings to you through young Osric, who has told him that you are waiting for him in the hall. He wants to know if you still want to fence with Laertes, or if you'd like more time."},{"t":"sp","who":"HAMLET","lines":["I am constant to my purposes, they follow the King's pleasure. If his","fitness speaks, mine is ready. Now or whensoever, provided I be so able","as now."],"id":1285,"m":"I stick to my intentions; they follow the King's wishes. If he's ready, so am I, now or at any time, as long as I'm as fit as I am now."},{"t":"sp","who":"LORD","lines":["The King and Queen and all are coming down."],"id":1286,"m":"The King and Queen and everyone are coming down."},{"t":"sp","who":"HAMLET","lines":["In happy time."],"id":1287,"m":"Good timing."},{"t":"sp","who":"LORD","lines":["The Queen desires you to use some gentle entertainment to Laertes","before you fall to play."],"id":1288,"m":"The Queen wants you to be friendly to Laertes before you start fencing."},{"t":"sp","who":"HAMLET","lines":["She well instructs me."],"id":1289,"m":"That's good advice."},{"t":"sd","text":"Exit Lord","id":1290},{"t":"sp","who":"HORATIO","lines":["You will lose this wager, my lord."],"id":1291,"m":"You'll lose this bet, my lord."},{"t":"sp","who":"HAMLET","lines":["I do not think so. Since he went into France, I have been in continual","practice. I shall win at the odds. But thou wouldst not think how ill","all's here about my heart: but it is no matter."],"id":1292,"m":"I don't think so. Since he went to France, I've been practising all the time. I'll win with the odds I've been given. But you wouldn't believe how bad I feel here around my heart. But it doesn't matter."},{"t":"sp","who":"HORATIO","lines":["Nay, good my lord."],"id":1293,"m":"No, my good lord—"},{"t":"sp","who":"HAMLET","lines":["It is but foolery; but it is such a kind of gain-giving as would","perhaps trouble a woman."],"id":1294,"m":"It's only foolishness, but it's the kind of uneasy feeling that might worry a woman."},{"t":"sp","who":"HORATIO","lines":["If your mind dislike anything, obey it. I will forestall their repair","hither, and say you are not fit."],"id":1295,"m":"If your mind is uneasy about anything, obey it. I'll stop them coming here and say you're not well."},{"t":"sp","who":"HAMLET","lines":["Not a whit, we defy augury. There's a special providence in the fall of","a sparrow. If it be now, 'tis not to come; if it be not to come, it","will be now; if it be not now, yet it will come. The readiness is all.","Since no man has aught of what he leaves, what is't to leave betimes?"],"id":1296,"m":"Not at all. We defy omens. There's a special providence even in the fall of a sparrow. If it is now, it is not to come; if it is not to come, it will be now; if it is not now, still it will come. Being ready is everything. Since no one keeps any of what he leaves behind, what does it matter if he leaves early?"},{"t":"sd","text":"Enter King, Queen, Laertes, Lords, Osric and Attendants with foils &c.","id":1297},{"t":"sp","who":"CLAUDIUS","lines":["Come, Hamlet, come, and take this hand from me."],"id":1298,"m":"Come, Hamlet, come, and take this hand from me."},{"t":"sd","text":"The King puts Laertes's hand into Hamlet's","id":1299},{"t":"sp","who":"HAMLET","lines":["Give me your pardon, sir. I have done you wrong;","But pardon't as you are a gentleman.","This presence knows, and you must needs have heard,","How I am punish'd with sore distraction.","What I have done","That might your nature, honour, and exception","Roughly awake, I here proclaim was madness.","Was't Hamlet wrong'd Laertes? Never Hamlet.","If Hamlet from himself be ta'en away,","And when he's not himself does wrong Laertes,","Then Hamlet does it not, Hamlet denies it.","Who does it, then? His madness. If't be so,","Hamlet is of the faction that is wrong'd;","His madness is poor Hamlet's enemy.","Sir, in this audience,","Let my disclaiming from a purpos'd evil","Free me so far in your most generous thoughts","That I have shot my arrow o'er the house","And hurt my brother."],"id":1300,"m":"Forgive me, sir. I have done you wrong, but forgive it, as you are a gentleman. Everyone here knows, and you must have heard, how I have been punished with a terrible madness. Whatever I have done that might have roughly roused your feelings, your honour and your resentment, I declare here was madness. Was it Hamlet who wronged Laertes? Never Hamlet. If Hamlet is taken away from himself, and when he's not himself he wrongs Laertes, then Hamlet doesn't do it. Hamlet denies it. Who does it, then? His madness. If that's so, Hamlet is on the side of the injured. His madness is poor Hamlet's enemy. Sir, in front of these people, let my denial that I meant any harm free me so far in your generous thoughts as if I had shot an arrow over the house and accidentally hurt my brother."},{"t":"sp","who":"LAERTES","lines":["I am satisfied in nature,","Whose motive in this case should stir me most","To my revenge. But in my terms of honour","I stand aloof, and will no reconcilement","Till by some elder masters of known honour","I have a voice and precedent of peace","To keep my name ungor'd. But till that time","I do receive your offer'd love like love,","And will not wrong it."],"id":1301,"m":"As far as my natural feelings go, which in this case should push me hardest towards revenge, I am satisfied. But as far as honour goes, I hold back, and I won't make peace until some older experts in matters of honour give me their opinion and a precedent for peace, so that my name is not stained. But until then, I accept your offered love as love, and I won't wrong it."},{"t":"sp","who":"HAMLET","lines":["I embrace it freely,","And will this brother's wager frankly play.—","Give us the foils; come on."],"id":1302,"m":"I welcome that wholeheartedly, and I'll fence in this brotherly contest with an open heart. Give us the swords. Come on."},{"t":"sp","who":"LAERTES","lines":["Come, one for me."],"id":1303,"m":"Come, give me one."},{"t":"sp","who":"HAMLET","lines":["I'll be your foil, Laertes; in mine ignorance","Your skill shall like a star i' th' darkest night,","Stick fiery off indeed."],"id":1304,"m":"I'll be your foil, Laertes. Next to my lack of skill, yours will shine out like a star in the darkest night."},{"t":"sp","who":"LAERTES","lines":["You mock me, sir."],"id":1305,"m":"You're mocking me, sir."},{"t":"sp","who":"HAMLET","lines":["No, by this hand."],"id":1306,"m":"No, I swear by this hand."},{"t":"sp","who":"CLAUDIUS","lines":["Give them the foils, young Osric. Cousin Hamlet,","You know the wager?"],"id":1307,"m":"Give them the swords, young Osric. Nephew Hamlet, you know the bet?"},{"t":"sp","who":"HAMLET","lines":["Very well, my lord.","Your Grace has laid the odds o' the weaker side."],"id":1308,"m":"Very well, my lord. Your Grace has bet on the weaker side."},{"t":"sp","who":"CLAUDIUS","lines":["I do not fear it. I have seen you both;","But since he is better'd, we have therefore odds."],"id":1309,"m":"I'm not worried. I've seen you both fence. But since he has improved, we've been given odds."},{"t":"sp","who":"LAERTES","lines":["This is too heavy. Let me see another."],"id":1310,"m":"This one's too heavy. Let me see another."},{"t":"sp","who":"HAMLET","lines":["This likes me well. These foils have all a length?"],"id":1311,"m":"I like this one. Are these swords all the same length?"},{"t":"sd","text":"They prepare to play","id":1312},{"t":"sp","who":"OSRIC","lines":["Ay, my good lord."],"id":1313,"m":"Yes, my good lord."},{"t":"sp","who":"CLAUDIUS","lines":["Set me the stoups of wine upon that table.","If Hamlet give the first or second hit,","Or quit in answer of the third exchange,","Let all the battlements their ordnance fire;","The King shall drink to Hamlet's better breath,","And in the cup an union shall he throw","Richer than that which four successive kings","In Denmark's crown have worn. Give me the cups;","And let the kettle to the trumpet speak,","The trumpet to the cannoneer without,","The cannons to the heavens, the heavens to earth,","'Now the King drinks to Hamlet.' Come, begin.","And you, the judges, bear a wary eye."],"id":1314,"m":"Put the jugs of wine on that table for me. If Hamlet makes the first or second hit, or gets even in the third bout, let all the cannons on the battlements fire. The King will drink to Hamlet's health, and he'll throw a pearl into the cup, richer than the one four kings in a row have worn in Denmark's crown. Give me the cups, and let the kettledrum tell the trumpet, the trumpet the gunner outside, the cannons the heavens, and the heavens the earth: 'Now the King drinks to Hamlet!' Come, begin. And you judges, watch carefully."},{"t":"sp","who":"HAMLET","lines":["Come on, sir."],"id":1315,"m":"Come on, sir."},{"t":"sp","who":"LAERTES","lines":["Come, my lord."],"id":1316,"m":"Come, my lord."},{"t":"sd","text":"They play","id":1317},{"t":"sp","who":"HAMLET","lines":["One."],"id":1318,"m":"One."},{"t":"sp","who":"LAERTES","lines":["No."],"id":1319,"m":"No."},{"t":"sp","who":"HAMLET","lines":["Judgement."],"id":1320,"m":"Judges?"},{"t":"sp","who":"OSRIC","lines":["A hit, a very palpable hit."],"id":1321,"m":"A hit, a very clear hit."},{"t":"sp","who":"LAERTES","lines":["Well; again."],"id":1322,"m":"Well, again."},{"t":"sp","who":"CLAUDIUS","lines":["Stay, give me drink. Hamlet, this pearl is thine;","Here's to thy health."],"id":1323,"m":"Wait, give me a drink. Hamlet, this pearl is yours. Here's to your health!"},{"t":"sd","text":"Trumpets sound, and cannon shot off within","id":1324},{"t":"sp","who":"CLAUDIUS","cont":1,"lines":["Give him the cup."],"id":1325,"m":"Give him the cup."},{"t":"sp","who":"HAMLET","lines":["I'll play this bout first; set it by awhile."],"id":1326,"m":"I'll fence this bout first. Put it down for a while."},{"t":"sd","text":"They play","id":1327},{"t":"sp","who":"HAMLET","cont":1,"lines":["Come. Another hit; what say you?"],"id":1328,"m":"Come on. Another hit. What do you say?"},{"t":"sp","who":"LAERTES","lines":["A touch, a touch, I do confess."],"id":1329,"m":"A touch, a touch, I admit."},{"t":"sp","who":"CLAUDIUS","lines":["Our son shall win."],"id":1330,"m":"Our son will win."},{"t":"sp","who":"GERTRUDE","lines":["He's fat, and scant of breath.","Here, Hamlet, take my napkin, rub thy brows.","The Queen carouses to thy fortune, Hamlet."],"id":1331,"m":"He's sweaty and out of breath. Here, Hamlet, take my handkerchief and wipe your forehead. The Queen drinks to your good luck, Hamlet."},{"t":"sp","who":"HAMLET","lines":["Good madam."],"id":1332,"m":"Thank you, madam."},{"t":"sp","who":"CLAUDIUS","lines":["Gertrude, do not drink."],"id":1333,"m":"Gertrude, don't drink."},{"t":"sp","who":"GERTRUDE","lines":["I will, my lord; I pray you pardon me."],"id":1334,"m":"I will, my lord. Please excuse me."},{"t":"sp","who":"CLAUDIUS","lines":["[Aside] It is the poison'd cup; it is too late."],"id":1335,"m":"[Aside] It's the poisoned cup. It's too late."},{"t":"sp","who":"HAMLET","lines":["I dare not drink yet, madam. By and by."],"id":1336,"m":"I don't dare drink yet, madam. Soon."},{"t":"sp","who":"GERTRUDE","lines":["Come, let me wipe thy face."],"id":1337,"m":"Come, let me wipe your face."},{"t":"sp","who":"LAERTES","lines":["My lord, I'll hit him now."],"id":1338,"m":"My lord, I'll hit him now."},{"t":"sp","who":"CLAUDIUS","lines":["I do not think't."],"id":1339,"m":"I don't think so."},{"t":"sp","who":"LAERTES","lines":["[Aside] And yet 'tis almost 'gainst my conscience."],"id":1340,"m":"[Aside] And yet it's almost against my conscience."},{"t":"sp","who":"HAMLET","lines":["Come for the third, Laertes. You do but dally.","I pray you pass with your best violence.","I am afeard you make a wanton of me."],"id":1341,"m":"Come on, the third bout, Laertes. You're only playing about. Please attack with all your force. I'm afraid you're treating me like a spoilt child."},{"t":"sp","who":"LAERTES","lines":["Say you so? Come on."],"id":1342,"m":"Is that what you say? Come on."},{"t":"sd","text":"They play","id":1343},{"t":"sp","who":"OSRIC","lines":["Nothing neither way."],"id":1344,"m":"No hit either way."},{"t":"sp","who":"LAERTES","lines":["Have at you now."],"id":1345,"m":"Take that!"},{"t":"sd","text":"Laertes wounds Hamlet; then, in scuffling, they change rapiers, and Hamlet wounds Laertes","id":1346},{"t":"sp","who":"CLAUDIUS","lines":["Part them; they are incens'd."],"id":1347,"m":"Part them. They're getting angry."},{"t":"sp","who":"HAMLET","lines":["Nay, come again!"],"id":1348,"m":"No, come on again!"},{"t":"sd","text":"The Queen falls","id":1349},{"t":"sp","who":"OSRIC","lines":["Look to the Queen there, ho!"],"id":1350,"m":"Look after the Queen there, ho!"},{"t":"sp","who":"HORATIO","lines":["They bleed on both sides. How is it, my lord?"],"id":1351,"m":"They are both bleeding. How are you, my lord?"},{"t":"sp","who":"OSRIC","lines":["How is't, Laertes?"],"id":1352,"m":"How are you, Laertes?"},{"t":"sp","who":"LAERTES","lines":["Why, as a woodcock to my own springe, Osric.","I am justly kill'd with mine own treachery."],"id":1353,"m":"Why, like a stupid bird caught in my own trap, Osric. I'm justly killed by my own treachery."},{"t":"sp","who":"HAMLET","lines":["How does the Queen?"],"id":1354,"m":"How is the Queen?"},{"t":"sp","who":"CLAUDIUS","lines":["She swoons to see them bleed."],"id":1355,"m":"She's fainted at seeing them bleed."},{"t":"sp","who":"GERTRUDE","lines":["No, no, the drink, the drink! O my dear Hamlet!","The drink, the drink! I am poison'd."],"id":1356,"m":"No, no, the drink, the drink! Oh, my dear Hamlet! The drink, the drink! I've been poisoned."},{"t":"sd","text":"Dies","id":1357},{"t":"sp","who":"HAMLET","lines":["O villany! Ho! Let the door be lock'd:","Treachery! Seek it out."],"id":1358,"m":"Oh, villainy! Ho! Lock the door! Treachery! Find out who did it!"},{"t":"sd","text":"Laertes falls","id":1359},{"t":"sp","who":"LAERTES","lines":["It is here, Hamlet. Hamlet, thou art slain.","No medicine in the world can do thee good.","In thee there is not half an hour of life;","The treacherous instrument is in thy hand,","Unbated and envenom'd. The foul practice","Hath turn'd itself on me. Lo, here I lie,","Never to rise again. Thy mother's poison'd.","I can no more. The King, the King's to blame."],"id":1360,"m":"It's here, Hamlet. Hamlet, you are killed. No medicine in the world can help you. You don't have half an hour to live. The treacherous weapon is in your hand, unblunted and poisoned. The foul trick has turned back on me. Look, here I lie, never to get up again. Your mother has been poisoned. I can't say any more. The King, the King is to blame."},{"t":"sp","who":"HAMLET","lines":["The point envenom'd too!","Then, venom, to thy work."],"id":1361,"m":"The tip poisoned too! Then, poison, do your work!"},{"t":"sd","text":"Stabs the King","id":1362},{"t":"sp","who":"OSRIC AND LORDS","lines":["Treason! treason!"],"id":1363,"m":"Treason! Treason!"},{"t":"sp","who":"CLAUDIUS","lines":["O yet defend me, friends. I am but hurt."],"id":1364,"m":"Oh, defend me still, friends. I'm only wounded."},{"t":"sp","who":"HAMLET","lines":["Here, thou incestuous, murderous, damned Dane,","Drink off this potion. Is thy union here?","Follow my mother."],"id":1365,"m":"Here, you incestuous, murdering, damned Dane, drink up this potion! Is your pearl in here? Follow my mother!"},{"t":"sd","text":"King dies","id":1366},{"t":"sp","who":"LAERTES","lines":["He is justly serv'd.","It is a poison temper'd by himself.","Exchange forgiveness with me, noble Hamlet.","Mine and my father's death come not upon thee,","Nor thine on me."],"id":1367,"m":"He has got what he deserves. It's a poison he mixed himself. Let's forgive each other, noble Hamlet. May my death and my father's not be on your head, nor yours on mine!"},{"t":"sd","text":"Dies","id":1368},{"t":"sp","who":"HAMLET","lines":["Heaven make thee free of it! I follow thee.","I am dead, Horatio. Wretched Queen, adieu.","You that look pale and tremble at this chance,","That are but mutes or audience to this act,","Had I but time,—as this fell sergeant, death,","Is strict in his arrest,—O, I could tell you,—","But let it be. Horatio, I am dead,","Thou liv'st; report me and my cause aright","To the unsatisfied."],"id":1369,"m":"May heaven free you from guilt for it! I'll follow you. I'm dead, Horatio. Wretched Queen, goodbye! You who look pale and tremble at what has happened, who are only silent extras or audience to this act, if only I had time, since this cruel officer, death, is strict in his arrest, oh, I could tell you— But let it be. Horatio, I'm dead. You are alive. Tell my story and my cause truthfully to those who don't know."},{"t":"sp","who":"HORATIO","lines":["Never believe it.","I am more an antique Roman than a Dane.","Here's yet some liquor left."],"id":1370,"m":"Never believe it. I'm more like an ancient Roman than a Dane. There's still some poison left."},{"t":"sp","who":"HAMLET","lines":["As th'art a man,","Give me the cup. Let go; by Heaven, I'll have't.","O good Horatio, what a wounded name,","Things standing thus unknown, shall live behind me.","If thou didst ever hold me in thy heart,","Absent thee from felicity awhile,","And in this harsh world draw thy breath in pain,","To tell my story."],"id":1371,"m":"As you are a man, give me the cup. Let go! By heaven, I'll have it. Oh, good Horatio, what a damaged name I'll leave behind me if things stay unknown like this! If you ever held me in your heart, keep away from the happiness of death for a while, and in this harsh world breathe in pain, to tell my story."},{"t":"sd","text":"March afar off, and shot within","id":1372},{"t":"sp","who":"HAMLET","cont":1,"lines":["What warlike noise is this?"],"id":1373,"m":"What warlike noise is this?"},{"t":"sp","who":"OSRIC","lines":["Young Fortinbras, with conquest come from Poland,","To the ambassadors of England gives","This warlike volley."],"id":1374,"m":"Young Fortinbras, coming back victorious from Poland, fires this military salute to the ambassadors from England."},{"t":"sp","who":"HAMLET","lines":["O, I die, Horatio.","The potent poison quite o'er-crows my spirit:","I cannot live to hear the news from England,","But I do prophesy th'election lights","On Fortinbras. He has my dying voice.","So tell him, with the occurrents more and less,","Which have solicited. The rest is silence."],"id":1375,"m":"Oh, I'm dying, Horatio. The strong poison completely overpowers my spirit. I can't live to hear the news from England. But I predict that the election will fall on Fortinbras. He has my dying vote. So tell him, along with the events, large and small, that have led to this. The rest is silence."},{"t":"sd","text":"Dies","id":1376},{"t":"sp","who":"HORATIO","lines":["Now cracks a noble heart. Good night, sweet prince,","And flights of angels sing thee to thy rest.","Why does the drum come hither?"],"id":1377,"m":"Now a noble heart breaks. Good night, sweet prince, and may flights of angels sing you to your rest! Why is the drum coming this way?"},{"t":"sd","text":"March within","id":1378},{"t":"sd","text":"Enter Fortinbras, the English Ambassadors and others.","id":1379},{"t":"sp","who":"FORTINBRAS","lines":["Where is this sight?"],"id":1380,"m":"Where is this sight?"},{"t":"sp","who":"HORATIO","lines":["What is it you would see?","If aught of woe or wonder, cease your search."],"id":1381,"m":"What is it you want to see? If it's anything of sorrow or horror, look no further."},{"t":"sp","who":"FORTINBRAS","lines":["This quarry cries on havoc. O proud death,","What feast is toward in thine eternal cell,","That thou so many princes at a shot","So bloodily hast struck?"],"id":1382,"m":"This pile of bodies cries out of slaughter. Oh, proud Death, what feast is being prepared in your eternal cell, that you have struck down so many princes with one shot, so bloodily?"},{"t":"sp","who":"FIRST AMBASSADOR","lines":["The sight is dismal;","And our affairs from England come too late.","The ears are senseless that should give us hearing,","To tell him his commandment is fulfill'd,","That Rosencrantz and Guildenstern are dead.","Where should we have our thanks?"],"id":1383,"m":"The sight is terrible, and our business from England has come too late. The ears that should hear us, to be told his order has been carried out and that Rosencrantz and Guildenstern are dead, can no longer hear. Who will thank us now?"},{"t":"sp","who":"HORATIO","lines":["Not from his mouth,","Had it th'ability of life to thank you.","He never gave commandment for their death.","But since, so jump upon this bloody question,","You from the Polack wars, and you from England","Are here arriv'd, give order that these bodies","High on a stage be placed to the view,","And let me speak to th' yet unknowing world","How these things came about. So shall you hear","Of carnal, bloody and unnatural acts,","Of accidental judgements, casual slaughters,","Of deaths put on by cunning and forc'd cause,","And, in this upshot, purposes mistook","Fall'n on the inventors' heads. All this can I","Truly deliver."],"id":1384,"m":"Not his mouth, even if it had the life to thank you. He never ordered their deaths. But since you have arrived here so soon after this bloody business, you from the Polish wars and you from England, give orders that these bodies be put high on a platform for everyone to see, and let me tell the world, which doesn't know yet, how these things happened. Then you will hear of lustful, bloody and unnatural acts, of accidental judgements and chance killings, of deaths caused by cunning and by force, and, in this ending, of plans gone wrong that fell back on the heads of those who made them. All this I can truthfully tell you."},{"t":"sp","who":"FORTINBRAS","lines":["Let us haste to hear it,","And call the noblest to the audience.","For me, with sorrow I embrace my fortune.","I have some rights of memory in this kingdom,","Which now to claim my vantage doth invite me."],"id":1385,"m":"Let's hurry to hear it, and call the noblest people to listen. As for me, I accept my good fortune with sorrow. I have some long-remembered rights to this kingdom, which my position now invites me to claim."},{"t":"sp","who":"HORATIO","lines":["Of that I shall have also cause to speak,","And from his mouth whose voice will draw on more.","But let this same be presently perform'd,","Even while men's minds are wild, lest more mischance","On plots and errors happen."],"id":1386,"m":"I'll have reason to speak of that too, on behalf of one whose vote will bring others with it. But let this be done at once, while people's minds are still wild, in case more disasters happen through plots and mistakes."},{"t":"sp","who":"FORTINBRAS","lines":["Let four captains","Bear Hamlet like a soldier to the stage,","For he was likely, had he been put on,","To have prov'd most royally; and for his passage,","The soldiers' music and the rites of war","Speak loudly for him.","Take up the bodies. Such a sight as this","Becomes the field, but here shows much amiss.","Go, bid the soldiers shoot."],"id":1387,"m":"Let four captains carry Hamlet like a soldier onto the platform, because he would probably have proved a great king, if he had been given the chance. And to mark his passing, let soldiers' music and the rites of war speak loudly for him. Take up the bodies. A sight like this belongs on a battlefield, but here it looks very wrong. Go, tell the soldiers to fire."},{"t":"sd","text":"A dead march","id":1388},{"t":"sd","text":"Exeunt, bearing off the bodies, after which a peal of ordnance is shot off","id":1389}];
const STUDY={"chars":[{"name":"Hamlet","group":"The royal family","desc":"Prince of Denmark, son of the murdered King Hamlet and of Gertrude. A student at Wittenberg (though the gravedigger's dates in Act 5 make him about thirty), clever, witty and deeply depressed by his father's death and his mother's quick remarriage. Told by the Ghost to avenge a murder, he pretends to be mad, tests the King with a play, kills Polonius by mistake, is sent to England, escapes and finally kills Claudius as he himself dies of a poisoned wound."},{"name":"Claudius","group":"The royal family","desc":"King of Denmark, Hamlet's uncle. He murdered his brother by pouring poison in his ear, took the crown and married the widowed Queen. A skilful, calm politician in public, he is troubled by guilt in private but will not give up what he gained. He plots Hamlet's death twice and is killed by him in the final scene."},{"name":"Gertrude","group":"The royal family","desc":"Queen of Denmark, Hamlet's mother, who married Claudius less than two months after her husband's death. She loves her son and seems not to know about the murder. After Hamlet confronts her she is shaken but stays with Claudius. She dies drinking the poisoned cup meant for Hamlet."},{"name":"Ghost","group":"The royal family","desc":"The spirit of Hamlet's father, the dead King Hamlet, who appears in armour on the battlements. It tells Hamlet he was murdered by Claudius and demands revenge, but asks him to spare Gertrude. Hamlet sometimes wonders if it could be a devil in disguise."},{"name":"Polonius","group":"Polonius's family","desc":"Lord Chamberlain, the King's chief adviser, father of Laertes and Ophelia. Wordy, self-important and fond of spying, he is sure Hamlet is mad for love of Ophelia. Hamlet kills him by mistake as he hides behind a curtain in Gertrude's room."},{"name":"Laertes","group":"Polonius's family","desc":"Polonius's son, a young courtier who lives in France. When his father is killed and his sister goes mad, he returns at the head of a mob, ready to 'dare damnation' for revenge. Claudius turns him into a tool: he wounds Hamlet with a poisoned sword, is wounded by it himself, and confesses before he dies."},{"name":"Ophelia","group":"Polonius's family","desc":"Polonius's daughter, who has been courted by Hamlet. She obeys her father and brother, rejects Hamlet's letters and lets herself be used as bait to spy on him. Hamlet treats her cruelly, then kills her father. She goes mad, sings songs and hands out flowers, and drowns in a stream."},{"name":"Reynaldo","group":"Polonius's family","desc":"Polonius's servant, sent to Paris with money for Laertes and orders to spy on him."},{"name":"Horatio","group":"Hamlet's friends and the watch","desc":"Hamlet's loyal friend from university, calm and sceptical. He sees the Ghost, watches Claudius during the play, and stays with Hamlet to the end. He survives to tell Hamlet's story."},{"name":"Marcellus","group":"Hamlet's friends and the watch","desc":"An officer of the watch who has seen the Ghost and brings Horatio to see it. He says 'Something is rotten in the state of Denmark.'"},{"name":"Barnardo","group":"Hamlet's friends and the watch","desc":"An officer of the watch who has seen the Ghost twice before the play begins."},{"name":"Francisco","group":"Hamlet's friends and the watch","desc":"A soldier on guard at the start of the play, cold and 'sick at heart'."},{"name":"Rosencrantz","group":"The court","desc":"One of Hamlet's old school friends, summoned by Claudius and Gertrude to find out what is wrong with him. He reports to the King and escorts Hamlet to England, carrying the letter that would have Hamlet killed. Hamlet rewrites it, and he is executed in England."},{"name":"Guildenstern","group":"The court","desc":"Rosencrantz's partner and another of Hamlet's school friends. Hamlet tells him he cannot play on Hamlet like a recorder. He too is executed in England."},{"name":"Osric","group":"The court","desc":"A fashionable, affected courtier who brings Hamlet the challenge to fence with Laertes and judges the match."},{"name":"Voltemand","group":"The court","desc":"An ambassador sent by Claudius to the King of Norway."},{"name":"Cornelius","group":"The court","desc":"Voltemand's fellow ambassador to Norway."},{"name":"Gentleman","group":"The court","desc":"A courtier who tells Gertrude that Ophelia has gone mad."},{"name":"Lord","group":"The court","desc":"A courtier who checks that Hamlet is ready for the fencing match."},{"name":"Fortinbras","group":"Norway","desc":"Prince of Norway, whose father was killed by old Hamlet. He first plans to attack Denmark, then leads an army against Poland. He arrives at the end, takes the Danish crown with Hamlet's dying vote, and orders a soldier's funeral for Hamlet."},{"name":"Captain","group":"Norway","desc":"An officer in Fortinbras's army who tells Hamlet they are fighting for a worthless patch of land."},{"name":"First Player","group":"The players","desc":"The leading actor of the travelling company. His speech about Hecuba moves him to tears and makes Hamlet feel ashamed."},{"name":"Player King","group":"The players","desc":"The king in The Murder of Gonzago, who is poisoned in his garden."},{"name":"Player Queen","group":"The players","desc":"The queen in The Murder of Gonzago, who swears she will never remarry."},{"name":"Lucianus","group":"The players","desc":"The king's nephew in The Murder of Gonzago, who pours the poison in the sleeping king's ear."},{"name":"First Clown","group":"Others","desc":"A gravedigger, witty and down to earth, who digs Ophelia's grave and shows Hamlet Yorick's skull."},{"name":"Second Clown","group":"Others","desc":"The gravedigger's companion, who is sent to fetch drink."},{"name":"Priest","group":"Others","desc":"He conducts Ophelia's funeral with reduced rites because her death was 'doubtful'."},{"name":"First Ambassador","group":"Others","desc":"An ambassador from England who arrives at the end to report that Rosencrantz and Guildenstern are dead."}],"scenes":{"a1s1":{"sum":"At midnight on the battlements of Elsinore, the sentry Barnardo takes over from Francisco. Marcellus and Horatio join him: Horatio has come to test their story of a ghost. The Ghost appears, in armour, looking exactly like the dead King Hamlet. Horatio orders it to speak, but it stalks away. Horatio explains that Denmark is arming because young Fortinbras of Norway wants back the lands his father lost to old Hamlet. The Ghost returns, seems about to speak, and vanishes when the cock crows. They decide to tell young Hamlet.","key":["The play opens with a question, 'Who's there?', and the whole play asks who people really are.","The Ghost may be a warning about Denmark's future: Horatio compares it to the omens before Julius Caesar's murder.","Fortinbras, a son ready to avenge his father, is set up as a mirror for Hamlet."],"quiz":[{"q":"Why has Horatio come to the battlements?","o":["To keep watch over the King's sleep","To test the guards' story of a ghost","To meet Hamlet on his way home","To watch for the Norwegian army"],"a":1,"b":2,"p":"purpose"},{"q":"What does the Ghost look like?","o":["A skeleton wrapped in a torn grave shroud","The dead King Hamlet in armour","Claudius, pale as a sheet","A shadow with no face at all"],"a":1,"b":1,"p":"information"},{"q":"Why does the play open with nervous guards asking 'Who's there?'","o":["It shows that Denmark is about to be invaded by the Norwegians","It introduces the guards as the play's main comic characters","It explains that Horatio has come back from Wittenberg","It sets a mood of fear, doubt and hidden identity from the start"],"a":3,"b":4,"p":"implication"},{"q":"Why does Horatio think the Ghost has appeared?","o":["It wants a proper burial in the chapel","It is warning them about the harvest","It has come to forgive the new King","It bodes some trouble for the state"],"a":3,"b":2,"p":"inference"},{"q":"What does the Ghost's silence with Horatio suggest?","o":["Its message is meant for Hamlet alone","It cannot speak because it is a demon","It has nothing to say to the living at all","It is waiting for Claudius to come up"],"a":0,"b":4,"p":"inference"}]},"a1s2":{"sum":"In a formal court scene, King Claudius explains that he has married Gertrude, his dead brother's widow, and sends ambassadors to Norway to stop Fortinbras. He lets Laertes return to France but refuses to let Hamlet go back to university in Wittenberg. Claudius and Gertrude tell Hamlet his long mourning is unnatural. Alone, Hamlet wishes he could die and is disgusted that his mother remarried within two months. Horatio, Marcellus and Barnardo tell him about the Ghost, and he decides to watch with them that night.","key":["Claudius is a smooth, capable politician: his first speech balances grief and joy in neat pairs.","Hamlet's first line is a bitter pun, and his black clothes set him apart from the celebrating court.","His first soliloquy shows his disgust with his mother before he knows anything about a murder."],"quiz":[{"q":"Whom has Claudius married?","o":["The young Queen of Norway's sister","Gertrude, his brother's widow","A noble lady of the Danish court","Nobody yet: he means to wait a year"],"a":1,"b":1,"p":"information"},{"q":"Why does Claudius refuse to let Hamlet go back to Wittenberg?","o":["He needs Hamlet to lead the war against Norway","Gertrude has begged him to keep Hamlet for her sake","The university has closed for the winter months","He wants Hamlet where he can watch him"],"a":3,"b":2,"p":"purpose"},{"q":"What does Hamlet's first soliloquy reveal that the court scene hides?","o":["His secret plan to kill Claudius that very night","His love for Ophelia and his wish to marry her","His disgust at his mother's hasty remarriage","His fear that the Ghost has been seen on the walls"],"a":2,"b":4,"p":"inference"},{"q":"How does Claudius's balanced language ('mirth in funeral') present him?","o":["As a grieving brother who cannot hide his true sorrow at all","As a smooth politician smoothing over an awkward marriage","As a soldier who speaks plainly and bluntly to all","As a madman whose words make no sense at all"],"a":1,"b":4,"p":"view"},{"q":"What does Hamlet say about the clothes of mourning?","o":["They are the best he has ever owned at court","They are only the trappings and suits of woe","They were chosen for him by his mother","They are what the whole court should be wearing"],"a":1,"b":2,"p":"concept"}]},"a1s3":{"sum":"Before leaving for France, Laertes warns his sister Ophelia that Hamlet's love cannot last: as a prince, he is not free to marry whom he likes, and she must guard her chastity. Polonius arrives and gives Laertes a list of rules for life abroad, ending 'to thine own self be true'. Then he questions Ophelia about Hamlet, mocks her belief in Hamlet's vows and orders her not to see or speak to Hamlet again. She agrees to obey.","key":["Both men treat Ophelia's love as a danger to the family's honour.","Polonius's advice sounds wise, but it is mostly about appearance and self-interest.","Ophelia has little voice of her own: 'I shall obey, my lord.'"],"quiz":[{"q":"Why does Laertes say Hamlet cannot freely choose a wife?","o":["He is too young to marry","As a prince, his choice must suit the state","He is already promised to a Norwegian princess","The King forbids it"],"a":1,"b":2,"p":"purpose"},{"q":"Which line ends Polonius's advice to Laertes?","o":["'Neither a borrower nor a lender be'","'To thine own self be true'","'Brevity is the soul of wit'","'Get thee to a nunnery'"],"a":1,"b":1,"p":"information"},{"q":"What do Laertes and Polonius both assume about Ophelia?","o":["That she is secretly engaged to marry Hamlet already","That she cannot judge Hamlet's love for herself","That she wants to leave Denmark for France","That she has already lost her heart to Laertes"],"a":1,"b":4,"p":"assumption"},{"q":"How might 'to thine own self be true' be ironic from Polonius?","o":["He has never given anyone advice in his whole life","He is speaking to a son he plans to disown","He means it as a joke and Laertes knows it","He is a schemer who spies and manipulates others"],"a":3,"b":5,"p":"view"},{"q":"What does Polonius say about Hamlet's vows?","o":["They are traps to catch woodcocks","They are honest and must be believed","They are what a prince should always say","They are spoken in a language she cannot know"],"a":0,"b":2,"p":"concept"}]},"a1s4":{"sum":"On the cold battlements at midnight, Hamlet, Horatio and Marcellus hear the King's noisy drinking party. Hamlet says the custom gives Denmark a bad name, and reflects that one flaw can ruin a man's whole reputation. The Ghost appears and beckons Hamlet. His friends fear it may lure him to madness or death, but he breaks free and follows it. Marcellus says 'Something is rotten in the state of Denmark.'","key":["Hamlet's speech about a single 'vicious mole' that corrupts a good man is often read as a hint about his own tragic flaw.","Hamlet does not know whether the Ghost is from heaven or hell, a doubt that comes back later.","'Something is rotten' starts the play's imagery of decay and disease."],"quiz":[{"q":"How does Hamlet's speech on the 'vicious mole' of nature foreshadow the play?","o":["One flaw can ruin a whole man, as it may ruin him","A small army can defeat a great one, as in Poland","Drinking will be the cause of the King's death","Ghosts always bring good news to the living"],"a":0,"b":4,"p":"implication"},{"q":"Why do Horatio and Marcellus try to stop Hamlet following the Ghost?","o":["It might lead him to madness or death","He is unarmed and alone","The King has forbidden it on pain of death","It is nearly dawn"],"a":0,"b":2,"p":"purpose"},{"q":"Who says 'Something is rotten in the state of Denmark'?","o":["Hamlet","Horatio","Marcellus","The Ghost"],"a":2,"b":1,"p":"information"},{"q":"What does Hamlet's readiness to follow the Ghost show?","o":["He knows the Ghost is an angel sent from heaven","He wants to prove his courage to Marcellus","He thinks the Ghost will lead him to Wittenberg","Grief has made him reckless of his own life"],"a":3,"b":4,"p":"inference"},{"q":"Why does Hamlet say the drinking custom is a bad one?","o":["It wastes the money of the whole kingdom","It keeps the King from his work in the day","It began only when his father died","Other nations call the Danes drunkards"],"a":3,"b":2,"p":"purpose"}]},"a1s5":{"sum":"Alone with Hamlet, the Ghost says it is his father's spirit, suffering in purgatory. It reveals that Claudius murdered him by pouring poison in his ear while he slept in the orchard, then seduced Gertrude. The Ghost demands revenge but tells Hamlet not to harm his mother. Hamlet swears to remember. When his friends find him, he makes them swear on his sword never to reveal what they saw, while the Ghost cries 'Swear' from under the stage. Hamlet warns that he may pretend to be mad.","key":["The Ghost gives Hamlet his task: revenge for murder, but leave Gertrude to heaven.","Hamlet's 'antic disposition' is announced as a plan, which makes his later madness hard to judge.","He resents his duty at once: 'O cursed spite, that ever I was born to set it right.'"],"quiz":[{"q":"How did Claudius kill old Hamlet, according to the Ghost?","o":["With a sword thrust in his side as he slept","Poison poured in his ear","Poisoned wine at a feast in the great hall","Drowning"],"a":1,"b":1,"p":"information"},{"q":"Why does the Ghost tell Hamlet to leave Gertrude 'to heaven'?","o":["He knows that Gertrude helped to murder him in the orchard","He wants Hamlet's revenge aimed at Claudius alone","He wants Hamlet to marry Ophelia instead","He has forgiven Claudius for the murder"],"a":1,"b":2,"p":"purpose"},{"q":"What does Hamlet warn his friends he may do?","o":["Leave Denmark that very night for Wittenberg","Put on an 'antic disposition' (act mad)","Kill the King before the morning","Marry Ophelia in secret"],"a":1,"b":2,"p":"purpose"},{"q":"What problem does the Ghost's story create for Hamlet?","o":["He must find out who the Ghost really was in its life","He must act on the word of a spirit he cannot prove","He must leave Denmark at once for his own safety","He must tell the whole court what he has heard"],"a":1,"b":4,"p":"implication"},{"q":"What does 'one may smile, and smile, and be a villain' show Hamlet learning?","o":["Laughter is good for the soul","Appearances can hide evil","Kings are always honest men","Villains can never hide well"],"a":1,"b":4,"p":"concept"}]},"a2s1":{"sum":"Polonius sends his servant Reynaldo to Paris with money for Laertes, telling him to spread small rumours about Laertes' bad behaviour to trick people into telling the truth about him. Ophelia rushes in, frightened. Hamlet has visited her room looking wild, with his clothes undone, stared at her face, sighed and left without a word. Polonius decides that Hamlet is mad with love because Ophelia rejected him, and goes to tell the King.","key":["Polonius's motto, 'By indirections find directions out', describes the spying that runs through the play.","We only hear about Hamlet's visit to Ophelia: is it real grief, love, or the first act of his pretended madness?","Polonius jumps to a confident explanation without real evidence."],"quiz":[{"q":"What is Reynaldo sent to do in Paris?","o":["Bring Laertes home at once","Spy on Laertes by spreading rumours","Buy weapons for the King","Find a wife for Laertes"],"a":1,"b":1,"p":"information"},{"q":"How does Hamlet look when he visits Ophelia?","o":["Calm, smartly dressed and smiling at her","Pale, wild, with his clothes undone","Angry, with his sword drawn","Drunk"],"a":1,"b":2,"p":"information"},{"q":"What does Polonius's reading of Hamlet's visit assume?","o":["That Hamlet already knows all about the murder","That Hamlet is only pretending to be mad","That Hamlet wants to leave for France","That Hamlet's madness must be about Ophelia"],"a":3,"b":4,"p":"assumption"},{"q":"Why does Polonius tell Reynaldo to spread false rumours?","o":["To make Laertes come home sooner","To shame Laertes in front of his friends","To hide his own spying from the King","To bait a carp of truth with a lie"],"a":3,"b":2,"p":"purpose"},{"q":"What do the Reynaldo episode and Ophelia's report show about Polonius?","o":["He trusts his children completely and freely","He is too old and tired to care about anything","He has guessed the truth about the murder","He spies on everyone, even his own children"],"a":3,"b":4,"p":"inference"}]},"a2s2":{"sum":"Claudius and Gertrude ask Hamlet's old school friends, Rosencrantz and Guildenstern, to find out what is troubling him. The ambassadors report that Norway has turned Fortinbras's army against Poland. Polonius reads out a love letter from Hamlet to Ophelia and plans to watch Hamlet meet her. Hamlet mocks Polonius, then forces his friends to admit they were sent for. A troupe of actors arrives; one recites a speech about Pyrrhus killing King Priam and weeps for Queen Hecuba. Hamlet asks the players to perform The Murder of Gonzago the next night, with a short speech of his own added. Alone, he attacks himself for doing nothing and plans to use a play to test Claudius's guilt.","key":["Hamlet is surrounded by spies, even his friends.","The actor can weep for Hecuba, while Hamlet, with a real cause, does nothing: the clearest statement of his delay.","Hamlet now doubts the Ghost: it may be the devil. 'The play's the thing wherein I'll catch the conscience of the King.'"],"quiz":[{"q":"Why have Rosencrantz and Guildenstern come to Elsinore?","o":["To spend a holiday at the Danish court as old friends","The King and Queen sent for them to spy on Hamlet","To bring Hamlet urgent news from the university at Wittenberg","To join the actors"],"a":1,"b":2,"p":"purpose"},{"q":"Why is Hamlet moved by the Player's speech about Hecuba?","o":["He has always loved the story of the fall of Troy since childhood","He is jealous of the Player's skill and wants to act himself","An actor weeps for a fiction while he does nothing for a real father","He thinks the speech proves his mother is guilty of the murder"],"a":2,"b":4,"p":"inference"},{"q":"Why does Hamlet want the play performed?","o":["To entertain the court after supper","To see if Claudius shows guilt","To please Ophelia, who loves plays","To mock Polonius"],"a":1,"b":2,"p":"purpose"},{"q":"What does 'Denmark's a prison' suggest about Hamlet's state of mind?","o":["He wants Rosencrantz to free a friend from the town jail","He is planning to escape to England by ship","He believes the King has locked him in a cell","He feels trapped by the court and his own thoughts"],"a":3,"b":4,"p":"concept"},{"q":"What does Polonius say is the soul of wit?","o":["Wisdom","Patience","Brevity","Honesty"],"a":2,"b":1,"p":"information"}]},"a3s1":{"sum":"Rosencrantz and Guildenstern tell the King they have learned nothing, but that Hamlet is excited about the play. Claudius and Polonius hide to watch Hamlet meet Ophelia. Polonius's remark about sugaring over the devil makes Claudius admit his guilt in an aside. Hamlet, thinking he is alone, wonders whether it is better to live or die. Ophelia tries to return his gifts, and he turns on her, telling her to go to a nunnery. Alone, she mourns his ruined mind. Claudius is sure it is not love and decides to send Hamlet to England.","key":["Claudius's aside is the first proof for the audience that he is guilty.","'To be, or not to be' turns from revenge to a general question about life, death and fear of the unknown.","Hamlet's cruelty to Ophelia may come from suspecting she is a decoy."],"quiz":[{"q":"Why do Claudius and Polonius hide?","o":["To catch Hamlet plotting in secret with the actors","To hear what Ophelia says about her father","To arrest Hamlet if he draws a sword","To find out if love is the cause of Hamlet's madness"],"a":3,"b":2,"p":"purpose"},{"q":"Why does Hamlet turn on Ophelia with 'Get thee to a nunnery'?","o":["He wants to protect her from his own dangerous plans","He suspects she is part of the plot to spy on him","He has decided to marry her in secret after all","He is angry that she has failed to return his letters"],"a":1,"b":2,"p":"purpose"},{"q":"What does Claudius's aside about his 'deed' prove to the audience?","o":["His guilt is real before the play tests it","Hamlet's suspicions have no basis at all","Polonius was the real murderer of the King","Gertrude knew everything from the start"],"a":0,"b":4,"p":"inference"},{"q":"How does 'To be, or not to be' differ from Hamlet's other soliloquies?","o":["It is spoken to Ophelia and not alone to the audience","It thinks about life and death in general, not his own revenge","It is full of plans for how to kill his uncle","It is in prose and full of jokes about the court"],"a":1,"b":4,"p":"inference"},{"q":"What does Hamlet say makes cowards of us all?","o":["Fear of the King","Love","Old age","Conscience"],"a":3,"b":1,"p":"information"}]},"a3s2":{"sum":"Hamlet tells the actors how to act naturally and asks Horatio to watch the King during the play. Before it starts he jokes crudely with Ophelia. The actors perform a dumb show and then The Murder of Gonzago, in which a nephew poisons a sleeping king in his garden and wins the queen. When Lucianus pours poison in the sleeper's ear, Claudius rises and calls for lights, and the play stops. Hamlet and Horatio are sure of his guilt. Rosencrantz and Guildenstern say Gertrude wants to see Hamlet; he accuses them of trying to play on him like a pipe. Alone, he steels himself to speak daggers to his mother, but use none.","key":["The play-within-the-play is Hamlet's test: he calls it The Mousetrap.","Claudius's reaction convinces Hamlet, but it happens in public, so the court sees only Hamlet's wild behaviour.","Hamlet refuses to be 'played upon' by spies."],"quiz":[{"q":"What does Hamlet call the play?","o":["The Murder of Gonzago only","The Mousetrap","The Revenger","Hecuba"],"a":1,"b":1,"p":"concept"},{"q":"Why does the poisoning in the ear make Claudius stop the play?","o":["The actor playing the king is badly hurt","He hates plays and wants to go to bed","Gertrude has fainted in the audience","It mirrors his own crime too exactly"],"a":3,"b":2,"p":"inference"},{"q":"What point does Hamlet make with the recorder?","o":["He wants Guildenstern to learn music to calm his mind","He is asking the players to add music to their show","He thinks the King should hire better musicians for court","They cannot 'play' him, though they try to pluck out his secret"],"a":3,"b":4,"p":"concept"},{"q":"How convincing is the play-within-the-play as proof of guilt?","o":["It is useless, for Claudius did not react at all","It is complete proof that any court would accept","It is strong evidence but still not legal proof","It proves only that Gertrude knew of the crime"],"a":2,"b":5,"p":"question"},{"q":"What does Gertrude say about the Player Queen?","o":["The lady speaks the truth of her heart","The lady should have married again","The lady has a fine voice for the part","The lady doth protest too much"],"a":3,"b":2,"p":"view"}]},"a3s3":{"sum":"Claudius orders Rosencrantz and Guildenstern to take Hamlet to England at once. Polonius goes to hide in Gertrude's room. Alone, Claudius confesses that his crime is 'a brother's murder' and tries to pray, but knows he cannot be forgiven while he keeps the crown and the Queen. Hamlet enters, sees him kneeling and draws his sword, but decides not to kill him at prayer in case his soul goes to heaven. After Hamlet leaves, Claudius admits his prayer has failed.","key":["Claudius is shown with a real conscience, which makes him more than a simple villain.","Hamlet's reason for delay here is to damn Claudius, not just kill him: a terrible wish, or an excuse?","The irony: Claudius was not really praying, so Hamlet's chance was real."],"quiz":[{"q":"Why can Claudius not pray?","o":["He is interrupted by Polonius","He still has the crown and the Queen he murdered for","He does not believe in God","He is too tired"],"a":1,"b":2,"p":"purpose"},{"q":"Why does Hamlet not kill Claudius now?","o":["He has no sword with him in the chapel at all","He fears Claudius's soul would go to heaven","Gertrude is watching him","Horatio stops him"],"a":1,"b":2,"p":"purpose"},{"q":"What does Claudius say after Hamlet leaves?","o":["'My words fly up, my thoughts remain below'","'O my offence is rank, it smells to heaven above'","'Pray can I not, though inclination be as sharp as will'","'Lights, lights, lights!'"],"a":0,"b":1,"p":"information"},{"q":"What is ironic about Hamlet sparing Claudius at prayer?","o":["Claudius saw Hamlet and called the guards to arrest him","Hamlet killed Claudius anyway on the very next day","Claudius could not pray after all, so the chance was real","Gertrude was praying beside Claudius all along"],"a":2,"b":4,"p":"implication"},{"q":"What does Hamlet's reason for waiting suggest about his revenge?","o":["He is afraid of Claudius's guards waiting in the chapel","He wants not just death but damnation for Claudius","He has forgotten the Ghost's command entirely","He thinks Claudius is already sorry enough"],"a":1,"b":4,"p":"inference"}]},"a3s4":{"sum":"Polonius hides behind a curtain in Gertrude's room. Hamlet speaks to his mother so fiercely that she cries for help. Polonius shouts too, and Hamlet stabs through the curtain, hoping it is the King. He has killed Polonius. He makes Gertrude compare pictures of his father and Claudius and attacks her for her marriage. The Ghost appears, visible only to Hamlet, to remind him of his purpose and protect Gertrude. Gertrude thinks Hamlet is mad; he urges her to repent and not to tell Claudius he is only mad in craft. He drags the body away.","key":["Hamlet acts on impulse at last, and kills the wrong man.","Gertrude seems to know nothing of the murder ('As kill a king?'), but she is shaken by her son's accusations.","The Ghost's return suggests Hamlet's purpose is 'almost blunted'."],"quiz":[{"q":"Where is Polonius hiding?","o":["In a cupboard in the Queen's closet","Behind the arras (curtain)","Under the Queen's bed","Outside the door, listening"],"a":1,"b":1,"p":"information"},{"q":"Why does Hamlet make Gertrude compare the two pictures?","o":["To prove that his father was the taller man","To shame her for choosing Claudius over his father","To show her that he can paint as well as anyone","To ask her which king she thinks is more handsome"],"a":1,"b":2,"p":"purpose"},{"q":"Why does Gertrude not see the Ghost?","o":["She is far too frightened to look towards the wall","It appears only to Hamlet, so she thinks him mad","She has closed her eyes in prayer at the time","The room is too dark for her to see anything"],"a":1,"b":2,"p":"inference"},{"q":"What does Hamlet's killing of Polonius show about his delay?","o":["He was waiting all along for exactly the right moment","He can act rashly when he does not stop to think","He has finally decided to give up revenge","He is truly mad and does not know what he does"],"a":1,"b":4,"p":"inference"},{"q":"What are the consequences of Polonius's death?","o":["It makes Gertrude confess everything to the whole Danish court","It frees Hamlet to marry Ophelia without her father's leave","It ends Claudius's suspicion of Hamlet once and for all","It gives Claudius cause to send Hamlet away and starts Laertes' revenge"],"a":3,"b":4,"p":"implication"}]},"a4s1":{"sum":"Gertrude tells Claudius that Hamlet, in a mad fit, has killed Polonius. Claudius realises it could have been him and worries that people will blame him for not keeping Hamlet under control. He decides to ship Hamlet off at dawn and sends Rosencrantz and Guildenstern to find him and bring the body to the chapel.","key":["Gertrude keeps her promise and calls Hamlet mad, and even says he weeps for what he did.","Claudius thinks first of his own safety and reputation.","The pressure on Claudius is growing."],"quiz":[{"q":"What does Gertrude tell Claudius about Hamlet?","o":["He is sane and only pretending","He is as mad as the sea and wind","He has left Denmark","He knows about the murder and means revenge"],"a":1,"b":1,"p":"information"},{"q":"Why does Claudius react to Polonius's death by thinking of himself?","o":["He realises he was the intended victim","He blames himself for Polonius's poor health","He wants Polonius's job for one of his friends","He thinks Gertrude killed Polonius herself"],"a":0,"b":2,"p":"view"},{"q":"Why is Gertrude's claim that Hamlet weeps significant?","o":["She has seen Hamlet cry for the first time","She wants Claudius to feel sorry for Hamlet","She is lying to make Hamlet look mad","She may be protecting her son from Claudius"],"a":3,"b":4,"p":"view"},{"q":"Why does Claudius send Hamlet away at dawn?","o":["To let him rest after the shock of the killing in private","To bring Laertes home from France to see him","To hide Polonius's body before anyone sees it","To get him out of Denmark before more harm is done"],"a":3,"b":2,"p":"purpose"},{"q":"What does Claudius's worry about public blame show?","o":["He is deeply sorry for Polonius's family","He is ready to step down as King","His main concern is his own reputation","He wants to make Hamlet the next King"],"a":2,"b":4,"p":"inference"}]},"a4s2":{"sum":"Hamlet has hidden Polonius's body. When Rosencrantz and Guildenstern ask where it is, he mocks them as sponges that soak up the King's favour and will be squeezed dry when he has used them. He runs off, calling it a game of hide and seek.","key":["Hamlet sees clearly what Rosencrantz and Guildenstern are.","His riddles are a mix of real anger and performance.","Hiding the body turns a death into a joke, which shocks."],"quiz":[{"q":"What does Hamlet call Rosencrantz?","o":["A sponge","A fishmonger","A mole","A rat"],"a":0,"b":1,"p":"concept"},{"q":"Why does he say the King keeps such men?","o":["To use them and squeeze them dry later","Because he loves them as true friends","To guard Hamlet on the journey to England","To spy on the Queen in her rooms"],"a":0,"b":2,"p":"purpose"},{"q":"How does Hamlet treat Rosencrantz and Guildenstern now?","o":["With warm trust, as his oldest and dearest friends","With fear, as men who may kill him","With open contempt, as the King's tools","With pity, as men who are ill-paid"],"a":2,"b":2,"p":"view"},{"q":"What is Hamlet suggesting with 'The body is with the King'?","o":["A plain statement that he has hidden it in Claudius's room","A joke that Polonius was really the King all along","A riddle hinting that Claudius too will soon be a corpse","A confession that he has given the body to the guards"],"a":2,"b":4,"p":"concept"},{"q":"What does the 'hide and seek' game suggest about Hamlet's madness?","o":["He has truly lost his mind after the shock of the killing","He is tired and wants to go to bed now","He uses it as cover to mock and confuse the court","He wants to play games with his old friends"],"a":2,"b":4,"p":"inference"}]},"a4s3":{"sum":"Claudius says he cannot punish Hamlet openly because the people love him. Hamlet is brought in and says Polonius is 'at supper', being eaten by worms, and that a king can pass through the guts of a beggar. He finally says the body is under the stairs. Claudius tells him he must leave for England for his own safety. Alone, Claudius reveals that his letters order the King of England to kill Hamlet at once.","key":["Hamlet's jokes about worms and kings show his obsession with death and its levelling of rank.","Claudius's public kindness hides a death sentence.","Claudius now acts decisively, unlike Hamlet."],"quiz":[{"q":"Why can Claudius not punish Hamlet publicly?","o":["Gertrude forbids it","The people love Hamlet","There is no law against murder","Hamlet is a prince of Norway"],"a":1,"b":2,"p":"purpose"},{"q":"Where does Hamlet say Polonius is?","o":["Already in heaven with the angels","At supper, being eaten by worms","In France","In the chapel"],"a":1,"b":1,"p":"information"},{"q":"What does the order in Claudius's letters reveal?","o":["He wants Hamlet cared for and cured in England","He is sending Hamlet to marry a princess","He wants England to send soldiers to Denmark","He now means to have Hamlet killed in secret"],"a":3,"b":4,"p":"inference"},{"q":"What point does Hamlet make with the king and the beggar?","o":["Death makes kings and beggars equal","Kings must feed the beggars of their land","Beggars will one day become kings","Kings should always fear their own subjects"],"a":0,"b":2,"p":"concept"},{"q":"Why does Hamlet call Claudius 'dear mother'?","o":["He has mistaken Claudius for Gertrude in the dark","Man and wife are one flesh, so he mocks the marriage","He wants to show Claudius some affection at last","He is too mad to remember who is who any more"],"a":1,"b":4,"p":"concept"}]},"a4s4":{"sum":"Fortinbras and his army cross Denmark on their way to Poland. A captain tells Hamlet they will fight over a patch of land worth nothing. Alone, Hamlet compares himself with Fortinbras, who risks thousands of lives for an eggshell, while he, with a murdered father and a disgraced mother, does nothing. He vows that from now on his thoughts will be bloody.","key":["Fortinbras is another son who acts while Hamlet thinks.","Hamlet admits he has 'cause, and will, and strength, and means', so delay is not explained by circumstances.","The soliloquy is ambiguous: is fighting for 'a straw' admirable or absurd?"],"quiz":[{"q":"What is Fortinbras's army fighting for?","o":["Denmark's throne, which his father lost","A worthless patch of Polish land","The gold in the Polish treasury","Revenge for his father's death"],"a":1,"b":1,"p":"information"},{"q":"Why does Fortinbras's army make Hamlet ashamed?","o":["The army is better trained than the Danish soldiers","Fortinbras has more men than Claudius will ever have","Men risk death for nothing while he delays for a real cause","He wishes that he were a soldier instead of a prince"],"a":2,"b":2,"p":"view"},{"q":"What does 'my thoughts be bloody or be nothing worth' promise?","o":["A plan to give up revenge and go home to Wittenberg","A turn from thinking to violent action","A decision to join Fortinbras's army","A wish to become a priest in England"],"a":1,"b":2,"p":"implication"},{"q":"How fair is Hamlet's comparison of himself to Fortinbras?","o":["Completely fair, since Fortinbras is the better man","Unfair, since Fortinbras has never fought in a war","Partly: Fortinbras acts, but for a worthless cause","Unfair, since Hamlet has already killed Claudius"],"a":2,"b":5,"p":"view"},{"q":"What does Hamlet's idea of greatness assume?","o":["That honour is worth any cost, however small the cause","That peace is always better than war of any kind","That kings should never fight their own battles","That the common soldier is wiser than his general"],"a":0,"b":4,"p":"assumption"}]},"a4s5":{"sum":"Ophelia has gone mad after her father's death. She sings songs about death and lost virginity. Claudius lists his troubles: Polonius's death, the people's anger and Laertes' secret return. Laertes bursts in at the head of a mob who want him as king, demanding his father. Claudius calmly persuades him that he is innocent. Ophelia returns, handing out flowers with meanings, and Laertes is heartbroken. Claudius promises to show Laertes who is to blame.","key":["Ophelia's madness is real, unlike Hamlet's: grief has broken her mind.","Laertes acts instantly, 'I dare damnation', the opposite of Hamlet.","Claudius manages Laertes brilliantly, turning his anger towards Hamlet."],"quiz":[{"q":"Why do Ophelia's songs disturb the court?","o":["They are sung in a foreign tongue no one understands","They mock Claudius openly for murdering the King","They speak of death and love the court has hushed up","They are too loud and keep the King from sleeping"],"a":2,"b":2,"p":"inference"},{"q":"How does Laertes' response to his father's death contrast with Hamlet's?","o":["He waits patiently and prays to heaven for guidance","He acts at once, with no thought of conscience","He refuses to believe that his father is dead","He blames himself and leaves for France again"],"a":1,"b":4,"p":"inference"},{"q":"What does rosemary stand for, according to Ophelia?","o":["Thoughts","Remembrance","Sorrow","Faithfulness"],"a":1,"b":1,"p":"information"},{"q":"What does Claudius say about sorrows?","o":["They pass in time if you let them run their course","They are sent to test those that are truly good","They come not single spies, but in battalions","They are best hidden from the eyes of the people"],"a":2,"b":2,"p":"concept"},{"q":"What is ironic in Claudius claiming divine protection?","o":["He has never believed in God","He killed a king himself","Laertes is a priest","Gertrude is the one in danger"],"a":1,"b":4,"p":"implication"}]},"a4s6":{"sum":"Sailors bring Horatio a letter from Hamlet. Pirates attacked his ship. Hamlet boarded theirs and was taken prisoner while his ship sailed on. The pirates treated him well in return for a favour. He asks Horatio to deliver letters to the King and come to him quickly, and says he has much to tell about Rosencrantz and Guildenstern.","key":["Chance, or providence, sends Hamlet back to Denmark.","Hamlet acted boldly in the sea fight.","The letter builds suspense about what happened to Rosencrantz and Guildenstern."],"quiz":[{"q":"Who attacked Hamlet's ship?","o":["Norwegians","Pirates","English soldiers","Rosencrantz and Guildenstern"],"a":1,"b":1,"p":"information"},{"q":"How did Hamlet escape?","o":["He swam ashore near Elsinore","He boarded the pirate ship, which then let him go","He bribed the captain with gold","Horatio rescued him"],"a":1,"b":2,"p":"information"},{"q":"Why does Hamlet's letter change the situation?","o":["He has been killed by the pirates at sea","He has reached England and been executed","He has decided to stay with the pirates","He is back in Denmark, alive and free"],"a":3,"b":2,"p":"implication"},{"q":"How does the pirate attack serve the plot?","o":["It kills Rosencrantz and Guildenstern at sea","It makes Hamlet a hero in England","It returns Hamlet to Denmark by chance","It shows the pirates are Norwegians"],"a":2,"b":4,"p":"implication"},{"q":"What does the pirates' good treatment suggest about Hamlet's luck?","o":["The pirates were hired by Claudius all along","Chance, or providence, is now working for him","He has made friends with criminals on purpose","He must pay them back with Denmark's gold"],"a":1,"b":4,"p":"inference"}]},"a4s7":{"sum":"Claudius convinces Laertes that Hamlet killed Polonius and explains he could not punish him because of Gertrude and the people. A letter arrives: Hamlet is back in Denmark. Claudius and Laertes plot a fencing match in which Laertes will use a sharp sword, which Laertes decides to poison as well. Claudius adds a poisoned cup as a back-up. Laertes says he would cut Hamlet's throat in a church. Gertrude brings news that Ophelia has drowned, falling from a willow into a stream.","key":["Laertes lets himself be used by Claudius, giving up his honour for revenge.","The plot has two layers, sword and cup, which will both go wrong.","Gertrude's beautiful description of Ophelia's death leaves it unclear whether it was an accident."],"quiz":[{"q":"Why does Laertes add poison to the plan?","o":["Claudius forbids him to use a sword","He wants to frighten Hamlet only","He fears the King will betray him","He wants to make sure Hamlet dies"],"a":3,"b":2,"p":"purpose"},{"q":"Why does Claudius want a back-up plan?","o":["In case the poisoned blade fails","In case Gertrude finds out the plan","In case Laertes changes his mind","In case Hamlet refuses to fence"],"a":0,"b":2,"p":"purpose"},{"q":"How did Ophelia die?","o":["She was murdered by the King's men","She fell from a willow into a stream and drowned","She took poison","She jumped from the battlements"],"a":1,"b":1,"p":"information"},{"q":"How does Claudius manipulate Laertes?","o":["By paying him a great fortune in Danish gold","By flattering his skill and stirring his grief","By threatening to banish him for ever","By giving him Ophelia's dowry back"],"a":1,"b":4,"p":"inference"},{"q":"What does Gertrude's lyrical account of Ophelia's death do?","o":["It softens a possible suicide into a gentle accident","It proves that Ophelia was murdered by Claudius","It shows that Gertrude was there and did nothing","It reveals that Hamlet pushed Ophelia into the stream"],"a":0,"b":4,"p":"view"}]},"a5s1":{"sum":"Two gravediggers joke about whether Ophelia, a possible suicide, deserves a Christian burial. Hamlet and Horatio arrive and watch. Hamlet reflects on the skulls being dug up: politicians, courtiers and lawyers all come to this. The gravedigger shows him the skull of Yorick, the King's jester, whom Hamlet loved as a child. Ophelia's funeral procession arrives with reduced rites. Laertes leaps into her grave; Hamlet reveals himself, leaps in too, and they fight. Hamlet claims he loved Ophelia more than forty thousand brothers.","key":["Death levels everyone: Alexander the Great ends as dust stopping a beer barrel.","The gravedigger's wit matches Hamlet's own.","Hamlet learns of Ophelia's death here, and his grief bursts out as rivalry with Laertes."],"quiz":[{"q":"What does the argument over Ophelia's burial suggest about justice?","o":["The Church treats everyone the same","The poor are always buried first","Rank buys privileges even in death","The gravediggers make all the rules"],"a":2,"b":4,"p":"implication"},{"q":"Whose skull does Hamlet hold?","o":["His father's","Yorick, the King's jester","Polonius's","Alexander's"],"a":1,"b":1,"p":"information"},{"q":"What does Hamlet say about his love for Ophelia?","o":["He never truly loved her at all","Forty thousand brothers could not match it","He loved her only as a sister, nothing more","He only pretended to love her to fool the King"],"a":1,"b":2,"p":"view"},{"q":"How does Yorick's skull change Hamlet's thoughts on death?","o":["He becomes afraid of ghosts and wants to leave","Death becomes personal and equalising, not abstract","He decides to give up his plans for revenge for good","He realises that Yorick was secretly his father"],"a":1,"b":4,"p":"inference"},{"q":"Why does the gravedigger's joke about England land?","o":["He wants Hamlet to know he has been to England himself","He thinks madness won't be noticed there, where all are mad","He thinks England is a fine place to cure a sick man","He believes Hamlet was sent there as a spy for Denmark"],"a":1,"b":2,"p":"concept"}]},"a5s2":{"sum":"Hamlet tells Horatio how he found Claudius's order for his death and replaced it with one ordering the deaths of Rosencrantz and Guildenstern. He now feels a divine power shapes events. Osric brings a challenge to fence with Laertes. Hamlet has a bad feeling but accepts: 'the readiness is all'. In the match, Gertrude drinks from the poisoned cup, Laertes wounds Hamlet with the poisoned sword, and in the scuffle they swap swords and Hamlet wounds Laertes. Gertrude dies, Laertes confesses, and Hamlet stabs Claudius with the poisoned sword and forces him to drink the poisoned wine. Laertes and Hamlet forgive each other before Laertes dies. Horatio tries to drink the rest of the poison, but Hamlet stops him and asks him to live and tell his story, then names Fortinbras as the next king and dies. Fortinbras arrives with ambassadors from England, who report that Rosencrantz and Guildenstern are dead, and orders a soldier's funeral for Hamlet.","key":["Hamlet's calm acceptance of providence replaces his earlier agonising.","The revenge happens almost by accident, after Gertrude's death and Laertes' confession.","Order is restored by an outsider, Fortinbras, the son who acted.","Hamlet's last request is not for revenge but for his story to be told truthfully."],"quiz":[{"q":"How did Hamlet get rid of Rosencrantz and Guildenstern?","o":["He killed them himself on the ship to England","He rewrote the letter to order their deaths","He left them behind with the pirates at sea","He sent them home to Wittenberg"],"a":1,"b":2,"p":"information"},{"q":"Who drinks from the poisoned cup first?","o":["Hamlet","Claudius","Gertrude","Laertes"],"a":2,"b":1,"p":"information"},{"q":"What does Hamlet's choice of Fortinbras as king suggest?","o":["Hamlet is still loyal to Claudius right up to the end","Fortinbras was Hamlet's secret ally all along","The people of Denmark have chosen Fortinbras","Order returns from outside a ruined royal line"],"a":3,"b":4,"p":"implication"},{"q":"Is Hamlet right to send Rosencrantz and Guildenstern to their deaths?","o":["It is harsh but they knowingly served the King's plot","It is completely fair, for they had planned to kill him themselves","It is cruel, for they knew nothing of the letter","It is wrong, for they were only ever kind to him"],"a":0,"b":5,"p":"question"},{"q":"What does Hamlet say about the fall of a sparrow?","o":["There is special providence in it","It is a sign that he will soon die","It shows that the gods do not care","It means the King is about to fall"],"a":0,"b":2,"p":"concept"}]}},"notes":{"2":"The play opens with a question, and the wrong person asks it: the relieving guard challenges the one on duty. Nerves are on edge before anything happens.","9":"'Sick at heart' sets the mood of the whole play before we know why.","34":"The Ghost looks exactly like the dead king and wears armour: it seems to come with a warlike purpose.","53":"Old Hamlet killed old Fortinbras in single combat. Young Fortinbras wants to win back his father's lands, so he is a second son seeking to avenge a father.","55":"Horatio links the Ghost to the omens before Caesar's assassination: the death of a ruler shakes the whole order of nature.","68":"Christian belief that spirits cannot walk at Christmas hints that the Ghost may be unholy.","74":"Claudius's speech balances opposites ('mirth in funeral', 'dirge in marriage'). The smooth rhetoric covers an uncomfortable truth.","83":"Hamlet's first words are an aside and a pun. 'Kind' means both natural (of the same kind) and kindly.","89":"Hamlet attacks 'seeming' from his first long speech. Appearance and reality become a central theme.","95":"The first soliloquy. Notice the broken syntax: dashes and exclamations show a mind in turmoil.","108":"Hamlet's sarcasm is a weapon he uses throughout the play.","162":"Laertes talks about Ophelia's chastity as a 'treasure', something belonging to the family's honour.","169":"Polonius's advice is full of balanced, proverb-like lines. It sounds wise, but much of it is about self-protection and keeping up appearances.","186":"Polonius uses money and trade images ('tenders', 'sterling', 'brokers'): love as a market.","201":"The 'vicious mole of nature' speech is often read as Shakespeare describing a tragic flaw, the single weakness that ruins a great man.","204":"Hamlet does not know whether the Ghost is 'a spirit of health or goblin damn'd'. This doubt returns in Act 2.","226":"'Rotten' begins the imagery of disease and decay that runs through the play.","241":"The Ghost suffers in fire until its sins are 'burnt and purg'd away': a Catholic idea of purgatory, which Protestant England officially rejected.","249":"Poison poured in the ear: the image returns when the court's ears are 'abused' with lies, and in the play-within-the-play.","251":"Hamlet promises to wipe his memory clean of everything but the Ghost's command. Remembering becomes his duty.","295":"The 'antic disposition' means that from now on we cannot be sure when Hamlet is mad and when he is acting.","319":"Polonius's spying on his own son is a small version of the spying on Hamlet that follows.","337":"We only hear about this scene. Is Hamlet heartbroken, testing Ophelia, or starting his act of madness?","344":"Claudius uses Hamlet's friends as spies. Trust is corrupted everywhere at court.","373":"Hamlet's letter is clumsy, conventional love poetry, quite unlike his brilliant speech elsewhere.","395":"A fishmonger may also be slang for a pimp: Hamlet may be hinting that Polonius is using his daughter as bait.","409":"Hamlet's madness lets him insult Polonius to his face.","455":"Hamlet's speech moves from the glory of humanity to 'this quintessence of dust'. It is written in prose, yet it is one of the most poetic passages in the play.","466":"A reference to the boy actors' companies popular in London around 1600, an in-joke for Shakespeare's audience.","503":"Pyrrhus, avenging his father Achilles, pauses with his sword raised, then strikes. He is a picture of what Hamlet cannot do.","528":"The second soliloquy. Hamlet swings from self-hatred to rage to a practical plan, and admits the Ghost might be the devil.","550":"The first confirmation for the audience that the Ghost told the truth.","554":"'To be, or not to be' never mentions Claudius or revenge. Hamlet thinks about death as anyone might.","570":"Many productions show Hamlet discovering the hidden watchers just before this outburst, which would explain his sudden cruelty.","578":"Ophelia's lament is her longest speech, a portrait of the Hamlet she knew.","580":"Claudius is not fooled by Polonius's theory: he senses danger in Hamlet.","586":"Hamlet's advice to the players is often read as Shakespeare's own view of acting.","605":"Hamlet admires Horatio as a man who is 'not passion's slave', everything Hamlet himself finds hard to be.","653":"The play-within-the-play is in old-fashioned rhyming couplets, so it sounds clearly different from the main play.","659":"The Player King's speech about how intentions fade is a comment on Hamlet's own delay.","671":"'The Mousetrap' is Hamlet's title for a play meant to catch the King.","683":"Claudius stops the play, but the court sees only an insult from Hamlet, not a confession.","737":"The recorder is a perfect image of manipulation. Hamlet refuses to be played like an instrument.","752":"Hamlet sounds like a stage revenger here, but he is going to see his mother, not the King.","766":"Claudius's soliloquy makes him human: he wants forgiveness but will not give up the crown and the Queen.","769":"Hamlet spares Claudius to send him to hell. Some critics find this monstrous; others think it is an excuse for delay.","772":"The final couplet reveals the irony: Hamlet's reason for waiting was false.","794":"Hamlet's one impulsive act kills the wrong man.","803":"Gertrude's surprise at 'As kill a king?' suggests she did not know about the murder.","808":"The two pictures, perhaps miniatures worn round the neck, make the brothers' difference visible.","816":"Gertrude cannot see the Ghost. Either it chooses who sees it, or Hamlet is seeing things.","833":"'I must be cruel only to be kind': Hamlet presents himself as heaven's 'scourge and minister'.","839":"'Hoist with his own petard': blown up by his own bomb. The image predicts the end of the play.","892":"Hamlet's jokes about worms prepare for the graveyard scene.","913":"Claudius's secret letter orders the King of England to kill Hamlet.","938":"The last soliloquy. Hamlet admits he has every reason and means to act, yet still has not.","952":"Ophelia's songs mix grief for her father with fragments about lost love and seduction.","971":"Claudius's list of disasters shows how his crime has led to chaos.","990":"Claudius, a regicide, claims that 'divinity doth hedge a king': a bold piece of acting.","995":"Laertes is the revenger Hamlet thinks he should be, and it makes him easy for Claudius to use.","1011":"Each flower has a meaning: rosemary for remembrance, pansies for thoughts, fennel for flattery, columbines for unfaithfulness, rue for regret, daisies for false love, violets for faithfulness.","1033":"The pirate episode is pure chance, which Hamlet later reads as providence.","1069":"Claudius's lecture on how love fades echoes the Player King.","1072":"Laertes adds poison himself: he is no longer simply an honourable son.","1078":"Gertrude describes Ophelia's death in beautiful detail, though she was not there.","1087":"The gravediggers are 'clowns': comic, lower-class characters who mock the privileges of the rich.","1145":"The gravedigger started work the day Hamlet was born, which makes Hamlet thirty years old.","1168":"The skull of Yorick, a jester Hamlet loved as a child, makes death personal.","1186":"Ophelia's 'maimed rites' show that the church suspects suicide.","1191":"'This is I, Hamlet the Dane': Hamlet claims the royal title for the first time.","1216":"Hamlet now believes in 'a divinity that shapes our ends'. His attitude has changed since Act 1.","1228":"Hamlet feels no guilt about sending Rosencrantz and Guildenstern to their deaths.","1296":"The calm prose of 'the readiness is all' contrasts with the frantic soliloquies.","1300":"Hamlet blames his madness for the harm he did Laertes. Is that honest?","1360":"Laertes' confession reveals the plot to everyone just in time.","1365":"Hamlet finally kills Claudius with both the sword and the cup: the King is destroyed by his own plans.","1375":"Hamlet's last words leave the rest unspoken.","1387":"Fortinbras gives Hamlet a soldier's funeral, an odd ending for a scholar-prince."},"gloss":{"unfold":"reveal","rivals":"partners","liegemen":"loyal subjects","fantasy":"imagination","approve":"confirm","assail":"attack","harrows":"tears up, torments","usurp'st":"wrongly take over","parle":"meeting for talks","jump":"exactly","martial":"warlike","gross":"overall view; or coarse","toils":"tires out","impress":"forced labour","moiety":"portion","gaged":"pledged","carriage":"terms","mettle":"spirit, character","resolutes":"desperadoes","post-haste":"great hurry","rummage":"bustle","portentous":"ominous","palmy":"flourishing","gibber":"chatter","precurse":"forewarning","harbingers":"messengers sent ahead","partisan":"long-handled spear","erring":"straying","probation":"proof","russet":"reddish-brown","jointress":"partner in ownership","dirge":"funeral song","dole":"grief","suit":"request; or set of clothes","nighted":"black, like night","vailed":"lowered","suspiration":"sighing","haviour":"expression","obsequious":"dutiful in mourning","condolement":"grief","unschool'd":"untaught","retrograde":"contrary","rouse":"drinking bout","bruit":"announce loudly","canon":"law","self-slaughter":"suicide","rank":"foul, overgrown","merely":"completely","Hyperion":"the sun god","satyr":"half-man, half-goat, a lustful creature","beteem":"allow","Niobe":"woman in Greek myth who wept endlessly for her children","galled":"sore","dexterity":"speed","truant":"one who skips school","bak'd meats":"pies","beaver":"face guard of a helmet","sable":"black","tenable":"kept","requite":"repay","doubt":"suspect","convoy":"means of sending","primy":"springtime","suppliance":"pastime","crescent":"growing","thews":"muscles","cautel":"deceit","credent":"trusting","importunity":"pleading","chariest":"most careful","canker":"caterpillar or worm that eats buds","calumnious":"slanderous","libertine":"pleasure seeker","dalliance":"flirtation","recks":"heeds","rede":"advice","precepts":"rules","character":"write; handwriting","unfledg'd":"immature","censure":"opinion","husbandry":"thrift","tenders":"offers","sterling":"genuine money","springes":"snares","woodcocks":"foolish birds","brokers":"go-betweens","bawds":"pimps","slander":"misuse; or spread lies about","shrewdly":"sharply","eager":"sharp, biting","wassail":"drinking party","Rhenish":"Rhine wine","traduc'd":"insulted","clepe":"call","pith":"essence","complexion":"temperament","plausive":"pleasing","livery":"uniform","questionable":"inviting questions","canoniz'd":"buried with church rites","cerements":"burial clothes","sepulchre":"tomb","beetles":"overhangs","toys":"whims","Nemean lion":"the lion killed by Hercules","porpentine":"porcupine","blazon":"description","Lethe":"the river of forgetfulness in the underworld","adulterate":"adulterous","hebenon":"a poison","quicksilver":"mercury","posset":"curdle","tetter":"skin disease","lazar":"leper","unhous'led":"without the last communion","unanel'd":"without the last rites","matin":"morning","distracted globe":"confused head","saws":"sayings","pernicious":"wicked","truepenny":"honest fellow","cellarage":"cellar","pioner":"soldier who digs tunnels","antic":"strange, mad","perturbed":"troubled","Danskers":"Danes","encompassment":"roundabout talk","forgeries":"inventions","drabbing":"whoring","incontinency":"sexual excess","quaintly":"skilfully","videlicet":"that is to say","windlasses":"roundabout ways","assays of bias":"indirect attempts, like a curving bowl","doublet":"jacket","unbrac'd":"unfastened","down-gyved":"fallen down like ankle chains","ecstasy":"madness","quoted":"observed","beshrew":"curse","gentry":"courtesy","expostulate":"discuss","perpend":"consider","beautified":"made beautiful","machine":"body","tribute":"payment","arras":"wall tapestry","carters":"cart drivers","fishmonger":"fish seller (also slang for a pimp)","carrion":"dead flesh","conception":"understanding, or pregnancy","pregnant":"full of meaning","confines":"cells","Lenten":"meagre","coted":"overtook","target":"shield","humorous":"moody","inhibition":"ban","aerie":"nest","eyases":"young hawks","escoted":"paid for","tarre":"provoke","handsaw":"heron","swaddling clouts":"baby's wrappings","Roscius":"a famous Roman actor","Seneca":"Roman writer of tragedies","Plautus":"Roman writer of comedies","Jephthah":"biblical judge who sacrificed his daughter","valanc'd":"fringed with a beard","chopine":"platform shoe","caviare to the general":"too fine for ordinary people","sallets":"spicy bits","Pyrrhus":"Greek warrior who killed King Priam of Troy","Hyrcanian":"from Hyrcania, a land of tigers","gules":"red (heraldry)","carbuncles":"red gems","Priam":"King of Troy","Ilium":"Troy","Cyclops":"one-eyed giants who forged weapons","mobled":"muffled","bisson rheum":"blinding tears","Hecuba":"Queen of Troy, Priam's wife","milch":"milky with tears","bodikin":"little body (an oath)","peak":"mope","John-a-dreams":"a dreamer","pate":"head","pigeon-liver'd":"meek","gall":"bitterness, courage","kites":"birds of prey","offal":"guts","kindless":"unnatural","drab":"prostitute","scullion":"kitchen servant","tent":"probe","blench":"flinch","grating":"disturbing","espials":"spies","orisons":"prayers","contumely":"insult","quietus":"settlement of a debt; death","bodkin":"dagger","fardels":"burdens","bourn":"boundary","nunnery":"convent (also slang for a brothel)","bawd":"pimp, go-between","paragon":"perfect example","periwig-pated":"wig-wearing","groundlings":"audience standing in the pit","Termagant":"a ranting stage character","Herod":"a ranting tyrant in old plays","journeymen":"hired workmen","candied":"sugary","occulted":"hidden","stithy":"forge","chameleon":"lizard believed to live on air","country matters":"sex (a crude pun)","sables":"rich black furs","hobby-horse":"a figure in morris dancing","miching mallecho":"sneaking mischief","posy":"motto inscribed in a ring","Phoebus":"the sun god","Tellus":"goddess of the earth","Hymen":"god of marriage","wormwood":"bitter herb","Hecate":"goddess of witchcraft","pajock":"peacock","choler":"anger","purgation":"cleansing (with medicine)","pickers and stealers":"hands","recorders":"wooden pipes","ventages":"finger holes","fret":"annoy (and the frets on an instrument)","witching time":"midnight, when witches walk","Nero":"Roman emperor who killed his mother","commission":"written orders","massy":"massive","primal eldest curse":"the curse on Cain, who killed his brother","rood":"cross","glass":"mirror","ducat":"gold coin","contraction":"marriage contract","rhapsody":"jumble","index":"introduction","Mercury":"messenger of the gods","Jove":"king of the gods","batten":"gorge","apoplex'd":"paralysed","hoodman-blind":"blind man's buff","mutine":"rebel","enseamed":"greasy","tithe":"tenth","cutpurse":"pickpocket","unction":"ointment","pursy":"bloated","paddock":"toad","gib":"tomcat","petard":"small bomb","enginer":"engineer, bomb-maker","brainish":"crazy","countenance":"favour","convocation":"assembly","progress":"royal journey","cherub":"angel","cicatrice":"scar","hectic":"fever","fust":"go mouldy","craven":"cowardly","importunate":"insistent","shoon":"shoes","cockle hat":"pilgrim's hat with a shell","larded":"decorated","dild":"reward","Switzers":"Swiss guards","rabble":"mob","cuckold":"man whose wife is unfaithful","pelican":"bird thought to feed its young with its own blood","sweepstake":"taking all the stakes","rosemary":"herb for remembrance","pansies":"flowers for thoughts","fennel":"herb for flattery","columbines":"flowers for unfaithfulness","rue":"bitter herb for regret","flaxen":"pale yellow","hatchment":"coat of arms on a tomb","Lamord":"a Norman horseman","unbated":"without a safety button","mountebank":"quack doctor","cataplasm":"poultice","simples":"healing herbs","chalice":"cup","crow-flowers":"buttercups","long purples":"wild orchids","coronet":"crown of flowers","se offendendo":"in self-offence (the clown's mistake for self-defence)","argal":"therefore (a muddled 'ergo')","crowner":"coroner","quest":"inquest","stoup":"jug","loggets":"a game of throwing sticks","quiddits":"quibbles","quillets":"fine distinctions","sconce":"head","Yorick":"the old King's jester","gorge":"stomach","chop-fallen":"jaw hanging down","bung-hole":"hole in a barrel","churlish":"rude","Pelion":"mountain in Greek myth","Olympus":"mountain of the gods","Ossa":"mountain in Greek myth","eisel":"vinegar","bilboes":"shackles","packet":"bundle of letters","signet":"seal ring","waterfly":"insect, a buzzing idler","chough":"jackdaw, chatterer","Barbary":"North African","poniards":"daggers","foils":"blunted fencing swords","augury":"omens","providence":"God's care","union":"pearl","palpable":"clear","quarry":"heap of dead","havoc":"slaughter"}};
const PARTS={"52":[[0,4,"Please, sit down, and whoever knows, tell me why this strict, watchful guard is kept every night, wearing out the people of the country, and why bronze cannons are cast every day and weapons bought abroad;"],[5,9,"why shipbuilders are forced to work so hard that they don't get Sundays off. What is about to happen, that this sweating haste makes night work as hard as day? Who can tell me?"]],"53":[[0,6,"I can; at least, this is the rumour. Our last King, whose image appeared to us just now, was, as you know, challenged to single combat by Fortinbras of Norway, who was spurred on by jealous pride. In that fight our brave Hamlet, for that's how this half of the known world thought of him,"],[7,16,"killed this Fortinbras. By a sealed agreement, properly made by law and the rules of chivalry, Fortinbras lost all the lands he owned, along with his life, to the winner. Our King had staked an equal share of land, which would have gone to Fortinbras if he had won; by the same agreement and its terms, Fortinbras's lands went to Hamlet."],[17,24,"Now, sir, young Fortinbras, untested, hot-headed and full of spirit, has rounded up a band of lawless desperadoes from the edges of Norway, men who'll fight for their food, for some bold enterprise. As our government sees it, this is nothing other than to take back from us by force the lands his father lost."],[25,28,"And this, I think, is the main reason for our preparations, the cause of our guard duty and the chief source of all this rush and bustle in the country."]],"55":[[0,4,"It's a speck of dust to trouble the mind's eye. In Rome, at the height of its glory, just before the mighty Julius Caesar fell, the graves were emptied and the dead in their shrouds squeaked and gibbered in the Roman streets."],[5,8,"There were comets with tails of fire, dews of blood, bad signs in the sun, and the moon, which controls the tides, was so darkened by eclipse it was almost like the end of the world."],[9,13,"And the same kind of warnings of terrible events, like messengers always running ahead of fate and like a prologue to the disaster that is coming, have been shown by heaven and earth together to our country and our people."]],"57":[[0,6,"But wait, look! Here it comes again! I'll stand in its way, even if it destroys me. Stop, illusion! If you can make any sound or use a voice, speak to me. If there is any good deed that could be done to give you peace and win me grace, speak to me."],[7,13,"If you know some secret about your country's fate, which knowing in advance might help us avoid, oh, speak! Or if in your life you buried stolen treasure in the earth, which they say is why spirits often walk after death, speak of it. Stop, and speak!"]],"67":[[0,4,"And then it jumped, like a guilty person called to answer for something. I've heard that the cock, the trumpeter of the morning, wakes the god of day with his high, shrill throat,"],[5,8,"and when he gives his warning, any wandering spirit, whether in sea or fire, earth or air, hurries back to where it is confined. And what we've just seen proves that this is true."]],"69":[[0,2,"So I've heard, and I partly believe it. But look, the morning, dressed in a reddish-brown cloak, is walking over the dew on that high hill in the east."],[3,8,"Let's end our watch, and I advise that we tell young Hamlet what we've seen tonight. I'd bet my life this spirit, silent to us, will speak to him. Do you agree that we should tell him, as our love for him demands and as our duty requires?"]],"74":[[0,6,"Although the death of our dear brother Hamlet is still fresh in our memory, and it was right for us to keep our hearts in mourning and for the whole kingdom to wear one frowning face of grief, good sense has so far fought against natural feeling that we think of him with wise sorrow while also remembering ourselves."],[7,15,"So we have married our former sister-in-law, now our queen, who shares the rule of this warlike country. We have done it with a kind of spoiled joy, with one eye hopeful and one eye weeping, with laughter at the funeral and lament at the wedding, weighing happiness and grief equally. And we did not ignore your wise advice, which freely supported this whole matter. Thank you all."],[16,24,"Next, as you know, young Fortinbras, who either thinks little of our strength or believes that our dear brother's recent death has thrown our country into disorder, has joined that fantasy of his advantage to constant messages pestering us to hand back the lands his father lost, legally, to our brave brother. So much for him."],[25,32,"Now for us and the reason for this meeting. This is the business: we have written to the King of Norway, young Fortinbras's uncle, who is weak and bedridden and has hardly heard of his nephew's plans, asking him to stop him going any further, since the troops, the lists of recruits and all the supplies are drawn from his own subjects."],[33,38,"And we are sending you, good Cornelius, and you, Voltemand, to carry this greeting to old Norway. You have no personal power to deal with the King beyond what these detailed terms allow. Goodbye, and show your loyalty by your speed."]],"78":[[0,4,"And now, Laertes, what's your news? You mentioned a request. What is it, Laertes? You can't make a reasonable request to the King of Denmark and waste your breath. What could you ask for, Laertes, that I wouldn't offer before you asked?"],[5,8,"The head is not more closely linked to the heart, nor the hand more ready to serve the mouth, than the throne of Denmark is to your father. What do you want, Laertes?"]],"89":[[0,5,"Seems, madam? No, it is. I don't know about 'seems'. It isn't just my inky black cloak, good mother, or my usual formal black clothes, or heavy sighing, or the flood of tears from my eyes, or the downcast look on my face,"],[6,10,"together with all the outward forms, moods and signs of grief, that can show what I truly feel. Those things really do seem, because they are actions a man could put on like an actor. But I have something inside me that goes beyond any show; those are just the decorations and costumes of grief."]],"90":[[0,7,"It is sweet and admirable in your nature, Hamlet, to give your father these duties of mourning. But you must know that your father lost a father; that father lost his; and the son left behind was bound by duty to mourn for a while. But to carry on stubbornly grieving is a course of ungodly obstinacy. It is unmanly grief."],[8,14,"It shows a will that rebels against heaven, a weak heart, an undisciplined mind, a simple, untrained understanding. Why should we, in childish resistance, take to heart something we know must happen, something as ordinary as the most common thing we see? Shame!"],[15,20,"It is an offence against heaven, an offence against the dead, an offence against nature and completely unreasonable, since reason's constant theme is the death of fathers, and it has always cried, from the first corpse to the man who died today, 'This is how it must be.' We beg you, throw away this useless grief, and think of us as a father."],[21,25,"For let the world note that you are next in line to our throne, and that I offer you love no less noble than the dearest father feels for his son."],[26,30,"As for your plan to go back to university in Wittenberg, it is completely against our wishes. We beg you to agree to stay here, where we can cheer and comfort you, as our leading courtier, our nephew and our son."]],"95":[[0,5,"Oh, I wish this too, too solid flesh would melt, thaw and dissolve into dew! Or that God had not made his law against suicide! Oh God! God! How weary, stale, flat and pointless all the ways of this world seem to me!"],[6,13,"Damn it, damn it! It's an unweeded garden that is going to seed; rank and coarse things completely fill it. That it should come to this! Only two months dead, no, not even that, not two. Such an excellent king, compared to this one like the sun god to a goat-man. So loving to my mother that he wouldn't let the winds of heaven blow too roughly on her face."],[14,20,"Heaven and earth! Must I remember? Why, she would cling to him as if her hunger grew by feeding on him. And yet, within a month, I won't think about it! Weakness, your name is woman! One little month, before the shoes she wore to follow my poor father's coffin were even old, weeping like Niobe,"],[21,28,"why she, even she, oh God, an animal with no power to reason would have mourned longer, married my uncle, my father's brother, but no more like my father than I am like Hercules. Within a month, before the salt of her false tears had stopped reddening her sore eyes, she married. Oh, wicked speed, to rush so nimbly into an incestuous bed!"],[29,30,"It is not good, and it can't come to any good. But break, my heart, because I must keep quiet."]],"119":[[0,6,"For two nights in a row these gentlemen, Marcellus and Barnardo, on guard duty in the dead, empty middle of the night, met this. A figure like your father, armed exactly from head to foot, appears in front of them, and with a solemn march walks slowly and grandly past."],[7,12,"Three times he walked past their frightened, astonished eyes, as close as the length of his staff, while they, almost melted to jelly with fear, stand silent and do not speak to him. They told me this in fearful secrecy, and on the third night I kept watch with them."],[13,16,"And there, just as they had described it, at the same time and in the same shape, every word proved true, the ghost comes. I knew your father. These two hands are not more alike."]],"150":[[0,6,"If it takes my noble father's shape, I'll speak to it, even if hell itself opens its mouth and tells me to be quiet. I beg you all, if you've kept this sight secret until now, keep holding it in silence. And whatever else happens tonight, understand it but don't talk about it."],[7,9,"I will repay your love. So, goodbye. I'll come to you on the battlements between eleven and twelve."]],"162":[[0,8,"Think of it as nothing more. When a person grows up, it isn't only muscles and size that grow; as the body, this temple, gets bigger, the mind and soul inside it grow too. Perhaps he loves you now, and no stain or deceit spoils his honest intentions. But you must be careful: considering his rank, his will is not his own, because he is bound by his birth."],[9,18,"He can't choose for himself, as unimportant people do, because the safety and health of the whole country depend on his choice. So his choice must be limited by the agreement and approval of the nation he will lead. So if he says he loves you, you would be wise to believe it only as far as a man in his particular position can act on what he says, which is no further than the main body of Denmark agrees."],[19,25,"Then think what damage your honour may suffer if you listen too trustingly to his love songs, or lose your heart, or open your chaste treasure to his uncontrolled pleading. Be afraid of it, Ophelia, be afraid of it, my dear sister. Keep back behind your feelings, out of range of the shots and dangers of desire."],[26,34,"The most careful girl is reckless enough if she shows her beauty even to the moon. Virtue itself can't escape the blows of slander. The canker worm eats the young flowers of spring too often before their buds have opened, and in the dewy morning of youth, infection is most likely to strike. So be careful. The safest thing is fear. Youth rebels against itself even when no one else is near."]],"169":[[0,7,"And make sure you write these few rules in your memory. Don't say what you are thinking, and don't act on any unwise thought. Be friendly, but not overfamiliar with everyone. Once you have friends and have tested them, hold them to your soul with hoops of steel, but don't wear out your hand shaking hands with every new, untried companion."],[8,16,"Be careful not to get into a quarrel, but once you are in one, act so that your opponent learns to beware of you. Listen to everyone, but speak to few. Hear everyone's opinion, but keep your own judgement to yourself. Buy clothes as expensive as you can afford, but not showy; rich, not flashy, because clothes often show what a man is, and the French of the highest rank are especially choosy and refined in this."],[17,23,"Don't be a borrower or a lender, because a loan often loses both the money and the friend, and borrowing blunts the habit of thrift. Above all: be true to yourself, and it must follow, as night follows day, that you can't then be false to anyone. Goodbye. May my blessing make this advice grow in you."]],"178":[[0,3,"Indeed, that's a good thought. I've been told he has very often spent time alone with you lately, and that you have been very free and generous in letting him see you."],[4,8,"If that is true, as I've been told by people warning me, I must tell you that you don't understand your position as clearly as my daughter should, for the sake of your honour. What is going on between you? Tell me the truth."]],"186":[[0,5,"Yes, traps to catch stupid birds. I know how generously the soul supplies the tongue with vows when passion is burning. These flames, daughter, give more light than heat, and both die out even while the promise is being made. You must not take them for real fire."],[6,11,"From now on, be a little more sparing with your company. Don't be so ready to talk just because he asks you to. As for Lord Hamlet, believe this much: he is young, and he can do more of what he likes than you can."],[12,20,"In short, Ophelia, don't believe his vows. They are go-betweens, not what they appear to be, just pleaders for sinful requests, speaking like holy, religious pimps to trick you better. This is my final word: plainly, from now on, I don't want you to waste a single spare moment talking to Lord Hamlet. See to it, I order you. Come along."]],"201":[[0,9,"Yes, it is. And to my mind, though I was born here and brought up in these ways, it's a custom it would be more honourable to break than to keep. This drunken partying makes us mocked and criticised by other nations, east and west. They call us drunkards and dirty our name by calling us pigs. And it does take away the heart and core of our reputation from our achievements, however great they are."],[10,19,"It often happens the same way with individual men. Because of some natural flaw in them, perhaps from their birth, which isn't their fault, since nobody can choose where he comes from; or because one part of their temperament grows too strong and breaks down the fences and forts of reason; or because of some habit that spoils their good manners; these men, I say, who carry the mark of one defect, whether it came from nature or from bad luck,"],[20,25,"even if their other virtues are as pure as grace and as great as any man can have, will be thought corrupt by everyone because of that one fault. A tiny drop of evil can spoil all the noble substance and bring it into disgrace."]],"204":[[0,6,"Angels and messengers of God, protect us! Whether you are a good spirit or a damned demon, whether you bring heavenly air or blasts from hell, whether your purpose is evil or kind, you come in such a shape that invites questions, so I will speak to you. I'll call you Hamlet, King, father, royal Dane. Oh, answer me!"],[7,12,"Don't let me burst with not knowing, but tell me why your holy bones, buried with full rites, have broken out of their burial clothes; why the tomb where we saw you quietly laid has opened its heavy marble jaws to throw you up again."],[13,18,"What can it mean, that you, a dead body, in full armour again, come back to the moonlit world, making the night hideous, and making us, mere fools of nature, shake so horribly with thoughts beyond what our souls can reach? Say, why is this? Why? What should we do?"]],"212":[[0,5,"What if it tempts you toward the sea, my lord, or to the terrifying top of the cliff that hangs over its base into the sea, and there takes on some other horrible shape that might rob you of your reason and drive you mad? Think about it."],[6,9,"The place itself, without any other reason, puts desperate thoughts into the head of anyone who looks down so far to the sea and hears it roaring below."]],"241":[[0,4,"I am your father's spirit, condemned for a fixed time to walk at night, and in the day shut away to starve in fire until the foul sins I committed while I was alive are burnt and cleansed away."],[5,11,"If I were not forbidden to tell the secrets of my prison, I could tell a story whose lightest word would tear up your soul, freeze your young blood, make your eyes jump out of their sockets like shooting stars, part your neatly combed hair and make each separate hair stand on end like the quills of an angry porcupine."],[12,14,"But this description of eternity must not be told to ears of flesh and blood. Listen, listen, oh, listen! If you ever loved your dear father—"]],"247":[[0,3,"I see you are ready. You'd be duller than the fat weed that lazily rots on the banks of Lethe, the river of forgetting, if this didn't stir you. Now, Hamlet, listen."],[4,9,"It has been announced that a snake stung me while I was sleeping in my orchard, so all of Denmark has been grossly deceived by a false story of my death. But know this, noble young man: the snake that took your father's life now wears his crown."]],"249":[[0,4,"Yes, that incestuous, adulterous beast. With his clever witchcraft and treacherous gifts, oh, wicked cleverness and gifts that have the power to seduce like that, he won over my queen, who seemed so virtuous, to his shameful lust."],[5,14,"Oh, Hamlet, what a fall that was! From me, whose love was so honourable that it kept faithfully to the vow I made her at our wedding, down to a wretch whose natural gifts were poor compared to mine. But just as virtue will never be tempted, even if lust courts it disguised as an angel, so lust, even if it is joined to a shining angel, will get tired of a heavenly bed and feed on garbage."],[15,19,"But wait! I think I can smell the morning air. Let me be quick. While I was sleeping in my orchard, as I always did in the afternoon, your uncle crept up on me in that unguarded hour with a bottle of the juice of cursed hebenon,"],[20,30,"and poured the poisonous liquid into the entrances of my ears. Its effect is so hostile to human blood that it runs as fast as mercury through the natural gates and passages of the body, and with sudden force it thickens and curdles the thin, healthy blood, like acid dropped into milk. That is what it did to mine. And at once a scaly rash covered my smooth body with a vile, disgusting crust like a leper's."],[31,37,"So, while I slept, by my brother's hand I lost my life, my crown and my queen all at once. I was cut off with my sins in full bloom, without the last sacrament, unprepared, without the last rites, with no chance to settle my account, but sent to judgement with all my faults on my head. Oh, horrible! Horrible! Most horrible!"],[38,45,"If you have natural feeling in you, don't put up with it. Don't let the royal bed of Denmark be a bed for lust and damned incest. But however you carry out this act, don't corrupt your mind, and don't let your soul plot anything against your mother. Leave her to heaven, and to the thorns of conscience inside her to prick and sting her."],[46,48,"Goodbye now! The glow-worm shows that morning is near, and its light is fading. Goodbye, goodbye, goodbye. Remember me."]],"251":[[0,5,"Oh, all you angels in heaven! Oh, earth! What else? Shall I call on hell too? Oh, no! Hold on, my heart, and you, my muscles, don't grow suddenly old, but hold me firmly up. Remember you? Yes, you poor ghost, as long as memory has a place in this confused head."],[6,12,"Remember you? Yes, from the notebook of my memory I'll wipe out all trivial, foolish notes, all sayings from books, all images and impressions from the past that youth and observation copied there, and your command alone shall live in the book of my brain, not mixed with less important things. Yes, by heaven!"],[13,17,"Oh, most wicked woman! Oh, villain, villain, smiling, damned villain! My notebook. It's right that I write it down, that one may smile, and smile, and be a villain. At least I'm sure it can be so in Denmark."]],"295":[[0,2,"Then welcome it as you would a stranger. There are more things in heaven and earth, Horatio, than your philosophy dreams of. But come."],[3,15,"Swear, as before, as you hope for God's mercy, that however strange or odd I behave, since I may later think it right to act crazy, when you see me at those times you will never fold your arms like this, or shake your head like this, or say something mysterious like 'Well, we know', or 'We could if we wanted', or 'If we chose to speak', or 'There are some who could if they were allowed', or any such hint, to show that you know anything about me. Swear you won't do this, so may grace and mercy help you when you need it most."]],"297":[[0,5,"Rest, rest, troubled spirit! So, gentlemen, I give you all my love, and whatever a poor man like Hamlet can do to show his love and friendship, God willing, he will do. Let's go in together, and keep your fingers on your lips, I beg you."],[6,8,"The times are out of joint. Oh, cursed bad luck that I was ever born to set them right! No, come on, let's go together."]],"305":[[0,6,"Indeed, well said, very well said. Look, sir, first find out for me which Danes are in Paris, and how and who they are, what money they have, where they live, who they mix with and what they spend. And when you discover, by this roundabout way of asking, that they know my son, then get closer to the point than direct questions would."],[7,9,"Pretend to know him a little, from a distance, like this: 'I know his father and his friends, and a bit of him.' Are you following this, Reynaldo?"]],"315":[[0,8,"Well, sir, here is my plan, and I believe it's a trick that works. When you put these slight stains on my son, as if he were something a little soiled in the making, listen to me: the man you are talking to, the one you want to sound out, if he has ever seen the young man you mention committing those faults, you can be sure he will agree with you like this:"],[9,11,"'Good sir', or something like it, or 'friend', or 'gentleman', depending on how people speak and address each other in that country."]],"319":[[0,7,"At 'will agree with you', yes, indeed! He'll agree with you like this: 'I know the gentleman. I saw him yesterday, or the other day, or then, or then, with so-and-so, and, as you say, he was gambling there, there he was drunk, there quarrelling over tennis.' Or perhaps, 'I saw him go into a house of business', that is, a brothel, and so on."],[8,13,"You see now: your bait of lies catches this fish of truth. And that's how we wise and far-sighted men, by roundabout ways and indirect approaches, find out the direct truth. So, by my lecture and advice, you'll find out about my son. You understand me, don't you?"]],"337":[[0,4,"He took me by the wrist and held me tight. Then he moved back the whole length of his arm, and with his other hand over his forehead like this, he started studying my face as if he were going to draw it. He stayed like that a long time."],[5,9,"At last, shaking my arm a little and nodding his head up and down three times like this, he gave a sigh so pitiful and deep that it seemed to shatter his whole body and end his life."],[10,13,"After that, he let me go, and with his head turned over his shoulder, he seemed to find his way without his eyes, because he went out of the door without their help, and kept them fixed on me to the end."]],"340":[[0,6,"That has made him mad. I'm sorry I didn't watch him with more care and judgement. I was afraid he was only playing with you and meant to ruin you. Curse my suspicion! It seems old men are as likely to go too far in our opinions as young people are to lack good sense."],[7,9,"Come, let's go to the King. He must know about this. Keeping it secret might cause more grief than the anger we'll cause by revealing this love."]],"344":[[0,8,"Welcome, dear Rosencrantz and Guildenstern. Besides wanting very much to see you, we sent for you in a hurry because we need your help. You have heard something about Hamlet's transformation; I call it that because neither his outward appearance nor his inner self is like it was. What it can be, other than his father's death, that has put him so far out of his right mind, I can't imagine."],[9,17,"I beg you both, since you were brought up with him from childhood and know his youth and temperament so well, to agree to stay here at our court for a little while, so that your company may draw him into some pleasures, and to find out, from whatever chances you get, whether something we don't know about is troubling him, which, once revealed, we could cure."]],"366":[[0,7,"He returns your greetings and good wishes most kindly. As soon as we raised the matter, he sent orders to stop his nephew's recruiting, which he had thought was preparation for a war against the Poles. But when he looked into it, he found it was really against your Highness. He was upset that his sickness, age and weakness had been taken advantage of,"],[8,15,"so he sent orders to arrest Fortinbras. In short, Fortinbras obeys, is told off by the King of Norway, and finally swears before his uncle never again to take up arms against your Majesty. At this, old Norway, overjoyed, gives him an income of three thousand crowns a year and permission to use the soldiers he raised against the Poles,"],[16,21,"with a request, set out here [Gives a paper], that you would allow them to pass peacefully through your lands for this expedition, on the terms of safety and permission written down in it."]],"369":[[0,4,"This business has ended well. My King and madam, to discuss what majesty should be, what duty is, why day is day, night is night, and time is time, would only waste night, day and time."],[5,10,"So, since keeping it short is the heart of wisdom, and long-windedness is just its limbs and outward decoration, I will be brief. Your noble son is mad. I call it mad, because what is true madness except being nothing else but mad? But let that go."]],"371":[[0,8,"Madam, I swear I'm not using any fancy talk at all. That he is mad is true; it's true it's a pity; and it's a pity it's true. A foolish figure of speech, but goodbye to it, because I won't use any art. Let's agree he is mad, then. Now what remains is to find the cause of this effect, or rather the cause of this defect, because this defective effect has a cause. That's what remains, and here's the rest. Consider this."],[9,17,"I have a daughter, have her while she's still mine, who, out of duty and obedience, mark you, has given me this. Now listen and draw your conclusions. [Reads] 'To the heavenly one, my soul's idol, the most beautified Ophelia.' That's a bad phrase, a vile phrase; 'beautified' is a vile phrase. But you'll hear. [Reads] 'These, to her excellent white breast, these...' and so on."]],"373":[[0,9,"Good madam, wait a moment. I'll read it all faithfully. [Reads] 'Doubt that the stars are fire, doubt that the sun moves, doubt that truth is truth, but never doubt that I love. Oh, dear Ophelia, I'm bad at writing verse. I don't have the skill to count out my groans in rhyme. But that I love you best, oh, very best, believe it. Goodbye. Yours forever, dearest lady, while this body belongs to him, Hamlet.'"],[10,13,"My daughter, out of obedience, has shown me this, and besides that she has told me about all his advances, when, how and where they happened."]],"377":[[0,8,"I'd like to prove that I am. But what would you have thought, when I saw this passionate love taking flight, and I noticed it, I must tell you, before my daughter told me, what would you, or my dear Majesty your queen here, have thought, if I had kept it to myself like a desk or notebook, or made my heart shut its eyes and stay silent, or looked on this love without seeing it? What would you have thought?"],[9,14,"No, I got straight to work, and spoke to my young lady like this: 'Lord Hamlet is a prince, out of your sphere. This must not happen.' And then I gave her orders to lock herself away from his visits, to see no messengers and accept no gifts. She did as I advised,"],[15,20,"and he, rejected, to make a long story short, became sad, then stopped eating, then couldn't sleep, then grew weak, then light-headed, and, sinking step by step like this, fell into the madness he now raves in, and that we all grieve over."]],"455":[[0,3,"I'll tell you why, and then I'll have said it before you have to reveal it, and your promise of secrecy to the King and Queen won't lose a single feather. Lately, though I don't know why, I have lost all my cheerfulness and given up all my usual exercise."],[4,7,"And it weighs so heavily on my mind that this fine structure, the earth, seems to me a barren rock sticking out into the sea. This most excellent canopy, the air, look, this splendid overhanging sky, this majestic roof decorated with golden fire, why, it seems to me nothing more than a foul, diseased mass of vapours."],[8,13,"What a masterpiece man is! How noble in his reason, how unlimited in his powers, in his shape and movement how precise and admirable, in action how like an angel, in understanding how like a god! The beauty of the world, the finest of animals! And yet, to me, what is this essence of dust? Man doesn't delight me. No, nor woman either, though your smiling seems to say so."]],"501":[[0,4,"You're welcome, masters, welcome, all. I'm glad to see you well. Welcome, good friends. Oh, my old friend! Your face has grown a beard since I last saw you. Have you come to beard me in Denmark? What, my young lady and mistress! By our Lady, your ladyship is closer to heaven than when I last saw you, by the height of a platform shoe."],[5,8,"Please God your voice hasn't cracked, like a gold coin cracked inside the ring and no longer worth anything. Masters, you are all welcome. We'll go straight at it like French falconers, fly at anything we see. We'll have a speech right now. Come, give us a taste of your skill. Come, a passionate speech."]],"503":[[0,8,"I heard you recite a speech to me once, but it was never acted, or if it was, not more than once, because the play, I remember, didn't please the masses; it was caviar to the common people. But it was, as I and others whose judgement in such things was better than mine thought, an excellent play, well arranged in its scenes, written with as much restraint as skill."],[9,11,"I remember someone said there were no spicy bits in the lines to make the story tasty, and nothing in the language that could charge the author with showing off, but called it an honest style, as healthy as it was sweet, and much more truly beautiful than showy. One speech in it I especially loved: it was Aeneas telling Dido the story, and especially the part where he speaks of Priam's murder. If you remember it, start at this line, let me see, let me see:"],[12,18,"'The rugged Pyrrhus, like the tiger of Hyrcania,' no, that's not it; it begins with Pyrrhus: 'The rugged Pyrrhus, whose black armour, as black as his purpose, looked like the night when he lay hidden in the fateful wooden horse, has now smeared his dark and dreadful look with a more dismal colour."],[19,27,"From head to foot he is now all red, horribly painted with the blood of fathers, mothers, daughters, sons, baked and crusted on by the burning streets, which give a cruel, damned light to their vile murders. Roasted in anger and fire, and covered like this with clotted blood, with eyes like glowing red jewels, hellish Pyrrhus looks for old grandfather Priam.' Now you carry on."]],"505":[[0,6,"'Soon he finds him, striking at the Greeks and falling short. His old sword, refusing to obey his arm, stays where it falls, disobeying orders. Unevenly matched, Pyrrhus rushes at Priam; in his rage he misses, but the rush of air from his deadly sword is enough to knock the weakened father down."],[7,14,"Then the senseless city of Troy, seeming to feel this blow, collapses with its burning towers, and with a hideous crash catches Pyrrhus's ear. For look, his sword, which was coming down on the white head of the respected Priam, seemed to stick in the air. So Pyrrhus stood like a tyrant in a painting, and, as if halfway between his intention and the deed, did nothing."],[15,24,"But as we often see, before a storm, a silence in the heavens, the clouds standing still, the bold winds silent and the earth below as quiet as death, then suddenly dreadful thunder rips the sky; so, after Pyrrhus's pause, reawakened vengeance sets him to work again. And the Cyclops' hammers never fell on the armour of Mars, made to last forever, with less pity than Pyrrhus's bleeding sword now falls on Priam."],[25,29,"Out, out, you whore, Fortune! All you gods, in a general council, take away her power. Break all the spokes and rims of her wheel, and roll the round hub down the hill of heaven as low as hell!'"]],"511":[[0,6,"'Running barefoot up and down, threatening the flames with her blinding tears, a rag on the head where the crown so recently sat, and for a robe, wrapped round her thin body worn out with childbearing, a blanket grabbed up in the panic. Anyone who had seen this, with a tongue soaked in poison, would have spoken treason against the rule of Fortune."],[7,13,"But if the gods themselves had seen her then, when she saw Pyrrhus making cruel sport, chopping up her husband's limbs with his sword, the sudden cry she let out, unless human things don't move them at all, would have made the burning eyes of heaven flow with tears and filled the gods with grief.'"]],"528":[[0,9,"Yes, goodbye to you. Now I'm alone. Oh, what a rogue and low slave I am! Isn't it monstrous that this actor here, just in a story, in a dream of passion, could force his soul to feel what he imagined, so that it made his face go pale, tears in his eyes, wildness in his look, a broken voice, and his whole body acting out what he imagined? And all for nothing! For Hecuba!"],[10,17,"What is Hecuba to him, or he to Hecuba, that he should weep for her? What would he do if he had the reason and the cue for passion that I have? He would drown the stage with tears, split everyone's ears with terrible words, drive the guilty mad, terrify the innocent, confuse the ignorant and stun the very senses of sight and hearing."],[18,22,"And yet I, a dull, spiritless rascal, mope around like a dreamer, not stirred by my cause, and can say nothing. No, not even for a king whose kingdom and precious life were destroyed by a damned crime."],[23,33,"Am I a coward? Who calls me villain? Hits me across the head? Pulls off my beard and blows it in my face? Tweaks my nose? Calls me a liar to my face, as deep as my lungs? Who does this to me? Ha! By God's wounds, I would take it, because I must be as meek as a pigeon and have no bitterness to make wrongs feel bitter, or I would have fattened all the hawks in the sky with this slave's guts by now. Bloody, filthy villain! Pitiless, treacherous, lustful, unnatural villain! Oh, vengeance!"],[34,39,"Why, what an ass I am! This is really fine, that I, the son of a dear father who was murdered, urged on to my revenge by heaven and hell, must unload my heart with words like a whore, and start cursing like a common slut, a kitchen servant! Shame on it! Ugh!"],[40,49,"Get to work, my brain! I have heard that guilty people watching a play have been so struck to the soul by the skill of the scene that they have confessed their crimes on the spot. For murder, though it has no tongue, will speak by some miraculous means. I'll have these actors perform something like my father's murder in front of my uncle. I'll watch his face. I'll probe him to the quick. If he so much as flinches, I'll know what to do."],[50,57,"The spirit I have seen may be the devil, and the devil has the power to take on a pleasing shape. Yes, and perhaps, because of my weakness and my depression, since he has great power over people in that state, he is deceiving me to damn me. I'll get evidence more solid than this. The play's the thing in which I'll catch the conscience of the King."]],"545":[[0,3,"Sweet Gertrude, leave us too, because we have secretly sent for Hamlet to come here, so that, as if by accident, he may meet Ophelia face to face."],[4,9,"Her father and I, spying for good reasons, will hide ourselves so that, seeing without being seen, we can judge their meeting clearly and work out from the way he behaves whether it is lovesickness or not that makes him suffer like this."]],"554":[[0,8,"To be, or not to be, that is the question: whether it is nobler to put up with all the blows and arrows that cruel fortune throws at us, or to fight against a whole sea of troubles and end them by fighting? To die, to sleep, nothing more; and if by a sleep we could end the heartache and the thousand natural shocks that the body inherits, that would be an ending we should pray for. To die, to sleep."],[9,13,"To sleep, perhaps to dream. Yes, that's the problem, because the thought of what dreams may come in that sleep of death, once we have thrown off the tangle of this life, must make us stop and think. That's the consideration that makes us put up with misery for so long."],[14,21,"For who would bear the whips and scorn of the world, the wrongs of the oppressor, the insults of the proud, the pain of rejected love, the slowness of the law, the rudeness of officials and the kicks that patient, deserving people get from the unworthy, when he could settle his own account with a simple dagger? Who would carry these burdens, grunting and sweating under a weary life,"],[22,26,"if it weren't that the dread of something after death, that undiscovered country from which no traveller ever comes back, confuses the will, and makes us prefer to bear the troubles we have rather than rush to others we know nothing about?"],[27,34,"So thinking makes cowards of us all, and so the natural colour of determination is covered with the pale, sickly look of thought, and great, important plans turn aside because of this and lose the name of action. But quiet now: the lovely Ophelia! Beautiful girl, remember all my sins in your prayers."]],"578":[[0,4,"Oh, what a noble mind is ruined here! The eye of a courtier, the tongue of a scholar, the sword of a soldier, the hope and flower of this fair kingdom, the mirror of fashion and the model of good behaviour, the one everyone watched, completely, completely fallen!"],[5,11,"And I, the most miserable and wretched of women, who sucked the honey of his musical promises, now see that noble, commanding reason jangling out of tune and harsh like sweet bells, that unequalled shape and face of young manhood in full bloom destroyed by madness. Oh, how wretched I am, to have seen what I saw, and to see what I see!"]],"580":[[0,6,"Love? His feelings don't go that way. And what he said, though it was a little disordered, wasn't like madness. There's something in his soul that his depression is sitting on like a bird on eggs, and I fear that when it hatches and comes out it will be dangerous. To prevent that, I have quickly made up my mind:"],[7,13,"he will go to England at once, to demand the payment they owe us and haven't paid. Perhaps the sea and different countries, with new things to see, will drive out this thing that has settled in his heart, which his brain keeps beating on, making him so unlike himself. What do you think?"]],"581":[[0,4,"It will work well. But I still believe the origin and beginning of his grief came from rejected love. Well, Ophelia? You needn't tell us what Lord Hamlet said; we heard it all."],[5,11,"My lord, do as you like, but if you think it right, after the play let his mother the Queen beg him alone to reveal his grief. Let her be blunt with him, and, if you agree, I'll hide where I can hear their whole conversation. If she can't find out what's wrong, send him to England, or shut him away wherever your wisdom thinks best."]],"586":[[0,5,"Say the speech, please, the way I said it to you, lightly and naturally. But if you overact it the way many of you actors do, I'd rather have the town crier speak my lines. And don't saw the air with your hand like this, but do everything gently, because even in the flood, the storm, and I might say the whirlwind of passion, you must find and create a self-control that gives it smoothness."],[6,10,"Oh, it hurts me to the soul to hear a loud, bewigged actor tear a passion to shreds, to rags, to split the ears of the people standing in the pit, who mostly can't appreciate anything except meaningless mime and noise. I'd have that sort of actor whipped for overplaying the ranting villain. It out-Herods Herod. Please avoid it."]],"588":[[0,6,"Don't be too tame either, but let your own judgement teach you. Fit the action to the word and the word to the action, taking special care not to go beyond what is natural. Anything overdone like that goes against the purpose of acting, whose aim, from the beginning until now, was and is to hold a mirror up to nature: to show virtue its own face, scorn its own image, and the age and body of the times its shape and imprint."],[7,14,"Now, if this is overdone or underdone, though it makes the ignorant laugh, it can only upset the judicious, and you must value the opinion of one of them more than a whole theatre full of the others. Oh, there are actors I have seen, and heard others praise highly, who, not to put it too irreverently, didn't speak or walk like Christians, pagans or even men, and strutted and bellowed so much that I thought some of Nature's apprentice workmen had made them, and made them badly, they imitated humanity so horribly."]],"605":[[0,6,"No, don't think I'm flattering you. What reward could I hope for from you, when you have no income except your good spirits to feed and clothe you? Why should anyone flatter the poor? No, let the sugary tongue lick foolish grandeur, and let the ready knee bend where profit may follow from fawning. Do you hear?"],[7,18,"Ever since my soul could make its own choices and tell one man from another, it has chosen you for itself. Because you have been like someone who suffers everything and yet is not hurt by it, a man who has taken Fortune's blows and rewards with equal thanks. And blessed are those whose passion and judgement are so well mixed that they are not a pipe for Fortune to play whatever note she likes. Give me the man who is not a slave to passion, and I will keep him at the centre of my heart, yes, in my heart of hearts, as I do you. That's a little too much of this."],[19,24,"There is a play tonight in front of the King. One scene in it is close to what I told you about my father's death. Please, when you see that part start, watch my uncle with all the attention of your soul."],[25,31,"If his hidden guilt doesn't break out of hiding at one particular speech, then it is a damned ghost we have seen, and my imaginings are as filthy as the blacksmith god Vulcan's forge. Watch him carefully, because I'll fix my eyes on his face, and afterwards we'll put our judgements together to decide what his reaction showed."]],"654":[[0,5,"May the sun and moon make as many journeys again before our love is over! But I'm so sorry, you have been so ill lately, so far from cheerful and from your old self, that I am worried about you. But although I'm worried, it mustn't upset you at all, my lord,"],[6,11,"because women's fear and love go together in equal amounts: either none of either, or too much of both. Now, you know from experience how great my love is, and my fear is as great as my love. Where love is great, the smallest doubts become fears; where little fears grow great, great love grows there."]],"659":[[0,9,"I do believe you mean what you are saying now, but we often break what we decide. Intentions are only slaves to memory, strong when they are born but with little staying power. Now, like unripe fruit, they stick to the tree, but they fall without shaking once they are ripe. It is unavoidable that we forget to pay ourselves the debts we owe ourselves. What we promise ourselves in passion, we lose the purpose of once the passion ends."],[10,17,"Violent grief or joy destroys its own actions along with itself. Where joy celebrates most, grief mourns most; grief turns to joy and joy to grief on the slightest chance. This world doesn't last forever, and it isn't strange that even our loves should change with our fortunes, because it's still an open question whether love leads fortune, or fortune love."],[18,23,"When a great man falls, you'll see his favourite runs away; when a poor man rises, his enemies become his friends. And so far love follows fortune, because the man who doesn't need anything will never lack a friend, and the man in need who tests a false friend immediately turns him into an enemy."],[24,29,"But to finish properly where I began, our wishes and our fates run so contrary to each other that our plans are always overthrown. Our thoughts are our own, but their outcomes are not. So you think you will never marry a second husband, but your thoughts will die when your first lord is dead."]],"752":[[0,4,"Now it's the very time of night when witches work, when churchyards open and hell itself breathes out disease into this world. Now I could drink hot blood, and do such cruel things that the day would tremble to see them. Quiet now, I must go to my mother."],[5,11,"Oh, heart, don't lose your natural feeling. Never let the soul of Nero, who killed his mother, enter this firm heart. Let me be cruel, but not unnatural. I'll speak daggers to her, but use none. Let my tongue and soul be hypocrites in this: however much my words shame her, my soul, never agree to turn them into actions."]],"758":[[0,4,"Every private individual is bound, with all the strength and armour of the mind, to protect himself from harm; but much more so the man on whose well-being the lives of many depend and rest."],[5,12,"When a king dies, he doesn't die alone, but like a whirlpool drags what's near him down with him. He is a huge wheel fixed on the top of the highest mountain, with ten thousand smaller things fitted and joined to its great spokes; when it falls, every small attachment, every little thing connected to it, goes down with the noisy ruin. The King never sighs alone, but the whole nation groans with him."]],"763":[[0,5,"My lord, he's going to his mother's room. I'll hide myself behind the curtain to hear what happens. I promise you she'll tell him off thoroughly. And as you said, and it was wisely said, it's right that someone other than his mother, since mothers are naturally biased, should overhear what he says, from a good hiding place."],[6,8,"Goodbye, my King. I'll come to you before you go to bed and tell you what I know."]],"766":[[0,6,"Oh, my crime is foul. It stinks all the way to heaven. It carries the first and oldest curse, Cain's curse: a brother's murder. I can't pray, though my wish to is as strong as my will. My stronger guilt defeats my strong intention, and like a man bound to do two things at once, I stand hesitating over where to begin, and do neither."],[7,14,"What if this cursed hand were coated thicker than itself with a brother's blood? Isn't there enough rain in the sweet heavens to wash it as white as snow? What is mercy for, if not to face sin head on? And what is prayer, if not this double power: to stop us before we fall, or to pardon us once we have fallen? Then I'll look up."],[15,20,"My crime is in the past. But oh, what kind of prayer can work for me? 'Forgive me my foul murder'? That can't be, since I still have all the things I murdered for: my crown, my own ambition and my queen. Can a man be pardoned and keep what he gained from the crime?"],[21,28,"In the corrupt ways of this world, the gold-covered hand of crime can push justice aside, and often the stolen profits themselves are used to buy off the law. But it isn't like that in heaven. There's no trickery there; there the deed is seen as it really is, and we ourselves are forced to give evidence against our own faults, face to face."],[29,36,"What then? What's left? Try what repentance can do. What can't it do? But what can it do when someone cannot repent? Oh, wretched state! Oh, heart as black as death! Oh, trapped soul, that struggles to be free and only gets more stuck! Help, angels! Make an effort. Bend, stubborn knees, and heart, with your strings of steel, be as soft as the muscles of a newborn baby! All may be well."]],"769":[[0,5,"Now I could do it easily, now he's praying. And now I'll do it. And so he goes to heaven, and so I'm revenged. That needs thinking about. A villain kills my father, and for that I, his only son, send this same villain to heaven. Oh, this is like doing him a paid favour, not revenge."],[6,12,"He killed my father when he was full of food and unprepared, with all his sins in full bloom, as lush as May. And how his account stands, who knows except heaven? But as far as we can see and think, it goes badly for him. And am I then revenged, if I kill this man while he is cleansing his soul, when he is ready and prepared for his journey? No."],[13,21,"Back in your sheath, sword, and wait for a more horrible occasion: when he is asleep drunk, or in a rage, or enjoying the incestuous pleasures of his bed, gambling, swearing, or doing something that has no hint of salvation in it. Then trip him up, so that his heels kick at heaven and his soul is as damned and black as hell, where it is going. My mother is waiting. This medicine of prayer only lengthens your sick life."]],"804":[[0,3,"Yes, lady, that's what I said. [To Polonius] You wretched, rash, interfering fool, goodbye! I took you for your superior. Accept your fate. You've found out that being too busy is dangerous."],[4,8,"Stop wringing your hands. Quiet, sit down, and let me wring your heart instead, because I will, if it's made of anything that can be pierced, if damned habit hasn't turned it to brass so that it's armoured and defended against all feeling."]],"806":[[0,5,"Such a deed that it stains the grace and the blush of modesty, calls virtue a hypocrite, takes the rose from the fair forehead of innocent love and puts a brand there; makes wedding vows as false as gamblers' oaths."],[6,11,"Oh, such a deed as plucks the very soul out of the marriage contract, and turns sweet religion into a jumble of words. Heaven's face is blushing, and yes, this solid earth, with a sad face as if Judgement Day were coming, is sick at the thought of the deed."]],"808":[[0,9,"Look here at this picture, and at this one, the painted likenesses of two brothers. See what grace was in this face: the curls of the sun god Hyperion, the forehead of Jove himself, an eye like Mars, the god of war, to threaten and command, a stance like the messenger god Mercury just landed on a hill that kisses the sky; a combination and a shape indeed where every god seemed to put his stamp, to show the world what a real man is."],[10,17,"This was your husband. Look now at what comes next. Here is your husband, like a diseased ear of corn infecting his healthy brother. Do you have eyes? Could you stop feeding on this fine mountain and gorge yourself on this barren moor? Ha! Do you have eyes? You can't call it love, because at your age the excitement in the blood is tamed, it's humble, and it obeys judgement."],[18,28,"And what judgement would step down from this to this? You must have senses, or you couldn't move. But those senses must be paralysed, because even madness wouldn't make that mistake, and the senses were never so enslaved by madness that they didn't keep some power of choice to see such a difference. What devil tricked you like this in a game of blind man's buff? Eyes without touch, touch without sight, ears without hands or eyes, smell without anything else, even one sickly part of a single true sense could not be so stupid."],[29,35,"Oh, shame! Where is your blush? Rebellious hell, if you can stir up revolt in a middle-aged woman's bones, then let virtue be like wax for passionate youth and melt in its own fire. Don't call it shameful when hot young desire attacks, since frost itself burns just as fiercely, and reason acts as a pimp for lust."]],"821":[[0,6,"Oh, how are you, that you stare at empty space and hold a conversation with the bodiless air? Your spirits peep wildly out of your eyes, and your hair, which was lying flat, jumps up and stands on end as if it were alive, like sleeping soldiers when the alarm sounds."],[7,8,"Oh, gentle son, sprinkle cool patience on the heat and flame of your illness. What are you looking at?"]],"831":[[0,7,"Madness! My pulse beats as steadily as yours and makes just as healthy a music. It isn't madness that I have spoken. Test me, and I'll repeat everything I said word for word, which madness would leap away from. Mother, for the love of God, don't put that comforting ointment on your soul, telling yourself it is my madness speaking and not your sin."],[8,16,"It will only put a skin over the infected place while foul corruption eats away everything inside it unseen. Confess yourself to heaven. Repent what is past. Avoid what is to come, and don't spread manure on the weeds to make them grow stronger. Forgive me for my virtue, because in these fat, bloated times virtue itself has to beg vice for pardon, yes, bow and beg for permission to do it good."]],"833":[[0,8,"Oh, throw away the worse part of it, and live more purely with the other half. Good night. But don't go to my uncle's bed. Act as if you are virtuous, even if you aren't. That monster habit, which eats up all awareness of evil habits, is still an angel in this way: it also gives us a uniform for good and fair actions that fits easily."],[9,15,"Hold back tonight, and that will make the next time you hold back a bit easier; the next time easier still, because habit can almost change our nature, and either control the devil or throw him out with wonderful power. Once more, good night, and when you want to be blessed by God, I'll ask you to bless me."],[16,24,"[Pointing to Polonius] As for this lord, I'm sorry. But heaven has chosen to punish me with this and him with me, so that I must be heaven's whip and its agent. I'll get rid of the body and take responsibility for killing him. So again, good night. I must be cruel only to be kind. This is a bad beginning, and worse is still to come. One more word, good lady."]],"835":[[0,7,"Certainly not what I tell you to do: let the bloated King tempt you to bed again, pinch your cheek lustfully, call you his mouse, and for a couple of stinking kisses, or by fondling your neck with his damned fingers, get you to reveal all this, that I am not really mad, only mad on purpose."],[8,15,"It would be good to let him know, because what queen, who is beautiful, sensible and wise, would hide such important matters from a toad, a bat, a tomcat? Who would do that? No, forget sense and secrecy: open the basket on the roof, let the birds fly out, and, like the famous ape, climb into the basket to test it and fall and break your own neck."]],"839":[[0,8,"There are sealed letters, and my two schoolfellows, whom I'll trust as much as poisonous snakes, carry the orders. They are to clear the way for me and lead me into some trap. Let it happen, because it's fun to see the bomb-maker blown up with his own bomb. It will be hard luck if I don't dig a yard under their tunnels and blow them up to the moon. Oh, it's very sweet when two plots meet head on."],[9,15,"This man will make me pack up and leave in a hurry. I'll drag the guts into the next room. Mother, good night. This adviser really is very still now, very secretive and very serious, who in life was a foolish, chattering rogue. Come, sir, let's finish with you. Good night, mother."]],"849":[[0,4,"Oh, terrible deed! It would have happened to us if we had been there. His freedom is a threat to everyone, to you yourself, to us, to all. Oh dear, how shall we explain this bloody deed?"],[5,11,"It will be blamed on us, who should have had the foresight to keep this mad young man on a short lead, restrained and away from people. But our love was so great that we wouldn't see what was the right thing to do, and like someone with a foul disease who keeps it hidden, we let it feed on the very core of life. Where has he gone?"]],"880":[[0,5,"I've sent people to look for him and find the body. How dangerous it is that this man is free! But we mustn't use the full force of the law on him. He is loved by the confused common people, who judge by what they see, not by reason,"],[6,10,"and when that's the case, they weigh up the offender's punishment, but never the offence. To keep everything smooth and calm, sending him away suddenly like this must look like a carefully considered decision. Diseases that have become desperate can only be cured by desperate remedies, or not at all."]],"913":[[0,6,"And King of England, if you value my love at all, as my great power should make you do, since your scar from the Danish sword still looks raw and red and you pay us respect out of your own free fear, you can't ignore our royal command, which is set out fully in letters urging this: the immediate death of Hamlet."],[7,10,"Do it, England, because he rages in my blood like a fever, and you must cure me. Until I know it's done, whatever my luck, my happiness can never begin."]],"938":[[0,7,"How everything that happens accuses me and spurs on my slow revenge! What is a man, if the main good and use of his time is only to sleep and eat? A beast, nothing more. Surely the one who made us with such a great power of reasoning, able to look forward and back, didn't give us that ability and godlike reason to go mouldy in us unused."],[8,14,"Now, whether it is animal forgetfulness or some cowardly worry from thinking too carefully about the outcome, a thought which, cut into four, has only one part wisdom and always three parts cowardice, I don't know why I am still alive to say 'This must be done', when I have the reason, the will, the strength and the means to do it. Examples as big as the earth urge me on."],[15,24,"Look at this army, so large and so expensive, led by a delicate, young prince whose spirit, swollen with divine ambition, pulls faces at the unknown outcome, exposing what is mortal and uncertain to everything that fortune, death and danger can do, all for an eggshell. To be truly great is not to act without a great cause, but to find a great reason to fight over a straw when honour is at stake."],[25,34,"Where does that leave me, then, who have a murdered father and a disgraced mother, things that should rouse my reason and my passion, and yet I let it all sleep, while to my shame I see twenty thousand men about to die, who for a fantasy and a trick of fame go to their graves as if to bed, fighting for a plot of land that isn't big enough for all the armies to fight on, and isn't even a big enough tomb to hold the dead? Oh, from now on, let my thoughts be bloody, or be worth nothing!"]],"945":[[0,3,"She talks a lot about her father, says she hears there is trickery in the world, coughs and beats her breast, kicks angrily at straws, and says things that are unclear and only half make sense."],[4,11,"Her words mean nothing, and yet their confused shape makes listeners try to piece them together. They guess at her meaning and patch the words up to fit their own thoughts, and her winks, nods and gestures do make you think there might be some meaning behind them, nothing certain, but something very unhappy. It would be good to speak with her, because she may spread dangerous suspicions in minds that breed trouble."]],"963":[[0,2,"Please, let's not talk about this, but when they ask you what it means, say this: [Sings]"],[3,10,"Tomorrow is Saint Valentine's Day, early in the morning, and I'm a girl at your window, to be your Valentine. Then up he got and put his clothes on, and opened the bedroom door, and let the girl in, who never left it a girl again."]],"965":[[0,5,"Yes, really, without swearing, I'll finish it. [Sings] By Jesus and by holy charity, oh no, and shame on them! Young men will do it if they get the chance; by God, they are to blame."],[6,9,"She said, 'Before you tumbled me, you promised to marry me.' He answers: 'I would have done it, by that sun up there, if you hadn't come to my bed.'"]],"971":[[0,7,"Oh, this is the poison of deep grief. It all comes from her father's death. Oh, Gertrude, Gertrude, when sorrows come, they don't come like single spies, but in whole battalions. First her father killed; next your son gone, and he himself the violent cause of his own rightful exile; the people stirred up, muddy and unhealthy in their thoughts and whispers about good Polonius's death."],[8,10,"And we have acted foolishly in burying him in secret. Poor Ophelia, cut off from herself and her good judgement, without which we are only pictures or mere animals."],[11,20,"Last, and as serious as all of these together, her brother has come back secretly from France. He feeds on his suspicions, keeps himself hidden in clouds, and has no shortage of gossips to infect his ear with poisonous stories about his father's death, in which, since they don't know the facts, they won't hesitate to accuse me from ear to ear. Oh, my dear Gertrude, this, like a cannon firing scattered shot, hits me in many places and kills me more times than I need."]],"977":[[0,4,"Save yourself, my lord. The ocean, rising over its limits, doesn't swallow up the shore with more violent speed than young Laertes, at the head of a rioting crowd, is overpowering your officers. The mob call him lord,"],[5,10,"and as if the world were only just beginning, with tradition forgotten and custom unknown, though these are what confirm and support every title, they shout 'We choose! Laertes shall be king!' Caps, hands and tongues cheer it to the clouds: 'Laertes shall be king! Laertes king!'"]],"1006":[[0,4,"Oh, heat, dry up my brain! Tears seven times salty, burn out the feeling and power of my eyes! By heaven, your madness will be paid for in full, until our side of the scales outweighs the other. Oh, rose of May! Dear girl, kind sister, sweet Ophelia!"],[5,9,"Oh, heavens! Is it possible that a young girl's mind can be as easily killed as an old man's life? Human nature is refined by love, and when it is, it sends some precious part of itself after the thing it loves."]],"1015":[[0,5,"[Sings] And won't he come back again? And won't he come back again? No, no, he is dead. Go to your deathbed. He will never come back again."],[6,11,"His beard was as white as snow, his hair all pale like flax. He is gone, he is gone, and we throw away our grief. God have mercy on his soul! And on all Christian souls, I pray to God. God be with you."]],"1018":[[0,7,"Laertes, I must share in your grief, or you deny me what is right. Just go aside, choose whichever of your wisest friends you like, and let them hear us and judge between you and me. If they find that I was involved, directly or indirectly, I will give you our kingdom, our crown, our life and everything we call ours, to make up for it."],[8,10,"But if not, be content to be patient with us, and we will work together with you to give your soul the satisfaction it deserves."]],"1033":[[0,7,"[Reads] 'Horatio, when you have read this, help these fellows get to the King. They have letters for him. Before we were two days out at sea, a pirate ship very well armed chased us. Finding we were too slow, we were forced to be brave, and in the fight I boarded their ship. At that moment they got clear of our ship, so I alone became their prisoner. They have treated me like merciful thieves, but they knew what they were doing: I am to do them a favour."],[8,14,"Let the King have the letters I have sent, and come to me as fast as you would run from death. I have things to tell you that will leave you speechless, and yet my words are far too light for the weight of the matter. These good fellows will bring you to where I am. Rosencrantz and Guildenstern are still on their way to England. I have a lot to tell you about them. Goodbye. The one you know is yours, Hamlet.'"],[15,17,"Come, I'll get these letters of yours delivered, and I'll do it all the faster so that you can take me to the man who gave them to you."]],"1039":[[0,7,"Oh, for two special reasons, which may seem very weak to you, but to me they are strong. The Queen, his mother, lives almost for the sight of him, and as for me, whether it is my virtue or my curse, she is so closely joined to my life and soul that, just as a star only moves within its own sphere, I can only move with her."],[8,15,"The other reason I couldn't bring him to public trial is the great love the common people have for him. They dip all his faults in their affection and, like the spring that turns wood into stone, would turn his chains into honours. So my arrows, too light for such a strong wind, would have blown back to my bow and not gone where I aimed them."]],"1059":[[0,4,"A mere ribbon in the cap of youth, and yet a necessary one too, because light, carefree clothes suit youth no less than sober furs and robes suit settled old age, showing well-being and seriousness."],[5,13,"Two months ago there was a gentleman from Normandy here. I've seen the French myself and fought against them, and they ride very well, but this young man was like a magician. He seemed to grow into his saddle, and he made his horse do such amazing things, it was as if he had become one body with the fine animal, half man, half horse. He went so far beyond what I could imagine that I can't invent the moves and tricks he did."]],"1065":[[0,7,"He told us about you, and gave you such a glowing report for your skill and practice in fencing, especially with the rapier, that he exclaimed it would be a real sight if anyone could match you. He swore the fencers of his country had no movement, defence or eye when they faced you."],[8,11,"Sir, this report of his made Hamlet so poisoned with envy that he could do nothing but wish and beg for you to come back quickly and fence with him. Now, out of this—"]],"1069":[[0,8,"Not because I think you didn't love your father, but because I know that love is started by time, and I see, from experience, that time weakens its spark and fire. Inside the very flame of love there lives a sort of wick or burnt end that will dim it, and nothing stays at the same level of goodness forever, because goodness, growing too full, dies of its own excess."],[9,16,"What we want to do, we should do when we want to, because this 'want' changes and has as many weakenings and delays as there are tongues, hands and accidents, and then this 'should' is like a wasteful sigh that hurts while it eases. But to the heart of the sore: Hamlet comes back. What would you do to show yourself your father's son in actions, more than in words?"]],"1071":[[0,6,"No place, it's true, should give sanctuary to a murderer. Revenge should have no limits. But, good Laertes, if you'll do this, stay shut up in your room. When Hamlet comes back, he'll learn that you are home. We'll get people to praise your skill and put a double coat of polish on the reputation the Frenchman gave you, and finally bring you together and bet on you."],[7,12,"He, being careless, very generous and free of all scheming, won't examine the swords, so that easily, or with a little sleight of hand, you can choose a sword without a safety tip, and with a thrust in the practice match pay him back for your father."]],"1072":[[0,6,"I'll do it, and for that purpose I'll smear poison on my sword. I bought an ointment from a travelling quack so deadly that if you just dip a knife in it, where it draws blood, no remedy, however rare, made from every herb with healing powers under the moon, can save anyone from death who is even scratched with it."],[7,9,"I'll touch the tip of my sword with this poison, so that if I graze him even slightly, it will mean death."]],"1073":[[0,6,"Let's think further about this, and consider what timing and means will best suit our roles. If this should fail, and our plan should show through because we carry it out badly, it would be better not to try. So this plan should have a backup, a second one that would work if this one blew up when tested. Wait, let me see."],[7,13,"We'll make a formal bet on your skills. I've got it! When you are hot and thirsty from moving, and you should make your bouts more violent for that purpose, and he asks for a drink, I'll have prepared a cup for him for the occasion. If he just sips it, even if by chance he escapes your poisoned thrust, our plan will still succeed."]],"1078":[[0,5,"There is a willow growing at an angle over a stream, showing its grey-white leaves in the glassy water. There she came with fantastic garlands she had made of buttercups, nettles, daisies and long purple flowers, which the coarse shepherds give a rude name, but our chaste girls call dead men's fingers."],[6,13,"There, as she climbed to hang her crown of flowers on the hanging branches, a spiteful branch broke, and down she fell with her flowery trophies into the weeping stream. Her clothes spread out wide and held her up like a mermaid for a while, and all that time she sang bits of old songs, as if she didn't understand the danger she was in, or like a creature born and suited to the water."],[14,17,"But it couldn't be long before her clothes, heavy with all the water they had soaked up, pulled the poor girl from her lovely singing down to a muddy death."]],"1128":[[0,3,"There's another. Why couldn't that be the skull of a lawyer? Where are his quibbles now, his fine distinctions, his cases, his property rights and his tricks? Why does he let this rough rogue knock him on the head with a dirty shovel, and not threaten to sue him for assault?"],[4,11,"Hm. This fellow might have been a great buyer of land in his time, with his contracts, his bonds, his transfers, his double guarantees, his legal recoveries. Is this the end of his transfers and the recovery of his recoveries, to have his fine head full of fine dirt? Will all his guarantees, even the double ones, guarantee him no more land than the length and width of a pair of contracts? The deeds to his lands would hardly fit in this box, and must the owner himself have no more than this, ha?"]],"1168":[[0,4,"Let me see. [Takes the skull] Oh, poor Yorick! I knew him, Horatio, a fellow of endless jokes and the most brilliant imagination. He carried me on his back a thousand times, and now how disgusting it is to think of! It makes me feel sick. Here hung those lips that I kissed I don't know how often."],[5,9,"Where are your jokes now? Your capers? Your songs? Your flashes of fun that used to set the whole table roaring? Not one left now to mock your own grin? Your jaw has quite dropped. Now go to my lady's room and tell her that even if she paints her make-up on an inch thick, she must come to this face in the end. Make her laugh at that. Please, Horatio, tell me one thing."]],"1177":[[0,4,"No, honestly, not a bit. Just follow him there reasonably, with likelihood to lead the way, like this: Alexander died, Alexander was buried, Alexander turns back into dust; the dust is earth; from earth we make clay; and why couldn't they use the clay he turned into to plug a beer barrel?"],[5,9,"Mighty Caesar, dead and turned to clay, might plug a hole to keep the wind away. Oh, that the earth which kept the world in awe should patch a wall to keep out the winter's gusts! But quiet! Quiet! Step aside! Here comes the King."]],"1184":[[0,4,"Her funeral has been given as many rites as we are allowed. Her death was suspicious, and if the King's orders hadn't overruled the normal rules, she would have been buried in unholy ground until the trumpet sounds on Judgement Day."],[5,8,"Instead of charitable prayers, broken pots, flints and pebbles would have been thrown on her. Yet here she is allowed the garlands of a virgin, flowers scattered for a maiden, and to be brought to her last home with the bell and a proper burial."]],"1190":[[0,5,"Oh, may three times the sorrow fall ten times three times on that cursed head whose wicked deed robbed you of your fine mind! Hold back the earth for a while, until I've held her in my arms once more. [Leaps into the grave]"],[6,9,"Now pile your dust on the living and the dead, until you've made a mountain out of this flat ground, higher than old Mount Pelion or the sky-high top of blue Olympus."]],"1204":[[0,5,"By God's wounds, show me what you'll do. Will you weep? Will you fight? Will you starve yourself? Will you tear yourself to pieces? Will you drink vinegar? Eat a crocodile? I'll do it. Did you come here to whine? To outdo me by leaping into her grave? Be buried alive with her, and so will I."],[6,10,"And if you babble about mountains, let them throw millions of acres on top of us, until the pile scorches its head against the burning sun and makes Mount Ossa look like a wart. No, if you're going to rant, I'll rant as well as you."]],"1218":[[0,6,"I got up from my cabin, wrapped my sea-coat round me, and groped in the dark to find them. I got what I wanted, fingered their package of letters, and finally went back to my own room, being so bold, since my fears made me forget my manners, as to break the seal on their important orders. And there I found, Horatio,"],[7,13,"oh, royal villainy! an exact command, padded with lots of different reasons about the welfare of Denmark and of England too, with such bogeymen and goblins if I were left alive, that as soon as the letter was read, with no time wasted, not even to wait for the axe to be sharpened, my head should be cut off."]],"1222":[[0,3,"Being caught like this in a net of villainy, before I could even begin to think about it, my brain had started the play. I sat down, invented a new set of orders and wrote it out neatly."],[4,8,"I used to think, as our statesmen do, that neat handwriting was something for lowly clerks, and I worked hard to forget that skill, but, sir, now it did me loyal service. Do you want to know what I wrote?"]],"1224":[[0,5,"A solemn request from the King, since England was his loyal subject state, since love between them should flourish like the palm tree, since peace should always wear her garland of wheat and stand like a link between their friendships, and many more such 'since's of great importance,"],[6,9,"that as soon as he had seen and read these contents, without any more discussion of any kind, he should put the bearers to immediate death, with no time allowed for confession."]],"1300":[[0,6,"Forgive me, sir. I have done you wrong, but forgive it, as you are a gentleman. Everyone here knows, and you must have heard, how I have been punished with a terrible madness. Whatever I have done that might have roughly roused your feelings, your honour and your resentment, I declare here was madness."],[7,13,"Was it Hamlet who wronged Laertes? Never Hamlet. If Hamlet is taken away from himself, and when he's not himself he wrongs Laertes, then Hamlet doesn't do it. Hamlet denies it. Who does it, then? His madness. If that's so, Hamlet is on the side of the injured. His madness is poor Hamlet's enemy."],[14,18,"Sir, in front of these people, let my denial that I meant any harm free me so far in your generous thoughts as if I had shot an arrow over the house and accidentally hurt my brother."]],"1301":[[0,5,"As far as my natural feelings go, which in this case should push me hardest towards revenge, I am satisfied. But as far as honour goes, I hold back, and I won't make peace until some older experts in matters of honour give me their opinion and a precedent for peace,"],[6,8,"so that my name is not stained. But until then, I accept your offered love as love, and I won't wrong it."]],"1314":[[0,7,"Put the jugs of wine on that table for me. If Hamlet makes the first or second hit, or gets even in the third bout, let all the cannons on the battlements fire. The King will drink to Hamlet's health, and he'll throw a pearl into the cup, richer than the one four kings in a row have worn in Denmark's crown."],[8,12,"Give me the cups, and let the kettledrum tell the trumpet, the trumpet the gunner outside, the cannons the heavens, and the heavens the earth: 'Now the King drinks to Hamlet!' Come, begin. And you judges, watch carefully."]],"1369":[[0,5,"May heaven free you from guilt for it! I'll follow you. I'm dead, Horatio. Wretched Queen, goodbye! You who look pale and tremble at what has happened, who are only silent extras or audience to this act, if only I had time, since this cruel officer, death, is strict in his arrest, oh, I could tell you—"],[6,8,"But let it be. Horatio, I'm dead. You are alive. Tell my story and my cause truthfully to those who don't know."]],"1384":[[0,5,"Not his mouth, even if it had the life to thank you. He never ordered their deaths. But since you have arrived here so soon after this bloody business, you from the Polish wars and you from England,"],[6,14,"give orders that these bodies be put high on a platform for everyone to see, and let me tell the world, which doesn't know yet, how these things happened. Then you will hear of lustful, bloody and unnatural acts, of accidental judgements and chance killings, of deaths caused by cunning and by force, and, in this ending, of plans gone wrong that fell back on the heads of those who made them. All this I can truthfully tell you."]],"1387":[[0,5,"Let four captains carry Hamlet like a soldier onto the platform, because he would probably have proved a great king, if he had been given the chance. And to mark his passing, let soldiers' music and the rites of war speak loudly for him."],[6,8,"Take up the bodies. A sight like this belongs on a battlefield, but here it looks very wrong. Go, tell the soldiers to fire."]]};
const QUOTES={"themes":{"revenge":["Revenge","The Ghost's command, three sons with dead fathers, and what revenge does to those who seek it."],"action":["Thought and action","Delay, doubt, conscience and the gap between knowing and doing."],"death":["Death and mortality","Skulls, graves, suicide and the undiscovered country."],"madness":["Madness","Hamlet's 'antic disposition', Ophelia's real breakdown, and how hard it is to tell them apart."],"appearance":["Appearance and reality","Seeming versus being: masks, acting, spying and painted faces."],"corruption":["Corruption and disease","Something rotten in Denmark: poison, ulcers, weeds and decay."],"women":["Women and sex","Gertrude and Ophelia as Hamlet and the other men see them."],"kingship":["Kingship and the state","A murdered king, an elected usurper, and the health of the nation."],"fate":["Fate and providence","Chance, the will of heaven and Hamlet's readiness at the end."],"truth":["Certainty and truth","How can anyone know the truth: about the Ghost, about guilt, about madness, about what follows death?"]},"quotes":[{"id":"37","who":"HORATIO","text":"It harrows me with fear and wonder.","themes":["fate"],"note":"Horatio, the sceptic, is shaken: the Ghost is real enough for a scholar."},{"id":"55","who":"HORATIO","text":"In the most high and palmy state of Rome, A little ere the mightiest Julius fell, The graves stood tenantless and the sheeted dead Did squeak and gibber in the Roman streets;","themes":["fate","kingship"],"note":"Horatio links the Ghost to the omens before Caesar's murder: a state in danger."},{"id":"83","who":"HAMLET","text":"A little more than kin, and less than kind.","themes":["appearance"],"note":"Hamlet's first words, an aside and a pun: related, but not kind or natural."},{"id":"85","who":"HAMLET","text":"Not so, my lord, I am too much i' the sun.","themes":["appearance"],"note":"A pun on sun and son: he resents being called Claudius's son."},{"id":"89","who":"HAMLET","text":"Seems, madam! Nay, it is; I know not seems.","themes":["appearance"],"note":"Hamlet insists his grief is real, unlike the court's performance."},{"id":"89","who":"HAMLET","text":"But I have that within which passeth show; These but the trappings and the suits of woe.","themes":["appearance","death"],"note":"Inner feeling is beyond any outward show."},{"id":"95","who":"HAMLET","text":"O that this too too solid flesh would melt, Thaw, and resolve itself into a dew! Or that the Everlasting had not fix'd His canon 'gainst self-slaughter.","themes":["death"],"note":"The first soliloquy opens with a wish to dissolve and die."},{"id":"95","who":"HAMLET","text":"How weary, stale, flat, and unprofitable Seem to me all the uses of this world!","themes":["death","action"],"note":"Four adjectives drain the world of meaning."},{"id":"95","who":"HAMLET","text":"'tis an unweeded garden That grows to seed; things rank and gross in nature Possess it merely.","themes":["corruption"],"note":"Denmark, or the world, as a garden gone to seed."},{"id":"95","who":"HAMLET","text":"Frailty, thy name is woman!","themes":["women"],"note":"Hamlet turns his mother's remarriage into a judgement on all women."},{"id":"95","who":"HAMLET","text":"But break, my heart, for I must hold my tongue.","themes":["action"],"note":"Hamlet must keep silent: his first enforced inaction."},{"id":"108","who":"HAMLET","text":"Thrift, thrift, Horatio! The funeral bak'd meats Did coldly furnish forth the marriage tables.","themes":["corruption","women"],"note":"Bitter wit: the funeral food was served again at the wedding."},{"id":"112","who":"HAMLET","text":"He was a man, take him for all in all, I shall not look upon his like again.","themes":["kingship"],"note":"Hamlet's ideal of his father, the standard Claudius is measured against."},{"id":"154","who":"HAMLET","text":"foul deeds will rise, Though all the earth o'erwhelm them, to men's eyes.","themes":["corruption","fate"],"note":"Hamlet trusts that hidden crimes will come out."},{"id":"162","who":"LAERTES","text":"His greatness weigh'd, his will is not his own;","themes":["kingship","women"],"note":"A prince's marriage belongs to the state, not to him."},{"id":"169","who":"POLONIUS","text":"Give every man thine ear, but few thy voice: Take each man's censure, but reserve thy judgement.","themes":["appearance"],"note":"Polonius's cautious advice: listen, but give nothing away."},{"id":"169","who":"POLONIUS","text":"This above all: to thine own self be true; And it must follow, as the night the day, Thou canst not then be false to any man.","themes":["appearance"],"note":"Famous advice from a man who spends the play pretending and spying."},{"id":"201","who":"HAMLET","text":"So oft it chances in particular men That for some vicious mole of nature in them, As in their birth, wherein they are not guilty, Since nature cannot choose his origin, By their o'ergrowth of some complexion, Oft breaking down the pales and forts of reason; Or by some habit, that too much o'erleavens The form of plausive manners;—that these men, Carrying, I say, the stamp of one defect, Being Nature's livery or Fortune's star,— His virtues else,—be they as pure as grace, As infinite as man may undergo, Shall in the general censure take corruption From that particular fault.","themes":["action","corruption"],"note":"One flaw can spoil a noble man: often read as a hint of Hamlet's own."},{"id":"226","who":"MARCELLUS","text":"Something is rotten in the state of Denmark.","themes":["corruption","kingship"],"note":"The state itself is diseased."},{"id":"243","who":"GHOST","text":"Revenge his foul and most unnatural murder.","themes":["revenge"],"note":"The Ghost's command sets the plot going."},{"id":"249","who":"GHOST","text":"With all my imperfections on my head. O horrible!","themes":["death","revenge"],"note":"Murdered without confession, the old King suffers for his sins."},{"id":"249","who":"GHOST","text":"Taint not thy mind, nor let thy soul contrive Against thy mother aught; leave her to heaven,","themes":["revenge","women"],"note":"The limit on revenge: Gertrude is to be left to her conscience."},{"id":"251","who":"HAMLET","text":"O villain, villain, smiling damned villain! My tables. Meet it is I set it down, That one may smile, and smile, and be a villain! At least I am sure it may be so in Denmark.","themes":["appearance"],"note":"A smiling face can hide a murderer."},{"id":"295","who":"HAMLET","text":"There are more things in heaven and earth, Horatio, Than are dreamt of in your philosophy.","themes":["fate","truth"],"note":"Human reason cannot explain everything."},{"id":"295","who":"HAMLET","text":"To put an antic disposition on—","themes":["madness","appearance"],"note":"Hamlet plans to pretend madness, so we can never be sure."},{"id":"297","who":"HAMLET","text":"The time is out of joint. O cursed spite, That ever I was born to set it right.","themes":["action","revenge"],"note":"Hamlet resents the duty of revenge as soon as he accepts it."},{"id":"319","who":"POLONIUS","text":"By indirections find directions out.","themes":["appearance"],"note":"Polonius's method of spying: crooked ways to the truth."},{"id":"369","who":"POLONIUS","text":"brevity is the soul of wit","themes":["appearance"],"note":"Said by the most long-winded man in the play."},{"id":"410","who":"POLONIUS","text":"Though this be madness, yet there is method in't.","themes":["madness"],"note":"Even Polonius sees sense in Hamlet's madness."},{"id":"437","who":"HAMLET","text":"there is nothing either good or bad but thinking makes it so.","themes":["appearance","truth"],"note":"Perception shapes reality: a key idea for the whole play."},{"id":"433","who":"HAMLET","text":"Denmark's a prison.","themes":["kingship","corruption"],"note":"Hamlet feels trapped in Claudius's Denmark."},{"id":"455","who":"HAMLET","text":"What a piece of work is man, how noble in reason, how infinite in faculties, in form and moving, how express and admirable; in action how like an angel, in apprehension, how like a god: the beauty of the world, the paragon of animals. And yet, to me, what is this quintessence of dust?","themes":["death","action"],"note":"Humanity is godlike and yet, to Hamlet now, only dust."},{"id":"478","who":"HAMLET","text":"I am but mad north-north-west. When the wind is southerly, I know a hawk from a handsaw.","themes":["madness"],"note":"Hamlet hints to his spying friends that his madness is controlled."},{"id":"528","who":"HAMLET","text":"O what a rogue and peasant slave am I!","themes":["action"],"note":"Hamlet attacks himself for not acting."},{"id":"528","who":"HAMLET","text":"Is it not monstrous that this player here, But in a fiction, in a dream of passion, Could force his soul so to his own conceit","themes":["appearance","action"],"note":"An actor can feel more for a story than Hamlet seems to for his father."},{"id":"528","who":"HAMLET","text":"Am I a coward?","themes":["action"],"note":"Hamlet questions his own courage."},{"id":"528","who":"HAMLET","text":"Bloody, bawdy villain!","themes":["revenge"],"note":"A burst of rage, which Hamlet immediately mocks as mere words."},{"id":"528","who":"HAMLET","text":"The spirit that I have seen May be the devil,","themes":["fate","revenge","truth"],"note":"Doubt about the Ghost gives Hamlet a reason to test it."},{"id":"528","who":"HAMLET","text":"The play's the thing Wherein I'll catch the conscience of the King.","themes":["appearance","action","truth"],"note":"Hamlet will use theatre to reveal the truth."},{"id":"550","who":"CLAUDIUS","text":"How smart a lash that speech doth give my conscience!","themes":["appearance","corruption"],"note":"Claudius's first admission of guilt."},{"id":"554","who":"HAMLET","text":"To be, or not to be, that is the question:","themes":["death","action"],"note":"Is it better to live or to die?"},{"id":"554","who":"HAMLET","text":"To sleep, perchance to dream—ay, there's the rub,","themes":["death"],"note":"Fear of what comes after death stops us."},{"id":"554","who":"HAMLET","text":"The undiscover'd country, from whose bourn No traveller returns,","themes":["death"],"note":"Death as a country no one comes back from."},{"id":"554","who":"HAMLET","text":"Thus conscience does make cowards of us all,","themes":["action"],"note":"Thinking too much makes us afraid to act."},{"id":"570","who":"HAMLET","text":"Get thee to a nunnery. Why wouldst thou be a breeder of sinners?","themes":["women"],"note":"Hamlet's cruelty to Ophelia, and his disgust at sex and birth."},{"id":"576","who":"HAMLET","text":"God hath given you one face, and you make yourselves another.","themes":["women","appearance"],"note":"Women's make-up becomes a sign of falseness."},{"id":"578","who":"OPHELIA","text":"O, what a noble mind is here o'erthrown!","themes":["madness"],"note":"Ophelia's grief at Hamlet's apparent madness."},{"id":"582","who":"CLAUDIUS","text":"Madness in great ones must not unwatch'd go.","themes":["madness","kingship"],"note":"Claudius sees Hamlet as a danger to be watched."},{"id":"588","who":"HAMLET","text":"to hold as 'twere the mirror up to nature;","themes":["appearance"],"note":"Theatre should show the truth: what The Mousetrap will do."},{"id":"666","who":"GERTRUDE","text":"The lady protests too much, methinks.","themes":["women","appearance"],"note":"Gertrude's remark on the Player Queen's vows."},{"id":"737","who":"HAMLET","text":"Call me what instrument you will, though you can fret me, you cannot play upon me.","themes":["appearance"],"note":"Hamlet refuses to be manipulated by spies."},{"id":"752","who":"HAMLET","text":"I will speak daggers to her, but use none;","themes":["revenge","women"],"note":"Hamlet will wound his mother with words only."},{"id":"766","who":"CLAUDIUS","text":"O, my offence is rank, it smells to heaven;","themes":["corruption"],"note":"Claudius's guilt stinks like rotting flesh."},{"id":"766","who":"CLAUDIUS","text":"A brother's murder!","themes":["revenge","corruption"],"note":"Cain's crime: the first murder in the Bible."},{"id":"769","who":"HAMLET","text":"Now might I do it pat, now he is praying.","themes":["action","revenge"],"note":"Hamlet's best chance, and he refuses it."},{"id":"772","who":"CLAUDIUS","text":"My words fly up, my thoughts remain below. Words without thoughts never to heaven go.","themes":["appearance","truth"],"note":"Claudius's prayer is empty words."},{"id":"802","who":"HAMLET","text":"A bloody deed. Almost as bad, good mother, As kill a king and marry with his brother.","themes":["revenge","women"],"note":"Hamlet accuses Gertrude, testing what she knew."},{"id":"808","who":"HAMLET","text":"Here is your husband, like a mildew'd ear Blasting his wholesome brother.","themes":["corruption","kingship"],"note":"Claudius as a diseased ear of corn infecting his brother."},{"id":"833","who":"HAMLET","text":"Assume a virtue, if you have it not.","themes":["appearance"],"note":"Acting virtuous may become real virtue."},{"id":"833","who":"HAMLET","text":"I must be cruel, only to be kind:","themes":["revenge","women"],"note":"Hamlet justifies his harsh words to his mother."},{"id":"839","who":"HAMLET","text":"For 'tis the sport to have the enginer Hoist with his own petard,","themes":["revenge","fate"],"note":"Hamlet looks forward to turning the plotters' plan against them."},{"id":"892","who":"HAMLET","text":"Your worm is your only emperor for diet.","themes":["death","kingship"],"note":"Death makes kings food for worms."},{"id":"938","who":"HAMLET","text":"How all occasions do inform against me, And spur my dull revenge.","themes":["action","revenge"],"note":"Hamlet sees reproaches to his delay everywhere."},{"id":"938","who":"HAMLET","text":"Rightly to be great Is not to stir without great argument, But greatly to find quarrel in a straw When honour's at the stake.","themes":["action"],"note":"Honour justifies fighting over almost nothing."},{"id":"938","who":"HAMLET","text":"My thoughts be bloody or be nothing worth.","themes":["revenge","action"],"note":"Another vow, though still only of thoughts."},{"id":"971","who":"CLAUDIUS","text":"When sorrows come, they come not single spies, But in battalions.","themes":["fate","kingship"],"note":"Claudius feels his troubles closing in."},{"id":"990","who":"CLAUDIUS","text":"There's such divinity doth hedge a king,","themes":["kingship","appearance"],"note":"Ironic from a man who killed a king."},{"id":"995","who":"LAERTES","text":"I dare damnation.","themes":["revenge"],"note":"Laertes will risk his soul for revenge, unlike Hamlet."},{"id":"1011","who":"OPHELIA","text":"There's rosemary, that's for remembrance; pray love, remember.","themes":["madness","death"],"note":"Ophelia's flowers carry meanings."},{"id":"1070","who":"LAERTES","text":"To cut his throat i' th' church.","themes":["revenge"],"note":"Laertes would murder anywhere: revenge without limits."},{"id":"1078","who":"GERTRUDE","text":"There is a willow grows aslant a brook, That shows his hoary leaves in the glassy stream.","themes":["death","women"],"note":"Gertrude's description of Ophelia's death."},{"id":"1168","who":"HAMLET","text":"Alas, poor Yorick. I knew him, Horatio, a fellow of infinite jest, of most excellent fancy.","themes":["death"],"note":"Hamlet remembers the jester whose skull he holds."},{"id":"1177","who":"HAMLET","text":"Imperious Caesar, dead and turn'd to clay, Might stop a hole to keep the wind away.","themes":["death","kingship"],"note":"Even the greatest men end as dust."},{"id":"1187","who":"LAERTES","text":"A minist'ring angel shall my sister be When thou liest howling.","themes":["death","women"],"note":"Laertes defends his sister against the priest."},{"id":"1201","who":"HAMLET","text":"I lov'd Ophelia; forty thousand brothers Could not, with all their quantity of love, Make up my sum.","themes":["women"],"note":"Hamlet's declaration of love, too late."},{"id":"1206","who":"HAMLET","text":"The cat will mew, and dog will have his day.","themes":["fate"],"note":"Everyone will have their turn."},{"id":"1216","who":"HAMLET","text":"There's a divinity that shapes our ends, Rough-hew them how we will.","themes":["fate"],"note":"Hamlet now believes heaven shapes events."},{"id":"1296","who":"HAMLET","text":"There's a special providence in the fall of a sparrow.","themes":["fate","death"],"note":"Even a sparrow's death is part of God's plan."},{"id":"1296","who":"HAMLET","text":"The readiness is all.","themes":["fate","action"],"note":"Hamlet's new calm about death."},{"id":"1353","who":"LAERTES","text":"I am justly kill'd with mine own treachery.","themes":["revenge"],"note":"Laertes recognises he is caught in his own trap."},{"id":"1365","who":"HAMLET","text":"Here, thou incestuous, murderous, damned Dane,","themes":["revenge","kingship"],"note":"The revenge is finally done."},{"id":"1371","who":"HAMLET","text":"Absent thee from felicity awhile, And in this harsh world draw thy breath in pain, To tell my story.","themes":["death"],"note":"Hamlet wants his story told truly."},{"id":"1375","who":"HAMLET","text":"The rest is silence.","themes":["death"],"note":"Hamlet's last words."},{"id":"1377","who":"HORATIO","text":"Now cracks a noble heart. Good night, sweet prince, And flights of angels sing thee to thy rest.","themes":["death"],"note":"Horatio's farewell to Hamlet."}]};
const EX={"intro":["Prince Hamlet comes home from university for his father's funeral and finds his uncle Claudius on the throne, married to his mother Gertrude less than two months later. Grieving and disgusted, he wishes he were dead.","On the castle battlements, a ghost in his father's shape tells Hamlet that Claudius poisoned him, and demands revenge. Hamlet swears to obey, then pretends to be mad while he decides whether the Ghost can be trusted.","The court spies on Hamlet, and Hamlet tests the King with a play. His hesitation, and the deaths it leads to, drive the play to a final scene in which almost everyone dies."],"timeline":[{"s":"a1s1","t":"The Ghost appears on the battlements","id":34},{"s":"a1s2","t":"Claudius, newly crowned, refuses to let Hamlet leave","id":90},{"s":"a1s2","t":"Hamlet's first soliloquy: disgust at his mother's marriage","id":95},{"s":"a1s3","t":"Polonius orders Ophelia to reject Hamlet","id":186},{"s":"a1s5","t":"The Ghost reveals the murder and demands revenge","id":247},{"s":"a1s5","t":"Hamlet plans an 'antic disposition'","id":295},{"s":"a2s1","t":"Hamlet appears, wild, in Ophelia's room","id":337},{"s":"a2s2","t":"Rosencrantz and Guildenstern are hired to spy","id":344},{"s":"a2s2","t":"The actors arrive; Hamlet plans The Mousetrap","id":528},{"s":"a3s1","t":"'To be, or not to be'","id":554},{"s":"a3s1","t":"Hamlet rejects Ophelia: 'Get thee to a nunnery'","id":570},{"s":"a3s2","t":"The play-within-the-play; Claudius rises","id":683},{"s":"a3s3","t":"Hamlet spares Claudius at prayer","id":769},{"s":"a3s4","t":"Hamlet kills Polonius behind the arras","id":794},{"s":"a4s3","t":"Hamlet is sent to England to be killed","id":913},{"s":"a4s4","t":"Hamlet sees Fortinbras's army and vows to act","id":938},{"s":"a4s5","t":"Ophelia goes mad; Laertes returns for revenge","id":987},{"s":"a4s6","t":"Hamlet escapes with the pirates","id":1033},{"s":"a4s7","t":"Claudius and Laertes plot the fencing match","id":1071},{"s":"a4s7","t":"Ophelia drowns","id":1078},{"s":"a5s1","t":"Hamlet holds Yorick's skull","id":1168},{"s":"a5s1","t":"Hamlet and Laertes fight in Ophelia's grave","id":1192},{"s":"a5s2","t":"The fencing match: poisoned sword and cup","id":1345},{"s":"a5s2","t":"Hamlet kills Claudius and dies; Fortinbras arrives","id":1375}],"irony":{"82":"Claudius calls Hamlet 'my son', not knowing Hamlet will soon learn he murdered his father.","90":"Claudius lectures Hamlet that grief for fathers is natural and must end, when he himself killed the father.","169":"Polonius's 'to thine own self be true' comes from a man who lives by pretence and spying.","361":"Gertrude guesses the real cause of Hamlet's distemper is 'his father's death', closer to the truth than she knows.","549":"Polonius says we 'sugar o'er the devil himself' with holy looks, not knowing the King beside him is doing just that.","666":"Gertrude criticises the Player Queen for protesting too much about never remarrying.","769":"Hamlet spares Claudius to avoid sending him to heaven, but Claudius has not managed to pray at all.","799":"Hamlet hopes the man behind the arras is the King; it is Polonius.","990":"Claudius claims a king is protected by divine power, though he murdered a king himself.","1069":"Claudius asks whether Laertes truly loved his father, the man Claudius is using his love for.","1189":"Gertrude hoped to strew flowers on Ophelia's bride-bed, not her grave.","1323":"Claudius toasts Hamlet's health with the poisoned cup.","1334":"Gertrude ignores the King's order not to drink, and the poisoned wine meant for her son kills her."},"devices":{"disease":"Disease and poison","garden":"Weeds and gardens","theatre":"Acting and theatre","ear":"Ears and listening","grave":"Dust, earth and the grave","heaven":"Heaven and hell"},"dev":{"51":[["disease","The Ghost is a sign of 'some strange eruption', like a disease breaking out on the skin of the state.","eruption to our state"]],"89":[["theatre","Mourning clothes are 'actions that a man might play': Hamlet already thinks in terms of acting.","actions that a man might play"]],"95":[["garden","The world as 'an unweeded garden' taken over by rank weeds.","unweeded garden"]],"162":[["garden","Love as a spring flower eaten by the canker worm before it opens.","The canker galls the infants of the spring"]],"201":[["disease","A single 'vicious mole' of nature spoils a whole reputation.","vicious mole of nature"]],"226":[["disease","The state of Denmark is rotting from inside.","Something is rotten"]],"247":[["ear","The 'whole ear of Denmark' has been poisoned with a lie, as the King's ear was poisoned.","the whole ear of Denmark"]],"249":[["ear","Poison poured into the 'porches of my ears'.","porches of my ears"],["disease","The poison curdles the blood and covers the body in a leper's crust.","lazar-like"],["heaven","Lust 'though to a radiant angel link'd' will 'prey on garbage'.","radiant angel"]],"295":[["theatre","Hamlet plans to 'put an antic disposition on' like a costume.","antic disposition"]],"455":[["grave","Man, the 'paragon of animals', is only a 'quintessence of dust'.","quintessence of dust"]],"528":[["theatre","An actor's false tears shame Hamlet's real grief.","this player here"],["heaven","Hamlet is urged on 'by heaven and hell', and fears the Ghost may be the devil.","by heaven and hell"]],"550":[["theatre","Claudius compares his words to a harlot's painted cheek.","The harlot's cheek"]],"554":[["grave","Death as a sleep, and the afterlife as an 'undiscover'd country'.","undiscover'd country"]],"588":[["theatre","Acting should 'hold the mirror up to nature'.","mirror up to nature"]],"671":[["theatre","The Mousetrap: a play used as a trap.","The Mousetrap"]],"766":[["disease","Claudius's crime 'smells to heaven' like rotting flesh.","smells to heaven"],["heaven","He cannot pray: 'O bosom black as death!'","bosom black as death"]],"769":[["heaven","Hamlet wants Claudius's soul to be 'as damn'd and black as hell'.","damn'd and black"]],"808":[["disease","Claudius is 'a mildew'd ear blasting his wholesome brother'.","mildew'd ear"]],"831":[["disease","Sin covered over is an ulcer that infects unseen.","ulcerous place"],["garden","Do not 'spread the compost on the weeds'.","compost on the weeds"]],"880":[["disease","'Diseases desperate grown by desperate appliance are reliev'd.'","Diseases desperate grown"]],"892":[["grave","The worm is the only emperor: kings are food for worms.","Your worm is your only emperor"]],"913":[["disease","Hamlet rages 'like the hectic in my blood'.","hectic in my blood"]],"932":[["disease","Pointless war is 'th'imposthume of much wealth and peace'.","imposthume"]],"971":[["ear","Gossips 'infect his ear with pestilent speeches'.","infect his ear"]],"1121":[["grave","A skull that 'could sing once', thrown about like Cain's jawbone.","That skull had a tongue in it"]],"1168":[["grave","Yorick's skull: the jester's face reduced to bone.","Alas, poor Yorick"]],"1177":[["grave","Caesar's dust may 'stop a hole to keep the wind away'.","Imperious Caesar"]],"1360":[["disease","The poisoned sword: 'No medicine in the world can do thee good.'","No medicine in the world"]]},"stage":{"platform":"The battlements","room":"A room in the castle","hall":"A hall in the castle","house":"Polonius's house","plain":"A plain in Denmark","churchyard":"The churchyard"},"why":{"0":"Even the sceptic believes: the Ghost must be taken seriously.","1":"Sets the Ghost against a background of political murder and omens.","2":"Hamlet's first words establish his wit, his anger and his habit of speaking in asides.","3":"The son/sun pun shows his resentment of Claudius's fatherly claims.","4":"Begins the theme of seeming versus being.","5":"Hamlet claims an inner truth no performance can show: the root of his isolation.","6":"Shows his despair before he knows of any murder.","7":"His depression drains the world of value.","8":"The first image of Denmark as diseased and overgrown.","9":"His disgust with his mother spreads to all women.","10":"Silence and inaction are forced on him from the start.","11":"Bitter humour as a weapon against the court.","12":"His idealised father is the standard by which he judges Claudius.","13":"A prediction the play fulfils: hidden crimes come to light.","14":"Royal birth limits personal freedom, for Hamlet and for Ophelia.","15":"Polonius's cautious, self-protective way of living.","16":"Ironic advice from a man of masks; a key line on identity.","17":"Often read as Shakespeare's comment on Hamlet's own tragic flaw.","18":"The state is corrupted, a key image for the whole play.","19":"The command that starts the revenge plot.","20":"Murder robbed the King of the chance to repent: a theme that returns at the prayer scene.","21":"The limits of revenge: Gertrude is to be spared.","22":"Appearances can hide evil: Claudius smiles.","23":"Hamlet's sense that the world is stranger than reason allows.","24":"His feigned madness makes all his later behaviour ambiguous.","25":"He sees revenge as a curse, not a calling.","26":"Polonius's method of spying sums up the court.","27":"Comic irony from the play's least brief speaker.","28":"Even his enemies notice sense in Hamlet's madness.","29":"Perception shapes reality: the world is what we make of it.","30":"Hamlet feels trapped in Claudius's Denmark.","31":"The glory and emptiness of humanity in one speech.","32":"Hamlet signals that his madness is under control.","33":"Self-hatred at his own inaction.","34":"An actor's false passion shames Hamlet's real one.","35":"He questions his own courage directly.","36":"Rage that he immediately sees as only words.","37":"His doubt about the Ghost gives him a reason to delay and a plan.","38":"Theatre becomes a tool to reveal the truth.","39":"The audience's first proof of Claudius's guilt.","40":"The most famous question in drama: is life worth living?","41":"Fear of the afterlife stops people choosing death.","42":"Death as unknown territory: the heart of his fear.","43":"Thinking itself makes people afraid to act.","44":"His cruelty to Ophelia and disgust with sex and birth.","45":"Women's make-up as a symbol of deceit.","46":"Shows how Hamlet looked to those who loved him.","47":"Claudius sees Hamlet as a political threat.","48":"Shakespeare's view of what theatre should do.","49":"Ironic: Gertrude may be judging herself.","50":"Hamlet refuses to be manipulated.","51":"He limits his revenge on Gertrude to words.","52":"Claudius's guilt described as a smell rising to heaven.","53":"Links Claudius to Cain, the first murderer.","54":"Hamlet's clearest chance to kill Claudius, refused.","55":"Reveals that Claudius was not truly praying.","56":"Hamlet accuses Gertrude and tests her knowledge.","57":"Claudius as a disease that destroyed his brother.","58":"Acting virtue may lead to real virtue.","59":"Hamlet justifies his harshness to his mother.","60":"Foreshadows the ending, where plotters die by their own plots.","61":"Death makes kings food for worms.","62":"Hamlet sees everything as a reproach to his delay.","63":"Honour can make even small quarrels great.","64":"A vow of bloody thoughts, still not deeds.","65":"Claudius feels his crimes catching up with him.","66":"Claudius claims divine protection though he killed a king.","67":"Laertes will risk damnation; Hamlet would not.","68":"Ophelia's flowers turn grief into symbolic order.","69":"Laertes would ignore even sanctuary: revenge without limits.","70":"A beautiful, ambiguous account of Ophelia's death.","71":"Death becomes personal in the skull of a man Hamlet loved.","72":"Even the greatest men end as dust.","73":"Laertes defends his sister's innocence against the church.","74":"Hamlet's love for Ophelia, declared only when she is dead.","75":"Everyone will have their turn: a hint at fate.","76":"Hamlet now believes heaven shapes events.","77":"Every death, even a sparrow's, is part of God's plan.","78":"Hamlet's acceptance of whatever comes.","79":"Laertes recognises he is caught in his own trap.","80":"The revenge is finally completed.","81":"Hamlet wants his story told so his name is not wounded.","82":"Hamlet's last words, ending a play full of talk.","83":"Horatio's farewell gives Hamlet a gentle, heavenly ending."},"arc":{"Hamlet's resolve":[1,2,2,5,10,8,7,3,9,6,7,6,5,4,9,9,8,8,6,10],"Hamlet's action":[0,0,0,1,2,2,3,2,6,3,8,4,3,2,2,2,5,5,4,10]},"arcnote":"Hamlet's resolve leaps when the Ghost speaks and again after the play, but his actions lag behind. He spares Claudius at prayer, kills Polonius on impulse, then is shipped away. Only in the last scene, calm and ready, do resolve and action finally meet.","context":[["Date","Probably written around 1599 to 1601, soon after Julius Caesar, which Horatio remembers in the first scene."],["Three texts","Hamlet survives in three early versions: a short First Quarto (1603), a long Second Quarto (1604 to 1605) and the First Folio (1623). Modern editions, like this one, combine the Second Quarto and the Folio, which is why the play is so long."],["Sources","The story comes from a medieval Danish chronicle by Saxo Grammaticus, retold in French by François de Belleforest. An earlier English Hamlet play, now lost, was on stage in the 1580s."],["Revenge tragedy","Elizabethan audiences loved revenge plays, especially Thomas Kyd's The Spanish Tragedy, with its ghost, its play-within-a-play and its hesitating revenger. Hamlet uses these conventions and questions them."],["Ghosts and purgatory","Catholics believed souls could suffer in purgatory before reaching heaven. Protestant England had rejected purgatory, and many Protestants thought ghosts were devils in disguise. Hamlet's doubts about the Ghost reflect this debate."],["Wittenberg","Hamlet and Horatio study at Wittenberg, the university of Martin Luther, where the Protestant Reformation began: a place of questioning and conscience."],["Marrying a brother's widow","The Church treated marriage to a dead brother's wife as incest, based on Leviticus. Henry VIII used the same rule to end his marriage to Catherine of Aragon, his brother's widow."],["An elected king","Denmark's king was chosen by election, which is how Claudius 'popp'd in between th'election and my hopes'. In 1600, the ageing Elizabeth I had no heir, and the succession was an anxious subject in England."],["Melancholy","Elizabethans saw melancholy as a disease caused by too much black bile, linked with scholars, sadness and strange behaviour. Timothy Bright's Treatise of Melancholy (1586) describes many of Hamlet's symptoms."],["The boy players","Rosencrantz's 'little eyases' are the boy actors' companies who were rivals to adult companies like Shakespeare's around 1600."],["Duelling","Rapier fencing was a fashionable Italian and French art among Elizabethan gentlemen. Betting on a match, as Claudius does, was common."],["Hamnet","Shakespeare's only son, Hamnet, died in 1596 aged eleven, a few years before the play. Many readers wonder whether the name and the play's grief are connected, though there is no evidence either way."]],"critics":{"action":[["Johann Wolfgang von Goethe, Wilhelm Meister's Apprenticeship (1795)","Paraphrased: Hamlet is a sensitive, noble soul given a great deed he is not strong enough to carry, like an oak tree planted in a delicate vase that breaks it."],["Samuel Taylor Coleridge, lectures (1811 to 1819)","Paraphrased: Hamlet thinks so much that he loses the power to act; his mind is too active for the world of deeds."],["A. C. Bradley, Shakespearean Tragedy (1904)","Paraphrased: Hamlet's delay is not cowardice or over-thinking but deep melancholy brought on by the shock of his mother's remarriage, which drains his will."]],"madness":[["Elaine Showalter, 'Representing Ophelia' (1985)","Paraphrased: Ophelia has been read and painted for centuries as a model of female madness, and each age has shaped her to fit its own ideas about women."],["Samuel Johnson, notes on Hamlet (1765)","Paraphrased: Hamlet's pretended madness has no clear purpose in the plot, and he treats Ophelia with needless cruelty."]],"women":[["Sigmund Freud and Ernest Jones (1900 and 1949)","Paraphrased: Hamlet cannot kill Claudius because Claudius has done what Hamlet secretly wished to do, kill his father and take his mother: a psychoanalytic reading of the delay."],["Feminist critics","Paraphrased: Gertrude and Ophelia are seen almost entirely through male eyes; Hamlet's disgust at women says more about him than about them."]],"appearance":[["T. S. Eliot, 'Hamlet and His Problems' (1919)","Paraphrased: Hamlet's feelings are bigger than anything in the plot can explain, so the play fails to find a clear outward form for its emotion."],["Harold Bloom, Shakespeare: The Invention of the Human (1998)","Paraphrased: Hamlet is the most self-aware character in literature, always watching himself think and act."]],"kingship":[["Jan Kott, Shakespeare Our Contemporary (1964)","Paraphrased: Elsinore is a police state full of spies and informers, and Hamlet is a young man trapped in political machinery."],["G. Wilson Knight, The Wheel of Fire (1930)","Paraphrased: Claudius is a capable king and the court is healthy until Hamlet, obsessed with death, brings destruction into it."]],"death":[["Stephen Greenblatt, Hamlet in Purgatory (2001)","Paraphrased: the Ghost speaks from purgatory, which Protestant England had abolished; the play is haunted by the loss of old ways of mourning and remembering the dead."]],"fate":[["Critics of the last act","Paraphrased: Hamlet's calm in Act 5 can be read as Christian trust in providence or as a weary fatalism that simply lets events happen."]]},"insults":[{"id":83,"f":"A little more than kin, and less than kind","who":"Hamlet","n":"His first insult to Claudius is a whispered pun."},{"id":95,"f":"Hyperion to a satyr","who":"Hamlet","n":"His father was a sun god, his uncle a lustful goat-man."},{"id":249,"f":"that incestuous, that adulterate beast","who":"Ghost","n":"The Ghost reduces Claudius to an animal."},{"id":251,"f":"O villain, villain, smiling damned villain!","who":"Hamlet","n":"Hamlet's rage at a man who smiles and murders."},{"id":395,"f":"You are a fishmonger","who":"Hamlet","n":"A mad joke and perhaps a hint that Polonius is pimping his daughter."},{"id":409,"f":"a plentiful lack of wit","who":"Hamlet","n":"Hamlet insults Polonius by pretending to read a book."},{"id":415,"f":"These tedious old fools","who":"Hamlet","n":"Said once Polonius has gone."},{"id":481,"f":"That great baby you see there","who":"Hamlet","n":"Mocking Polonius to his spying friends."},{"id":528,"f":"Bloody, bawdy villain!","who":"Hamlet","n":"A string of insults at Claudius, which Hamlet then mocks as mere words."},{"id":528,"f":"A dull and muddy-mettled rascal","who":"Hamlet","n":"Hamlet insults himself."},{"id":576,"f":"You jig, you amble, and you lisp","who":"Hamlet","n":"Hamlet attacks all women through Ophelia."},{"id":804,"f":"Thou wretched, rash, intruding fool, farewell!","who":"Hamlet","n":"Hamlet's epitaph for Polonius, whom he has just killed."},{"id":812,"f":"A cutpurse of the empire and the rule","who":"Hamlet","n":"Claudius as a thief who stole the crown."},{"id":814,"f":"A king of shreds and patches","who":"Hamlet","n":"Claudius as a clown in rags."},{"id":870,"f":"that soaks up the King's countenance","who":"Hamlet","n":"Rosencrantz the sponge."},{"id":1187,"f":"churlish priest","who":"Laertes","n":"Laertes curses the priest who limits Ophelia's funeral."},{"id":1238,"f":"'tis a chough","who":"Hamlet","n":"Osric as a chattering jackdaw with lots of land."},{"id":1365,"f":"thou incestuous, murderous, damned Dane","who":"Hamlet","n":"Hamlet's last words to Claudius sum up all his crimes."}],"pronouns":[{"id":84,"f":"How is it that the clouds still hang on you?","n":"Claudius uses polite 'you' to Hamlet in front of the court, but calls him 'my son'."},{"id":86,"f":"Good Hamlet, cast thy nighted colour off","n":"Gertrude uses the loving 'thy' to her son."},{"id":239,"f":"So art thou to revenge, when thou shalt hear.","n":"The Ghost uses 'thou' as a father and a king giving orders."},{"id":782,"f":"Hamlet, thou hast thy father much offended.","n":"Gertrude scolds with a mother's 'thou'."},{"id":783,"f":"Mother, you have my father much offended.","n":"Hamlet answers with the cold, formal 'you'."},{"id":1192,"f":"The devil take thy soul!","n":"Laertes uses 'thy' as an insult to Hamlet."},{"id":1367,"f":"Exchange forgiveness with me, noble Hamlet.","n":"Laertes turns to the respectful 'noble Hamlet' as he dies, then forgives with 'thee'."}],"predict":{"a1s1":["The Ghost speaks to Horatio","They tell young Hamlet","They keep it secret"],"a1s2":["Hamlet goes back to Wittenberg","Hamlet sees the Ghost","Hamlet challenges Claudius"],"a1s3":["Ophelia obeys her father","Ophelia runs away with Hamlet","Laertes stays in Denmark"],"a1s4":["The Ghost speaks to Hamlet","Hamlet's friends stop him","The Ghost attacks"],"a1s5":["Hamlet kills Claudius at once","Hamlet pretends to be mad","Hamlet tells his mother"],"a2s1":["Polonius tells the King","Ophelia goes to Hamlet","Polonius forbids Hamlet the house"],"a2s2":["Claudius confesses","The play reveals Claudius's guilt","Hamlet leaves Denmark"],"a3s1":["The play goes ahead","Hamlet is arrested","Ophelia tells Hamlet she was used"],"a3s2":["Hamlet kills Claudius tonight","Hamlet speaks to his mother","Claudius flees"],"a3s3":["Hamlet kills Polonius","Gertrude confesses","Claudius is warned"],"a3s4":["Hamlet is sent away","Gertrude tells Claudius everything","Hamlet is executed"],"a4s1":["Hamlet hides the body","Hamlet gives himself up","Hamlet escapes"],"a4s2":["Hamlet tells the King where the body is","Hamlet runs away","Hamlet confesses"],"a4s3":["Hamlet arrives in England","Hamlet meets Fortinbras's army","Hamlet escapes at once"],"a4s4":["Hamlet returns to kill Claudius","Hamlet sails to England","Fortinbras attacks Denmark"],"a4s5":["Laertes kills Hamlet","Hamlet writes from the sea","Ophelia recovers"],"a4s6":["Claudius learns Hamlet is back","Horatio warns the King","Hamlet sails on to England"],"a4s7":["Ophelia's funeral","Laertes challenges Hamlet openly","Hamlet confronts Claudius"],"a5s1":["The fencing match","Hamlet leaves Denmark","Laertes confesses the plot"]},"contrast":[{"t":"Hamlet and Laertes","pts":["Both lose a father to violence and seek revenge.","Laertes acts at once and dares damnation; Hamlet doubts and delays.","Laertes is easily used by Claudius; Hamlet is hard to fool but cannot act."],"ids":[995,938]},{"t":"Hamlet and Fortinbras","pts":["Both are sons of dead kings who have lost what should be theirs.","Fortinbras turns his anger into action for 'an eggshell'.","Fortinbras ends the play as king; Hamlet gives him his dying vote."],"ids":[938,1385]},{"t":"Old Hamlet and Claudius","pts":["Hamlet sees his father as a god and Claudius as a satyr.","Old Hamlet fought openly; Claudius poisons in secret.","Both brothers are seen through Hamlet's eyes, so the contrast may be exaggerated."],"ids":[808,766]},{"t":"Gertrude and Ophelia","pts":["Both are loved by Hamlet and attacked by him for their sex.","Both are controlled by the men around them.","Ophelia goes mad and dies; Gertrude dies by disobeying her husband for once."],"ids":[570,1078]}],"keyfacts":[["Full title","The Tragedy of Hamlet, Prince of Denmark"],["Written","About 1599 to 1601; printed in 1603 (First Quarto), 1604 to 1605 (Second Quarto) and in the First Folio of 1623"],["Genre","Tragedy: a revenge tragedy"],["Setting","Elsinore, the royal castle of Denmark, with one scene on a plain near the coast"],["Time","Roughly the late Middle Ages, though the play never fixes a date"],["Protagonist","Prince Hamlet"],["Antagonist","King Claudius, his uncle and stepfather"],["Inciting incident","The Ghost tells Hamlet his father was murdered by Claudius"],["Rising action","Hamlet's pretended madness, the spying, and the play-within-the-play"],["Turning point","Hamlet kills Polonius instead of Claudius"],["Climax","The fencing match, where Gertrude, Laertes, Claudius and Hamlet all die"],["Length","Shakespeare's longest play, about 3,800 lines in this text"],["Soliloquies","Hamlet speaks seven, the heart of the play's inner drama"]],"analysis":{"HAMLET":["At the start Hamlet is a grieving student, sharp-tongued and full of disgust at his mother's quick remarriage. Before the Ghost appears he already wishes he were dead and sees the world as 'an unweeded garden'.","The Ghost gives him a clear duty, but he responds with thought: he pretends to be mad, doubts the Ghost, and tests the King with a play. His soliloquies turn the revenge plot into questions about death, conscience and what a man is.","When he does act, it is on impulse: he kills Polonius, sends Rosencrantz and Guildenstern to their deaths and fights Laertes in a grave. He can be cruel, especially to Ophelia and Gertrude.","After his sea voyage he is calmer, trusting that 'there's a divinity that shapes our ends'. He kills Claudius only when the King's treachery is exposed, and dies asking Horatio to tell his story."],"CLAUDIUS":["Claudius is a smooth, intelligent politician. His first speech balances grief and joy and manages the court, the Norwegian threat and Laertes' request with confidence.","He has a conscience. Polonius's words 'lash' it, and alone he admits his 'offence is rank' and tries to pray. But he will not give up the crown or the Queen.","Under pressure he becomes ruthless: he orders Hamlet's death in England, then plots with Laertes using a sharp sword, poison and a poisoned cup. His own plots kill him."],"GERTRUDE":["Gertrude remarried very quickly, and Hamlet and the Ghost see this as betrayal. The play never makes clear whether she knew about the murder; her surprise at 'As kill a king?' suggests she did not.","She loves her son and is shaken when he shows her the 'black and grained spots' in her soul, but she stays with Claudius.","At the end she drinks from the poisoned cup despite Claudius's order, possibly guessing the truth, and her dying words warn Hamlet: 'The drink, the drink!'"],"POLONIUS":["Polonius is the King's chief adviser and a fussy, long-winded father. His advice to Laertes sounds wise but is mainly about appearances.","He loves spying: on his son through Reynaldo, on Hamlet through Ophelia, and finally on Hamlet and Gertrude. He is sure Hamlet is mad for love.","Hiding behind the arras, he is killed by mistake. His death sets off Ophelia's madness and Laertes' revenge."],"OPHELIA":["Ophelia is a loving, obedient daughter who rejects Hamlet because her father and brother tell her to. She has few words of her own.","She is used as bait to spy on Hamlet, and he turns on her with cruel words about women and marriage. Her speech 'O, what a noble mind is here o'erthrown' shows her love for him.","After her father's death she goes truly mad, singing songs of death and lost love and handing out flowers. She drowns, perhaps by accident, perhaps not."],"LAERTES":["Laertes is a young courtier who lectures his sister on caution and goes back to France.","When his father is killed he returns at once with a mob, ready to 'dare damnation' for revenge: the kind of revenger Hamlet is not.","Claudius easily turns him into a tool. He poisons his own sword, is killed by it, and dies asking Hamlet's forgiveness and naming the King."],"HORATIO":["Horatio is Hamlet's loyal friend from Wittenberg, a calm, sceptical scholar who at first does not believe in the Ghost.","Hamlet trusts him completely and praises him as a man who is 'not passion's slave'.","He offers to die with Hamlet but agrees to live to tell his story truly."]},"motifs":[["Poison and disease","Old Hamlet is poisoned through the ear, Denmark is 'rotten', sin is an ulcer, and the play ends with a poisoned sword and cup.",[18,57,52]],["Incest and a tainted marriage","Hamlet and the Ghost call Gertrude's marriage to her husband's brother incest, and the word returns in Hamlet's last attack on Claudius. Sexual disgust colours Hamlet's view of his mother and of Ophelia.",[11,56,80]],["Acting and seeming","Hamlet rejects 'seems', puts on madness, coaches actors and uses a play to catch the King, while everyone else performs a role.",[4,24,38]],["Spying and watching","Polonius spies on Laertes, Claudius and Polonius spy on Hamlet, and Hamlet watches Claudius during the play.",[26,47,50]],["Death and the grave","From suicide to skulls, the play keeps returning to what happens to the body and soul after death.",[40,42,71]],["Ears and listening","Poison in the ear, lies poured into 'the whole ear of Denmark', and gossip that infects Laertes' ear.",[19,65,13]],["Thinking and doing","Hamlet's many soliloquies question why he thinks so much and acts so little.",[43,62,78]]],"symbols2":[["Yorick's skull","Death made personal: a face Hamlet once kissed is now bone. It reminds him that everyone, even Alexander, ends as dust."],["The Ghost","The past demanding to be remembered. It may also stand for the uncertainty of the afterlife and of truth itself."],["Ophelia's flowers","Each has a meaning: rosemary for remembrance, rue for sorrow. They turn her grief into a strange kind of order."],["The poisoned cup","Claudius's crime returning to him: the poison he used on his brother kills his wife and then himself."],["The recorder","Manipulation: Hamlet refuses to be played like an instrument by his spying friends."],["The unweeded garden","Denmark and the world gone to seed, overrun by things 'rank and gross'."]],"bigq":[["Why does Hamlet delay?",["He doubts the Ghost and needs proof","He thinks too much: 'conscience does make cowards of us all'","He is too depressed to act","He wants Claudius damned, not just dead"],[37,43,7,54]],["Is Hamlet really mad?",["He announces that he will pretend","He tells his spies he is only mad 'north-north-west'","His behaviour to Ophelia and at the grave is wild","Gertrude and Claudius disagree about it"],[24,32,46,47]],["Is Claudius a villain or a good king?",["He murdered his brother for the crown and the Queen","He rules calmly and deals well with Norway","He feels real guilt but will not repent","He plots Hamlet's death twice"],[53,52,55,65]],["How guilty is Gertrude?",["She married her husband's murderer very quickly","She seems not to know about the murder","She is shaken by Hamlet's accusations","She dies after disobeying Claudius"],[9,56,57,49]],["How does Hamlet treat women?",["He condemns his mother's sexuality","He is cruel to Ophelia","He sees make-up and marriage as false","He claims at the grave he loved Ophelia"],[9,44,45,74]],["Does Hamlet change by the end?",["He comes to trust providence","He no longer agonises in soliloquies","He kills Claudius only by chance","He still wants his story told and his name cleared"],[76,78,80,81]]],"symbols":{"Poison":"\\bpoison","Ears":"\\bears?\\b","Death and the grave":"\\bgraves?\\b|\\bdeath\\b|\\bdust\\b|\\bskull","Heaven and hell":"\\bheaven|\\bhell\\b","Rot and disease":"\\brott|\\bulcer|\\bdisease|\\bsick","Acting and playing":"\\bplay(er|ers|ed|ing)?\\b|\\bact(s|ion)?\\b"},"stagerules":[["platform","platform"],["churchyard","churchyard"],["plain","plain"],["polonius","house"],["hall","hall"],["room|castle","room"]],"solo":{"95":1,"251":1,"528":1,"554":1,"752":1,"766":1,"769":1,"938":1},"iago":[["a1s5","Swears to remember the Ghost and sweep to revenge 'with wings as swift as meditation'."],["a1s5","Decides to put on an 'antic disposition' instead of acting at once."],["a2s2","Doubts the Ghost: it may be the devil. Plans a play to test the King."],["a3s1","Wonders whether it is better to live or die, and blames thinking for making cowards of us all."],["a3s2","The Mousetrap works: Claudius rises. Hamlet will 'take the ghost's word for a thousand pound'."],["a3s3","Finds Claudius praying and spares him, so as to catch him in sin later."],["a3s4","Kills Polonius, thinking he is the King. The Ghost returns to 'whet thy almost blunted purpose'."],["a4s3","Is shipped to England without striking a blow."],["a4s4","Shamed by Fortinbras's army: 'My thoughts be bloody, or be nothing worth.'"],["a4s6","Escapes on a pirate ship and returns to Denmark (reported)."],["a5s2","Reveals he sent Rosencrantz and Guildenstern to their deaths, and asks if it is not 'perfect conscience' to kill Claudius."],["a5s2","Accepts the challenge: 'the readiness is all'."],["a5s2","Kills Claudius with the poisoned sword and the poisoned cup."]],"rel":{"1":[["GHOST","CLAUDIUS","hate"],["CLAUDIUS","HAMLET","deceive"],["HAMLET","GERTRUDE","hate"],["HORATIO","HAMLET","love"],["LAERTES","OPHELIA","love"],["POLONIUS","OPHELIA","trust"],["HAMLET","OPHELIA","love"],["HAMLET","GHOST","trust"]],"2":[["CLAUDIUS","ROSENCRANTZ","trust"],["CLAUDIUS","GUILDENSTERN","trust"],["ROSENCRANTZ","HAMLET","deceive"],["POLONIUS","HAMLET","deceive"],["HAMLET","POLONIUS","hate"],["HAMLET","CLAUDIUS","deceive"],["GERTRUDE","HAMLET","love"]],"3":[["HAMLET","OPHELIA","hate"],["CLAUDIUS","HAMLET","hate"],["HAMLET","CLAUDIUS","hate"],["HORATIO","HAMLET","love"],["HAMLET","GERTRUDE","hate"],["GERTRUDE","HAMLET","love"],["POLONIUS","HAMLET","deceive"]],"4":[["CLAUDIUS","LAERTES","deceive"],["LAERTES","HAMLET","hate"],["CLAUDIUS","HAMLET","hate"],["LAERTES","OPHELIA","love"],["HAMLET","ROSENCRANTZ","deceive"],["HORATIO","HAMLET","love"]],"5":[["HAMLET","LAERTES","love"],["LAERTES","HAMLET","deceive"],["CLAUDIUS","GERTRUDE","love"],["HAMLET","CLAUDIUS","hate"],["HAMLET","HORATIO","trust"],["HAMLET","FORTINBRAS","trust"]]},"examq":[["How does Shakespeare present Hamlet's delay?",[33,43,54,62,64,78]],["How does Shakespeare present Claudius?",[52,53,55,39,65,66]],["How does Shakespeare present madness in Hamlet?",[24,28,32,46,47,68]],["How does Shakespeare present the theme of appearance and reality?",[4,5,22,38,48,58]],["How does Shakespeare present death in Hamlet?",[6,40,42,71,72,82]],["How does Shakespeare present women in Hamlet?",[9,44,45,49,70,74]]],"check":["Answered the exact question in the first sentence","Made a clear argument (a thesis) and kept to it","Used short quotations, built into my own sentences","Explained what the quotation suggests, not just what it says","Zoomed in on a single word or image","Named a method (soliloquy, image, structure, contrast) and its effect","Linked to context where it helps the argument","Considered more than one interpretation","Referred to the whole play, not just one scene","Ended with a conclusion that answers the question"],"place":{"a1s1":"Elsinore","a1s2":"Elsinore","a1s3":"Elsinore","a1s4":"Elsinore","a1s5":"Elsinore","a2s1":"Elsinore","a2s2":"Elsinore","a3s1":"Elsinore","a3s2":"Elsinore","a3s3":"Elsinore","a3s4":"Elsinore","a4s1":"Elsinore","a4s2":"Elsinore","a4s3":"Elsinore","a4s4":"Near the coast","a4s5":"Elsinore","a4s6":"Elsinore","a4s7":"Elsinore","a5s1":"Elsinore","a5s2":"Elsinore"},"models":[[43,"Shakespeare presents Hamlet's delay as the result of too much thinking.","In 'Thus conscience does make cowards of us all', 'conscience' means both moral sense and awareness: thought itself becomes a kind of cowardice.","The audience see Hamlet's mind turning action into argument, so the delay feels tragic rather than lazy.","Revenge tragedies expected a hero who acts; Shakespeare's hero analyses why he cannot.","Some critics, like Bradley, see melancholy rather than thinking as the true cause."],[52,"Claudius is presented as a guilty murderer with a real conscience.","'O, my offence is rank, it smells to heaven' uses a disease image: his crime is a rotting body that heaven can smell.","Alone with the audience, Claudius becomes more than a stage villain, which makes him more frightening and more human.","The 'primal eldest curse' links him to Cain, the first murderer in the Bible.","His failure to repent shows that guilt alone is not enough without giving up what he gained."],[24,"Shakespeare makes Hamlet's madness deliberately hard to judge.","'To put an antic disposition on' presents madness as a costume to be put on, like an actor's.","Because the audience hear the plan, they watch every later wild speech asking whether it is real.","Elizabethans saw melancholy as a disease of scholars, so real and pretended madness could overlap.","Ophelia's real madness later provides a sharp contrast."],[4,"Hamlet rejects the false appearances of the court from his first speech.","'Seems, madam! Nay, it is; I know not seems' repeats 'seems' to mock outward show.","The audience are invited to look beneath surfaces in a court full of masks.","The play itself is a 'show', so Shakespeare makes us think about theatre too.","Ironically, Hamlet soon decides to 'seem' mad himself."],[40,"Death is presented as a question Hamlet cannot answer.","'To be, or not to be' uses simple verbs to ask the biggest question.","The audience share his uncertainty because the soliloquy never resolves it.","Suicide was a mortal sin in Shakespeare's Christian society, which is why 'the dread of something after death' holds him back.","By Act 5, 'the readiness is all' suggests he has found a kind of peace."],[9,"Women are presented through Hamlet's disgust and suspicion.","'Frailty, thy name is woman!' makes one woman's remarriage a judgement on all women.","The audience may sympathise with his grief while seeing the unfairness of his generalisation.","Remarriage to a brother-in-law was seen as incest, so Gertrude's act was shocking.","Feminist critics note that neither Gertrude nor Ophelia is allowed to explain herself."]],"lang":{"un":[[1201,"I lov'd Ophelia; forty thousand brothers Could not, with all their quantity of love, Make up my sum.","Forty thousand brothers could not make up my sum of love, with all their quantity of love. I loved Ophelia."],[95,"Frailty, thy name is woman!","Woman, your name is frailty!"],[528,"The play's the thing Wherein I'll catch the conscience of the King.","The thing is the play, in which I'll catch the King's conscience."],[772,"Words without thoughts never to heaven go.","Words without thoughts never go to heaven."]],"pun":[[83,"A little more than kin, and less than kind","kind","pun","Kind means both kindly and natural, of the same kind. Hamlet is too closely related to Claudius, but feels no natural bond."],[85,"I am too much i' the sun","sun","pun","Sun sounds like son: Hamlet resents being called 'my son' by Claudius."],[1134,"I think it be thine indeed, for thou liest in't.","liest","pun","Lie means both to lie down and to tell lies. Hamlet and the gravedigger play with both."],[737,"though you can fret me, you cannot play upon me","fret","pun","Frets are the ridges on an instrument; fret also means annoy. Hamlet turns the recorder into an image of being manipulated."]],"st":[[554,"To be, or not to be, that is the question:",[["be","Existence itself is the issue."],["not","The choice of not existing: suicide."],["question","Hamlet stresses that he is thinking, not deciding."]]],[1375,"The rest is silence.",[["rest","Rest also means sleep or peace after death."],["is","A simple, final statement."],["silence","The end of Hamlet's words, which have filled the play."]]],[1168,"Alas, poor Yorick.",[["Alas","Real sorrow for a lost friend."],["poor","Pity, perhaps also for all human beings."],["Yorick","The name gives the skull back a person."]]]]},"dir":[[34,"In the same figure, like the King that's dead.","How should the Ghost appear?",[["In full armour, slow and grand","A warlike, royal threat."],["Pale and half seen in smoke","Uncertain: is it real or a demon?"],["Played by the same actor as Claudius","The two brothers mirror each other."]]],[554,"To be, or not to be, that is the question:","Where is Hamlet as he speaks?",[["Alone, centre stage","A private meditation shared with the audience."],["Aware that Claudius and Polonius are hidden","He may be performing his madness for them."],["Holding a dagger","Suicide feels like a real possibility."]]],[570,"Get thee to a nunnery.","How does Hamlet treat Ophelia?",[["Cruelly, as if he hates her","His disgust with women takes over."],["Angrily, after spotting the spies","He is attacking them as much as her."],["Tenderly, trying to protect her","He sends her away from a corrupt court."]]],[683,"The King rises.","How does Claudius react to the play?",[["Leaps up in obvious panic","His guilt is clear to everyone."],["Rises slowly and calmly","He stays in control; only Hamlet is sure."],["Laughs and walks out","He hides behind contempt for the actors."]]],[769,"Now might I do it pat, now he is praying.","How close does Hamlet come to killing Claudius?",[["His sword touches the King's neck","The audience gasp at the near miss."],["He never draws his sword","He was never going to do it."],["Claudius almost turns and sees him","Tension and danger for both men."]]],[1168,"Let me see. [Takes the skull] Alas, poor Yorick.","How does Hamlet hold the skull?",[["Tenderly, close to his face","Real grief for a childhood friend."],["At arm's length, disgusted","Death repels him."],["Comically, playing with it","Death becomes a jester's joke."]]]],"ev":{"ctx":[["55","615"],["554","1296"],["433","1371"],["243","802","1070"],["243","528","769"],["91","100"],["95","789","802"],["1230","1375","85"],["89","95","455"],["589","666"],["1266","1270","1216"],["251","1177","1011"]],"cr":{"action":[["938","1377","455"],["554","938","769"],["95","455","938"]],"madness":[["1011","1078","578"],["478","570","410"]],"women":[["802","95","769"],["570","95","802"]],"appearance":[["89","95","554"],["528","554","938"]],"kingship":[["433","226","582"],["85","1002","1177"]],"death":[["243","251","1177"]],"fate":[["1296","1216","1371"]]}}};
